def _pri_dates(secid):
    j = json.loads(http_text("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description"
                             "&description.columns=name,value" % secid, timeout=25))
    m = {r[0]: r[1] for r in j["description"]["data"]}
    ok = lambda v: v if v and re.match(r"^\d{4}-\d\d-\d\d$", v) and not v.startswith("0000") else ""  # noqa: E731
    return [ok(m.get("ISSUEDATE")), ok(m.get("STARTDATEMOEX"))]


def _day_add(d, n):
    return (datetime.strptime(d, "%Y-%m-%d") + timedelta(days=n)).strftime("%Y-%m-%d")


def _pri_history(secid, d0, today):
    """Цена и доходность в 1-й день торгов, через 7 и 30 дней. Цена — % от номинала (средневзвешенная по основной площадке дня)."""
    till = min(today, _day_add(d0, 50))
    rows, start = [], 0
    while start < 400:
        j = json.loads(http_text(HIST_URL % (secid, d0, till, start), timeout=30))
        t = j["history"]
        part = [dict(zip(t["columns"], r)) for r in t["data"]]
        rows += part
        if len(part) < 100:
            break
        start += 100
    best = {}
    for r in rows:
        px = r.get("WAPRICE") or r.get("LEGALCLOSEPRICE") or r.get("CLOSE")
        if not px or not r.get("TRADEDATE"):
            continue
        cur = best.get(r["TRADEDATE"])
        if cur is None or (r.get("VALUE") or 0) > (cur.get("VALUE") or 0):
            best[r["TRADEDATE"]] = dict(r, px=px)
    days = sorted(best)
    out = {"d0": None, "p0": None, "y0": None, "p7": None, "y7": None, "p30": None, "y30": None, "t": time.time()}
    if days:
        f = days[0]
        if f <= _day_add(d0, 14):
            out.update(d0=f, p0=round(best[f]["px"], 2), y0=best[f].get("YIELDCLOSE") or best[f].get("YIELDATWAP"))
            for k, n in (("7", 7), ("30", 30)):
                lo, hi = _day_add(f, n), _day_add(f, n + 7)
                c = [x for x in days if lo <= x <= hi]
                if c:
                    out["p" + k] = round(best[c[0]]["px"], 2)
                    out["y" + k] = best[c[0]].get("YIELDCLOSE") or best[c[0]].get("YIELDATWAP")
            out["done"] = today >= _day_add(f, 40)
    out["n_days"] = len(days)
    # выпуск без сделок вообще (ещё не торговался) — перепроверим позже
    out["done"] = bool(out.get("done"))
    return out


def _pri_candidates():
    st = store()
    iss = st.get(PRI_ISS_KEY) or {}
    cut = _day_add(date.today().isoformat(), -PRI_DAYS)
    c = []
    for sid, (a, b) in iss.items():
        ref = b or a
        if ref and ref >= cut:
            c.append((ref, sid))
    c.sort(reverse=True)
    return iss, [(sid, ref) for ref, sid in c[:PRI_MAX]]


def _pri_run():
    try:
        st = store()
        st_rows = _scr["rows"] or screener_rows()
        uni = {r["id"]: r for r in st_rows}
        iss = st.get(PRI_ISS_KEY) or {}
        miss = [s for s in uni if s not in iss]
        _pri_h.update(phase="Узнаю даты размещения выпусков", done=0, total=len(miss))
        for k in range(0, len(miss), 200):
            part = miss[k:k + 200]

            def one(s):
                try:
                    return s, _pri_dates(s)
                except Exception:  # noqa: BLE001
                    return s, None
            for s, v in pool_map(one, part, workers=8):
                if v is not None:
                    iss[s] = v
            st.put(PRI_ISS_KEY, iss)
            _pri_h["done"] = min(len(miss), k + 200)
        iss, cand = _pri_candidates()
        cand = [(s, ref) for s, ref in cand if s in uni]
        today = date.today().isoformat()
        todo = []
        for s, ref in cand:
            e = st.get(PRI_H_PREFIX + s)
            if e and (e.get("done") or time.time() - e.get("t", 0) < 12 * 3600):
                continue
            todo.append((s, ref))
        _pri_h.update(phase="Загружаю историю торгов новых выпусков", done=0, total=len(todo))

        def hist(x):
            try:
                return x[0], _pri_history(x[0], x[1], today)
            except Exception:  # noqa: BLE001
                return x[0], None
        for k in range(0, len(todo), 40):
            res = pool_map(hist, todo[k:k + 40], workers=8)
            st.put_many([(PRI_H_PREFIX + s, v) for s, v in res if v is not None])
            _pri_h["done"] = min(len(todo), k + 40)
        _pri_h["fin"] = time.time()
        _pri_h["err"] = None
    except Exception as e:  # noqa: BLE001
        _pri_h["err"] = str(e)[:200]
    finally:
        _pri_h.update(running=False, phase="", memo=(0, None))


def primary_stats_start(force=False):
    with _rt_lock:
        if _pri_h["running"]:
            return
        if not force and time.time() - _pri_h["fin"] < 6 * 3600:
            return
        _pri_h["running"] = True
    threading.Thread(target=_pri_run, daemon=True).start()


def _grp_stats(items):
    p0 = [x["p0"] for x in items if x["p0"] is not None]
    p7 = [x["p7"] for x in items if x["p7"] is not None]
    p30 = [x["p30"] for x in items if x["p30"] is not None]
    dn = [x["now"] - x["p0"] for x in items if x["now"] is not None and x["p0"] is not None]
    abv = lambda arr: round(100.0 * sum(1 for v in arr if v > 100.0) / len(arr), 1) if arr else None  # noqa: E731
    return {"n": len(items), "p0": _med(p0), "p7": _med(p7), "p30": _med(p30), "n30": len(p30),
            "above0": abv(p0), "above7": abv(p7), "above30": abv(p30),
            "below30": round(100.0 * sum(1 for v in p30 if v < 100) / len(p30), 1) if p30 else None,
            "d_now": _med(dn)}


def primary_stats_payload():
    memo = _pri_h["memo"]
    if memo[1] is not None and time.time() - memo[0] < 120 and not _pri_h["running"]:
        return dict(memo[1], loading=False)
    primary_stats_start()
    st = store()
    iss, cand = _pri_candidates()
    uni = {r["id"]: r for r in _scr["rows"]}
    items = []
    for sid, ref in cand:
        e = st.get(PRI_H_PREFIX + sid)
        r = uni.get(sid)
        if not e or not r or e.get("p0") is None:
            continue
        rt, ci = None, None
        try:
            ti = globals().get("tcat_info")
            ci = ti(r.get("isin")) if ti and r.get("isin") else None
            rt = best_rating(r.get("isin"), (ci or {}).get("name") or r["name"]) if r["kind"] == "corp" else None
        except Exception:  # noqa: BLE001
            rt = None
        sector = (ci or {}).get("sector") if r["kind"] == "corp" else None
        sane = lambda v, lo, hi: v if v is not None and lo <= v <= hi else None  # noqa: E731
        now_ok = r.get("price") if (r.get("yield") or 0) > 0 else None       # без доходности цена ненадёжна (индексируемый номинал и т. п.)
        if not (80 <= e["p0"] <= 120):
            continue
        items.append({"secid": sid, "isin": r.get("isin"), "name": r["name"], "kind": r["kind"], "d0": e["d0"], "p0": e["p0"], "y0": e.get("y0"),
                      "p7": sane(e.get("p7"), 50, 150), "p30": sane(e.get("p30"), 50, 150), "y30": e.get("y30"),
                      "now": sane(now_ok, 10, 150), "ynow": r.get("yield"),
                      "rating": rt["v"] if rt else None, "bucket": "ОФЗ" if r["kind"] == "ofz" else rating_bucket(rt["v"] if rt else None),
                      "sector": sector})
    by_b, by_s = {}, {}
    for x in items:
        by_b.setdefault(x["bucket"], []).append(x)
        if x["sector"]:
            by_s.setdefault(x["sector"], []).append(x)
    order = ["ОФЗ"] + MKT_BUCKETS + ["нет рейтинга"]
    buckets = [dict(_grp_stats(by_b[b]), bucket=b) for b in order if b in by_b]
    sectors = sorted((dict(_grp_stats(v), sector=k) for k, v in by_s.items() if len(v) >= 3), key=lambda g: -g["n"])[:12]
    aged = [x for x in items if x["now"] is not None and x["d0"] <= _day_add(date.today().isoformat(), -7)]
    aged.sort(key=lambda x: x["now"] - x["p0"])
    trim = lambda x: dict(x, delta=round(x["now"] - x["p0"], 2))  # noqa: E731
    by_m = {}
    for x in items:
        by_m.setdefault(x["d0"][:7], []).append(x)
    months = [dict(_grp_stats(v), m=k) for k, v in sorted(by_m.items())]
    snaps = (st.get(PRI_SNAP_KEY) or {}).get("days") or {}
    d30 = _day_add(date.today().isoformat(), -30)
    d90 = _day_add(date.today().isoformat(), -90)
    win30 = _grp_stats([x for x in items if (x.get("d0") or "") >= d30])
    win90 = _grp_stats([x for x in items if (x.get("d0") or "") >= d90])
    res = {"all": _grp_stats(items), "win30": win30, "win90": win90, "buckets": buckets, "sectors": sectors, "months": months,
           "worst": [trim(x) for x in aged[:8]], "best": [trim(x) for x in aged[::-1][:8]],
           "universe": len(cand), "ready": len(items), "snap_days": len(snaps), "updated": _pri_h["fin"], "err": _pri_h["err"]}
    if not _pri_h["running"]:
        _pri_h["memo"] = (time.time(), res)
    return dict(res, loading=_pri_h["running"], phase=_pri_h["phase"], done=_pri_h["done"], total=_pri_h["total"])


def _api_primary_stats(cfg, acc, q, force):
    return primary_stats_payload()


API_GET["/api/primary/stats"] = _api_primary_stats


RATE_TERM_MIN, RATE_TERM_MAX, RATE_TERMS_MAX = 0.25, 30.0, 6
_rates_state = {"running": False, "ended": 0.0}


def kbd_interp(grid, term):
    """Доходность КБД на срок term (лет): линейная интерполяция между соседними точками сетки {срок: доходность}.
    Вне диапазона сетки возвращает None (не экстраполируем и не тянем крайнее значение)."""
    pts = sorted((float(k), v) for k, v in (grid or {}).items() if v is not None)
    if not pts or term is None or term < pts[0][0] - 1e-9 or term > pts[-1][0] + 1e-9:
        return None
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if term <= x1 + 1e-9:
            return y0 if x1 == x0 else y0 + (y1 - y0) * (term - x0) / (x1 - x0)
    return pts[-1][1]


def parse_rate_terms(raw):
    """'1,2,5.5' -> [1.0, 2.0, 5.5]: только числа в 0.25..30, без повторов, по возрастанию, не больше 6; по умолчанию [2.0]."""
    out = set()
    for x in str(raw or "").replace(";", ",").split(","):
        try:
            t = round(float(x.strip().replace(",", ".")), 2)
        except ValueError:
            continue
        if RATE_TERM_MIN <= t <= RATE_TERM_MAX:
            out.add(t)
    return sorted(out)[:RATE_TERMS_MAX] or [2.0]


def key_rate_series():
    st = store()
    hit = st.get(KEY_KEY, ttl=6 * 3600)
    if hit:
        return hit
    frm = (date.today() - timedelta(days=900)).strftime("%d.%m.%Y")
    to = date.today().strftime("%d.%m.%Y")
    try:
        s = http_text("https://www.cbr.ru/hd_base/KeyRate/?UniDbQuery.Posted=True&UniDbQuery.From=%s&UniDbQuery.To=%s" % (frm, to))
    except Exception:  # noqa: BLE001
        old = st.get(KEY_KEY)          # сайт ЦБ недоступен — последний сохранённый ряд лучше, чем ошибка на каждом экране
        if old:
            return old
        raise
    rows = []
    for d, v in re.findall(r"<td>(\d\d\.\d\d\.\d{4})</td>\s*<td>([\d,]+)</td>", s):
        rows.append([datetime.strptime(d, "%d.%m.%Y").date().isoformat(), float(v.replace(",", "."))])
    rows.sort()
    if rows:
        st.put(KEY_KEY, rows)
    return rows


def _kbd_one(d):
    j = json.loads(http_text("https://iss.moex.com/iss/engines/stock/zcyc.json?iss.meta=off&iss.only=yearyields&date=" + d))
    g = {str(float(r[2])): r[3] for r in j["yearyields"]["data"] if r[3] is not None}
    return d, (g or None)


def _rates_run(days):
    try:
        st = store()
        cache = st.get(KBD_KEY) or {}
        today = date.today()
        need = []
        for i in range(days + 1):
            d = today - timedelta(days=i)
            if d.weekday() < 5 and d.isoformat() not in cache:
                need.append(d.isoformat())
        try:
            key_rate_series()
        except Exception:  # noqa: BLE001
            pass
        for k in range(0, len(need), 40):
            part = need[k:k + 40]
            for d, v in pool_map(lambda x: _safe(_kbd_one, x), part, workers=8):
                if d is None:
                    continue
                if v is not None or d < today.isoformat():
                    cache[d] = v
            st.put(KBD_KEY, cache)
    finally:
        _rates_state["ended"] = time.time()
        _rates_state["running"] = False


def _safe(fn, x):
    try:
        return fn(x)
    except Exception:  # noqa: BLE001
        return None, None


def rates_start(days):
    with _rt_lock:
        # недокачанные дни (сбой ISS, праздники) повторяем не чаще раза в 10 минут — иначе экран вечно «загружается»
        if _rates_state["running"] or time.time() - _rates_state["ended"] < 600:
            return
        _rates_state["running"] = True
    threading.Thread(target=_rates_run, args=(days,), daemon=True).start()


def rates_payload(days, terms=None):
    days = max(30, min(int(days or 365), 900))
    tl = terms if isinstance(terms, list) else parse_rate_terms(terms)
    st = store()
    cache = st.get(KBD_KEY) or {}
    old = st.get(KBD_OLD_KEY) or {}
    today = date.today()
    first = (today - timedelta(days=days)).isoformat()
    # сегодняшняя КБД появляется только после расчёта биржей — её отсутствие не считаем недокачкой
    miss = sum(1 for i in range(1, days + 1) if (today - timedelta(days=i)).weekday() < 5
               and (today - timedelta(days=i)).isoformat() not in cache)
    if today.weekday() < 5 and today.isoformat() not in cache:
        rates_start(days)
    if miss > 0:
        rates_start(days)
    try:
        keys = key_rate_series()
    except Exception:  # noqa: BLE001
        keys = st.get(KEY_KEY) or []
    grids = {}
    for d in set(cache) | set(old):
        if d < first:
            continue
        g = cache.get(d)
        if g:
            grids[d] = g
        elif d not in cache and old.get(d) is not None:
            grids[d] = {"2.0": old[d]}      # запас до докачки v2: только срок 2 года
    iso = sorted(grids)
    kbd = {("%g" % t): [] for t in tl}
    key, ki, last = [], 0, None
    for d in iso:
        while ki < len(keys) and keys[ki][0] <= d:
            last = keys[ki][1]
            ki += 1
        for t in tl:
            v = kbd_interp(grids[d], t)
            kbd["%g" % t].append(round(v, 2) if v is not None else None)
        key.append(last)
    return {"iso": iso, "labels": [datetime.strptime(d, "%Y-%m-%d").strftime("%d.%m.%Y") for d in iso],
            "kbd": kbd, "terms": tl, "key": key, "loading": _rates_state["running"] or (miss > 0 and not _rates_state["ended"]),
            "keys": [k for k in keys if k[0] >= first], "next_cbr": _next_cbr_safe()}


def _next_cbr_safe():
    """Ближайшее заседание ЦБ для экрана «Ставки»; без сети — None (экран не должен падать из-за календаря ЦБ)."""
    fn = globals().get("cbr_next_meeting")
    try:
        return fn(wait=False) if fn else None
    except Exception:  # noqa: BLE001
        return None




# ── кривая КБД на прошлые даты ──

def kbd_curve_on(d):
    """Кривая КБД на дату d (ISO; при выходном берётся ближайший прошлый торговый день). Кэш для прошлых дат навсегда."""
    st = store()
    key = "kbdc1:" + d
    v = st.get(key)
    if v:
        return v
    if d >= date.today().isoformat():
        return [list(p) for p in kbd_curve()]
    for k in range(0, 6):
        dd = _day_add(d, -k)
        j = json.loads(http_text("https://iss.moex.com/iss/engines/stock/zcyc.json?iss.meta=off&iss.only=yearyields&date=" + dd))
        pts = sorted((r[2], r[3]) for r in j["yearyields"]["data"])
        if pts:
            v = [list(p) for p in pts]
            st.put(key, v)
            return v
    return None


CURVE_TERMS = [0.25, 0.5, 1, 2, 3, 5, 7, 10, 15, 20]
CURVE_AGO = [(0, "Сегодня"), (30, "1 мес. назад"), (91, "3 мес. назад"), (182, "6 мес. назад"), (365, "12 мес. назад")]


def _term_lab(t):
    return "%d мес" % round(t * 12) if t < 1 else "%d г." % t


def kbd_curves_payload():
    today = date.today().isoformat()
    ds = [(_day_add(today, -n), lab) for n, lab in CURVE_AGO]

    def one(x):
        try:
            return kbd_curve_on(x[0])
        except Exception:  # noqa: BLE001
            return None
    res = pool_map(one, ds, workers=5)
    items = []
    for (d, lab), pts in zip(ds, res):
        if pts:
            items.append({"date": d, "label": lab, "y": [round(_interp(pts, t), 2) for t in CURVE_TERMS]})
    return {"terms": CURVE_TERMS, "labels": [_term_lab(t) for t in CURVE_TERMS], "items": items}


def _fmt_pp(v):
    return ("%.2f" % abs(v)).replace(".", ",")


def _curve_notes(cv):
    out = []
    its = cv.get("items") or []
    if len(its) < 2:
        return out
    now = its[0]
    i2, i10, i1 = CURVE_TERMS.index(2), CURVE_TERMS.index(10), CURVE_TERMS.index(1)
    for it in its[1:]:
        if it["label"] != "3 мес. назад":
            continue
        s0, s1 = it["y"][i10] - it["y"][i2], now["y"][i10] - now["y"][i2]
        if abs(s1 - s0) < 0.15:
            out.append("Форма кривой за 3 месяца почти не изменилась: разница между 10-летними и 2-летними ставками %s п.п." % _fmt_pp(s1))
        else:
            out.append("За 3 месяца кривая КБД стала %s: разница между 10-летними и 2-летними ставками %s с %s до %s п.п." % (
                "круче (длинные ставки выше коротких сильнее)" if s1 > s0 else "положе (длинные и короткие ставки сближаются)",
                "выросла" if s1 > s0 else "сократилась", ("-" if s0 < 0 else "") + _fmt_pp(s0), ("-" if s1 < 0 else "") + _fmt_pp(s1)))
        d1 = now["y"][i1] - it["y"][i1]
        if abs(d1) >= 0.1:
            out.append("Доходность 1-летних гособлигаций %s на %s п.п. (с %s до %s %%)." % (
                "выросла" if d1 > 0 else "снизилась", _fmt_pp(d1), _fmt_pp(it["y"][i1]), _fmt_pp(now["y"][i1])))
    yr = [it for it in its if it["label"] == "12 мес. назад"]
    if yr:
        d2 = now["y"][i2] - yr[0]["y"][i2]
        out.append("За год 2-летняя доходность КБД %s на %s п.п." % ("выросла" if d2 > 0 else "снизилась", _fmt_pp(d2)))
    return out


# ── история медианных спредов к КБД по рейтингам: накопленные снимки + разовое восстановление по истории торгов ──

BF_KEY = "mkt_bf_v1"
_bf = {"running": False, "last": 0}


def _bf_dates():
    t = date.today()
    ds = set()
    for n in [7 * k for k in range(1, 9)] + [91, 119, 147, 182]:
        d = t - timedelta(days=n)
        while d.weekday() > 4:
            d -= timedelta(days=1)
        ds.add(d.isoformat())
    return sorted(ds)


HB_URL = ("https://iss.moex.com/iss/history/engines/stock/markets/bonds/boards/TQCB/securities.json?iss.meta=off&date=%s&start=%d"
          "&iss.only=history,history.cursor&history.columns=SECID,YIELDCLOSE,YIELDATWAP,DURATION,MATDATE,NUMTRADES,VALUE,CURRENCYID")


def _bf_day(d, bucket_of):
    pts = kbd_curve_on(d)
    if not pts:
        return None

    def page(s):
        j = json.loads(http_text(HB_URL % (d, s), timeout=40))
        t = j["history"]
        return [dict(zip(t["columns"], r)) for r in t["data"]], j["history.cursor"]["data"][0][1]
    rows, total = page(0)
    starts = list(range(100, min(total, 6000), 100))
    for part, _ in pool_map(lambda s: _safe_pg(page, s), starts, workers=6):
        rows += part
    by = {}
    for r in rows:
        b = bucket_of.get(r["SECID"])
        y = r.get("YIELDCLOSE") or r.get("YIELDATWAP")
        if not b or not y or not r.get("DURATION") or not (r.get("NUMTRADES") or 0) or r.get("CURRENCYID") not in ("SUR", "RUB", None):
            continue
        if not (0 < y < 60) or not r.get("MATDATE") or r["MATDATE"] <= _day_add(d, 40):
            continue
        by.setdefault(b, []).append(y - _interp(pts, r["DURATION"] / 365.0))
    sp, nn = {}, {}
    for b, v in by.items():
        if len(v) >= 3:
            sp[b], nn[b] = _med(v), len(v)
    return {"sp": sp, "n": nn, "bf": True} if sp else None


def _safe_pg(fn, s):
    try:
        return fn(s)
    except Exception:  # noqa: BLE001
        return [], 0


def _bf_run():
    try:
        rows = _scr["rows"]
        if not rows or not any(r.get("rating") for r in rows):
            screener_payload()
            rows = _scr["rows"]
        bucket_of = {r["id"]: rating_bucket(r["rating"]) for r in rows if r.get("kind") == "corp" and r.get("cur") == "RUB" and r.get("rating")}
        st = store()
        bf = st.get(BF_KEY) or {}
        for d in _bf_dates():
            if d in bf:
                continue
            try:
                v = _bf_day(d, bucket_of)
            except Exception:  # noqa: BLE001
                v = None
            if v:
                bf[d] = v
                st.put(BF_KEY, bf)
        _bf["last"] = time.time()
    except Exception:  # noqa: BLE001
        _bf["last"] = time.time() - 3600 * 5
    finally:
        _bf["running"] = False


def spreads_backfill_start():
    with _rt_lock:
        if _bf["running"] or time.time() - _bf["last"] < 6 * 3600:
            return
        _bf["running"] = True
    threading.Thread(target=_bf_run, daemon=True).start()


def spreads_history_payload():
    st = store()
    live = st.get(MKT_HIST2_KEY) or {}
    old = st.get(MKT_HIST_KEY) or {}
    allh = dict(st.get(BF_KEY) or {})
    for d, sp in old.items():           # v1 (только спреды), если нет v2
        if d not in live:
            allh[d] = {"sp": sp}
    allh.update(live)
    days = sorted(allh)[-400:]
    series = {b: [(allh[d].get("sp") or {}).get(b) for d in days] for b in MKT_BUCKETS}
    series = {b: v for b, v in series.items() if any(x is not None for x in v)}
    return {"dates": days, "series": series, "bf": [d for d in days if allh[d].get("bf")]}


def _spread_notes(h):
    out = []
    ds = h["dates"]
    if len(ds) < 2:
        return ["История спредов накапливается: каждый день работы программы добавляет точку."]
    last = ds[-1]
    for b in ("AAA", "AA", "A", "BBB"):
        v = h["series"].get(b)
        if not v or v[-1] is None:
            continue
        tgt = _day_add(last, -30)
        cand = [i for i, d in enumerate(ds[:-1]) if d <= tgt and v[i] is not None]
        if not cand:
            cand = [i for i, d in enumerate(ds[:-1]) if v[i] is not None and d <= _day_add(last, -7)]
        if not cand:
            continue
        i = cand[-1]
        diff = v[-1] - v[i]
        days = (datetime.strptime(last, "%Y-%m-%d") - datetime.strptime(ds[i], "%Y-%m-%d")).days
        per = "за месяц" if 25 <= days <= 40 else "за %d дн." % days
        if abs(diff) < 0.1:
            out.append("Спред %s почти не изменился %s: %s п.п." % (b, per, _fmt_pp(v[-1])))
        else:
            out.append("Спред %s %s на %s п.п. %s (с %s до %s п.п.)." % (
                b, "расширился" if diff > 0 else "сузился", _fmt_pp(diff), per, _fmt_pp(v[i]), _fmt_pp(v[-1])))
    return out or ["Для вывода о динамике пока мало данных по спредам."]


def rates_extra_payload():
    spreads_backfill_start()
    h = spreads_history_payload()
    cv = kbd_curves_payload()
    return {"spreads": h, "curves": cv, "notes": _curve_notes(cv), "spread_notes": _spread_notes(h), "loading": _bf["running"]}


API_GET["/api/rates/extra"] = lambda cfg, acc, q, force: rates_extra_payload()


# ── ежедневная фоновая работа: снимок размещений и спреды (история копится, даже если разделы не открывали) ──

def _market_daily_loop():
    time.sleep(20)
    while True:
        try:
            primary_payload()
        except Exception:  # noqa: BLE001
            pass
        try:
            h = store().get(MKT_HIST2_KEY) or {}
            if date.today().isoformat() not in h:
                screener_payload()
            spreads_backfill_start()
            # статистика первички (тысячи запросов к ISS при первом расчёте) — только по открытию раздела «Первичка»
        except Exception:  # noqa: BLE001
            pass
        time.sleep(6 * 3600)


def _market_daily_start():
    threading.Thread(target=_market_daily_loop, daemon=True).start()


STARTUP_HOOKS.append(_market_daily_start)


# ── первичка: объёмы размещений («простыня» новых выпусков) ──
# Что нашли в ISS (проверено вживую):
#  * Корпоративные и региональные облигации размещаются на РЫНКЕ ndm (не bonds!), площадка PSAU «Размещение - адрес.»
#    (PAUS — в USD, PACY — в CNY). Размещение ОФЗ и аукционы — рынок bonds, площадки PACT/AUCT/PAYT.
#    Новый выпуск до начала торгов в bonds вообще не виден: /engines/stock/markets/bonds/securities/{secid} пуст.
#  * Сегодняшние обороты: /engines/stock/markets/ndm/boards/PSAU/securities.json (marketdata: VALTODAY — ₽ по цене сделок,
#    VOLTODAY — штуки, NUMTRADES). Это же — список всех бумаг, открытых на площадке размещения (около 80, большинство — «краны»
#    без сделок), поэтому «новый выпуск» отбираем по описанию: /iss/securities/{secid}.json (description: ISSUEDATE — дата
#    начала торгов, ISSUESIZE — объём выпуска в ШТУКАХ, FACEVALUE/INITIALFACEVALUE — номинал, MATDATE).
#  * Дневная история размещения: /iss/history/engines/stock/markets/ndm/boards/PSAU/securities.json?date=YYYY-MM-DD
#    (одна страница ≈ 80 строк; столбцы VALUE — ₽ по цене сделок, VOLUME — штуки, NUMTRADES, WAPRICE, CLOSE).
#    По конкретной бумаге — /iss/history/engines/stock/markets/{ndm|bonds}/securities/{secid}.json (все площадки сразу).
#  * Размещено: ISSUESIZEPLACED (штуки) есть только у бумаг, которые уже торгуются на bonds; для ndm-размещений берём сумму
#    VOLUME по площадке размещения. Объём в номинале = штуки × номинал (VALUE у дисконтных/структурных может быть заметно меньше).

PV_DAYS = 30
PV_ACTIVE_MAX_DAYS = 400   # старше — показываем активный выпуск, только если по нему были сделки размещения за PV_DAYS
PV_PLACE_NDM = ("PSAU", "PAUS", "PACY")
PV_PLACE_BONDS = ("PACT", "AUCT", "PAYT")
PV_PLACE = set(PV_PLACE_NDM) | set(PV_PLACE_BONDS)
PV_BOARD_NAMES = {"PSAU": "размещение", "PAUS": "размещение", "PACY": "размещение", "PACT": "размещение (аукцион)",
                  "AUCT": "размещение (аукцион)", "PAYT": "размещение (аукцион)", "TQCB": "Т+ корп.", "TQOB": "Т+ ОФЗ",
                  "TQIR": "Т+ ПИР", "TQRD": "Т+ Д", "TQOD": "Т+ USD", "TQOE": "Т+ EUR", "TQOY": "Т+ CNY", "TQUD": "Т+ USD Д",
                  "PSOB": "РПС", "PTOB": "РПС с ЦК", "PSDB": "РПС Д"}
PV_DAY_KEY, PV_DESC_KEY, PV_DAYS_KEY = "pv_day1:", "pv_desc1:", "pv_secdays1:"
PV_CUM_KEY = "pv_cum1:"       # кумулятив по площадкам размещения с даты старта: {from, last, q, v, n, first}
_pv = {"running": False, "res": None, "t": 0.0, "phase": "", "err": None}
_pv_lock = threading.Lock()
_pv_mem = {}          # короткий кэш по бумагам: ключ -> (время, значение)
PV_ISS = "https://iss.moex.com/iss/"


def pv_msk_now():
    return datetime.now(timezone(timedelta(hours=3)))


def pv_ttl(now=None):
    """Срок жизни живых данных: 5 минут в торговые часы (будни 7:00-23:50 МСК), иначе 30 минут."""
    n = now or pv_msk_now()
    return 300 if n.weekday() < 5 and 7 <= n.hour < 24 else 1800


def pv_num(v):
    try:
        return float(v) if v is not None and v != "" else None
    except (TypeError, ValueError):
        return None


def pv_date(v):
    return v if isinstance(v, str) and re.match(r"^\d{4}-\d\d-\d\d$", v) and not v.startswith("0000") else ""


def pv_table(j, name):
    """Таблица ISS как список словарей; отсутствующая или пустая -> []."""
    t = (j or {}).get(name) or {}
    cols = t.get("columns") or []
    return [dict(zip(cols, r)) for r in t.get("data") or []]


def pv_json(url, timeout=30):
    try:
        return json.loads(http_text(url, timeout=timeout))
    except (OSError, ValueError):      # ISS иногда рвёт соединение: одна повторная попытка
        time.sleep(0.5)
        return json.loads(http_text(url, timeout=timeout))


def pv_hist_parse(rows, board_only=None):
    """Строки истории ISS -> компактные записи. Пустые строки (площадка открыта, сделок нет) отбрасываются."""
    out = []
    for r in rows:
        b = r.get("BOARDID")
        d = pv_date(r.get("TRADEDATE"))
        if not d or not r.get("SECID") or (board_only and b not in board_only):
            continue
        v, q, n = pv_num(r.get("VALUE")) or 0.0, pv_num(r.get("VOLUME")) or 0.0, int(pv_num(r.get("NUMTRADES")) or 0)
        if not (v or q or n):
            continue
        out.append({"s": r["SECID"], "b": b, "d": d, "v": round(v, 2), "q": q, "n": n, "w": pv_num(r.get("WAPRICE")),
                    "c": pv_num(r.get("CLOSE")), "y": pv_num(r.get("YIELDCLOSE")) or pv_num(r.get("YIELDATWAP")),
                    "nm": r.get("SHORTNAME"), "f": pv_num(r.get("FACEVALUE"))})
    return out


def pv_paged(url, table, timeout=30, maxpages=30):
    """Все страницы таблицы ISS (по 100 строк)."""
    rows, start = [], 0
    for _ in range(maxpages):
        j = pv_json(url + ("&start=%d" % start if start else ""), timeout)
        part = pv_table(j, table)
        rows += part
        if len(part) < 100:
            break
        start += len(part)
    return rows


_PV_HCOLS = "BOARDID,TRADEDATE,SECID,SHORTNAME,NUMTRADES,VALUE,VOLUME,WAPRICE,CLOSE,YIELDCLOSE,YIELDATWAP,FACEVALUE"


def pv_day_fetch(d):
    """Площадка размещения PSAU за один день (прошедший)."""
    url = (PV_ISS + "history/engines/stock/markets/ndm/boards/PSAU/securities.json?iss.meta=off&iss.only=history"
           "&history.columns=%s&date=%s" % (_PV_HCOLS, d))
    return pv_hist_parse(pv_paged(url, "history"))


def pv_days_cached(dates, errs):
    """Дни окна: прошедшие дни хранятся в базе насовсем (вчерашний — 3 часа, пока площадка может поправить итоги)."""
    st = store()
    today = pv_msk_now().date().isoformat()
    res, need = {}, []
    for d in dates:
        e = st.get(PV_DAY_KEY + d, 3 * 3600 if d >= _day_add(today, -1) else None)
        if e is None:
            need.append(d)
        else:
            res[d] = e
    if need:
        def one(d):
            try:
                return d, pv_day_fetch(d)
            except Exception as ex:  # noqa: BLE001
                return d, str(ex)[:120]
        got = []
        for d, v in pool_map(one, need, workers=8):
            if isinstance(v, list):
                res[d] = v
                got.append((PV_DAY_KEY + d, v))
            else:
                errs.append("история %s: %s" % (d, v))
        if got:
            st.put_many(got)
    return res


def pv_range_fetch(mk, board, d1, d2):
    url = (PV_ISS + "history/engines/stock/markets/%s/boards/%s/securities.json?iss.meta=off&iss.only=history"
           "&history.columns=%s&from=%s&till=%s" % (mk, board, _PV_HCOLS, d1, d2))
    return pv_hist_parse(pv_paged(url, "history"))


def pv_other_boards(d1, d2, errs):
    """Остальные площадки размещения (USD, CNY, аукционы ОФЗ): мелкие, одним запросом за период; кэш на 3 часа."""
    st, out = store(), []
    for mk, b in [("ndm", x) for x in PV_PLACE_NDM[1:]] + [("bonds", x) for x in PV_PLACE_BONDS]:
        k = "pv_rng1:%s:%s" % (mk, b)
        e = st.get(k, 3 * 3600)
        if e is None:
            try:
                e = pv_range_fetch(mk, b, d1, d2)
                st.put(k, e)
            except Exception as ex:  # noqa: BLE001
                errs.append("площадка %s: %s" % (b, str(ex)[:100]))
                e = []
        out += e
    return out


def pv_parse_desc(j):
    m = {r.get("name"): r.get("value") for r in pv_table(j, "description")}
    face = pv_num(m.get("FACEVALUE")) or pv_num(m.get("INITIALFACEVALUE")) or 0.0
    init = pv_num(m.get("INITIALFACEVALUE")) or face
    return {"name": m.get("SHORTNAME") or "", "full": m.get("NAME") or "", "kind": m.get("ISSUENAME") or "", "isin": m.get("ISIN") or "",
            "issued": pv_date(m.get("ISSUEDATE")), "start": pv_date(m.get("STARTDATEMOEX")), "mat": pv_date(m.get("MATDATE")),
            "size": pv_num(m.get("ISSUESIZE")), "face": face, "face0": init, "cur": m.get("FACEUNIT") or "SUR",
            "ftype": m.get("FACEVALUE_TYPE") or "", "emitter": m.get("EMITTER_ID")}


def pv_desc_old(d, cut):
    """Описание выпуска с датой старта раньше окна: дата не меняется и в «первичку» выпуск уже не вернётся — хранить можно насовсем."""
    st = (d or {}).get("issued") or (d or {}).get("start") or ""
    return bool(st) and st < cut


def pv_desc(secid):
    st = store()
    cut = _day_add(pv_msk_now().date().isoformat(), -PV_DAYS)
    e = st.get(PV_DESC_KEY + secid)
    if e is not None and pv_desc_old(e, cut):
        return e
    e = st.get(PV_DESC_KEY + secid, 7 * 86400)
    if e is not None:
        return e
    j = pv_json(PV_ISS + "securities/%s.json?iss.meta=off&iss.only=description&description.columns=name,value" % secid, 25)
    e = pv_parse_desc(j)
    st.put(PV_DESC_KEY + secid, e)
    return e


def pv_issuer_name(full):
    """«Банк ВТБ ПАО КС-4-1328» -> «Банк ВТБ ПАО»: отбрасываем серию в конце для поиска рейтинга."""
    s = re.sub(r"\s+(?:[A-Za-zА-Яа-я0-9\-/]*\d[A-Za-zА-Яа-я0-9\-/.]*)\s*$", "", (full or "").strip())
    return s or (full or "")


def pv_live_parse(j):
    """ndm/bonds: бумаги + marketdata по площадкам -> {secid: [{b, today, vol, n, last, wap, yield, size, placed, ...}]}."""
    sec = {}
    for r in pv_table(j, "securities"):
        sec.setdefault(r.get("SECID"), {})[r.get("BOARDID")] = r
    out = {}
    for m in pv_table(j, "marketdata"):
        sid, b = m.get("SECID"), m.get("BOARDID")
        s = (sec.get(sid) or {}).get(b) or {}
        out.setdefault(sid, []).append({
            "b": b, "today": pv_num(m.get("VALTODAY_RUR")) or pv_num(m.get("VALTODAY")) or 0.0, "vol": pv_num(m.get("VOLTODAY")) or 0.0,
            "n": int(pv_num(m.get("NUMTRADES")) or 0), "last": pv_num(m.get("LAST")), "wap": pv_num(m.get("WAPRICE")),
            "yield": pv_num(m.get("YIELD")) or pv_num(m.get("YIELDATWAPRICE")) or pv_num(m.get("CLOSEYIELD")) or None,
            "status": m.get("TRADINGSTATUS"), "name": s.get("SHORTNAME"), "full": s.get("SECNAME"), "settle": pv_date(s.get("SETTLEDATE")),
            "size": pv_num(s.get("ISSUESIZE")), "placed": pv_num(s.get("ISSUESIZEPLACED")), "face": pv_num(s.get("FACEVALUE")),
            "cpn": pv_num(s.get("COUPONPERCENT")), "ctype": s.get("BONDTYPE"), "mat": pv_date(s.get("MATDATE")),
            "offer": pv_date(s.get("OFFERDATE")), "isin": s.get("ISIN")})
    return out


_PV_LS = "SECID,BOARDID,SHORTNAME,SECNAME,FACEVALUE,SETTLEDATE,MATDATE,OFFERDATE,ISSUESIZE,ISSUESIZEPLACED,COUPONPERCENT,BONDTYPE,ISIN"
_PV_LM = "SECID,BOARDID,VALTODAY,VALTODAY_RUR,VOLTODAY,NUMTRADES,LAST,WAPRICE,YIELD,YIELDATWAPRICE,CLOSEYIELD,TRADINGSTATUS"


def pv_live_board(mk, board):
    j = pv_json(PV_ISS + "engines/stock/markets/%s/boards/%s/securities.json?iss.meta=off&iss.only=securities,marketdata"
                "&securities.columns=%s&marketdata.columns=%s" % (mk, board, _PV_LS, _PV_LM), 40)
    return pv_live_parse(j)


def pv_live_secid(secid):
    """Вторичные торги по бумаге на рынке bonds (все площадки): оборот сегодня, доходность, купон, размещено (ISSUESIZEPLACED)."""
    k = "bm:" + secid
    c = _pv_mem.get(k)
    if c and time.time() - c[0] < pv_ttl():
        return c[1]
    j = pv_json(PV_ISS + "engines/stock/markets/bonds/securities/%s.json?iss.meta=off&iss.only=securities,marketdata"
                "&securities.columns=%s&marketdata.columns=%s" % (secid, _PV_LS, _PV_LM), 25)
    v = pv_live_parse(j).get(secid) or []
    _pv_mem[k] = (time.time(), v)
    return v


def pv_sec_hist(mk, secid, frm, till):
    """История выпуска по рынку (все площадки), записи pv_hist_parse. Общий источник для pv_secid_days и кумулятива."""
    return pv_hist_parse(pv_paged(PV_ISS + "history/engines/stock/markets/%s/securities/%s.json?iss.meta=off&iss.only=history"
                                  "&history.columns=%s&from=%s&till=%s" % (mk, secid, _PV_HCOLS, frm, till), "history"))


def pv_cum(secid, frm, today, mks, errs):
    """Размещено с даты старта по площадкам размещения (без сегодняшнего дня): {q, v, n, first, last}.
    Дни до позавчера неизменны — копим в базе (pv_cum1:) и докачиваем только новые; вчера может поправиться — держим в памяти 3 часа."""
    st = store()
    k = PV_CUM_KEY + secid
    yday, final_to = _day_add(today, -1), _day_add(today, -2)
    e = st.get(k)
    if not e or e.get("from") != frm or e.get("mks") != sorted(mks):
        e = {"from": frm, "mks": sorted(mks), "last": _day_add(frm, -1), "q": 0.0, "v": 0.0, "n": 0, "first": ""}
    tk = "cumtail:" + secid
    tail = _pv_mem.get(tk)
    tail_ok = tail and time.time() - tail[0] < 3 * 3600 and tail[2] == e["last"]
    if e["last"] < yday and not (e["last"] >= final_to and tail_ok):
        rows = []
        for mk in mks:
            try:
                rows += [r for r in pv_sec_hist(mk, secid, _day_add(e["last"], 1), yday) if r["b"] in PV_PLACE and r["d"] < today]
            except Exception as ex:  # noqa: BLE001
                errs.append("кумулятив %s %s: %s" % (secid, mk, str(ex)[:100]))
                return None
        fin = [r for r in rows if r["d"] <= final_to]
        if fin:
            e["q"] += sum(r["q"] for r in fin)
            e["v"] += sum(r["v"] for r in fin)
            e["n"] += sum(r["n"] for r in fin)
            e["first"] = e["first"] or min(r["d"] for r in fin)
        if e["last"] < final_to:
            e["last"] = final_to
            st.put(k, e)
        tl = [r for r in rows if r["d"] > final_to]
        tail = (time.time(), {"q": sum(r["q"] for r in tl), "v": sum(r["v"] for r in tl), "n": sum(r["n"] for r in tl),
                              "first": min([r["d"] for r in tl] or [""])}, e["last"])
        _pv_mem[tk] = tail
    t = tail[1] if tail and tail[2] == e["last"] else {"q": 0.0, "v": 0.0, "n": 0, "first": ""}
    return {"q": e["q"] + t["q"], "v": round(e["v"] + t["v"], 2), "n": e["n"] + t["n"], "first": e["first"] or t["first"]}


def pv_aggregate(day_rows):
    """Записи истории площадок размещения -> по бумаге: сумма штук, ₽, сделок, первый/последний день, дневной ряд."""
    out = {}
    for r in day_rows:
        if r["b"] not in PV_PLACE:
            continue
        a = out.setdefault(r["s"], {"q": 0.0, "v": 0.0, "n": 0, "first": r["d"], "last": r["d"], "name": r.get("nm"), "face": r.get("f"), "days": {}})
        a["q"] += r["q"]
        a["v"] += r["v"]
        a["n"] += r["n"]
        a["first"] = min(a["first"], r["d"])
        a["last"] = max(a["last"], r["d"])
        dd = a["days"].setdefault(r["d"], {"q": 0.0, "v": 0.0, "n": 0})
        dd["q"] += r["q"]
        dd["v"] += r["v"]
        dd["n"] += r["n"]
    return out


def pv_coupon_text(live, desc):
    """(текст, флоатер?) — формулу плавающего купона ISS не отдаёт: показываем тип."""
    ct = (live or {}).get("ctype") or ""
    cp = (live or {}).get("cpn")
    kind = (desc or {}).get("kind") or ""
    if "плавающ" in ct:
        return "флоатер", True
    if cp and cp > 0:
        return ("%.2f" % cp).replace(".", ",") + " %", False
    if "дисконт" in kind.lower():
        return "дисконт", False
    if "структурн" in kind.lower() or "структурн" in ct.lower():
        return "структурная", False
    return "", False


def pv_build_row(secid, desc, agg, today_place, bm, today, rating, cum=None, fx=None):
    """Одна строка «простыни». today_place — строки marketdata площадки размещения, bm — marketdata рынка bonds."""
    face = desc.get("face") or desc.get("face0") or 1000.0
    cur = (desc.get("cur") or "SUR").replace("SUR", "RUB")
    a = agg or {}
    live = None
    if bm:
        live = max(bm, key=lambda x: x.get("today") or 0)
    size_pcs = desc.get("size") or (live or {}).get("size")
    placed_moex = max([x.get("placed") or 0 for x in bm or []] or [0])
    tp_val = sum(x.get("today") or 0 for x in today_place or [])
    tp_vol = sum(x.get("vol") or 0 for x in today_place or [])
    tp_n = sum(x.get("n") or 0 for x in today_place or [])
    base = cum if cum is not None else a               # cum — кумулятив с даты старта (бумага сейчас открыта на площадке размещения)
    trades_pcs = (base.get("q") or 0) + tp_vol
    placed_pcs, src = (placed_moex, "moex") if placed_moex > trades_pcs else ((trades_pcs, "trades") if trades_pcs else (0.0, ""))
    sec_today = sum(x.get("today") or 0 for x in bm or [])
    pl_days = sorted(a.get("days") or {})
    start = desc.get("issued") or desc.get("start") or a.get("first") or ""
    try:
        days_on = max(0, (datetime.strptime(today, "%Y-%m-%d") - datetime.strptime(start, "%Y-%m-%d")).days) if start else None
    except ValueError:
        days_on = None
    if tp_val > 0 or (tp_n > 0) or (cum is not None and trades_pcs):
        status = "placing"
    elif trades_pcs:
        status = "placed"
    else:
        status = "upcoming"
    cpn, flt = pv_coupon_text(live, desc)
    return {"secid": secid, "isin": desc.get("isin") or secid, "name": desc.get("name") or a.get("name") or secid, "full": desc.get("full") or "",
            "rating": rating, "coupon": cpn, "floating": flt, "mat": desc.get("mat") or (live or {}).get("mat") or "",
            "offer": (live or {}).get("offer") or "", "start": start, "first_place": (base.get("first") or (pl_days[0] if pl_days else "")) or (today if tp_val > 0 else ""), "days_on": days_on,
            "face": face, "size_pcs": size_pcs, "size_rub": round(cur_to_rub(size_pcs * face, cur, fx), 2) if size_pcs else None,
            "placed_pcs": placed_pcs, "placed_rub": round(cur_to_rub(placed_pcs * face, cur, fx), 2) if placed_pcs else None, "placed_src": src,
            "placed_pct": round(100.0 * placed_pcs / size_pcs, 1) if size_pcs and placed_pcs else None,
            "place_value": round((base.get("v") or 0) + tp_val, 2), "place_trades": (base.get("n") or 0) + tp_n,
            "today_place": round(tp_val, 2), "today_sec": round(sec_today, 2), "today": round(tp_val + sec_today, 2),
            "today_trades": tp_n + sum(x.get("n") or 0 for x in bm or []),
            "price": (live or {}).get("wap") or (live or {}).get("last"), "yield": (live or {}).get("yield"),
            "status": status, "cur": cur}


def pv_upcoming(cal, known_isins, today):
    """Строки календаря Мосбиржи, которых ещё нет среди размещающихся (начало размещения сегодня или позже)."""
    out = []
    for r in cal:
        if r.get("start", "") < today or (r.get("isin") and r["isin"] in known_isins):
            continue
        out.append({"secid": r.get("isin") or "", "isin": r.get("isin") or "", "name": r.get("short") or r.get("issuer") or "",
                    "full": r.get("desc") or "", "rating": r.get("rating"), "coupon": "", "floating": False, "mat": "", "offer": "",
                    "start": r["start"], "first_place": "", "days_on": None, "face": None, "size_pcs": None, "size_rub": None, "placed_pcs": 0,
                    "placed_rub": None, "placed_src": "", "placed_pct": None, "place_value": 0, "place_trades": 0, "today_place": 0,
                    "today_sec": 0, "today": 0, "today_trades": 0, "price": None, "yield": None, "status": "upcoming", "cur": "RUB",
                    "book": r.get("book") or "", "end": r.get("end") or ""})
    return out


def _pv_rating(isin, name):
    try:
        r = best_rating(isin, name)
        return r
    except Exception:  # noqa: BLE001
        try:
            return rating_for(name)
        except Exception:  # noqa: BLE001
            return None


def pv_calendar_fallback(res=None, today=None):
    """Резервный календарь, когда investmint недоступен: выпуски с площадок размещения Мосбиржи (данные ISS из сводки объёмов),
    у которых дата размещения сегодня или позже, в формате строк календаря. Заранее объявленные, но ещё не заведённые на
    площадку выпуски здесь не видны. res — результат primary_volumes_payload (по умолчанию берётся готовый/запускается в фоне)."""
    try:
        res = res if res is not None else primary_volumes_payload()
    except Exception:  # noqa: BLE001
        return []
    today = today or date.today().isoformat()
    out = []
    for r in (res or {}).get("rows") or []:
        st = r.get("start") or ""
        if st < today or not r.get("isin") or r.get("book"):      # book есть только у строк из календаря investmint
            continue
        out.append({"issuer": r.get("full") or r.get("name") or "", "short": r.get("name") or "", "desc": "", "isin": r["isin"],
                    "start": st, "end": "", "book": "", "status": "Площадка размещения Мосбиржи", "link": ""})
    out.sort(key=lambda x: x["start"])
    return out


def pv_calendar_bg(out):
    """Календарь investmint в фоновом потоке: результат кладём в out (cal/err), пока основной конвейер грузит MOEX."""
    t0 = time.time()
    try:
        out["cal"] = primary_rows() or []
    except Exception as ex:  # noqa: BLE001
        out["err"] = "календарь заранее объявленных размещений недоступен (%s); показаны выпуски с площадок размещения Мосбиржи" % str(ex)[:100]
    out["t"] = time.time() - t0


def pv_bonds_batch():
    """Весь рынок bonds одним запросом (~3,5 тыс. бумаг, ≈1 МБ): {secid: [marketdata-строки по площадкам]}."""
    j = pv_json(PV_ISS + "engines/stock/markets/bonds/securities.json?iss.meta=off&iss.only=securities,marketdata"
                "&securities.columns=%s&marketdata.columns=%s" % (_PV_LS, _PV_LM), 60)
    return pv_live_parse(j)


def pv_compute():
    errs, tm = [], {}
    t0 = time.time()

    def lap(name):
        nonlocal t0
        t1 = time.time()
        tm[name] = round(t1 - t0, 2)
        t0 = t1
    cal_box = {}
    cal_th = threading.Thread(target=pv_calendar_bg, args=(cal_box,), daemon=True)
    cal_th.start()
    now = pv_msk_now()
    today = now.date().isoformat()
    cut = _day_add(today, -PV_DAYS)
    _pv["phase"] = "История площадки размещения"
    dates = [_day_add(today, -i) for i in range(1, PV_DAYS + 1)]
    dates = [d for d in dates if datetime.strptime(d, "%Y-%m-%d").weekday() < 5]
    byday = pv_days_cached(dates, errs)
    day_rows = [r for d in sorted(byday) for r in byday[d]] + [r for r in pv_other_boards(cut, _day_add(today, -1), errs) if (r.get("d") or "") < today]
    agg = pv_aggregate(day_rows)
    lap("history")
    descs = {}

    def d1(s):
        try:
            return s, pv_desc(s)
        except Exception as ex:  # noqa: BLE001
            return s, str(ex)[:100]

    def load_descs(secs, sink):
        for s, v in pool_map(d1, sorted(secs), workers=8):
            sink[s] = v
    pre = set(agg)                                      # описания бумаг с историей размещения грузим параллельно «сегодняшним» запросам
    pre_got = {}
    pre_th = threading.Thread(target=load_descs, args=(pre, pre_got), daemon=True)
    pre_th.start()
    _pv["phase"] = "Обороты сегодня"
    live = {}
    for mk, b in [("ndm", x) for x in PV_PLACE_NDM] + [("bonds", x) for x in PV_PLACE_BONDS]:
        try:
            for sid, ms in pv_live_board(mk, b).items():
                live.setdefault(sid, []).extend(ms)
        except Exception as ex:  # noqa: BLE001
            errs.append("сегодня %s: %s" % (b, str(ex)[:100]))
    bonds_all = None
    try:
        bonds_all = pv_bonds_batch()
    except Exception as ex:  # noqa: BLE001
        errs.append("рынок bonds: %s" % str(ex)[:100])
    lap("live")
    _pv["phase"] = "Календарь размещений"
    cal_th.join(60)
    lap("calendar_wait")
    tm["calendar"] = round(cal_box.get("t") or 0, 2)
    cal = cal_box.get("cal") or []
    if cal_box.get("err"):
        errs.append(cal_box["err"])
    elif "cal" not in cal_box:
        errs.append("календарь размещений investmint: не ответил вовремя; показаны выпуски с площадок размещения Мосбиржи")
    elif not cal:
        errs.append("календарь размещений investmint: 0 строк — возможно, изменилась разметка сайта; показаны выпуски с площадок размещения Мосбиржи")
    cal_isin = {r["isin"]: r for r in cal if r.get("isin")}
    cand = set(agg) | set(live)                         # всё, что сейчас открыто на площадке размещения, — независимо от даты старта
    for sid, ms in live.items():
        if any((m.get("today") or 0) > 0 or (m.get("n") or 0) > 0 or (m.get("settle") or "") >= cut for m in ms):
            cand.add(sid)
    cand |= set(cal_isin)
    _pv["phase"] = "Описания выпусков (%d)" % len(cand)
    pre_th.join()
    got = dict(pre_got)
    load_descs(cand - set(pre_got), got)
    for s, v in got.items():
        if isinstance(v, dict):
            descs[s] = v
        else:
            errs.append("описание %s: %s" % (s, v))
    lap("desc")
    old_cut = _day_add(today, -PV_ACTIVE_MAX_DAYS)

    def _alive(s):
        st0 = descs[s].get("issued") or descs[s].get("start") or ""
        return st0 >= old_cut or s in agg or any((m.get("today") or 0) > 0 or (m.get("n") or 0) > 0 for m in live[s])
    # открыты на площадке размещения сейчас: затянувшиеся размещения не теряем, но многолетние «висяки»
    # (региональные выпуски, годами числящиеся на PSAU без сделок) берём, только если по ним были сделки за PV_DAYS дней
    active = {s for s in live if s in descs and _alive(s)}
    new = [s for s, d in descs.items() if s in active or (d.get("issued") or d.get("start") or "") >= cut]
    _pv["phase"] = "Размещено с начала (%d)" % len(active)
    cums = {}

    def c1(s):
        d = descs[s]
        frm = d.get("issued") or d.get("start") or cut
        mks = sorted({"ndm" if m["b"] in PV_PLACE_NDM else "bonds" for m in live[s] if m["b"] in PV_PLACE}) or ["ndm"]
        try:
            return s, pv_cum(s, frm, today, mks, errs)
        except Exception as ex:  # noqa: BLE001
            errs.append("кумулятив %s: %s" % (s, str(ex)[:100]))
            return s, None
    for s, v in pool_map(c1, sorted(active), workers=8):
        if v is not None:
            cums[s] = v
    lap("cum")
    _pv["phase"] = "Вторичные торги (%d)" % len(new)
    bms = {}
    if bonds_all is not None:
        for s in new:
            bms[s] = bonds_all.get(s) or []           # нет в рынке bonds — торгов там ещё нет (как пустой ответ по бумаге)
    else:
        def b1(s):
            try:
                return s, pv_live_secid(s)
            except Exception as ex:  # noqa: BLE001
                return s, str(ex)[:100]
        for s, v in pool_map(b1, new, workers=8):
            if isinstance(v, list):
                bms[s] = v
            else:
                errs.append("торги %s: %s" % (s, v))
    lap("secondary")
    fx = {"RUB": 1.0}
    for s in new:
        c = ((descs[s] or {}).get("cur") or "SUR").replace("SUR", "RUB").upper()
        if c not in fx:
            try:
                fx[c] = tax_cbr_rate(c, today) or 1.0
            except Exception:  # noqa: BLE001
                fx[c] = 1.0
    rows = []
    for s in new:
        d = descs[s]
        tp = [m for m in live.get(s, []) if m["b"] in PV_PLACE]
        rt = _pv_rating(d.get("isin") or s, pv_issuer_name(d.get("full") or d.get("name")))
        row = pv_build_row(s, d, agg.get(s), tp, bms.get(s), today, rt, cums.get(s), fx=fx)
        if row["status"] == "upcoming" and (row["start"] or "") < today:
            continue                                    # открыт на площадке, но сделок не было и даты размещения в будущем нет
        rows.append(row)
    known = {r["isin"] for r in rows} | {r["secid"] for r in rows}
    for r in pv_upcoming(cal, known, today):
        r["rating"] = r["rating"] if r.get("rating") else None
        rows.append(r)
    rows.sort(key=lambda r: r.get("start") or "", reverse=True)
    rows.sort(key=lambda r: {"placing": 0, "upcoming": 1}.get(r["status"], 2))
    return {"rows": rows, "today": today, "window": PV_DAYS, "errors": errs[:10], "updated": time.time(), "timing": tm,
            "totals": {"placing": sum(1 for r in rows if r["status"] == "placing"), "today_rub": round(sum(r["today"] for r in rows), 2),
                       "size_rub": round(sum(r["size_rub"] or 0 for r in rows), 2)}}


def _pv_run():
    try:
        res = pv_compute()
        with _pv_lock:
            _pv.update(res=res, t=time.time(), err=None)
    except Exception as e:  # noqa: BLE001
        _pv["err"] = str(e)[:200]
    finally:
        _pv.update(running=False, phase="")


def primary_volumes_payload(force=False):
    if not force:                                     # готовый расчёт сервера (calc_worker), если он свежий
        with _pv_lock:
            need = _pv["res"] is None or time.time() - _pv["t"] >= pv_ttl()
        if need:
            got = ds_calc("pri_vol")
            if got and isinstance(got[0], dict) and isinstance(got[0].get("rows"), list) and time.time() - got[1] < pv_ttl():
                with _pv_lock:
                    _pv.update(res=got[0], t=got[1], err=None)
    with _pv_lock:
        fresh = _pv["res"] is not None and time.time() - _pv["t"] < pv_ttl() and not force
        if not fresh and not _pv["running"]:
            _pv["running"] = True
            threading.Thread(target=_pv_run, daemon=True).start()
        res = _pv["res"]
        running, phase, err = _pv["running"], _pv["phase"], _pv["err"]
    if res is None:
        return {"rows": [], "loading": running, "phase": phase, "error": None if running else (err or "нет данных"), "errors": []}
    return dict(res, loading=running, phase=phase, stale_error=err)


# ── по дням: история торгов выпуска по всем площадкам ──

def pv_days_merge(rows, live_rows, today):
    """Записи истории + сегодняшняя marketdata -> [{d, q, v, n, price, yield, place_v, sec_v, boards:[{b,label,q,v,n}]}] по возрастанию даты."""
    days = {}
    for r in rows:
        d = days.setdefault(r["d"], {"d": r["d"], "q": 0.0, "v": 0.0, "n": 0, "place_v": 0.0, "sec_v": 0.0, "px": None, "y": None, "_pv": -1, "boards": {}})
        d["q"] += r["q"]
        d["v"] += r["v"]
        d["n"] += r["n"]
        if r["b"] in PV_PLACE:
            d["place_v"] += r["v"]
        else:
            d["sec_v"] += r["v"]
        b = d["boards"].setdefault(r["b"], {"b": r["b"], "label": PV_BOARD_NAMES.get(r["b"], r["b"]), "place": r["b"] in PV_PLACE, "q": 0.0, "v": 0.0, "n": 0})
        b["q"] += r["q"]
        b["v"] += r["v"]
        b["n"] += r["n"]
        px = r.get("w") or r.get("c")
        if px and r["v"] > d["_pv"]:
            d["_pv"], d["px"] = r["v"], px
            d["y"] = r.get("y")
        elif d["y"] is None and r.get("y"):
            d["y"] = r["y"]
    for m in live_rows or []:
        if not ((m.get("today") or 0) or (m.get("vol") or 0) or (m.get("n") or 0)):
            continue
        d = days.setdefault(today, {"d": today, "q": 0.0, "v": 0.0, "n": 0, "place_v": 0.0, "sec_v": 0.0, "px": None, "y": None, "_pv": -1, "boards": {}, "live": True})
        d["live"] = True
        d["q"] += m.get("vol") or 0
        d["v"] += m.get("today") or 0
        d["n"] += m.get("n") or 0
        if m["b"] in PV_PLACE:
            d["place_v"] += m.get("today") or 0
        else:
            d["sec_v"] += m.get("today") or 0
        b = d["boards"].setdefault(m["b"], {"b": m["b"], "label": PV_BOARD_NAMES.get(m["b"], m["b"]), "place": m["b"] in PV_PLACE, "q": 0.0, "v": 0.0, "n": 0})
        b["q"] += m.get("vol") or 0
        b["v"] += m.get("today") or 0
        b["n"] += m.get("n") or 0
        px = m.get("wap") or m.get("last")
        if px and (m.get("today") or 0) > d["_pv"]:
            d["_pv"], d["px"] = m.get("today") or 0, px
            d["y"] = m.get("yield") or d["y"]
    out = []
    for k in sorted(days):
        d = days[k]
        d.pop("_pv", None)
        d["boards"] = sorted(d["boards"].values(), key=lambda x: -x["v"])
        for f in ("v", "place_v", "sec_v"):
            d[f] = round(d[f], 2)
        out.append(d)
    return out


def pv_secid_days(secid):
    """История торгов выпуска за всё время (обе рынка: ndm — размещение и РПС, bonds — вторичка) + сегодня."""
    k = "pvd:" + secid
    c = _pv_mem.get(k)
    if c and time.time() - c[0] < pv_ttl():
        return c[1]
    desc = pv_desc(secid)
    frm = desc.get("issued") or desc.get("start") or _day_add(pv_msk_now().date().isoformat(), -PV_DAYS)
    today = pv_msk_now().date().isoformat()
    errs, rows, live = [], [], []
    for mk in ("ndm", "bonds"):
        try:
            rows += pv_sec_hist(mk, secid, frm, today)
        except Exception as ex:  # noqa: BLE001
            errs.append("%s: %s" % (mk, str(ex)[:100]))
        try:
            j = pv_json(PV_ISS + "engines/stock/markets/%s/securities/%s.json?iss.meta=off&iss.only=securities,marketdata&securities.columns=%s"
                        "&marketdata.columns=%s" % (mk, secid, _PV_LS, _PV_LM), 25)
            live += pv_live_parse(j).get(secid) or []
        except Exception as ex:  # noqa: BLE001
            errs.append("сегодня %s: %s" % (mk, str(ex)[:100]))
    rows = [r for r in rows if r["d"] != today]            # сегодняшний день берём из marketdata (в истории он появляется вечером)
    days = pv_days_merge(rows, live, today)
    face = desc.get("face") or desc.get("face0") or 1000.0
    res = {"secid": secid, "name": desc.get("name"), "face": face, "size_pcs": desc.get("size"), "days": days, "errors": errs, "today": today,
           "total": {"q": sum(d["q"] for d in days), "v": round(sum(d["v"] for d in days), 2), "n": sum(d["n"] for d in days),
                     "place_v": round(sum(d["place_v"] for d in days), 2)}}
    if not errs:
        _pv_mem[k] = (time.time(), res)
    return res


def _api_primary_vol(cfg, acc, q, force):
    return primary_volumes_payload(force)


def _api_primary_days(cfg, acc, q, force):
    secid = (q.get("secid") or "").strip().upper()
    if not re.match(r"^[A-Z0-9]{4,20}$", secid):
        raise ApiError("Неверный код выпуска.", 400)
    return pv_secid_days(secid)


API_GET["/api/primary/volumes"] = _api_primary_vol
API_GET["/api/primary/days"] = _api_primary_days
# ═══════════════════ ссылки на документы выпуска (без обращения к сети) ═══════════════════


def bond_doc_links(isin, secid=None, inn=None):
    """Ссылки на раскрытие информации по выпуску. e-disclosure.ru закрыт для ботов, поэтому строим только ссылку
    на поиск по ИНН эмитента (без ИНН — по ISIN); страница выпуска на Мосбирже открывается по коду бумаги."""
    isin = (isin or "").strip().upper()
    secid = (secid or isin or "").strip().upper()
    inn = re.sub(r"\D", "", str(inn or ""))
    inn = inn if len(inn) in (10, 12) else ""
    q = inn or isin
    return {"inn": inn or None,
            # СКРИН открывает страницу раскрытия эмитента прямо по ИНН; поиск e-disclosure по ссылке не заполняется (страница на JS)
            "skrin": "https://disclosure.skrin.ru/disclosure/" + inn if inn else None,
            "edisclosure": "https://www.e-disclosure.ru/poisk-po-kompaniyam?query=" + urllib.parse.quote(q) if q else None,
            "moex": "https://www.moex.com/ru/issue.aspx?code=" + urllib.parse.quote(secid) if secid else None}
# ═══════════════════ карточка облигации: описание, история, денежный поток, аналоги ═══════════════════

_bc_univ = {"t": 0, "rows": []}
_bc_lock = threading.Lock()
BC_DESC = ("ISSUENAME", "ISSUEDATE", "MATDATE", "ISSUESIZE", "FACEVALUE", "INITIALFACEVALUE", "COUPONFREQUENCY",
           "COUPONPERCENT", "COUPONVALUE", "COUPONDATE", "BOND_TYPE", "BOND_SUBTYPE", "FACEVALUE_TYPE", "LISTLEVEL",
           "ISQUALIFIEDINVESTORS", "ISSUESIZEPLACED", "HASDEFAULT", "HASTECHNICALDEFAULT", "REGNUMBER", "TYPENAME", "EMITTER_ID")


def _bc_json(url, timeout=25):
    return json.loads(http_text(url, timeout=timeout))


def _bc_desc(isin):
    j = _bc_json("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description" % isin)
    d = {r[0]: r[2] for r in j["description"]["data"]}
    out = {k: d[k] for k in BC_DESC if d.get(k) not in (None, "")}
    eid = d.get("EMITTER_ID")
    if eid:
        try:
            e = _bc_json("https://iss.moex.com/iss/emitters/%s.json?iss.meta=off&iss.only=emitter" % eid, timeout=15)
            row = dict(zip(e["emitter"]["columns"], (e["emitter"]["data"] or [[]])[0]))
            out["EMITTER"] = row.get("TITLE") or row.get("title")
            out["EMITTER_INN"] = row.get("INN") or row.get("inn")
        except Exception:  # noqa: BLE001
            pass
    return out


def _bc_history(secid):
    key = "bondhist_v1_" + secid
    hit = store().get(key, ttl=6 * 3600)
    if hit:
        return hit
    frm = (date.today() - timedelta(days=370)).isoformat()
    rows, start = [], 0
    while start < 1500:
        j = _bc_json("https://iss.moex.com/iss/history/engines/stock/markets/bonds/securities/%s.json?iss.meta=off"
                     "&history.columns=BOARDID,TRADEDATE,CLOSE,LEGALCLOSEPRICE,WAPRICE,YIELDCLOSE,YIELDATWAP,VALUE"
                     "&from=%s&start=%d" % (secid, frm, start))
        part = _iss_table(j, "history")
        rows += part
        if len(part) < 100:
            break
        start += 100
    boards = defaultdict(int)
    for r in rows:
        boards[r["BOARDID"]] += 1
    main = next((b for b in ("TQCB", "TQOB") if boards.get(b)), max(boards, key=boards.get) if boards else None)
    out = {"d": [], "p": [], "y": [], "v": []}
    for r in sorted((r for r in rows if r["BOARDID"] == main), key=lambda r: r["TRADEDATE"]):
        p = r.get("LEGALCLOSEPRICE") or r.get("CLOSE") or r.get("WAPRICE")
        y = r.get("YIELDCLOSE") or r.get("YIELDATWAP")
        if p is None:
            continue
        out["d"].append(r["TRADEDATE"])
        out["p"].append(round(p, 3))
        out["y"].append(round(y, 2) if y else None)
        out["v"].append(round(r.get("VALUE") or 0))
    if out["d"]:
        store().put(key, out)
    return out


def _bc_norm_table(t):
    if isinstance(t, dict) and "columns" in t:
        return [dict(zip(t["columns"], r)) for r in t["data"]]
    return [x for x in (t or []) if isinstance(x, dict)]


def _bc_flows(isin):
    j = None
    fn = globals().get("moex_bondization")
    if callable(fn):
        try:
            j = fn(isin)
        except Exception:  # noqa: BLE001
            j = None
    if not isinstance(j, dict) or not any(k in j for k in ("coupons", "amort", "amortizations", "offers")):
        j = _bc_json("https://iss.moex.com/iss/securities/%s/bondization.json?iss.meta=off&limit=unlimited"
                     "&iss.only=coupons,amortizations,offers" % isin, timeout=30)
    today = date.today().isoformat()
    ev = []
    for c in _bc_norm_table(j.get("coupons")):
        d = c.get("coupondate")
        if d and d >= today:
            ev.append({"d": d, "t": "coupon", "amt": c.get("value_rub") if c.get("value_rub") is not None else c.get("value"),
                       "pct": c.get("valueprc")})
    # moex_bondization отдаёт график под ключом "amort" (ISS — "amortizations"); последняя строка графика — погашение
    am = [a for a in _bc_norm_table(j.get("amort") if j.get("amort") is not None else j.get("amortizations")) if a.get("amortdate")]
    last = max((a["amortdate"] for a in am), default=None)
    for a in am:
        d = a["amortdate"]
        if d >= today:
            ev.append({"d": d, "t": "redemption" if d == last else "amort",
                       "amt": a.get("value_rub") if a.get("value_rub") is not None else a.get("value"),
                       "pct": a.get("valueprc")})
    for o in _bc_norm_table(j.get("offers")):
        d = o.get("offerdate")
        if d and d >= today:
            ev.append({"d": d, "t": "offer", "amt": o.get("value"), "pct": o.get("price")})
    ev.sort(key=lambda e: e["d"])
    return ev


def _bc_mark_est(flows, isin, floating, face):
    """Купоны флоатера без объявленной ставки: подставляем прогноз (ключевая ставка + спред), помечаем est/base/spread."""
    if not floating or not face or not any(e["t"] == "coupon" and e.get("amt") is None for e in flows):
        return False
    bz = moex_bondization(isin)
    est = fl_estimates(bz, date.today().isoformat(), float(face)) if bz else {}
    done = False
    for e in flows:
        x = est.get(e["d"]) if e["t"] == "coupon" and e.get("amt") is None else None
        if x:
            e.update(amt=x["amt"], pct=x["rate"], est=True, base=round(x["base"], 2), spread=round(x["spread"], 2))
            done = True
    return done


def _bc_issuer_key(r):
    t = name_tokens(_bond_query(r.get("full") or r.get("name") or ""))
    return t


def _bc_universe():
    """screener_rows + рейтинг и данные каталога; кэш 10 минут."""
    if time.time() - _bc_univ["t"] < 600 and _bc_univ["rows"]:
        return _bc_univ["rows"]
    with _bc_lock:
        if time.time() - _bc_univ["t"] < 600 and _bc_univ["rows"]:
            return _bc_univ["rows"]
        src = screener_rows()
        out = []
        for r in src:
            e = dict(r)
            e["_isin"] = r.get("isin") or r["id"]
            e["_ci"] = tcat_info(e["_isin"])
            rt = best_rating(e["_isin"], (e["_ci"] or {}).get("name") or r.get("name") or "")
            e["_rt"] = rt
            e["_iss"] = _bc_issuer_key(r)
            out.append(e)
        _bc_univ.update(t=time.time(), rows=out)
        return out


def _bc_lite(e, base_y):
    rt, ci = e["_rt"], e["_ci"] or {}
    return {"isin": e["_isin"], "id": e["id"], "name": e["name"], "yield": e["yield"], "spread": e.get("spread"),
            "dur": e.get("dur"), "rating": rt["v"] if rt else None, "rating_approx": bool(rt and rt["approx"]),
            "sector": ci.get("sector"), "floating": bool(ci.get("floating")), "amort": bool(ci.get("amort")),
            "turn": e.get("turn"), "price": e.get("price"), "mat": e.get("mat"),
            "dy": round(e["yield"] - base_y, 2) if base_y is not None else None}


def _bc_cost(me, e, ri):
    """Расстояние между выпусками для подбора аналогов (меньше = ближе); None, если не аналог. ri: индекс рейтинга me или None."""
    if e["cur"] != "RUB" or not (0 < e["yield"] < 60) or not e.get("dur") or e["dur"] < 0.1:
        return None
    if e["kind"] != me["kind"]:
        return None
    if me["kind"] == "corp" and me["_iss"] and e["_iss"] and (e["_iss"] == me["_iss"]):
        return None
    ert = e["_rt"]
    d = 0.0
    if ri is not None:
        if not ert:
            return None
        n = abs(RATING_SCALE.index(ert["v"]) - ri)
        if n > 2:
            return None
        d += n * 1.0
    elif ert and me["kind"] == "corp":
        d += 0.5
    ci, eci = me["_ci"] or {}, e["_ci"] or {}
    sec, dur = ci.get("sector"), me.get("dur")
    if sec and eci.get("sector") and sec != eci["sector"]:
        d += 0.7
    if dur:
        rel = abs(e["dur"] - dur) / max(dur, e["dur"], 0.5)
        if rel > 0.6:
            return None
        d += rel * 3
    if bool(eci.get("floating")) != bool(ci.get("floating")):
        d += 1.5
    if bool(eci.get("amort")) != bool(ci.get("amort")):
        d += 0.5
    d -= min(1.0, len(str(int(e.get("turn") or 0))) / 9.0) * 0.6
    return d


def _bc_analogs(me, isin):
    """me: запись из _bc_universe (или None). Возвращает (список аналогов, относительная оценка)."""
    uni = _bc_universe()
    if not me:
        return [], None
    rt = me["_rt"]
    ri = RATING_SCALE.index(rt["v"]) if rt else None
    scored = []
    for e in uni:
        if e["_isin"] == isin:
            continue
        d = _bc_cost(me, e, ri)
        if d is not None:
            scored.append((d, e))
    scored.sort(key=lambda x: x[0])
    sps = sorted(e["spread"] for _, e in scored[:30] if e.get("spread") is not None)
    if len(sps) >= 5:      # отсекаем выбросы (дефолтные выпуски, линкеры) относительно медианы ближайших кандидатов
        m0 = sps[len(sps) // 2]
        scored = [x for x in scored if x[1].get("spread") is None or abs(x[1]["spread"] - m0) <= 8]
    top = [_bc_lite(e, me["yield"]) for _, e in scored[:12]]
    rel = None
    sp = [a["spread"] for a in top if a["spread"] is not None]
    if me.get("spread") is not None and len(sp) >= 3:
        sp.sort()
        med = sp[len(sp) // 2] if len(sp) % 2 else (sp[len(sp) // 2 - 1] + sp[len(sp) // 2]) / 2
        diff = round(me["spread"] - med, 2)
        c2 = lambda x: ("%.2f" % x).replace(".", ",")      # noqa: E731
        txt = ("Доходность в пределах разброса аналогов (спред к КБД %s п.п. против медианы %s п.п.)"
               % (c2(me["spread"]), c2(med))) if abs(diff) < 0.25 else \
            ("Облигация %s аналогов: спред к КБД на %s п.п. %s медианы по %d похожим выпускам" %
             ("дешевле" if diff > 0 else "дороже", c2(abs(diff)), "выше" if diff > 0 else "ниже", len(sp)))
        rel = {"median_spread": round(med, 2), "diff": diff, "n": len(sp), "text": txt}
    return top, rel


def _bc_issuer_curve(me):
    """Все торгуемые выпуски того же эмитента (по ключу названия): дюрация -> доходность, плюс КБД для ориентира."""
    key = me.get("_iss")
    pts = []
    if key and me["kind"] == "corp":
        for e in _bc_universe():
            if e["_iss"] == key and e["cur"] == "RUB" and e.get("dur") and e["yield"] > 0:
                rt = e["_rt"]
                pts.append({"isin": e["_isin"], "name": e["name"], "dur": e["dur"], "yield": e["yield"], "spread": e.get("spread"),
                            "rating": rt["v"] if rt else None, "turn": e.get("turn"), "me": e["_isin"] == me["_isin"],
                            "floating": bool((e["_ci"] or {}).get("floating"))})
    if len(pts) < 2:
        return None
    pts.sort(key=lambda p: p["dur"])
    lo, hi = max(0.0, pts[0]["dur"] - 0.3), pts[-1]["dur"] + 0.5
    kbd = []
    for i in range(13):
        x = lo + (hi - lo) * i / 12
        k = kbd_at(x)
        if k is not None:
            kbd.append([round(x, 2), round(k, 2)])
    return {"points": pts, "kbd": kbd}


def bond_card(isin):
    isin = (isin or "").strip().upper()
    errors = []
    card = {"isin": isin, "found": False, "errors": errors}
    if not re.fullmatch(r"[A-Z0-9]{6,14}", isin):
        errors.append("некорректный ISIN")
        return card
    me = None
    try:
        uni = _bc_universe()
        me = next((e for e in uni if e["_isin"] == isin or e["id"] == isin), None)
    except Exception as e:  # noqa: BLE001
        errors.append("рынок: %s" % str(e)[:120])
        uni = []
    if me:
        isin = me["_isin"]
        card["isin"] = isin
    secid = me["id"] if me else isin

    def run(fn):
        try:
            return fn(), None
        except Exception as e:  # noqa: BLE001
            return None, str(e)[:120]
    (desc, e1), (hist, e2), (flows, e3) = pool_map(
        run, [lambda: _bc_desc(isin), lambda: _bc_history(secid), lambda: _bc_flows(isin)], workers=3)
    for lab, er in (("описание", e1), ("история", e2), ("денежный поток", e3)):
        if er:
            errors.append("%s: %s" % (lab, er))
    ci = tcat_info(isin)
    card["catalog"] = ci
    card["desc"] = desc or {}
    card["history"] = hist or {"d": [], "p": [], "y": [], "v": []}
    card["flows"] = flows or []
    try:
        card["offers"] = [o for o in offers_of_isin(isin) if o["status"] != "cancelled"]
        for e in card["flows"]:
            if e["t"] == "offer":
                e["kind"] = offer_kind_on(card["offers"], e["d"])
    except Exception as e:  # noqa: BLE001
        card["offers"] = []
        errors.append("оферты: %s" % str(e)[:120])
    try:
        face = (desc or {}).get("FACEVALUE") or (me or {}).get("nominal")
        if _bc_mark_est(card["flows"], isin, bool((ci or {}).get("floating")), float(face) if face else 0.0):
            info = keyrate_forecast_info()
            card["keyrate"] = {"source": info["source"], "name": info["source_name"], "as_of": info["as_of"]}
    except Exception as e:  # noqa: BLE001
        errors.append("прогноз купонов: %s" % str(e)[:120])
    try:        # «КС + x %» для флоатера: из кэша спредов, иначе считаем по графику выплат (он уже в кэше после _bc_mark_est)
        if (ci or {}).get("floating"):
            fsp = fl_spread_cached([isin]).get(isin)
            if fsp is None:
                face2 = (desc or {}).get("FACEVALUE") or (me or {}).get("nominal")
                fsp = fl_spread_put(isin, (me or {}).get("full") or (desc or {}).get("ISSUENAME") or card.get("name"),
                                    moex_bondization(isin), float(face2) if face2 else None, (me or {}).get("kind"))
            card["fl_spread"] = fsp
            card["fl_label"] = fl_label(fsp, True)
    except Exception as e:  # noqa: BLE001
        errors.append("спред флоатера: %s" % str(e)[:120])
    try:
        rt = (me["_rt"] if me else None) or best_rating(isin, (desc or {}).get("ISSUENAME") or (ci or {}).get("name") or "")
    except Exception as e:  # noqa: BLE001
        rt = None
        errors.append("рейтинг: %s" % str(e)[:120])
    card["rating"] = rt
    if me:
        card["found"] = True
        card["market"] = {k: me.get(k) for k in ("id", "isin", "name", "full", "kind", "cur", "nominal", "price", "yield",
                                                 "dur", "coupon", "next", "mat", "offer", "level", "turn", "trades",
                                                 "zs", "spread", "size", "nkd")}
        k = kbd_at(me["dur"]) if me.get("dur") else None
        card["kbd"] = round(k, 2) if k is not None else None
        try:
            card["analogs"], card["rel"] = _bc_analogs(me, isin)
        except Exception as e:  # noqa: BLE001
            card["analogs"], card["rel"] = [], None
            errors.append("аналоги: %s" % str(e)[:120])
        try:
            card["issuer_curve"] = _bc_issuer_curve(me)
        except Exception as e:  # noqa: BLE001
            card["issuer_curve"] = None
            errors.append("кривая эмитента: %s" % str(e)[:120])
    else:
        card["market"] = None
        card["analogs"], card["rel"] = [], None
        card["issuer_curve"] = None
        if not errors:
            errors.append("нет торгов на основных режимах Мосбиржи — показаны только справочные данные")
    try:
        card["disclosure"] = disclosure_for_bond(isin, desc=desc)
    except Exception as e:  # noqa: BLE001
        card["disclosure"] = None
        errors.append("раскрытие: %s" % str(e)[:120])
    card["docs"] = bond_doc_links(isin, (me or {}).get("id") or isin, (desc or {}).get("EMITTER_INN"))
    card["name"] = (me or {}).get("full") or (desc or {}).get("ISSUENAME") or (ci or {}).get("name") or isin
    card["short"] = (me or {}).get("name") or (ci or {}).get("name") or isin
    return card
# ═══════════════════════════════ прогноз ключевой ставки ═══════════════════════════════
# Нужен для флоатеров: будущие купоны = прогноз ключевой ставки + спред эмитента (см. bond_flows в 08a_bondcalc.py).
# Источники по убыванию приоритета (первый сработавший):
#   cbr    — «Среднесрочный прогноз Банка России» (PDF на cbr.ru, строка «Ключевая ставка, в среднем за год»; диапазон -> середина);
#   survey — макроэкономический опрос Банка России (HTML-таблица, медиана «Ключевая ставка ... в среднем за год»);
#   market — форвардные ставки КБД Мосбиржи (приближение, см. _kr_market_path);
#   flat   — текущая ключевая ставка без изменений.

KR_TTL, KR_ERR_TTL = 24 * 3600, 3600
KR_MODES = ("cbr", "survey", "market", "flat")
KR_NAMES = {"cbr": "Среднесрочный прогноз Банка России", "survey": "Макроопрос аналитиков (Банк России)",
            "market": "Рыночные ожидания (форварды КБД)", "flat": "Ключевая ставка без изменений"}
KR_HORIZON_M = 48
_kr_mem = {}
_kr_lock = threading.Lock()


# ── минимальный разбор PDF (stdlib): Flate-потоки, ToUnicode, операторы Tf/Tm/Td/TJ ──

def _pdf_inflate(body):
    head, _, rest = body.partition(b"stream")
    if not rest:
        return b""
    rest = rest[1:] if rest[:1] == b"\n" else (rest[2:] if rest[:2] == b"\r\n" else rest[1:] if rest[:1] == b"\r" else rest)
    rest = rest[:rest.rfind(b"endstream")] if b"endstream" in rest else rest
    if b"FlateDecode" in head:
        return zlib.decompressobj().decompress(rest)
    return rest


def _pdf_objects(d):
    objs = {}
    for m in re.finditer(rb"(?<![0-9])(\d+) 0 obj(.*?)endobj", d, re.S):
        objs[int(m.group(1))] = m.group(2)
    for body in list(objs.values()):
        head = body.partition(b"stream")[0]
        if b"/ObjStm" not in head:
            continue
        n = int(re.search(rb"/N\s+(\d+)", head).group(1))
        first = int(re.search(rb"/First\s+(\d+)", head).group(1))
        data = _pdf_inflate(body)
        nums = [int(x) for x in re.findall(rb"\d+", data[:first])]
        pairs = list(zip(nums[0:2 * n:2], nums[1:2 * n:2]))
        for i, (num, off) in enumerate(pairs):
            end = pairs[i + 1][1] if i + 1 < len(pairs) else len(data) - first
            objs.setdefault(num, data[first + off:first + end])
    return objs


def _pdf_cmap(data):
    s = data.decode("latin-1")
    m = re.search(r"begincodespacerange\s*<([0-9A-Fa-f]+)>", s)
    width = len(m.group(1)) // 2 if m else 1
    mp = {}

    def u(h):
        return bytes.fromhex(h).decode("utf-16-be", "replace")
    for blk in re.findall(r"beginbfchar(.*?)endbfchar", s, re.S):
        for a, b in re.findall(r"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", blk):
            mp[int(a, 16)] = u(b)
    for blk in re.findall(r"beginbfrange(.*?)endbfrange", s, re.S):
        for a, b, c in re.findall(r"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*(<[0-9A-Fa-f]+>|\[[^\]]*\])", blk):
            lo, hi = int(a, 16), int(b, 16)
            if c.startswith("["):
                for i, h in enumerate(re.findall(r"<([0-9A-Fa-f]+)>", c)):
                    mp[lo + i] = u(h)
            else:
                base = int(c[1:-1], 16)
                nb = len(c) - 2
                for i in range(hi - lo + 1):
                    mp[lo + i] = u(("%0" + str(nb) + "x") % (base + i))
    return width, mp


def _pdf_tokens(s):
    i, n = 0, len(s)
    out = []
    ws = b" \t\r\n\x00\x0c"
    delim = b"()<>[]/%"
    while i < n:
        c = s[i:i + 1]
        if c in ws:
            i += 1
        elif c == b"%":
            while i < n and s[i:i + 1] not in b"\r\n":
                i += 1
        elif c == b"(":
            depth, j, buf = 1, i + 1, bytearray()
            while j < n and depth:
                ch = s[j:j + 1]
                if ch == b"\\":
                    nx = s[j + 1:j + 2]
                    if nx in b"01234567" and nx:
                        k = j + 1
                        while k < j + 4 and s[k:k + 1] and s[k:k + 1] in b"01234567":
                            k += 1
                        buf.append(int(s[j + 1:k], 8) & 255)
                        j = k
                        continue
                    buf += {b"n": b"\n", b"r": b"\r", b"t": b"\t", b"b": b"\b", b"f": b"\x0c"}.get(nx, nx)
                    j += 2
                    continue
                if ch == b"(":
                    depth += 1
                elif ch == b")":
                    depth -= 1
                    if not depth:
                        j += 1
                        break
                buf += ch
                j += 1
            out.append(("s", bytes(buf)))
            i = j
        elif c == b"<":
            if s[i + 1:i + 2] == b"<":
                out.append(("op", "<<"))
                i += 2
            else:
                j = s.index(b">", i)
                h = re.sub(rb"\s", b"", s[i + 1:j])
                if len(h) % 2:
                    h += b"0"
                out.append(("s", bytes.fromhex(h.decode())))
                i = j + 1
        elif c == b">":
            out.append(("op", ">>"))
            i += 2 if s[i + 1:i + 2] == b">" else 1
        elif c in b"[]":
            out.append(("op", c.decode()))
            i += 1
        elif c == b"/":
            j = i + 1
            while j < n and s[j:j + 1] not in ws and s[j:j + 1] not in delim:
                j += 1
            out.append(("n", s[i + 1:j].decode("latin-1")))
            i = j
        else:
            j = i
            while j < n and s[j:j + 1] not in ws and s[j:j + 1] not in delim:
                j += 1
            t = s[i:j].decode("latin-1")
            try:
                out.append(("num", float(t)))
            except ValueError:
                out.append(("op", t))
            i = max(j, i + 1)
    return out


def pdf_text_fragments(d):
    """[(x, y, size, text)] из PDF (stdlib: Flate + ToUnicode). Для простых однотипных документов ЦБ."""
    objs = _pdf_objects(d)
    fonts = {}
    for body in objs.values():
        head = body.partition(b"stream")[0]
        for m in re.finditer(rb"/Font\s*(?:<<(.*?)>>|(\d+)\s+0\s+R)", head, re.S):
            blk = m.group(1) if m.group(1) is not None else objs.get(int(m.group(2)), b"")
            for nm, num in re.findall(rb"/([A-Za-z0-9_.+-]+)\s+(\d+)\s+0\s+R", blk):
                fb = objs.get(int(num), b"")
                tu = re.search(rb"/ToUnicode\s+(\d+)\s+0\s+R", fb)
                if tu and nm.decode() not in fonts:
                    fonts[nm.decode()] = _pdf_cmap(_pdf_inflate(objs.get(int(tu.group(1)), b"")))
    frags = []
    for body in objs.values():
        head = body.partition(b"stream")[0]
        if b"/Length" not in head or b"/Type" in head and (b"/XObject" in head or b"/ObjStm" in head or b"/XRef" in head):
            continue
        try:
            data = _pdf_inflate(body)
        except Exception:
            continue
        if b"BT" not in data or b" Tf" not in data:
            continue
        stack, font, size = [], None, 10.0
        lm = [0.0, 0.0]
        for kind, v in _pdf_tokens(data):
            if kind != "op" or v in ("[", "]", "<<", ">>"):
                stack.append((kind, v))
                continue
            args = stack
            stack = []
            if v == "Tf":
                nm = [a for a in args if a[0] == "n"]
                nu = [a[1] for a in args if a[0] == "num"]
                font = nm[-1][1] if nm else font
                size = nu[-1] if nu else size
            elif v == "Tm":
                nu = [a[1] for a in args if a[0] == "num"]
                if len(nu) >= 6:
                    lm = [nu[4], nu[5]]
            elif v in ("Td", "TD"):
                nu = [a[1] for a in args if a[0] == "num"]
                if len(nu) >= 2:
                    lm = [lm[0] + nu[-2], lm[1] + nu[-1]]
            elif v in ("TJ", "Tj", "'", '"'):
                width, mp = fonts.get(font, (1, None))
                txt = ""
                for k, a in args:
                    if k != "s":
                        continue
                    if mp is None:
                        txt += a.decode("cp1252", "replace")
                    else:
                        w = width if len(a) % width == 0 else 1
                        for p in range(0, len(a), w):
                            txt += mp.get(int.from_bytes(a[p:p + w], "big"), "")
                if txt:
                    frags.append((lm[0], lm[1], size, txt))
    return frags


# ── источник 1: среднесрочный прогноз Банка России (PDF) ──

KR_CBR_PAGE = "https://www.cbr.ru/dkp/mp_dec/decision_key_rate/"


def _kr_num(s):
    return float(s.replace(",", "."))


def _kr_cells(txt):
    """'19,2 14,6 12,5–13,5 9,0–10,0' -> [(low, high)]. Одиночное значение с двумя знаками (14,61) — сноска, отбрасываем её."""
    toks = re.findall(r"(\d+(?:,\d+)?)(?:\s*[–-]\s*(\d+(?:,\d+)?))?", txt)
    cells = []
    for a, b in toks:
        if not b and re.fullmatch(r"\d+,\d\d", a):
            a = a[:-1]
        cells.append((_kr_num(a), _kr_num(b or a)))
    return cells


def _kr_parse_pdf(data, label="Ключевая ставка", tail=r"годовых(.*)$", need=""):
    """Строка таблицы основных параметров прогноза -> {год: (low, high)}.
    По умолчанию «Ключевая ставка, в среднем за год»; для инфляции — label «Инфляция», need «декабрь», tail r"года(.*)$"."""
    fr = pdf_text_fragments(data)
    big = [f for f in fr if f[2] >= 8]          # мелкий шрифт — сноски и надстрочные индексы

    def row(y, tol=2.5):
        rs = sorted((f for f in big if abs(f[1] - y) <= tol), key=lambda f: f[0])
        return "".join(f[3] for f in rs)
    lab = [f for f in big if f[3].startswith(label) and need in row(f[1])]
    first = [f for f in big if f[3].startswith("Инфляция")]
    if not lab or not first:
        raise ValueError("нет строки таблицы")
    y0 = max(f[1] for f in first)
    m = re.search(tail, row(lab[0][1]))
    cells = _kr_cells(m.group(1) if m else "")
    hdr = "".join(f[3] for f in sorted((f for f in big if y0 + 3 < f[1] < y0 + 45 and f[0] > 150), key=lambda f: (f[0], -f[1])))
    years = sorted({int(y) for y in re.findall(r"20\d\d", hdr)})
    if len(years) != len(cells) or not years:
        raise ValueError("не сошлись годы (%d) и значения (%d)" % (len(years), len(cells)))
    return {y: c for y, c in zip(years, cells)}


def _kr_cbr():
    s = http_text(KR_CBR_PAGE, 30)
    links = re.findall(r'href="(/Content/Document/File/\d+/forecast_(\d\d)(\d\d)(\d\d)\.pdf)"', s)
    if not links:
        raise ValueError("нет ссылки на прогноз")
    path, yy, mm, dd = max(links, key=lambda x: x[1:])
    as_of = "20%s-%s-%s" % (yy, mm, dd)
    st = store()
    ck = "kr_pdf:" + path
    pt = st.get(ck)
    if pt is None:
        yr = _kr_parse_pdf(http_bytes("https://www.cbr.ru" + path, 40))
        pt = {str(k): list(v) for k, v in yr.items()}
        st.put(ck, pt)                     # PDF конкретного заседания не меняется
    years = {int(k): tuple(v) for k, v in pt.items()}
    # в таблице первым идёт последний фактический год: он не прогноз
    return {"as_of": as_of, "url": "https://www.cbr.ru" + path, "years": years}


def inflation_forecast():
    """Прогноз инфляции (декабрь к декабрю) из того же среднесрочного прогноза Банка России.
    {source: 'cbr'|'none', as_of, url, yearly:[{year, low, high, mid}]} — только текущий и будущие годы.
    Кэш 24 часа; при ошибке — source 'none' и пустой yearly (вызывающий код берёт свою оценку, например 4%)."""
    st = store()
    raw = st.get("infl_src", ttl=KR_TTL)
    if raw is None:
        try:
            s = http_text(KR_CBR_PAGE, 30)
            links = re.findall(r'href="(/Content/Document/File/\d+/forecast_(\d\d)(\d\d)(\d\d)\.pdf)"', s)
            if not links:
                raise ValueError("нет ссылки на прогноз")
            path, yy, mm, dd = max(links, key=lambda x: x[1:])
            yr = _kr_parse_pdf(http_bytes("https://www.cbr.ru" + path, 40), "Инфляция", r"года(.*)$", "декабрь")
            raw = {"source": "cbr", "as_of": "20%s-%s-%s" % (yy, mm, dd), "url": "https://www.cbr.ru" + path,
                   "years": {str(k): list(v) for k, v in yr.items()}}
            st.put("infl_src", raw)
        except Exception as e:  # noqa: BLE001
            return {"source": "none", "as_of": "", "url": "", "yearly": [], "error": str(e)[:140]}
    y0 = date.today().year
    yearly = [{"year": int(k), "low": v[0], "high": v[1], "mid": round((v[0] + v[1]) / 2.0, 2)}
              for k, v in sorted(raw["years"].items()) if int(k) >= y0]
    return {"source": raw["source"], "as_of": raw["as_of"], "url": raw["url"], "yearly": yearly}


# ── источник 2: макроопрос Банка России (HTML-таблица) ──

KR_SURVEY_PAGE = "https://cbr.ru/statistics/ddkp/mo_br/"
_MONTHS_RU = ["январ", "феврал", "март", "апрел", "ма", "июн", "июл", "август", "сентябр", "октябр", "ноябр", "декабр"]


def _kr_survey():
    s = http_text(KR_SURVEY_PAGE, 30)
    i = s.find("Ключевая ставка")
    j = s.rfind("<table", 0, i)
    k = s.find("</table>", i)
    if i < 0 or j < 0 or k < 0:
        raise ValueError("нет таблицы опроса")
    rows = []
    for r in re.findall(r"<tr.*?</tr>", s[j:k], re.S):
        rows.append([re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", c)).replace("&nbsp;", " ").strip()
                     for c in re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", r, re.S)])
    hdr = next(r for r in rows if sum(bool(re.match(r"20\d\d", c)) for c in r) >= 3)
    kr = next(r for r in rows if r and r[0].startswith("Ключевая ставка"))
    years = {}
    for h, v in zip(hdr, kr):
        m, y = re.match(r"(20\d\d)", h), re.match(r"\s*(\d+,\d+|\d+)", v)
        if m and y and "факт" not in h:
            years[int(m.group(1))] = (_kr_num(y.group(1)),) * 2        # медиана; в скобках — прошлый опрос
    if not years:
        raise ValueError("нет прогнозных значений")
    plain = re.sub(r"<[^>]+>", " ", s)
    m = re.search(r"Результаты опроса:\s*([А-Яа-я]+)\s+(20\d\d)", plain)
    as_of = ""
    if m:
        mo = next((n + 1 for n, p in enumerate(_MONTHS_RU) if m.group(1).lower().startswith(p)), 0)
        as_of = "%s-%02d" % (m.group(2), mo) if mo else m.group(2)
    return {"as_of": as_of, "url": KR_SURVEY_PAGE, "years": years}


# ── фактическая ключевая ставка ──

def key_rate_on(series, d):
    """Ключевая ставка, действовавшая на дату d (ISO), по ряду [[дата, %]]; None, если ряд не покрывает дату."""
    if not series or d < series[0][0]:
        return None
    i = bisect.bisect_right([x[0] for x in series], d) - 1
    return series[i][1]


def _kr_current():
    ser = key_rate_series()
    if not ser:
        raise ValueError("нет ключевой ставки")
    return ser, ser[-1][1]


# ── построение месячного пути ──

def _kr_days(a, b):
    return (datetime.strptime(b, "%Y-%m-%d") - datetime.strptime(a, "%Y-%m-%d")).days


def _kr_add(d, n):
    return (datetime.strptime(d, "%Y-%m-%d") + timedelta(days=n)).strftime("%Y-%m-%d")


def _kr_interp(knots, t):
    if t <= knots[0][0]:
        return knots[0][1]
    for (x0, y0), (x1, y1) in zip(knots, knots[1:]):
        if t <= x1:
            return y0 + (y1 - y0) * (t - x0) / ((x1 - x0) or 1)
    return knots[-1][1]


def _kr_month_starts(today, n):
    y, m = int(today[:4]), int(today[5:7])
    out = []
    for _ in range(n):
        m += 1
        if m > 12:
            y, m = y + 1, 1
        out.append("%04d-%02d-01" % (y, m))
    return out


def _kr_path_from_yearly(yearly, k0, today, series):
    """Путь ставки, у которого среднее за год совпадает со срединным значением прогноза.
    Узлы: сегодня = текущая ставка; для текущего года — середина оставшейся части (цель = средняя ставка на остаток года,
    выведенная из годовой средней и уже известной фактической части); для следующих лет — 2 июля.
    Между узлами линейно, после последнего — плоско. Значения узлов подгоняются итерациями так, чтобы дневное среднее
    по году (для текущего — по оставшейся его части) равнялось целевому."""
    cur = int(today[:4])
    spans = []          # [год, t_от, t_до, цель, t_узла] в днях от сегодня
    for y in sorted(yearly):
        if y < cur:
            continue
        lo, hi = yearly[y]
        mid = (lo + hi) / 2.0
        b = _kr_days(today, "%d-12-31" % y)
        if y == cur:
            if b < 20:
                continue
            ny = _kr_days("%d-01-01" % y, "%d-12-31" % y) + 1
            done = _kr_days("%d-01-01" % y, today)
            tot = 0.0
            for i in range(done):
                r = key_rate_on(series, _kr_add("%d-01-01" % y, i))
                if r is None:
                    tot = None
                    break
                tot += r
            if tot is not None and ny > done:
                rest = (mid * ny - tot) / (ny - done)
                if abs(rest - mid) <= 6 and rest > 0.5:
                    mid = rest
            spans.append([y, 0, b, mid, b / 2.0])
        else:
            a = _kr_days(today, "%d-01-01" % y)
            spans.append([y, a, b, mid, float(_kr_days(today, "%d-07-02" % y))])
    if not spans:
        raise ValueError("нет прогнозных лет")
    vals = [s[3] for s in spans]
    for _ in range(40):
        knots = [(0.0, k0)] + [(s[4], v) for s, v in zip(spans, vals)]
        worst = 0.0
        for n_, s in enumerate(spans):
            avg = sum(_kr_interp(knots, t) for t in range(int(s[1]), int(s[2]) + 1)) / (s[2] - s[1] + 1)
            err = s[3] - avg
            worst = max(worst, abs(err))
            vals[n_] = max(0.5, vals[n_] + 0.8 * err)
        if worst < 0.005:
            break
    knots = [(0.0, k0)] + [(s[4], v) for s, v in zip(spans, vals)]
    pts = [(today, round(k0, 3))]
    for d in _kr_month_starts(today, KR_HORIZON_M):
        pts.append((d, round(_kr_interp(knots, _kr_days(today, d)), 3)))
    return pts


def _kr_market_path(k0, today):
    """Путь из форвардных ставок КБД: 3-месячный форвард f(t) на горизонте t (эффективная годовая ставка).
    Ключевая ставка ~ форвард минус срочная премия: премия принята 0,75 п.п. в год горизонта, но не более 1,5 п.п.
    Начало привязано к текущей ставке: сдвиг (k0 - f(0)) затухает линейно за 2 года. Это грубая оценка рыночных
    ожиданий, а не прогноз ЦБ."""
    if not kbd_curve():
        raise ValueError("нет КБД")

    def z(t):
        return (1 + kbd_at(t) / 100.0) ** t

    def fwd(t):
        h = 0.25
        return ((z(t + h) / z(t)) ** (1 / h) - 1) * 100.0
    f0 = fwd(0.0)
    pts = [(today, round(k0, 3))]
    for d in _kr_month_starts(today, KR_HORIZON_M):
        t = _kr_days(today, d) / 365.0
        pts.append((d, round(max(0.5, fwd(t) + (k0 - f0) * max(0.0, 1 - t / 2.0) - min(1.5, 0.75 * t)), 3)))
    return pts


def _kr_flat_path(k0, today):
    return [(today, round(k0, 3))] + [(d, round(k0, 3)) for d in _kr_month_starts(today, KR_HORIZON_M)]


def _kr_yearly_from_path(path):
    by = defaultdict(list)
    for d, v in path:
        by[int(d[:4])].append(v)
    return [{"year": y, "low": round(min(v), 2), "high": round(max(v), 2), "mid": round(sum(v) / len(v), 2)} for y, v in sorted(by.items())]


def _kr_try(src, today):
    """Один источник -> dict с path/yearly/as_of либо исключение."""
    ser, k0 = _kr_current()
    if src in ("cbr", "survey"):
        st = store()
        ck = "kr_src:" + src
        raw = st.get(ck, ttl=KR_TTL)
        if raw is None:
            raw = (_kr_cbr if src == "cbr" else _kr_survey)()
            st.put(ck, {"as_of": raw["as_of"], "url": raw["url"], "years": {str(k): list(v) for k, v in raw["years"].items()}})
        years = {int(k): tuple(v) for k, v in raw["years"].items() if int(k) >= int(today[:4])}     # фактические годы не нужны
        path = _kr_path_from_yearly(years, k0, today, ser)
        yearly = [{"year": y, "low": lo, "high": hi, "mid": round((lo + hi) / 2.0, 2)} for y, (lo, hi) in sorted(years.items())]
        return {"as_of": raw["as_of"], "url": raw["url"], "yearly": yearly, "path": path, "key_rate": k0}
    path = _kr_market_path(k0, today) if src == "market" else _kr_flat_path(k0, today)
    return {"as_of": today, "url": "", "yearly": _kr_yearly_from_path(path), "path": path, "key_rate": k0}


def keyrate_forecast_info(mode=None):
    """{source, source_name, mode, as_of, yearly:[{year, low, high, mid}], path:[(дата, %)], key_rate, tried:{источник: ошибка}}.
    mode — из настройки keyrate_mode; пробуем выбранный источник, затем следующие по цепочке cbr -> survey -> market -> flat.
    Кэш источников 24 часа (в базе), путь на сегодня — в памяти."""
    if mode is None:
        try:
            mode = load_config().get("keyrate_mode")
        except Exception:  # noqa: BLE001
            mode = None
    if mode not in KR_MODES:
        mode = "cbr"
    today = date.today().isoformat()
    ck = (mode, today)
    with _kr_lock:
        hit = _kr_mem.get(ck)
        if hit and time.time() - hit[0] < (KR_TTL if hit[1].get("source") != "none" else KR_ERR_TTL):
            return hit[1]
        tried, res = {}, None
        for src in KR_MODES[KR_MODES.index(mode):]:
            try:
                res = _kr_try(src, today)
                res["source"] = src
                break
            except Exception as e:  # noqa: BLE001
                tried[src] = str(e)[:140] or e.__class__.__name__
        if res is None:
            res = {"source": "none", "as_of": today, "url": "", "yearly": [], "path": [], "key_rate": None}
        res.update(mode=mode, tried=tried, source_name=KR_NAMES.get(res["source"], "нет данных"))
        _kr_mem.clear()
        _kr_mem[ck] = (time.time(), res)
        return res


def keyrate_path():
    """Месячный путь ключевой ставки [(дата ISO, % годовых)] на ~4 года вперёд (первая точка — сегодня).
    Источник — keyrate_forecast_info(); пусто, если ничего не получилось."""
    try:
        return keyrate_forecast_info()["path"]
    except Exception:  # noqa: BLE001
        return []


def keyrate_at(path, d):
    """Прогнозная ставка на дату d (ISO) по пути (линейная интерполяция между месячными точками)."""
    if not path:
        return None
    if d <= path[0][0]:
        return path[0][1]
    ds = [p[0] for p in path]
    i = bisect.bisect_right(ds, d)
    if i >= len(path):
        return path[-1][1]
    (d0, v0), (d1, v1) = path[i - 1], path[i]
    w = _kr_days(d0, d) / float(_kr_days(d0, d1) or 1)
    return v0 + (v1 - v0) * w

# ═══════════════════ сигналы: дороже/дешевле аналогов по всему рынку, история, возможные замены ═══════════════════

SIG_TTL = 900
SIG_HIST_KEY = "sig_hist_v1"
SIG_HIST_DAYS = 120
SIG_EPS = 0.25           # |diff| (п.п.) от которого выпуск считается «дешевле/дороже» аналогов
SIG_OUTLIER = 8.0        # |diff| больше этого, доходность выше SIG_MAX_YIELD или спред < -6: вероятно дефолтный/«битый» выпуск
SIG_MAX_YIELD = 40.0
SIG_MAX_GAIN = 8.0       # разницу доходности больше этого в замены не берём: это уже разница в риске, а не «недооценка»
SIG_MIN_SIGMA = 0.4      # нижняя граница разброса аналогов (п.п.) для z-оценки
_sig = {"t": 0, "rows": [], "meta": {}}
_sig_lock = threading.Lock()
_sig_hist = {"t": 0, "d": None}


def _sig_pool(uni):
    """Выпуски, участвующие в сравнении: рублёвые корпоративные с рейтингом, без флоатеров и бессрочных."""
    out = []
    for e in uni:
        if e["kind"] != "corp" or e["cur"] != "RUB" or not (0 < e["yield"] < 60) or not e.get("dur") or e["dur"] < 0.1:
            continue
        if not e["_rt"] or e.get("spread") is None:
            continue
        ci = e["_ci"] or {}
        if ci.get("floating") or ci.get("perpetual"):
            continue
        out.append(e)
    return out


def _sig_index(pool):
    """Индексы для быстрого перебора кандидатов: по индексу рейтинга, отсортировано по дюрации."""
    by = defaultdict(list)
    for e in pool:
        by[RATING_SCALE.index(e["_rt"]["v"])].append(e)
    idx = {}
    for ri, lst in by.items():
        lst.sort(key=lambda e: e["dur"])
        idx[ri] = (lst, [e["dur"] for e in lst])
    return idx


def _sig_cands(me, ri, idx, rng=2):
    """Кандидаты в аналоги (до применения _bc_cost): рейтинг ±rng ступеней и дюрация в допустимом окне."""
    d = me["dur"]
    lo, hi = d * 0.4, d * 2.5
    for r in range(ri - rng, ri + rng + 1):
        it = idx.get(r)
        if not it:
            continue
        lst, durs = it
        for e in lst[bisect.bisect_left(durs, lo):bisect.bisect_right(durs, hi)]:
            yield e


def _sig_nearest(me, ri, idx, isin_skip=None):
    """Ближайшие аналоги так же, как в карточке: 30 лучших -> отсев выбросов по спреду -> 12 лучших. Возвращает [(cost, e)]."""
    sc = []
    for e in _sig_cands(me, ri, idx):
        if e is me or e["_isin"] == isin_skip:
            continue
        c = _bc_cost(me, e, ri)
        if c is not None:
            sc.append((c, e["_isin"], e))
    sc.sort(key=lambda x: (x[0], x[1]))
    sps = sorted(x[2]["spread"] for x in sc[:30])
    if len(sps) >= 5:
        m0 = sps[len(sps) // 2]
        sc = [x for x in sc if abs(x[2]["spread"] - m0) <= 8]
    return [(c, e) for c, _, e in sc[:12]]


def _sig_median(xs):
    xs = sorted(xs)
    n = len(xs)
    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2


def _sig_row(e, near):
    sp = [a["spread"] for _, a in near]
    med = _sig_median(sp)
    mad = _sig_median([abs(x - med) for x in sp]) * 1.4826
    diff = e["spread"] - med
    ci, rt = e["_ci"] or {}, e["_rt"]
    return {"isin": e["_isin"], "id": e["id"], "name": e["name"], "rating": rt["v"], "rating_approx": bool(rt.get("approx")),
            "sector": ci.get("sector"), "yield": e["yield"], "spread": e["spread"], "dur": e["dur"], "price": e.get("price"),
            "mat": e.get("mat"), "med": round(med, 2), "diff": round(diff, 2), "sigma": round(max(mad, SIG_MIN_SIGMA), 2),
            "z": round(diff / max(mad, SIG_MIN_SIGMA), 2), "n": len(sp), "turn": e.get("turn") or 0, "trades": e.get("trades") or 0,
            "amort": bool(ci.get("amort")), "sub": bool(ci.get("subordinated")),
            "outlier": bool(abs(diff) > SIG_OUTLIER or e["yield"] > SIG_MAX_YIELD or e["spread"] < -6),
            "refs": [{"isin": a["_isin"], "name": a["name"], "spread": a["spread"]} for _, a in near[:3]]}


def _sig_hist_load():
    if _sig_hist["d"] is None or time.time() - _sig_hist["t"] > 60:
        _sig_hist["d"] = store().get(SIG_HIST_KEY) or {}
        _sig_hist["t"] = time.time()
    return _sig_hist["d"]


def _sig_snapshot(rows):
    """Сохраняет сегодняшний снимок diff (по будням; ликвидные выпуски), хранит SIG_HIST_DAYS последних дней."""
    h = _sig_hist_load()
    today = date.today()
    if today.weekday() < 5 and rows:
        h[today.isoformat()] = {r["isin"]: r["diff"] for r in rows if r["turn"] >= 2e5}
        for d in sorted(h)[:-SIG_HIST_DAYS]:
            h.pop(d, None)
        try:
            store().put(SIG_HIST_KEY, h)
        except Exception:  # noqa: BLE001
            pass
    return h


def _sig_streak(h, isin, diff):
    """Сколько последних снимков подряд знак и величина diff те же (дешевле/дороже). Возвращает (streak, series[старые..новые])."""
    days = sorted(h)
    ser = [h[d].get(isin) for d in days]
    sgn = 1 if diff >= SIG_EPS else -1 if diff <= -SIG_EPS else 0
    n = 0
    if sgn:
        for v in reversed(ser):
            if v is not None and v * sgn >= SIG_EPS:
                n += 1
            else:
                break
    return n, ser


def _sig_all(force=False):
    """Полный расчёт сигналов по рынку; кэш 15 минут. Возвращает (rows, meta)."""
    if not force and time.time() - _sig["t"] < SIG_TTL and _sig["rows"]:
        return _sig["rows"], _sig["meta"]
    with _sig_lock:
        if not force and time.time() - _sig["t"] < SIG_TTL and _sig["rows"]:
            return _sig["rows"], _sig["meta"]
        t0 = time.time()
        uni = _bc_universe()
        pool = _sig_pool(uni)
        idx = _sig_index(pool)
        rows = []
        for e in pool:
            near = _sig_nearest(e, RATING_SCALE.index(e["_rt"]["v"]), idx)
            if len(near) >= 5:
                rows.append(_sig_row(e, near))
        h = _sig_snapshot(rows)
        days = sorted(h)
        for r in rows:
            n, ser = _sig_streak(h, r["isin"], r["diff"])
            r["streak"] = n
            vals = [v for v in ser if v is not None]
            r["trend"] = round(r["diff"] - vals[-6], 2) if len(vals) >= 6 else (round(r["diff"] - vals[0], 2) if len(vals) >= 2 else None)
            r["hist"] = vals[-30:] if abs(r["z"]) >= 1 and len(vals) >= 2 else None
        meta = {"pool": len(pool), "scored": len(rows), "hist_days": len(days), "hist_from": days[0] if days else None,
                "calc_s": round(time.time() - t0, 2), "updated": time.time()}
        _sig.update(t=time.time(), rows=rows, meta=meta)
        return rows, meta


def _sig_replacements(cfg, acc, pool_idx, rows_by_isin, fee, thr, min_turn, tax_rate):
    """Для каждой облигации портфеля: возможные замены с большей доходностью (по рыночной доходности) с учётом издержек."""
    try:
        pf = build_bonds(cfg, acc, False)["rows"]
    except Exception:  # noqa: BLE001
        return [], []
    uni = {}
    for e in _bc_universe():
        uni[e["_isin"]] = e
        uni[e["id"]] = e
    pool, idx = pool_idx
    held = {r.get("ticker") for r in pf}
    out, skipped = [], []
    for r in pf:
        isin = r.get("ticker")
        V = r.get("value_rub") or 0
        base = {"isin": isin, "name": r.get("name"), "qty": r.get("qty"), "value": round(V, 2), "rating": (r.get("rating") or {}).get("v")}
        me = uni.get(isin)
        if not me or V <= 0 or r.get("cur") not in (None, "rub", "RUB"):
            skipped.append(dict(base, why="нет рыночных данных или не рублёвая"))
            continue
        if me["kind"] != "corp":
            skipped.append(dict(base, why="ОФЗ: сравнение не применяется"))
            continue
        ci = me["_ci"] or {}
        if ci.get("floating") or r.get("floating"):
            skipped.append(dict(base, why="флоатер: спред к КБД не сопоставим"))
            continue
        if not me["_rt"]:
            skipped.append(dict(base, why="нет рейтинга"))
            continue
        ri = RATING_SCALE.index(me["_rt"]["v"])
        y0 = me["yield"]
        mine_sig = rows_by_isin.get(me["_isin"])
        if not mine_sig or mine_sig["outlier"]:
            skipped.append(dict(base, why="нет надёжного сравнения с аналогами (нет спреда или аномальные данные)"))
            continue
        cands = []
        for t in _sig_cands(me, ri, idx):
            if t is me or t["_isin"] in held or t["yield"] <= y0 or (t.get("turn") or 0) < min_turn:
                continue
            c = _bc_cost(me, t, ri)
            if c is None or c > 2.5 or abs(t["dur"] - me["dur"]) / max(t["dur"], me["dur"], 0.5) > 0.35:
                continue
            cands.append((c, t))
        # потолок доходности: цель не должна быть выбросом относительно собственных аналогов
        price, buy, nom, qty = r.get("price_pct"), r.get("buy_pct"), r.get("nominal") or 1000.0, r.get("qty") or 0
        tax = 0.0
        if price and buy and price > buy:
            tax = tax_rate * (price - buy) / 100.0 * nom * qty
        cost_rub = 2 * fee * V + tax
        opts = []
        for c, t in cands:
            tr = rows_by_isin.get(t["_isin"])
            if tr is None or tr["n"] < 5:
                continue
            if tr["outlier"]:
                continue
            gain = t["yield"] - y0
            if gain > SIG_MAX_GAIN:
                continue
            hz = min(5.0, max(0.5, min(me["dur"], t["dur"])))
            net = gain - cost_rub / V * 100.0 / hz
            rt_i = RATING_SCALE.index(t["_rt"]["v"])
            gain_rub = V * gain / 100.0
            opts.append({"isin": t["_isin"], "name": t["name"], "rating": t["_rt"]["v"], "rating_worse": rt_i > ri,
                         "rating_better": rt_i < ri, "sector": (t["_ci"] or {}).get("sector"), "yield": t["yield"], "dur": t["dur"],
                         "spread": t["spread"], "turn": t.get("turn") or 0, "trades": t.get("trades") or 0, "mat": t.get("mat"),
                         "diff": tr["diff"], "z": tr["z"], "gain_pp": round(gain, 2), "net_pp": round(net, 2),
                         "gain_rub_year": round(gain_rub), "net_rub_year": round(V * net / 100.0),
                         "breakeven_months": round(cost_rub / gain_rub * 12, 1) if gain_rub > 0 else None, "horizon": round(hz, 1)})
        opts = [o for o in opts if o["net_pp"] >= thr]
        opts.sort(key=lambda o: -o["net_pp"])
        better = [o for o in opts if not o["rating_worse"]][:3]
        worse = [o for o in opts if o["rating_worse"]][:2]
        if better or worse:
            out.append(dict(base, yield_=y0, dur=me["dur"], spread=me["spread"], price_pct=price, buy_pct=buy, sector=ci.get("sector"),
                            turn=me.get("turn") or 0, diff=mine_sig["diff"] if mine_sig else None, z=mine_sig["z"] if mine_sig else None,
                            cost_rub=round(cost_rub), commission_rub=round(2 * fee * V), tax_rub=round(tax),
                            cost_pp=round(cost_rub / V * 100, 2), options=better, options_worse=worse))
    out.sort(key=lambda x: -((x["options"] or x["options_worse"])[0]["net_rub_year"]))
    return out, skipped


def signals_payload(cfg, acc, q=None):
    q = q or {}

    def num(k, d, lo, hi):
        try:
            return min(hi, max(lo, float(q.get(k, d))))
        except (TypeError, ValueError):
            return d
    min_turn = num("min_turn", 1e6, 0, 1e10)
    fee = num("fee", 0.3, 0, 5) / 100.0
    thr = num("threshold", 1.0, 0, 20)
    tax_rate = num("tax", 13, 0, 50) / 100.0
    rows, meta = _sig_all(q.get("force") == "1")
    liquid = [r for r in rows if r["turn"] >= min_turn]
    n_out = sum(1 for r in liquid if r["outlier"])
    liquid_ok = [r for r in liquid if not r["outlier"]]
    uni = _bc_universe()
    pool = _sig_pool(uni)
    by = {r["isin"]: r for r in rows}
    repl, skipped = _sig_replacements(cfg, acc, (pool, _sig_index(pool)), by, fee, thr, min_turn, tax_rate)
    cheap = sorted((r for r in liquid_ok if r["diff"] >= SIG_EPS), key=lambda r: -r["z"])
    rich = sorted((r for r in liquid_ok if r["diff"] <= -SIG_EPS), key=lambda r: r["z"])
    outl = [r for r in liquid if r["outlier"]]
    keep = {r["isin"] for r in cheap[:150]} | {r["isin"] for r in rich[:150]} | {r["isin"] for r in outl[:60]}
    return {"rows": [r for r in liquid if r["isin"] in keep],
            "kpis": {"universe": len(liquid), "outliers": n_out, "cheap": len(cheap), "rich": len(rich),
                     "cheap_strong": sum(1 for r in cheap if r["z"] >= 2), "rich_strong": sum(1 for r in rich if r["z"] <= -2),
                     "med_diff": round(_sig_median([r["diff"] for r in liquid_ok]), 2) if liquid_ok else None},
            "meta": meta, "params": {"min_turn": min_turn, "fee": fee * 100, "threshold": thr, "tax": tax_rate * 100},
            "replacements": repl, "skipped": skipped, "eps": SIG_EPS}
# ═══════════════════ мониторинг портфеля: тревоги, ликвидность, история спредов ═══════════════════
# Источники: журнал рейтинговых действий (ratings_log_v1, каналы @ru_ratings и @issuerRatings), рейтинги и статус «под наблюдением»
# из каталога T-Invest, история торгов и описание выпуска на Мосбирже (ISS), кривая КБД по датам.
# Чего программа НЕ видит: факт оплаты купона (ISS его не публикует), поэтому «задержка выплаты» определяется
# только косвенно: флаги дефолта в описании выпуска на Мосбирже, дефолтный рейтинг (D/RD/C), остановка торгов.

MON_DEFAULTS = {"mon_drop5": 3.0, "mon_drop30": 7.0, "mon_spread30": 2.0, "mon_sell_days": 5.0, "mon_offer_days": 30}
MON_SNAP_KEY, MON_CURVE_KEY = "mon_snap_v1", "kbd_curves_v1"
MON_RT_DAYS, MON_SPARK_DAYS, MON_PART = 90, 90, 0.2        # окно рейтинговых событий, окно спарклайна, доля оборота
_mon_lock = threading.Lock()
_SEV = {"high": 0, "medium": 1, "info": 2}


def mon_thresholds(cfg):
    out = {}
    for k, d in MON_DEFAULTS.items():
        try:
            out[k] = float(cfg.get(k, d))
        except (TypeError, ValueError):
            out[k] = d
    return out


def _mon_ymd(n):
    return (date.today() - timedelta(days=n)).isoformat()


def _mon_hist_for(secid):
    """История торгов выпуска (кэш 6 ч в kv) или None."""
    try:
        h = _bc_history(secid)
        return h if h and h.get("d") else None
    except Exception:  # noqa: BLE001
        return None


def _mon_flags(isin):
    """Флаги дефолта из описания выпуска на Мосбирже (кэш 12 ч)."""
    key = "mon_desc_v1_" + isin
    hit = store().get(key, ttl=12 * 3600)
    if hit is not None:
        return hit
    try:
        j = json.loads(http_text("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description" % isin, timeout=20))
        d = {r[0]: r[2] for r in j["description"]["data"]}
        out = {"default": str(d.get("HASDEFAULT") or "0") == "1", "tech": str(d.get("HASTECHNICALDEFAULT") or "0") == "1",
               "found": bool(d)}
    except Exception:  # noqa: BLE001
        return {"default": False, "tech": False, "found": False}
    store().put(key, out)
    return out


def _mon_ru(d):
    return d[8:] + "." + d[5:7] + "." + d[:4]


def mon_moex_events(bz, offers, today, horizon):
    """События выпуска по данным Мосбиржи (bondization + оферты): погашение, амортизации, оферты в окне [today, today+horizon] дней.
    Только будущие события. -> {'maturity': дата|None, 'events': [{kind: maturity|amort|offer, date, left, ...}], 'next_offer': дата|None}.
    Погашение — последняя дата в графике амортизаций (при его отсутствии — последний купон); остальные даты амортизаций — частичные."""
    end = (datetime.strptime(today, "%Y-%m-%d") + timedelta(days=int(horizon))).strftime("%Y-%m-%d")
    bz = bz or {}
    am = {}
    for a in bz.get("amort") or []:
        if a.get("amortdate"):
            am[a["amortdate"]] = a
    cps = [c["coupondate"] for c in bz.get("coupons") or [] if c.get("coupondate")]
    mat = max(am) if am else (max(cps) if cps else None)
    ev = []
    for d, a in sorted(am.items()):
        if today < d <= end:
            ev.append({"kind": "maturity" if d == mat else "amort", "date": d, "pct": a.get("valueprc"), "value": a.get("value")})
    if mat and not am and today < mat <= end:
        ev.append({"kind": "maturity", "date": mat})
    live = [o for o in offers or [] if o.get("status") != "cancelled" and o["date"] > today]
    for d in sorted({o["date"] for o in live if o["date"] <= end}):
        ev.append({"kind": "offer", "date": d, "offer_kind": offer_kind_on(live, d)})
    for e in ev:
        e["left"] = (datetime.strptime(e["date"], "%Y-%m-%d").date() - datetime.strptime(today, "%Y-%m-%d").date()).days
    ev.sort(key=lambda e: e["date"])
    return {"maturity": mat, "events": ev, "next_offer": min((o["date"] for o in live), default=None)}


def mon_event_alert(e):
    """Текст тревоги по событию мосбиржевого графика (погашение, амортизация)."""
    ds, left = _mon_ru(e["date"]), e["left"]
    if e["kind"] == "maturity":
        return "Погашение %s (через %d дн.) — по данным Мосбиржи" % (ds, left)
    part = ""
    if e.get("pct"):
        part = " %s %% номинала" % str(e["pct"]).replace(".", ",")
    return "Амортизация%s %s (через %d дн.) — по данным Мосбиржи" % (part, ds, left)


def mon_clean_issuer(s):
    """Название эмитента из поста агентства: убирает висячие кавычки, ПРОПИСНЫЕ -> обычный регистр (аббревиатуры до 4 букв остаются)."""
    s = re.sub(r"\s+", " ", s or "").strip()
    if s.count("«") != s.count("»"):
        s = s.replace("«", "").replace("»", "").strip()
    if s.isupper():
        s = " ".join(w if len(w) <= 4 or "." in w else w.capitalize() for w in s.split(" "))
    return s


def _mon_curve_one(d):
    j = json.loads(http_text("https://iss.moex.com/iss/engines/stock/zcyc.json?iss.meta=off&iss.only=yearyields&date=" + d))
    return d, [[r[2], round(r[3], 3)] for r in sorted(j["yearyields"]["data"], key=lambda r: r[2])]


def _mon_curves(days):
    """Кривые КБД по датам за последние days дней (кэш в kv навсегда; выходные и праздники хранятся пустыми)."""
    st = store()
    cache = st.get(MON_CURVE_KEY) or {}
    need = [_mon_ymd(i) for i in range(1, days + 1) if (date.today() - timedelta(days=i)).weekday() < 5
            and _mon_ymd(i) not in cache]
    if need:
        for d, pts in pool_map(lambda x: _safe(_mon_curve_one, x), need, workers=8):
            if d is not None:
                cache[d] = pts
        keep = _mon_ymd(800)
        cache = {k: v for k, v in cache.items() if k >= keep}
        st.put(MON_CURVE_KEY, cache)
    return cache


def _curve_on(curves, sorted_dates, d):
    """Кривая на дату d: последняя непустая на эту дату или раньше."""
    import bisect
    i = bisect.bisect_right(sorted_dates, d)
    while i > 0:
        i -= 1
        c = curves.get(sorted_dates[i])
        if c:
            return c
    return None


def _at_or_before(ds, target):
    """Индекс последней даты <= target либо None."""
    import bisect
    i = bisect.bisect_right(ds, target) - 1
    return i if i >= 0 else None


def _mon_match(a, b):
    if not a or not b:
        return False
    if a == b:
        return True
    lo, hi = (a, b) if len(a) <= len(b) else (b, a)           # «ЛК Европлан» ~ «Европлан», но «Золото Селигдара» != «Селигдар»
    return lo <= hi and sum(len(x) for x in lo) >= 5 and all(len(x) <= 2 for x in hi - lo)


def _mon_ev_tokens(e):
    """Ключи эмитента события: пересчитываются из названия (в старых журналах сохранены ключи прежнего формата)."""
    return set(name_tokens(e.get("issuer") or "")) or set(e.get("tokens") or ())


def _mon_issuer_keys(row):
    keys = [name_tokens(_bond_query(row.get("name") or ""))]
    b = _tcat_get(row.get("isin") or row.get("ticker"))
    if b:
        for s in (b.get("br"), _bond_query(b.get("n") or "")):
            if s:
                keys.append(name_tokens(s))
    return [k for k in keys if k]


def _mon_rating_state(row, keys, events):
    """Рейтинговое состояние для таблицы: лучший рейтинг, прогноз, флаг «под наблюдением»."""
    rt = row.get("rating")
    watch, outlook, last = False, "", {}
    b = _tcat_get(row.get("isin") or row.get("ticker"))
    if b:
        for ag, lv, dt, fc, w in b["r"]:
            if w:
                watch = True
            if fc and (ag not in last or dt >= last[ag][0]):
                last[ag] = (dt, fc)
    ws = {}
    for e in events:
        if any(_mon_match(_mon_ev_tokens(e), k) for k in keys):
            if e.get("watch") in ("set", "removed"):
                ws[e["agency"]] = e["watch"] == "set"
            if e.get("outlook") and e["agency"] not in last:
                last[e["agency"]] = (e["date"], e["outlook"])
    if any(ws.values()):
        watch = True
    cands = [x for x in (rt or {}).get("all") or []]
    if cands:
        w = max(cands, key=lambda x: RATING_SCALE.index(x["rating"]))
        outlook = (w.get("outlook") or "").split(" · ")[0]
    if not outlook and last:
        outlook = sorted(last.values())[-1][1]
    return {"v": rt["v"] if rt else None, "agency": rt["agency"] if rt else None, "outlook": outlook,
            "watch": watch, "neg": "негатив" in (outlook or "").lower()}


MON_RT_HIGH_DAYS = 30                                      # понижение старше этого срока уже не «высокая» тревога


def _mon_rating_alerts(rows_keys, events, cutoff, today=None):
    """Тревоги по журналу рейтинговых действий: одно событие -> одна тревога на все бумаги этого эмитента.
    Одинаковые действия одного агентства в один день (по эмитенту и по облигациям) склеиваются в одну тревогу.
    Давнее понижение (старше MON_RT_HIGH_DAYS дней) понижается до средней важности."""
    out, seen = [], {}
    old = (datetime.strptime(today, "%Y-%m-%d").date() - timedelta(days=MON_RT_HIGH_DAYS)).isoformat() if today else None
    for e in events:
        if e["date"] < cutoff:
            continue
        et = _mon_ev_tokens(e)
        hit = [r for r, keys in rows_keys if any(_mon_match(et, k) for k in keys)]
        if not hit:
            continue
        act, rt, prev = e["action"], e.get("rating"), e.get("prev")
        sev, msg = None, None
        who = "%s: " % e["agency"]
        lvl = "облигации" if e["level"] == "bond" else "эмитент"
        issuer = mon_clean_issuer(e["issuer"])
        if rt in ("D", "C", "CC") or (act == "понижен" and rt in ("CCC",)):
            sev, msg = "high", who + "дефолтный/преддефолтный уровень рейтинга %s (%s)" % (rt, lvl)
        elif act == "понижен":
            sev, msg = "high", who + "рейтинг понижен%s до %s (%s)" % (" с " + prev if prev else "", rt, lvl)
        elif e.get("watch") == "set" or act == "под наблюдением":
            sev, msg = "medium", who + "рейтинг %s взят «под наблюдение» (%s)" % (rt or "", lvl)
        elif act == "прогноз изменён" and (e.get("outlook") or "") == "негативный":
            sev, msg = "medium", who + "прогноз изменён на негативный, рейтинг %s (%s)" % (rt, lvl)
        elif act == "отозван":
            sev = "medium" if e["level"] == "issuer" else "info"
            msg = who + "рейтинг отозван (%s)%s" % (lvl, "; ранее " + prev if prev else "")
        elif act == "повышен":
            sev, msg = "info", who + "рейтинг повышен%s до %s (%s)" % (" с " + prev if prev else "", rt, lvl)
        elif e.get("outlook") == "негативный":
            sev, msg = "info", who + "рейтинг %s %s, прогноз негативный (%s)" % (rt, act, lvl)
        if not sev:
            continue
        if sev == "high" and old and e["date"] < old and rt not in ("D", "C", "CC"):
            sev = "medium"
        ident = (e["agency"], e["date"], act, rt, prev, e.get("watch"), e.get("outlook") if act == "прогноз изменён" else None, tuple(sorted(h.get("isin") or "" for h in hit)))
        if ident in seen:                              # то же действие по другому уровню (эмитент/облигации)
            if lvl not in seen[ident]["_lvl"]:
                seen[ident]["_lvl"].append(lvl)
                seen[ident]["message"] = seen[ident]["_msg"] % "эмитент и облигации"
            continue
        out.append({"id": "rt|%s|%s%s" % (e["agency"], "rr" if e.get("src") == "ru_ratings" else "", e["post"]), "severity": sev, "kind": "rating", "date": e["date"],
                    "isin": hit[0].get("isin"), "isins": [h.get("isin") for h in hit], "name": issuer,
                    "bonds": [h.get("name") for h in hit], "message": msg, "url": e.get("url") or
                    "https://t.me/%s/%s" % (e.get("src") or "issuerRatings", e["post"]), "_lvl": [lvl], "_msg": msg.replace("(" + lvl + ")", "(%s)")})
        seen[ident] = out[-1]
    for a in out:
        a.pop("_lvl", None)
        a.pop("_msg", None)
    return out


def _mon_snapshots(rows):
    """Ежедневный снимок цены/спреда по ISIN (хранится 400 дней): запасной источник истории спреда."""
    st = store()
    snap = st.get(MON_SNAP_KEY) or {}
    today = date.today().isoformat()
    changed = False
    for r in rows:
        isin = r.get("isin")
        if not isin or r.get("price_pct") is None:
            continue
        d = snap.setdefault(isin, {})
        if today not in d:
            d[today] = [round(r["price_pct"], 3), r.get("spread")]
            changed = True
    keep = _mon_ymd(400)
    if changed:
        for isin in snap:
            snap[isin] = {k: v for k, v in snap[isin].items() if k >= keep}
        st.put(MON_SNAP_KEY, snap)
    return snap


def build_monitor(cfg, acc):
    t0 = time.time()
    th = mon_thresholds(cfg)
    key = ("monitor", token_key(cfg), acc, tuple(sorted(th.items())))
    hit = mem_get(key, 300)
    if hit:
        return hit
    with _mon_lock:
        hit = mem_get(key, 300)
        if hit:
            return hit
        res = _build_monitor(cfg, acc, th, t0)
        mem_put(key, res)
        return res


def _build_monitor(cfg, acc, th, t0):
    tm = {}
    try:
        b = build_bonds(cfg, acc)
    except ApiError as e:
        if e.status != 404:
            raise
        return {"empty": True, "updated": time.time(), "thresholds": th, "alerts": [], "rows": [],
                "summary": {s: 0 for s in _SEV}, "timings": tm,
                "notes": ["Добавьте API-токен в «Настройках» или импортируйте отчёт брокера."],
                "log": {"events": 0, "since": None}, "cal_days": 0}
    tm["bonds"] = round(time.time() - t0, 2)
    rows = [r for r in (b.get("rows") or []) if r.get("isin") and r.get("qty")]
    return _monitor_core(rows, th, t0, tm, [])


def _monitor_core(rows, th, t0, tm, notes, liquidity=True):
    """Проверки мониторинга для произвольного списка бумаг. rows — строки вида build_bonds (isin, name, ticker, value_rub, qty,
    maturity, call, floating, price_pct, dur, spread, ytm, rating). Портфель и список наблюдения идут одним кодом."""
    today = date.today().isoformat()
    # соответствие ISIN -> код на Мосбирже
    t1 = time.time()
    sec = {}
    try:
        for s in screener_rows():
            if s.get("isin"):
                sec[s["isin"]] = s
    except Exception as e:  # noqa: BLE001
        notes.append("Скринер Мосбиржи недоступен: %s" % str(e)[:80])
    tm["screener"] = round(time.time() - t1, 2)
    t1 = time.time()
    secids = {r["isin"]: (sec.get(r["isin"]) or {}).get("id") or r.get("ticker") or r["isin"] for r in rows}
    hists = dict(zip([r["isin"] for r in rows], pool_map(lambda r: _mon_hist_for(secids[r["isin"]]), rows, workers=8)))
    tm["history"] = round(time.time() - t1, 2)
    t1 = time.time()
    flags = dict(zip([r["isin"] for r in rows], pool_map(lambda r: _mon_flags(r["isin"]), rows, workers=8)))
    tm["flags"] = round(time.time() - t1, 2)
    t1 = time.time()
    try:
        curves = _mon_curves(MON_SPARK_DAYS + 40)
    except Exception as e:  # noqa: BLE001
        curves = {}
        notes.append("Кривая КБД по датам недоступна: %s" % str(e)[:80])
    cdates = sorted(curves)
    tm["kbd_curves"] = round(time.time() - t1, 2)
    snap = _mon_snapshots(rows)
    log = store().get(RT_LOG_KEY) or {"events": []}
    events = log.get("events") or []
    if not events:
        notes.append("Журнал рейтинговых действий пока пуст: он наполняется при синхронизации рейтингов (раздел «Облигации» → обновить рейтинги).")
    # окно торгового календаря для среднего оборота
    win_from = _mon_ymd(30)
    cal = set()
    for h in hists.values():
        if h:
            cal.update(d for d in h["d"] if d > win_from)
    ndays = max(len(cal), 15)
    out_rows, alerts = [], []
    rows_keys = []
    for r in rows:
        isin = r["isin"]
        h = hists.get(isin)
        keys = _mon_issuer_keys(r)
        rows_keys.append((r, keys))
        row = {"isin": isin, "name": r.get("name"), "ticker": r.get("ticker"), "value_rub": r.get("value_rub"),
               "qty": r.get("qty"), "maturity": r.get("maturity"), "call": r.get("call"),
               "floating": bool(r.get("floating")), "price_pct": r.get("price_pct"), "flags": []}
        row["rating"] = _mon_rating_state(r, keys, events)
        price = chg5 = chg30 = sp_now = sp_chg = None
        spark = []
        last_d = None
        if h:
            ds, ps, ys, vs = h["d"], h["p"], h["y"], h["v"]
            last_d = ds[-1]
            price = ps[-1]
            for n, nm in ((5, "chg5"), (30, "chg30")):
                i = _at_or_before(ds, _mon_ymd(n))
                if i is not None and ds[i] >= _mon_ymd(n + 10) and ps[i]:
                    v = round((price / ps[i] - 1) * 100, 2)
                    if nm == "chg5":
                        chg5 = v
                    else:
                        chg30 = v
            # спред к КБД по датам: доходность дня минус КБД на дюрации бумаги
            dur = r.get("dur")
            if dur and not r.get("floating") and cdates:
                sp = []
                for d, y in zip(ds, ys):
                    if y is None or d < _mon_ymd(MON_SPARK_DAYS + 35):
                        continue
                    c = _curve_on(curves, cdates, d)
                    k = _interp(c, dur)
                    if k is not None and 0 < y < 80:
                        sp.append((d, round(y - k, 2)))
                if len(sp) >= 5:
                    sd = [x[0] for x in sp]
                    sp_now = sp[-1][1]
                    i = _at_or_before(sd, _mon_ymd(30))
                    if i is not None and sd[i] >= _mon_ymd(40):
                        sp_chg = round(sp_now - sp[i][1], 2)
                    spark = [[d, v] for d, v in sp if d >= _mon_ymd(MON_SPARK_DAYS)]
            tov = sum(v for d, v in zip(ds, vs) if d > win_from)
            avg = tov / ndays
            row["turnover_avg"] = round(avg)
            row["days_to_sell"] = round((r.get("value_rub") or 0) / (MON_PART * avg), 2) if avg > 0 else None
        else:
            row["turnover_avg"] = None
            row["days_to_sell"] = None
        if len(spark) < 5 and isin in snap:        # запасной вариант: накопленные ежедневные снимки
            sp = sorted((d, v[1]) for d, v in snap[isin].items() if v[1] is not None)
            if len(sp) >= 2:
                spark = [[d, v] for d, v in sp if d >= _mon_ymd(MON_SPARK_DAYS)]
                sp_now = sp[-1][1]
        row.update(price=price, chg5=chg5, chg30=chg30, spread=sp_now if sp_now is not None else r.get("spread"),
                   spread_chg30=sp_chg, spark=spark, last_trade=last_d, ytm=r.get("ytm"))
        row["no_history"] = h is None
        base = {"isin": isin, "isins": [isin], "name": r.get("name"), "bonds": [r.get("name")]}
        # --- ценовые тревоги
        parts, sev = [], None
        for chg, lim, lab in ((chg5, th["mon_drop5"], "5 дней"), (chg30, th["mon_drop30"], "30 дней")):
            if chg is not None and chg <= -lim:
                parts.append("%s %% за %s" % (str(chg).replace(".", ","), lab))
                s = "high" if chg <= -2 * lim else "medium"
                sev = s if sev is None or _SEV[s] < _SEV[sev] else sev
        if parts:
            alerts.append(dict(base, id="px|%s|%s" % (isin, today), severity=sev, kind="price", date=last_d or today,
                               message="Цена упала: " + "; ".join(parts) + (" (последняя цена %s %%)" % str(price).replace(".", ",")
                                                                              if price is not None else ""), url=""))
        if sp_chg is not None and sp_chg >= th["mon_spread30"]:
            s = "high" if sp_chg >= 2 * th["mon_spread30"] else "medium"
            alerts.append(dict(base, id="sp|%s|%s" % (isin, today), severity=s, kind="spread", date=last_d or today,
                               message="Спред к КБД вырос на %s п.п. за 30 дней (сейчас %s п.п.)" % (
                                   str(sp_chg).replace(".", ","), str(sp_now).replace(".", ",")), url=""))
        # --- события графика выпуска: даты берём с Мосбиржи (bondization и поля выпуска), а не у брокера
        win = max(int(th["mon_offer_days"]), 30)
        bz = offs = None
        try:
            bz = moex_bondization(isin)
            offs = offers_of_isin(isin, None if bz else r.get("call"), today)
        except Exception:  # noqa: BLE001
            pass
        if bz:
            me = mon_moex_events(bz, offs, today, win)
            row["maturity"] = me["maturity"] or row["maturity"]
            row["call"] = me["next_offer"]
            row["moex_dates"] = True
            for e in me["events"]:
                if e["kind"] == "offer":
                    alerts.append(dict(base, id="of|%s|%s" % (isin, e["date"]), severity="high" if e["left"] <= 7 else "medium",
                                       kind="offer", date=e["date"], message=offer_alert_text(e["offer_kind"], e["left"], _mon_ru(e["date"])) + " — по данным Мосбиржи", url=""))
                else:
                    alerts.append(dict(base, id="%s|%s|%s" % (e["kind"][:2], isin, e["date"]), severity="medium" if e["left"] <= 7 else "info",
                                       kind=e["kind"], date=e["date"], message=mon_event_alert(e), url=""))
        elif offs:                                       # Мосбиржа не отдала график: остаётся дата брокера
            row["call"] = offs[0]["date"]
            for d_ in sorted({o["date"] for o in offs if o["status"] != "cancelled" and o["date"] <= (date.today() + timedelta(days=win)).isoformat()}):
                left = (datetime.strptime(d_, "%Y-%m-%d").date() - date.today()).days
                alerts.append(dict(base, id="of|%s|%s" % (isin, d_), severity="high" if left <= 7 else "medium", kind="offer",
                                   date=d_, message=offer_alert_text(offer_kind_on(offs, d_), left, _mon_ru(d_)) + " (дата брокера)", url=""))
        # --- признаки дефолта
        fl = flags.get(isin) or {}
        if fl.get("default"):
            alerts.append(dict(base, id="df|%s" % isin, severity="high", kind="default", date=today, asof=True,
                               message="По данным Мосбиржи, по выпуску допущен дефолт", url="https://www.moex.com/ru/issue.aspx?code=" + isin))
            row["flags"].append("дефолт")
        elif fl.get("tech"):
            alerts.append(dict(base, id="td|%s" % isin, severity="high", kind="default", date=today, asof=True,
                               message="По данным Мосбиржи, по выпуску был допущен технический дефолт (задержка выплаты). Проверьте, погашена ли задолженность", url="https://www.moex.com/ru/issue.aspx?code=" + isin))
            row["flags"].append("тех. дефолт")
        if last_d and last_d < _mon_ymd(10) and not (r.get("maturity") and r["maturity"] < today):
            alerts.append(dict(base, id="nt|%s|%s" % (isin, last_d), severity="medium", kind="halt", date=last_d,
                               message="Нет торгов с %s: возможна остановка торгов, проверьте выпуск" % (
                                   last_d[8:] + "." + last_d[5:7] + "." + last_d[:4]), url=""))
            row["flags"].append("нет торгов")
        rts = row["rating"]
        if rts["v"] in ("D", "C", "CC"):
            alerts.append(dict(base, id="rd|%s" % isin, severity="high", kind="default", date=today, asof=True,
                               message="Дефолтный/преддефолтный рейтинг %s (%s)" % (rts["v"], rts["agency"]), url=""))
        elif rts["watch"]:
            alerts.append(dict(base, id="wt|%s" % isin, severity="medium", kind="watch", date=today, asof=True,
                               message="Рейтинг эмитента под наблюдением (по данным каталога T-Invest или журнала агентств)", url=""))
        if rts["neg"] and not rts["watch"]:
            alerts.append(dict(base, id="ng|%s" % isin, severity="info", kind="outlook", date=today, asof=True,
                               message="Негативный прогноз по рейтингу (%s)" % (rts["agency"] or ""), url=""))
        # --- ликвидность
        dts = row["days_to_sell"]
        if liquidity and h and (dts is None or dts > th["mon_sell_days"]):
            row["flags"].append("неликвид")
            alerts.append(dict(base, id="lq|%s|%s" % (isin, today[:7]), severity="info", kind="liquidity", date=today, asof=True,
                               message=("Нет оборота за 30 дней: продать позицию быстро не получится" if dts is None else
                                        "Низкая ликвидность: на продажу позиции нужно ~%s дн. (при 20%% дневного оборота)" % str(dts).replace(".", ",")),
                               url=""))
        out_rows.append(row)
    alerts += _mon_rating_alerts(rows_keys, events, _mon_ymd(MON_RT_DAYS), today)
    # дубль «под наблюдением» из каталога не нужен, если журнал уже сообщил о том же эмитенте
    wt_logged = {i for a in alerts if a["kind"] == "rating" for i in a.get("isins") or []}
    alerts = [a for a in alerts if not (a["kind"] in ("watch", "outlook") and a["isin"] in wt_logged)]
    alerts.sort(key=lambda a: (_SEV[a["severity"]], _neg(a["date"])))
    for a in alerts:
        for r in out_rows:
            if r["isin"] in (a.get("isins") or []):
                r["n_" + a["severity"]] = r.get("n_" + a["severity"], 0) + 1
    out_rows.sort(key=lambda r: (-(r.get("n_high") or 0), -(r.get("n_medium") or 0), -(r.get("value_rub") or 0)))
    tm["total"] = round(time.time() - t0, 2)
    return {"updated": time.time(), "thresholds": th, "alerts": alerts, "rows": out_rows,
            "summary": {s: sum(1 for a in alerts if a["severity"] == s) for s in _SEV}, "timings": tm, "notes": notes,
            "log": {"events": len(events), "since": min((e["date"] for e in events), default=None)},
            "cal_days": ndays}


def _neg(d):
    """Ключ для сортировки дат по убыванию."""
    return tuple(-ord(c) for c in d or "")


def monitor_watch_rows(isins):
    """Строки списка наблюдения в формате build_bonds (из строк скринера Мосбиржи и каталога T-Invest)."""
    sec = {}
    for s in screener_rows():
        if s.get("isin"):
            sec[s["isin"]] = s
    rows = []
    for isin in isins:
        s = sec.get(isin)
        if not s:
            continue
        ci = tcat_info(isin) or {}
        rows.append({"isin": isin, "name": s.get("name"), "ticker": s.get("id"), "value_rub": 0, "qty": 1, "maturity": s.get("mat"),
                     "call": s.get("offer"), "call_kind": "put" if s.get("offer") else None, "floating": bool(ci.get("floating")), "price_pct": s.get("price"),
                     "dur": s.get("dur"), "spread": s.get("spread"), "ytm": s.get("yield"),
                     "rating": best_rating(isin, ci.get("name") or s.get("name") or "")})
    return rows


def build_monitor_for(cfg, isins):
    """Те же проверки, что в «Мониторинге», для списка ISIN (без позиции в портфеле: ликвидность и стоимость не считаются)."""
    th = mon_thresholds(cfg)
    isins = sorted(set(i for i in isins if i))
    key = ("monitor_for", tuple(isins), tuple(sorted(th.items())))
    hit = mem_get(key, 300)
    if hit:
        return hit
    with _mon_lock:
        hit = mem_get(key, 300)
        if hit:
            return hit
        t0 = time.time()
        notes = []
        try:
            rows = monitor_watch_rows(isins)
        except Exception as e:  # noqa: BLE001
            rows = []
            notes.append("Скринер Мосбиржи недоступен: %s" % str(e)[:80])
        res = _monitor_core(rows, th, t0, {}, notes, liquidity=False)
        mem_put(key, res)
        return res
# ═══════════════════════════════ сравнение с рынком: индексы и фонды Мосбиржи ═══════════════════════════════
# Наружу уходят только обезличенные GET-запросы к iss.moex.com (история индексов и фондов); состав портфеля никуда не передаётся.

BENCH_CATALOG = [
    {"code": "RGBITR", "kind": "index", "group": "Индексы облигаций", "name": "ОФЗ (индекс гособлигаций)",
     "note": "Государственные облигации России с учётом купонов. Почти без кредитного риска, но цена заметно колеблется при смене ставок."},
    {"code": "RUCBTRNS", "kind": "index", "group": "Индексы облигаций", "name": "Корпоративные облигации (индекс)",
     "note": "Широкая корзина облигаций российских компаний с учётом купонов. Главный ориентир для облигационного портфеля."},
    {"code": "RUCBHYTR", "kind": "index", "group": "Индексы облигаций", "name": "Высокодоходные облигации — индекс ВДО",
     "note": "Облигации небольших компаний с повышенным риском (ВДО). Платят больше, но чаще встречаются просадки и дефолты."},
    {"code": "LQDT", "kind": "fund", "group": "Фонды ликвидности", "name": "LQDT — ликвидность (ВИМ)",
     "note": "Фонд денежного рынка: деньги «лежат» под ставку РЕПО, продаются в день сделки. Самый простой безрисковый ориентир."},
    {"code": "TMON", "kind": "fund", "group": "Фонды ликвидности", "name": "TMON — Денежный рынок (Т-Капитал)",
     "note": "Фонд денежного рынка от Т-Капитала. Работает по тому же принципу, что и LQDT."},
    {"code": "SBMM", "kind": "fund", "group": "Фонды ликвидности", "name": "SBMM — Сберегательный (УК «Первая»)",
     "note": "Фонд денежного рынка от УК «Первая»."},
    {"code": "AKMM", "kind": "fund", "group": "Фонды ликвидности", "name": "AKMM — Денежный рынок (Альфа-Капитал)",
     "note": "Фонд денежного рынка от Альфа-Капитала."},
    {"code": "SBRB", "kind": "fund", "group": "Облигационные фонды", "name": "SBRB — Корпоративные облигации (УК «Первая»)",
     "note": "Фонд, который накапливает купоны в цене пая (выплат пайщикам нет). Диверсифицированная корзина облигаций."},
    {"code": "AKMB", "kind": "fund", "group": "Облигационные фонды", "name": "AKMB — Управляемые облигации (Альфа-Капитал)",
     "note": "Облигационный фонд без выплат: доход остаётся в цене пая."},
    {"code": "TBRU", "kind": "fund", "group": "Облигационные фонды", "name": "TBRU — Облигации (Т-Капитал)",
     "note": "Облигационный фонд без выплат: доход остаётся в цене пая."},
]
BENCH_RF = {"code": "RUSFAR", "kind": "index", "group": "Ставка денежного рынка", "name": "Ставка RUSFAR (накопленная)",
            "note": "Ставка однодневного межбанковского кредита. Накопленная — как если бы деньги каждый день размещались под эту ставку."}
BENCH_PERIODS = ("1m", "3m", "6m", "12m", "3y", "ytd", "py", "all")      # сроки сравнения (на странице свой выбор срока)
BENCH_TTL = 6 * 3600
BENCH_FROM_MIN = "2019-01-01"
_bench_locks, _bench_locks_lock, _bench_fail = {}, threading.Lock(), {}
_bench_rf_memo = {}


def _bench_kind(code):
    for b in BENCH_CATALOG + [BENCH_RF]:
        if b["code"] == code:
            return b["kind"]
    return "index"


def _bench_iss(url):
    last = None
    for i in range(3):
        try:
            return json.loads(http_text(url, 30))
        except Exception as e:  # noqa: BLE001
            last = e
            time.sleep(0.4 * (i + 1))
    raise last


def _bench_fetch(code, frm, to=None):
    """Дневные закрытия с Мосбиржи (ISS отдаёт страницами по 100 строк). Фонд на нескольких досках за день — строка с максимальным оборотом."""
    fund = _bench_kind(code) == "fund"
    mkt = "shares" if fund else "index"
    h = ds_history(mkt, code, frm, to)               # архив сервера: один запрос вместо ~20 страниц ISS
    if h and str(h.get("cov_from") or "9") <= frm:     # архив покрывает весь запрошенный срок без пропусков
        return {r[0]: float(r[1]) for r in h["rows"] if r and r[1] is not None}
    cols = "BOARDID,TRADEDATE,CLOSE,VALUE" if fund else "TRADEDATE,CLOSE"
    out, best, start = {}, {}, 0
    for _ in range(80):
        url = ("https://iss.moex.com/iss/history/engines/stock/markets/%s/securities/%s.json?from=%s%s&start=%d"
               "&iss.only=history,history.cursor&history.columns=%s") % (mkt, code, frm, "&till=" + to if to else "", start, cols)
        j = _bench_iss(url)
        rows = (j.get("history") or {}).get("data") or []
        for r in rows:
            if fund:
                _, d, c, v = r
                if c is None:
                    continue
                if d not in best or (v or 0) >= best[d]:
                    best[d], out[d] = (v or 0), float(c)
            elif r[1] is not None:
                out[r[0]] = float(r[1])
        cur = ((j.get("history.cursor") or {}).get("data") or [[0, 0, 100]])[0]
        start = cur[0] + len(rows)
        if not rows or start >= cur[1]:
            break
    return out


def bench_history(code, frm=None, force=False):
    """{дата: закрытие}. Кэш в SQLite под ключом bench_v1:{CODE}: дозагружается хвост (с последней даты минус 5 дней)
    не чаще раза в 6 часов, а при запросе более ранней даты — начало. При сбое сети отдаётся прежний кэш."""
    frm = max(frm or BENCH_FROM_MIN, BENCH_FROM_MIN)
    key = "bench_v1:" + code
    with _bench_locks_lock:
        lk = _bench_locks.setdefault(code, threading.Lock())
    with lk:
        c = store().get(key)
        now = time.time()
        failed = now - _bench_fail.get(code, 0) < 300
        try:
            if not c or not c.get("d"):
                if failed:
                    return {}
                c = {"t": now, "from": frm, "d": _bench_fetch(code, frm)}
                store().put(key, c)
            else:
                changed = False
                if frm < c["from"] and not failed:
                    c["d"].update(_bench_fetch(code, frm, (datetime.strptime(c["from"], "%Y-%m-%d") + timedelta(days=7)).strftime("%Y-%m-%d")))
                    c["from"] = frm
                    changed = True
                if (force or now - c["t"] > BENCH_TTL) and not failed:
                    last = max(c["d"])
                    since = (datetime.strptime(last, "%Y-%m-%d") - timedelta(days=5)).strftime("%Y-%m-%d")
                    c["d"].update(_bench_fetch(code, since))
                    c["t"] = now
                    changed = True
                if changed:
                    store().put(key, c)
        except Exception:  # noqa: BLE001
            _bench_fail[code] = now
            return (c or {}).get("d") or {}
        return c["d"]


def _bench_carry(series, days):
    """Значения ряда на каждый календарный день с переносом последнего известного вперёд (до первой даты — None)."""
    ks = sorted(series)
    out, j, cur = [], 0, None
    for d in days:
        while j < len(ks) and ks[j] <= d:
            cur = series[ks[j]]
            j += 1
        out.append(cur)
    return out


def bench_rusfar_acc(frm=None):
    """RUSFAR — это ставка в % годовых. Накопленный доход: произведение (1 + r/100/365) по календарным дням. {дата: уровень}."""
    rates = bench_history("RUSFAR", frm)
    if not rates:
        return {}
    ks = sorted(rates)
    memo = _bench_rf_memo.get("v")
    if memo and memo[0] == (len(ks), ks[0], ks[-1]):
        return memo[1]
    d0, d1 = datetime.strptime(ks[0], "%Y-%m-%d").date(), date.today()
    lvl, r, out, j, d = 1.0, rates[ks[0]], {}, 0, d0
    while d <= d1:
        ds = d.isoformat()
        while j < len(ks) and ks[j] <= ds:
            r = rates[ks[j]]
            j += 1
        lvl *= 1 + r / 100.0 / 365.0
        out[ds] = lvl
        d += timedelta(days=1)
    _bench_rf_memo["v"] = ((len(ks), ks[0], ks[-1]), out)
    return out


def bench_lqdt_yield():
    """Текущая доходность фонда ликвидности LQDT, % годовых: рост цены пая за последние 30 дней, пересчитанный на год
    ((P_t / P_t-30) ^ (365 / дни) - 1). None при ошибке. Вызывается и из других разделов (калькулятор, скринер)."""
    key = "bench_lqdt_yield_v1"
    try:
        hit = store().get(key, 3 * 3600)
        if hit and hit.get("v") is not None:
            return hit["v"]
        frm = (date.today() - timedelta(days=75)).isoformat()
        h = bench_history("LQDT", frm)
        if len(h) < 5:
            return None
        ks = sorted(h)
        last = ks[-1]
        if (date.today() - datetime.strptime(last, "%Y-%m-%d").date()).days > 10:
            return None
        target = (datetime.strptime(last, "%Y-%m-%d") - timedelta(days=30)).strftime("%Y-%m-%d")
        i = bisect.bisect_right(ks, target) - 1
        if i < 0:
            return None
        days = (datetime.strptime(last, "%Y-%m-%d") - datetime.strptime(ks[i], "%Y-%m-%d")).days
        if days < 20 or h[ks[i]] <= 0:
            return None
        v = ((h[last] / h[ks[i]]) ** (365.0 / days) - 1) * 100
        v = round(v, 2)
        store().put(key, {"v": v, "d": last})
        return v
    except Exception:  # noqa: BLE001
        return None


# ── расчёты ──

def _bn_stats(xs):
    n = len(xs)
    if n < 2:
        return 0.0, 0.0
    m = sum(xs) / n
    return m, (sum((x - m) ** 2 for x in xs) / (n - 1)) ** 0.5


def _bn_risk(idx, lv, rf, pt=None):
    """Риск-метрики по точкам-индексам idx (торговые дни). lv/rf — уровни по календарным дням. pt — доходности портфеля для беты."""
    L = [lv[i] for i in idx]
    if len(L) < 3 or any(x is None or x <= 0 for x in L):
        return None
    r = [L[k] / L[k - 1] - 1 for k in range(1, len(L))]
    ex = []
    for k in range(1, len(idx)):
        a, b = rf[idx[k - 1]], rf[idx[k]]
        ex.append(r[k - 1] - ((b / a - 1) if a and b else 0.0))
    m, sd = _bn_stats(r)
    peak, dd = L[0], 0.0
    for x in L:
        peak = max(peak, x)
        dd = min(dd, x / peak - 1)
    res = {"vol": sd * 252 ** 0.5, "maxdd": dd, "n": len(r),
           "sharpe": (_bn_stats(ex)[0] / sd * 252 ** 0.5) if sd > 1e-9 else None, "ret": r}
    return res


def _bn_cov(a, b):
    n = min(len(a), len(b))
    if n < 3:
        return None, None
    ma, mb = sum(a) / n, sum(b) / n
    cov = sum((a[i] - ma) * (b[i] - mb) for i in range(n)) / (n - 1)
    va = sum((x - ma) ** 2 for x in a) / (n - 1)
    vb = sum((x - mb) ** 2 for x in b) / (n - 1)
    beta = cov / vb if vb > 1e-14 else None
    corr = cov / (va * vb) ** 0.5 if va > 1e-14 and vb > 1e-14 else None
    return beta, corr


def _bn_window(days, period):
    today = date.today()
    last = len(days) - 1
    s = e = None
    if period == "1m":
        s = (today - timedelta(days=30)).isoformat()
    elif period == "3m":
        s = (today - timedelta(days=91)).isoformat()
    elif period == "6m":
        s = (today - timedelta(days=182)).isoformat()
    elif period == "12m":
        s = (today - timedelta(days=365)).isoformat()
    elif period == "3y":
        s = (today - timedelta(days=1096)).isoformat()
    elif period == "ytd":
        s = "%d-01-01" % today.year
    elif period == "py":
        s, e = "%d-01-01" % (today.year - 1), "%d-12-31" % (today.year - 1)
    i0 = 0
    if s:
        i0 = next((i for i, d in enumerate(days) if d >= s), None)
        if i0 is None:
            return None
        i0 = max(0, i0 - 1)
    i1 = last
    if e:
        while i1 > 0 and days[i1] > e:
            i1 -= 1
    if i1 <= i0:
        return None
    return i0, i1


def _bn_thin(n, k=400):
    if n <= k:
        return list(range(n))
    step = (n - 1) / float(k - 1)
    idx = sorted({int(round(i * step)) for i in range(k)} | {n - 1})
    return idx


def bench_liquidity(cfg, acc, total):
    mon = build_monitor(cfg, acc)
    rows = [r for r in (mon.get("rows") or []) if (r.get("value_rub") or 0) > 0]
    defs = [("d1", "до 1 дня", lambda x: x <= 1), ("d5", "1–5 дней", lambda x: 1 < x <= 5), ("dm", "больше 5 дней", lambda x: x > 5)]
    bv = sum(r["value_rub"] for r in rows)
    out = []
    for k, label, fn in defs:
        sel = [r for r in rows if r.get("days_to_sell") is not None and fn(r["days_to_sell"])]
        out.append({"key": k, "label": label, "value": sum(r["value_rub"] for r in sel), "count": len(sel)})
    sel = [r for r in rows if r.get("days_to_sell") is None]
    out.append({"key": "na", "label": "нет данных", "value": sum(r["value_rub"] for r in sel), "count": len(sel)})
    for b in out:
        b["share"] = b["value"] / bv * 100 if bv else None
        b["share_total"] = b["value"] / total * 100 if total else None
    slow = sorted([r for r in rows if r.get("days_to_sell") is not None], key=lambda r: -r["days_to_sell"])[:8]
    return {"bonds_value": bv, "bonds_count": len(rows), "portfolio_value": total, "buckets": out,
            "slowest": [{"name": r.get("name"), "isin": r.get("isin"), "value_rub": r["value_rub"], "days": r["days_to_sell"],
                         "turnover": r.get("turnover_avg")} for r in slow],
            "part": MON_PART * 100, "fund_days": 0}


def bench_premium(cfg, acc):
    lq = bench_lqdt_yield()
    b = build_bonds(cfg, acc)
    m = b.get("metrics") or {}
    rows = [r for r in (b.get("rows") or []) if r.get("ytm") is not None and (r.get("value_rub") or 0) > 0 and r.get("qty")]
    ok = [r for r in rows if r["ytm"] <= YTM_HIGH]
    wv = sum(r["value_rub"] for r in ok)
    res = {"lqdt": lq, "ytm_ex": sum(r["ytm"] * r["value_rub"] for r in ok) / wv if wv else None, "ytm": m.get("ytm"), "irr": m.get("irr"), "ytm_tax": m.get("ytm_tax"), "bonds_value": m.get("value"),
           "count": m.get("count"), "high_yield_value": m.get("high_yield_value"), "below": [], "below_value": 0.0}
    if lq is not None:
        res["prem_ytm"] = m["ytm"] - lq if m.get("ytm") is not None else None
        res["prem_ytm_ex"] = res["ytm_ex"] - lq if res["ytm_ex"] is not None else None
        res["prem_irr"] = m["irr"] - lq if m.get("irr") is not None else None
        bl = sorted([r for r in rows if r["ytm"] < lq], key=lambda r: r["ytm"] - lq)
        res["below_value"] = sum(r["value_rub"] for r in bl)
        res["below"] = [{"name": r.get("name"), "isin": r.get("isin"), "ytm": r["ytm"], "diff": r["ytm"] - lq, "value_rub": r["value_rub"]} for r in bl[:12]]
        res["below_count"] = len(bl)
    return res


def bench_payload(cfg, acc, q=None):
    q = q or {}
    period = q.get("period") or "all"
    if period not in BENCH_PERIODS:
        period = "all"
    want = {c for c in (q.get("codes") or "").replace(";", ",").split(",") if c}
    key = ("bench", token_key(cfg), acc, period, tuple(sorted(want)))
    hit = mem_get(key, 600)
    if hit:
        return hit
    h = build_history_for(cfg, acc)
    days = h.get("days") or []
    if len(days) < 3:
        return {"error": "Нет операций для сравнения: история портфеля пуста."}
    win = _bn_window(days, period)
    if not win:
        return {"error": "За выбранный период нет данных по портфелю. Выберите период длиннее."}
    i0, i1 = win
    notes = []
    frm = (datetime.strptime(days[i0], "%Y-%m-%d") - timedelta(days=12)).strftime("%Y-%m-%d")
    cat = [b for b in BENCH_CATALOG if not want or b["code"] in want]
    jobs = [b["code"] for b in cat] + ["RUSFAR"]
    if not any(b["code"] == "LQDT" for b in cat):
        jobs.append("LQDT")      # календарь торговых дней
    jobs = list(dict.fromkeys(jobs))
    hs = dict(zip(jobs, pool_map(lambda c: bench_history(c, frm), jobs, workers=6)))
    # торговые дни Мосбиржи
    cal_src = hs.get("LQDT") or next((v for v in hs.values() if v), {})
    d_start, d_end = days[i0], days[i1]
    cal = sorted(d for d in cal_src if d_start < d <= d_end)
    didx = {d: i for i, d in enumerate(days)}
    cal_i = [didx[d] for d in cal if d in didx]
    # безрисковая ставка
    acc_rf = bench_rusfar_acc(frm)
    rf = _bench_carry(acc_rf, days) if acc_rf else [None] * len(days)
    if not acc_rf:
        notes.append("Ставка RUSFAR не загрузилась: коэффициент Шарпа посчитан без вычета безрисковой ставки.")
    elif acc_rf and min(acc_rf) > d_start:
        notes.append("Данные RUSFAR начинаются с %s: до этой даты безрисковая ставка принята равной нулю." % min(acc_rf))
    val, inv, twr = h["value"], h["invested"], h["twr"]
    # портфель
    base_t = twr[i0]
    pw = [x / base_t - 1 for x in twr[i0:i1 + 1]]
    years = (datetime.strptime(d_end, "%Y-%m-%d") - datetime.strptime(d_start, "%Y-%m-%d")).days / 365.25
    total = pw[-1]
    ann = (1 + total) ** (1 / years) - 1 if years >= 0.98 and total > -1 else None
    pidx = [i0] + cal_i
    prk = _bn_risk(pidx, twr, rf)
    if prk:
        k = max(range(len(prk["ret"])), key=lambda n: abs(prk["ret"][n]))
        if abs(prk["ret"][k]) > 0.1:
            notes.append("В истории портфеля есть резкий скачок %s%% за один торговый день (%s). Обычно это следствие неполных цен по какой-то бумаге; "
                         "из-за такого скачка волатильность, просадка и бета портфеля за период могут быть завышены." % (
                             ("%+.0f" % (prk["ret"][k] * 100)).replace("-", "−"), days[pidx[k + 1]]))
    flows = [(i, inv[i] - inv[i - 1]) for i in range(i0 + 1, i1 + 1) if abs(inv[i] - inv[i - 1]) > 0.005]
    net_flow = sum(f for _, f in flows)
    dts = [datetime.strptime(d, "%Y-%m-%d").date() for d in days]

    def xr(v_end, series_flows):
        fl = ([(dts[i0], -val[i0])] if val[i0] > 0 else []) + [(dts[i], -f) for i, f in series_flows] + [(dts[i1], v_end)]
        if years < 0.25:       # годовая ставка по коротким отрезкам вводит в заблуждение
            return None
        try:
            return xirr(fl)
        except Exception:  # noqa: BLE001
            return None

    pf = {"ret": total * 100, "ann": ann * 100 if ann is not None else None,
          "vol": prk["vol"] * 100 if prk else None, "maxdd": prk["maxdd"] * 100 if prk else None,
          "sharpe": prk["sharpe"] if prk else None, "xirr": (lambda x: x * 100 if x is not None else None)(xr(val[i1], flows)),
          "value_start": val[i0], "value_end": val[i1], "net_flow": net_flow, "gain": val[i1] - val[i0] - net_flow}
    # график: проредить
    tix = _bn_thin(i1 - i0 + 1)
    sd = [days[i0 + k] for k in tix]
    series = {"dates": sd, "portfolio": [round(pw[k] * 100, 3) for k in tix], "bench": {}}
    out = []
    for b in cat + [BENCH_RF]:
        code = b["code"]
        if code == "RUSFAR":
            if not acc_rf:
                continue
            lv = rf
        else:
            ser = hs.get(code) or {}
            if not ser:
                out.append(dict(b, available=False, reason="Мосбиржа не отдала историю"))
                continue
            lv = _bench_carry(ser, days)
        j = next((i for i in range(i0, i1 + 1) if lv[i]), None)
        if j is None or j > i1 - 5:
            out.append(dict(b, available=False, reason="нет данных за период"))
            continue
        partial = j > i0 + 7
        if partial:
            notes.append("%s: история в выбранном периоде начинается с %s." % (code, days[j]))
        j = max(j, i0)
        b0 = lv[j]
        cum = [None if lv[i] is None or i < j else lv[i] / b0 - 1 for i in range(i0, i1 + 1)]
        series["bench"][code] = [None if cum[k] is None else round(cum[k] * 100, 3) for k in tix]
        tot_b = cum[-1]
        yrs = (datetime.strptime(d_end, "%Y-%m-%d") - datetime.strptime(days[j], "%Y-%m-%d")).days / 365.25
        ann_b = (1 + tot_b) ** (1 / yrs) - 1 if yrs >= 0.98 and tot_b > -1 else None
        idx = [j] + [i for i in cal_i if i > j]
        rk = _bn_risk(idx, lv, rf)
        e = dict(b, available=True, partial=partial, start=days[j], ret=tot_b * 100, ann=ann_b * 100 if ann_b is not None else None,
                 vol=rk["vol"] * 100 if rk else None, maxdd=rk["maxdd"] * 100 if rk else None,
                 sharpe=rk["sharpe"] if (rk and code != "RUSFAR") else None, beta=None, corr=None, same=None)
        if rk and prk and code != "RUSFAR":
            pr = _bn_risk(idx, twr, rf)
            if pr:
                e["beta"], e["corr"] = _bn_cov(pr["ret"], rk["ret"])
        # «те же деньги в тот же день — в бенчмарк»
        if code != "RUSFAR":
            u = val[j] / lv[j] if val[j] > 0 else 0.0
            sf, ok = [], True
            for i in range(j + 1, i1 + 1):
                f = inv[i] - inv[i - 1]
                if abs(f) > 0.005:
                    if not lv[i]:
                        ok = False
                        break
                    u += f / lv[i]
                    sf.append((i, f))
            if ok and u >= 0:
                fin = u * lv[i1]
                nf = sum(f for _, f in sf)
                x = None
                if j == i0:
                    x = xr(fin, sf)
                e["same"] = {"final": fin, "diff": val[i1] - fin, "gain": fin - val[j] - nf, "xirr": x * 100 if x is not None else None}
        out.append(e)
    res = {"period": period, "start": d_start, "end": d_end, "years": years, "series": series, "portfolio": pf,
           "bench": out, "groups": list(dict.fromkeys([b["group"] for b in BENCH_CATALOG] + [BENCH_RF["group"]])),
           "trading_days": len(cal_i), "notes": notes}
    try:
        res["liquidity"] = bench_liquidity(cfg, acc, val[-1])
    except Exception as e:  # noqa: BLE001
        res["liquidity"] = None
        notes.append("Данные о ликвидности недоступны: %s" % str(e)[:100])
    try:
        res["premium"] = bench_premium(cfg, acc)
    except Exception as e:  # noqa: BLE001
        res["premium"] = None
        notes.append("Данные о доходности облигаций недоступны: %s" % str(e)[:100])
    res["lqdt_yield"] = bench_lqdt_yield()
    return mem_put(key, res)
# ═══════════════════════════════ калькулятор инвестиций: параметры рынка ═══════════════════════════════

CALC_TTL = 3600
CALC_LOSS_GIVEN_DEFAULT = 0.75      # потери при дефолте: 1 − ставка возмещения 25 %
CALC_STOCKS = {"div": 8.0, "growth": 6.0, "sigma": 22.0, "estimate": True}     # акции РФ: дивидендная доходность, рост цены, годовой разброс, %
CALC_FX_BONDS = {"yield": 6.0, "fx": 5.0, "sigma": 12.0, "estimate": True}     # замещающие облигации: купон в валюте, ослабление рубля %/год, разброс курса
CALC_FLT_SPREAD = 1.5               # запасной спред флоатеров к ключевой ставке, п.п.
_calc_mem = {}


def _calc_med(xs):
    xs = sorted(x for x in xs if x is not None)
    if not xs:
        return None
    n = len(xs)
    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2.0


def _calc_plain_bond(r, ti=None):
    """Обычный выпуск с постоянным купоном: без флоатеров, линкеров, бессрочных и субординированных (их доходность и дюрация искажают медианы)."""
    if r.get("floating") or r.get("linker"):
        return False
    sub = str(r.get("sub") or "").lower()
    if "floater" in sub or "linker" in sub or "суборд" in sub:
        return False
    if ti and r.get("isin"):
        try:
            ci = ti(r["isin"]) or {}
        except Exception:  # noqa: BLE001
            ci = {}
        if ci.get("perpetual") or ci.get("subordinated"):
            return False
    return True


def _calc_segments(key_rate):
    """Сегменты рынка: ОФЗ, AAA, AA, A, ВДО (с постоянным купоном) и флоатеры (ключевая + спред): текущая медианная доходность и дюрация.
    Что не нашли — запасной вариант с флагом."""
    pd = RISK_PD_HIST
    loss = lambda *ks: sum(pd[k] for k in ks) / len(ks) / 100.0 * CALC_LOSS_GIVEN_DEFAULT
    # ожидаемые годовые потери: средняя вероятность дефолта по рейтингам сегмента × (1 − 0,25)
    meta = {"ofz": ("ОФЗ", 0.0), "aaa": ("Корпоративные AAA", loss("AAA")),
            "aa": ("Корпоративные AA", loss("AA+", "AA", "AA-")),
            "a": ("Корпоративные A", loss("A+", "A", "A-")),
            "hy": ("ВДО (BB и ниже)", loss("BB+", "BB", "BB-", "B+")),
            "flt": ("Флоатеры (ключевая + спред)", loss("AA+", "AA", "AA-"))}
    fb = {"ofz": (key_rate - 0.5, 4.0), "aaa": (key_rate + 0.5, 2.5), "aa": (key_rate + 1.5, 2.5),
          "a": (key_rate + 3.0, 2.0), "hy": (key_rate + 8.0, 1.5), "flt": (key_rate + CALC_FLT_SPREAD, 0.25)}
    got = {}
    try:
        sp = screener_payload()
        rows = sp.get("rows") or []
        ti = globals().get("tcat_info")
        plain = [r for r in rows if _calc_plain_bond(r, ti)]
        buckets = {"aaa": "AAA", "aa": "AA", "a": "A", "hy": "BB и ниже"}
        for k, b in buckets.items():
            sel = [r for r in plain if r.get("kind") == "corp" and r.get("cur") == "RUB" and r.get("rating")
                   and rating_bucket(r["rating"]) == b and 0 < r["yield"] < 60 and (r.get("dur") or 0) > 0.1]
            if len(sel) >= 3:
                got[k] = (_calc_med([r["yield"] for r in sel]), _calc_med([r["dur"] for r in sel]), len(sel))
        sel = [r for r in plain if r.get("kind") == "ofz" and r.get("cur") == "RUB" and 0 < r["yield"] < 60 and (r.get("dur") or 0) > 0.1]
        if len(sel) >= 3:
            got["ofz"] = (_calc_med([r["yield"] for r in sel]), _calc_med([r["dur"] for r in sel]), len(sel))
        fl = [r for r in rows if r.get("floating") and not r.get("linker") and r.get("cur") == "RUB" and r.get("kind") in ("corp", "ofz")
              and 0 < (r.get("yield") or 0) < 60]
        if len(fl) >= 3:
            spr = max(-1.0, min(8.0, _calc_med([r["yield"] for r in fl]) - key_rate))
            got["flt"] = (key_rate + spr, _calc_med([r.get("dur") or 0.25 for r in fl]), len(fl))
    except Exception:  # noqa: BLE001
        pass
    out = {}
    for k, (name, ls) in meta.items():
        g = got.get(k)
        out[k] = {"name": name, "yield": round(g[0] if g else fb[k][0], 2), "dur": round(g[1] if g else fb[k][1], 2),
                  "loss": round(ls * 100, 3), "n": g[2] if g else 0, "estimate": g is None}
    out["flt"]["spread"] = round(out["flt"]["yield"] - key_rate, 2)
    return out


def _calc_shares(positions):
    """Доли классов активов портфеля по стоимости: облигации, акции, прочие фонды, фонды ликвидности, деньги (валюта), остальное."""
    mm = set(globals().get("MM_FUND_SEED") or ())
    w = {"bonds": 0.0, "stocks": 0.0, "funds": 0.0, "lqdt": 0.0, "cash": 0.0, "other": 0.0}
    for r in positions or []:
        v = r.get("value_rub") or 0.0
        t = r.get("type")
        if v <= 0 or t == "futures":
            continue
        if t == "bond":
            w["bonds"] += v
        elif t == "share":
            w["stocks"] += v
        elif t == "etf":
            w["lqdt" if (r.get("ticker") or "").upper() in mm else "funds"] += v
        elif t == "currency":
            w["cash"] += v
        else:
            w["other"] += v
    tot = sum(w.values())
    return {k: round(v / tot, 4) for k, v in w.items()} if tot > 0 else None


def _calc_income_month(cfg, acc):
    """Доход портфеля в месяц до налога: купоны и дивиденды по графику на 12 месяцев вперёд; None, если графика нет."""
    try:
        end = (date.today() + timedelta(days=365)).isoformat()
        pays = [p for p in (build_bonds(cfg, acc).get("payments") or []) if p.get("kind") in ("coupon", "dividend") and p.get("date", "") <= end]
        if pays:
            return round(sum(p["amount"] for p in pays) / 12.0, 2)
    except Exception:  # noqa: BLE001
        pass
    return None


def _calc_portfolio(cfg, acc):
    """Портфель целиком: стоимость, доли классов активов, доходность и дюрация облигационной части, купоны. Калькулятор считает «Мой портфель»
    как смесь частей (облигации с их дюрацией, акции, фонды ликвидности, деньги), а не как одну облигацию на весь капитал."""
    if not (cfg.get("token") or "").strip() and not imports_list():
        return None
    pf = {"value": None, "bonds_value": None, "irr": None, "irr_tax": None, "monthly": None, "coupons_12m": None,
          "shares": None, "dur_bonds": None, "income_month": None}
    s = None
    try:
        s = build_summary(cfg, acc, "all")
        pf["value"] = round(s["portfolio"]["total"], 2)
        pf["bonds_value"] = round(s["portfolio"]["bonds"], 2)
        pf["shares"] = _calc_shares(s["portfolio"].get("positions"))
    except Exception:  # noqa: BLE001
        pass
    try:
        if s:
            lim = (date.today() - timedelta(days=365)).strftime("%Y-%m")
            net = 0.0
            for m, v in s.get("months") or []:
                if m >= lim:
                    net += (v.get("deposits") or 0.0) - (v.get("withdrawals") or 0.0)
            pf["monthly"] = round(max(net, 0.0) / 12.0, 2)
    except Exception:  # noqa: BLE001
        pass
    try:
        bd = build_bonds(cfg, acc)
        m = bd.get("metrics") or {}
        irr = m.get("irr") if m.get("irr") is not None else m.get("ytm")
        if irr is not None:
            pf["irr"] = round(irr, 2)
        irt = m.get("irr_tax")
        if irt is not None:
            pf["irr_tax"] = round(irt, 2)
        pf["coupons_12m"] = round(m.get("coupons_12m") or 0.0, 2)
        dv = [(r["dur"], r.get("value_rub") or 0.0) for r in bd.get("rows") or [] if r.get("dur") and not r.get("floating") and (r.get("value_rub") or 0) > 0]
        if dv and sum(v for _, v in dv) > 0:
            pf["dur_bonds"] = round(sum(d * v for d, v in dv) / sum(v for _, v in dv), 2)
    except Exception:  # noqa: BLE001
        pass
    pf["income_month"] = _calc_income_month(cfg, acc)
    if all(pf[k] is None for k in ("value", "irr")):
        return None
    return pf


def calc_params(cfg, acc):
    key = (token_key(cfg), acc)
    hit = _calc_mem.get(key)
    if hit and time.time() - hit[0] < CALC_TTL:
        return hit[1]
    res = {"error": None}
    kr, path, kr_src, kr_est = None, [], "", True
    try:
        info = keyrate_forecast_info()
        kr = info.get("key_rate")
        path = [[p[0], p[1]] for p in info.get("path") or []]
        kr_src = info.get("source_name") or ""
        kr_est = info.get("source") == "none"
    except Exception:  # noqa: BLE001
        pass
    if kr is None:
        kr, kr_est = (path[0][1] if path else 16.0), True
        kr_src = kr_src or "нет данных (условное значение)"
    if not path:
        path = [[date.today().isoformat(), kr]]
    res["key_rate"] = {"current": kr, "source": kr_src, "estimate": kr_est, "path": path}
    infl = {"source": "none", "yearly": [], "estimate": True, "default": 4.0}
    try:
        i = inflation_forecast()
        if i.get("source") != "none" and i.get("yearly"):
            infl = {"source": i["source"], "as_of": i.get("as_of"), "yearly": [{"year": y["year"], "mid": y["mid"]} for y in i["yearly"]],
                    "estimate": False, "default": i["yearly"][-1]["mid"]}
    except Exception:  # noqa: BLE001
        pass
    res["inflation"] = infl
    segs = _calc_segments(kr)
    try:
        pf = _calc_portfolio(cfg, acc)
    except Exception:  # noqa: BLE001
        pf = None
    res["segments"] = segs
    ly, lest = None, True
    try:
        f = globals().get("bench_lqdt_yield")
        v = f() if f else None
        if isinstance(v, dict):
            v = v.get("yield")
        if v is not None and 0 < float(v) < 60:
            ly, lest = round(float(v), 2), False
    except Exception:  # noqa: BLE001
        pass
    if ly is None:
        ly = round(kr - 0.7, 2)
    res["lqdt"] = {"yield": ly, "estimate": lest, "spread": 0.7}
    res["deposit"] = {"spread": 1.5, "rate": round(max(kr - 1.5, 0.1), 2)}
    res["stocks"] = dict(CALC_STOCKS)
    res["fx_bonds"] = dict(CALC_FX_BONDS)
    res["portfolio"] = pf
    res["updated"] = datetime.now().strftime("%H:%M")
    _calc_mem[key] = (time.time(), res)
    return res


# ═══════════════════ цель по пассивному доходу: сколько капитала и какое пополнение нужны ═══════════════════
# Упрощённая запасная модель (экран калькулятора её больше не использует: цель считается единым клиентским движком вместе со счётом, ИИС-3 и шкалой НДФЛ):
# весь капитал приносит доход по одной ставке, налог 13 % удерживается с дохода (реинвестируется остаток), взносы не индексируются. Не прогноз и не рекомендация.

GOAL_TAX = 0.13
GOAL_MAX_YEARS = 50


def goal_calc(monthly, months, yield_pct, value=0.0, infl_pct=0.0, real=False, income_now=None, tax=GOAL_TAX):
    """monthly — желаемый доход в месяц после налога, ₽; months — срок; yield_pct — доходность портфеля до налога, % годовых;
    value — текущий капитал; infl_pct — инфляция, % в год; real=True — цель задана в сегодняшних деньгах (к дате цели её нужно умножить на инфляцию).
    income_now — текущий доход в месяц (купоны и дивиденды) для оценки покрытия. Возвращает словарь с результатами."""
    monthly, value, months = max(0.0, float(monthly)), max(0.0, float(value)), int(months)
    if months < 1 or months > GOAL_MAX_YEARS * 12:
        raise ValueError("срок должен быть от 1 месяца до %d лет" % GOAL_MAX_YEARS)
    if not (0 < yield_pct < 100):
        raise ValueError("доходность должна быть больше 0 и меньше 100 %")
    y_net = yield_pct / 100.0 * (1.0 - tax)
    infl = infl_pct / 100.0 if real else 0.0
    f_inf = (1.0 + infl) ** (months / 12.0)
    goal_end = monthly * f_inf                         # желаемый доход в месяц в рублях на дату цели
    cap_today = monthly * 12.0 / y_net                # капитал, который даёт цель в сегодняшних ценах
    cap_end = goal_end * 12.0 / y_net                 # капитал на дату цели с учётом инфляции цели
    r = (1.0 + y_net) ** (1.0 / 12.0) - 1.0           # месячная ставка после налога с реинвестированием
    g = (1.0 + r) ** months
    grown = value * g
    need = max(0.0, cap_end - grown)
    contrib = need * r / (g - 1.0) if need > 0 else 0.0
    fv = lambda k, c: value * (1.0 + r) ** k + c * (((1.0 + r) ** k - 1.0) / r)
    step = 1 if months <= 60 else 3 if months <= 180 else 6
    ks = list(range(0, months + 1, step))
    if ks[-1] != months:
        ks.append(months)
    today = date.today()
    labels = []
    for k in ks:
        mm = today.month - 1 + k
        labels.append("%04d-%02d" % (today.year + mm // 12, mm % 12 + 1))
    out = {"months": months, "yield_net": round(y_net * 100.0, 3), "capital_today": cap_today, "capital_end": cap_end, "goal_end": goal_end,
           "inflation_factor": f_inf, "value": value, "value_grown": grown, "contribution": contrib, "contribution_total": contrib * months,
           "reached": need <= 0, "gap": need,
           "chart": {"labels": labels, "capital": [fv(k, contrib) for k in ks], "no_contrib": [fv(k, 0.0) for k in ks],
                     "target": [cap_today * (1.0 + infl) ** (k / 12.0) for k in ks]},
           "income_from_value": value * y_net / 12.0}
    if income_now is not None:
        out["coverage"] = {"income": income_now, "pct": (income_now / monthly * 100.0) if monthly > 0 else None}
    return out


def goal_months(q, today=None):
    """Срок в месяцах из параметров: date=ГГГГ-ММ-ДД или years (допустимы дробные)."""
    today = today or date.today()
    d = (q.get("date") or "").strip()
    if d:
        t = datetime.strptime(d, "%Y-%m-%d").date()
        if t <= today:
            raise ValueError("дата цели должна быть в будущем")
        return max(1, int(round((t - today).days / 30.4375)))
    return max(1, int(round(float(q.get("years") or 10) * 12)))


def _goal_float(q, k):
    v = (q.get(k) or "").strip().replace(",", ".")
    return float(v) if v != "" else None


def _goal_infl():
    hit = _calc_mem.get("goal_infl")
    if hit and time.time() - hit[0] < CALC_TTL:
        return hit[1]
    v = {"value": 4.0, "estimate": True, "source": "условное значение"}
    try:
        i = inflation_forecast()
        if i.get("source") != "none" and i.get("yearly"):
            v = {"value": i["yearly"][-1]["mid"], "estimate": False, "source": "прогноз Банка России"}
    except Exception:  # noqa: BLE001
        pass
    _calc_mem["goal_infl"] = (time.time(), v)
    return v


def goal_defaults(cfg, acc):
    """Что известно о портфеле: стоимость, средневзвешенная доходность облигаций, текущий доход в месяц (купоны и дивиденды за 12 мес.)."""
    d = {"value": None, "yield": None, "income_month": None, "income_src": None, "portfolio": False}
    if not (cfg.get("token") or "").strip() and not imports_list():
        return d
    key = ("goal_pf", token_key(cfg), acc)
    hit = _calc_mem.get(key)
    if hit and time.time() - hit[0] < 300:
        return hit[1]
    try:
        pf = _calc_portfolio(cfg, acc)
    except Exception:  # noqa: BLE001
        pf = None
    if pf:
        d["portfolio"] = True
        d["value"] = pf.get("value")
        d["yield"] = pf.get("irr")
        if pf.get("coupons_12m"):
            d["income_month"], d["income_src"] = round(pf["coupons_12m"] / 12.0, 2), "купоны облигаций за 12 месяцев"
    inc = _calc_income_month(cfg, acc)
    if inc is not None:
        d["income_month"], d["income_src"] = inc, "купоны и дивиденды по графику на 12 месяцев"
    _calc_mem[key] = (time.time(), d)
    return d


def calc_goal_get(cfg, acc, q, force=False):
    """GET /api/calc/goal?monthly=&years=|date=&yield=&value=&real=1&infl=  Ручные значения важнее данных портфеля; без токена работают только они."""
    real = (q.get("real") or "1") not in ("0", "false", "")
    i_param, i_err = None, None
    try:
        i_param = _goal_float(q, "infl")
    except (ValueError, TypeError) as e:
        i_err = str(e)
    infl_info = _goal_infl() if (real and i_param is None and i_err is None) else {
        "value": i_param if i_param is not None else 4.0,
        "estimate": i_param is None,
        "source": "ручной ввод" if i_param is not None else "условное значение",
    }
    out = {"defaults": goal_defaults(cfg, acc), "infl": infl_info, "tax": GOAL_TAX, "result": None, "error": None}
    if i_err is not None:
        out["error"] = i_err
        return out
    try:
        monthly = _goal_float(q, "monthly")
        if monthly is None or monthly <= 0:
            return out
        dfl = out["defaults"]
        y = _goal_float(q, "yield")
        y = dfl["yield"] if y is None else y
        if y is None:
            out["error"] = "Укажите ожидаемую доходность портфеля: данных по облигациям портфеля нет."
            return out
        v = _goal_float(q, "value")
        v = (dfl["value"] or 0.0) if v is None else v
        i = infl_info["value"] if i_param is None else i_param
        inc = _goal_float(q, "income")
        if inc is None:
            inc = dfl["income_month"] if dfl["income_month"] is not None else (v * y / 100.0 * (1 - GOAL_TAX) / 12.0 if v else None)
        out["result"] = goal_calc(monthly, goal_months(q), y, v, i, real, inc)
        out["result"].update(yield_pct=y, infl_pct=i, real=real, monthly=monthly)
    except (ValueError, TypeError) as e:
        out["error"] = str(e)
    return out


API_GET["/api/calc/goal"] = calc_goal_get
# ═══════════════════════════════ оферты и конструктор лесенки ═══════════════════════════════
# Справочные подсказки на данных Мосбиржи (bondization) и скринера; не индивидуальные инвестиционные рекомендации.
#
# Как Мосбиржа отдаёт оферты (проверено на ~540 выпусках с датой оферты, ноябрь 2026):
#  1. Список бумаг /iss/engines/stock/markets/bonds/securities[/{ISIN}].json содержит поля
#     PUTOPTIONDATE (ближайшая дата пут-оферты, право держателя; совпадает с OFFERDATE), CALLOPTIONDATE (ближайшая дата колл,
#     право эмитента), BUYBACKDATE/BUYBACKPRICE (ближайшая дата и цена выкупа, put или call — тип не различает).
#     Поля хранят только ОДНУ ближайшую дату каждого типа; пустая дата приходит как null или «0000-00-00».
#  2. bondization.json -> offers[] хранит все даты, но тип записи у него всего три значения offertype:
#     «Оферта» — пут-оферта (все будущие «Оферта» в выборке были put: совпадают с PUTOPTIONDATE или идут следующими
#     циклами, из-за этого у выпуска может быть несколько будущих put-дат);
#     «Оферта/Погашение» — досрочное погашение по усмотрению эмитента (call): дата совпадает с CALLOPTIONDATE, а запись с
#     пустой датой «0000-00-00» — просто погашение в срок, это не оферта;
#     «Оферта (состоялось)» — уже прошедшая оферта.
#     Период предъявления (offerdatestart/offerdateend) Мосбиржа публикует только перед самой офертой.
#  3. /iss/securities/{ISIN}.json (description) даёт лишь BUYBACKDATE, без типа — для классификации не нужен.
#  4. T-Invest API (Bond) отдаёт одну дату callDate без указания типа; поля даты put в API нет. Эта дата в приложении
#     считается колл, если Мосбиржа не знает такой даты как пут.
#  Среди выборки не нашлось выпуска с одновременными put и call, но код допускает обе записи (даже на одну дату).

OF_PRICE_EPS, OF_MARGIN = 0.1, 0.5      # допуск цены, п. п.; запас до медианы аналогов, п. п.
OF_CALL_WORDS = ("колл", "call", "досроч", "погашени", "усмотрен")     # право эмитента
OF_PUT_WORDS = ("put", "пут", "по требованию", "выкуп", "предъявлен")  # право держателя
OF_KIND_ORDER = {"put": 0, "call": 1, "unknown": 2}
OPT_URL = ("https://iss.moex.com/iss/engines/stock/markets/bonds/securities/%s.json?iss.meta=off&iss.only=securities"
           "&securities.columns=SECID,BOARDID,BUYBACKDATE,BUYBACKPRICE,CALLOPTIONDATE,PUTOPTIONDATE")


def moex_bond_options(isin):
    """Явные даты put/call выпуска из списка бумаг Мосбиржи: {'put': [даты], 'call': [даты], 'prices': {дата: цена}}.
    Кэш 24 ч; ошибка кэшируется на 1 ч, тогда None."""
    isin = (isin or "").strip().upper()
    if not isin or not re.match(r"^[A-Z0-9]{4,14}$", isin):
        return None
    st = store()
    key = "bopt1:" + isin
    v = st.get(key, ttl=BC_TTL)
    if v is not None:
        if v.get("ok"):
            return v
        if time.time() - v.get("ts", 0) < BC_ERR_TTL:
            return None
    try:
        rows = _bc_table(json.loads(http_text(OPT_URL % isin, 20)), "securities")
        out = {"ok": True, "ts": time.time(), "put": [], "call": [], "prices": {}}
        for r in rows:
            for fld, k in (("PUTOPTIONDATE", "put"), ("CALLOPTIONDATE", "call")):
                d = _of_date(r.get(fld))
                if d and d not in out[k]:
                    out[k].append(d)
            bd = _of_date(r.get("BUYBACKDATE"))
            if bd and r.get("BUYBACKPRICE"):
                out["prices"][bd] = r["BUYBACKPRICE"]
        out["put"].sort()
        out["call"].sort()
    except Exception:  # noqa: BLE001
        out = {"ok": False, "ts": time.time()}
    st.put(key, out)
    return out if out.get("ok") else None


OF_BROKER_NEAR = 21                                   # дней: дата брокера рядом с датой Мосбиржи — то же событие


def _of_text_kind(t, has_period):
    """Тип по тексту offertype: ('put'|'call'|'unknown', вывод сделан по слабому признаку)."""
    base = re.sub(r"\(.*?\)", "", t).strip().lower()
    if any(w in base for w in OF_CALL_WORDS):
        return "call", False
    if any(w in base for w in OF_PUT_WORDS):
        return "put", False
    if base == "оферта":                      # так Мосбиржа обозначает пут-оферту
        return "put", not has_period
    return "unknown", False


def offer_kinds(bz, opt, broker_call=None, today=None, with_done=False):
    """Все БУДУЩИЕ оферты выпуска из всех источников, без дублей по (дата, тип).
    Запись: {date, kind: put|call|unknown, source, price, period_start, period_end, status: scheduled|cancelled, inferred}.
    with_done=True добавляет и состоявшиеся оферты из bondization (status 'done'; нужно календарю за прошлые месяцы).
    Приоритет: явные поля PUTOPTIONDATE/CALLOPTIONDATE, затем тип записи bondization, затем дата брокера (присоединяется к близкой дате
    Мосбиржи, иначе 'unknown'). Одна дата может быть и put, и call — тогда две записи. Неопределимый тип — 'unknown'."""
    today = today or date.today().isoformat()
    recs = {}

    def add(d, kind, source, price=None, ps=None, pe=None, status="scheduled", inferred=False):
        if not d or d <= today:
            return
        r = recs.get((d, kind))
        if r is None:
            recs[(d, kind)] = {"date": d, "kind": kind, "source": source, "price": price, "period_start": ps,
                               "period_end": pe, "status": status, "inferred": inferred}
            return
        if source not in r["source"].split("+"):
            r["source"] += "+" + source
        for k, val in (("price", price), ("period_start", ps), ("period_end", pe)):
            if r[k] is None:
                r[k] = val
        if status == "cancelled":
            r["status"] = "cancelled"
        r["inferred"] = r["inferred"] and inferred
    prices = (opt or {}).get("prices") or {}
    for k in ("put", "call"):
        for d in (opt or {}).get(k) or []:
            add(d, k, "moex_" + k + "_field", prices.get(d))
    for o in (bz or {}).get("offers") or []:
        t = o.get("offertype") or ""
        d = _of_date(o.get("offerdate"))
        tl = t.lower()
        done = "состоял" in tl and "не состоял" not in tl
        if not d or "оферт" not in tl or (done and not with_done):
            continue
        ps, pe = _of_date(o.get("offerdatestart")), _of_date(o.get("offerdateend"))
        kind, weak = _of_text_kind(t, bool(ps and pe))
        cancelled = "отмен" in tl or "не состоял" in tl
        add(d, kind, "moex_offertype", o.get("price"), ps, pe, "cancelled" if cancelled else ("done" if done else "scheduled"), weak)
    bc = _of_date(broker_call)
    if bc and bc > today:
        # Брокер отдаёт одну дату без типа и нередко на несколько дней раньше даты Мосбиржи (например, 09.02 вместо пута 12.02):
        # близкую дату Мосбиржи считаем тем же событием, иначе честно пишем «тип не указан».
        near = [k for k in recs if abs(_of_days(bc, k[0])) <= OF_BROKER_NEAR]
        if near:
            r = recs[min(near, key=lambda k: abs(_of_days(bc, k[0])))]
            if "broker" not in r["source"].split("+"):
                r["source"] += "+broker"
        else:
            add(bc, "unknown", "broker")
    for d in {k[0] for k in recs if k[1] in ("put", "call")}:      # «неизвестный» на дату с известным типом — тот же факт
        recs.pop((d, "unknown"), None)
    return sorted(recs.values(), key=lambda x: (x["date"], OF_KIND_ORDER[x["kind"]]))


def offers_of_isin(isin, broker_call=None, today=None):
    """Будущие оферты выпуска по кэшированным данным Мосбиржи; без данных — только дата брокера."""
    bz = opt = None
    try:
        bz = moex_bondization(isin)
    except Exception:  # noqa: BLE001
        pass
    try:
        opt = moex_bond_options(isin)
    except Exception:  # noqa: BLE001
        pass
    return offer_kinds(bz or {}, opt, broker_call, today)


def offer_kind_on(offs, d):
    """Тип оферт на дату d: put | call | both | unknown (если даты нет в списке)."""
    live = [x for x in offs if x["status"] != "cancelled"]
    near = [x["date"] for x in live if abs(_of_days(d, x["date"])) <= OF_BROKER_NEAR]
    if near and d not in near:                     # дата брокера чуть сдвинута относительно Мосбиржи
        d = min(near, key=lambda x: abs(_of_days(d, x)))
    ks = {x["kind"] for x in live if x["date"] == d}
    return "both" if {"put", "call"} <= ks else (next(iter(ks)) if len(ks) == 1 else ("put" if "put" in ks else "unknown"))


def annotate_offer_kinds(rows, today=None):
    """Строкам с датой оферты/колл (r['call']) добавляет r['call_kind']: put | call | both | unknown."""
    today = today or date.today().isoformat()
    rows = [r for r in rows if r.get("isin") and r.get("call") and r["call"] > today]

    def one(r):
        try:
            return offer_kind_on(offers_of_isin(r["isin"], r["call"], today), r["call"])
        except Exception:  # noqa: BLE001
            return None
    for r, k in zip(rows, pool_map(one, rows)):
        r["call_kind"] = k


def offer_alert_text(kind, left, ds):
    """Текст тревоги «Мониторинга» по типу оферты; left — дней до даты, ds — дата дд.мм.гггг."""
    if kind == "put":
        return "Пут-оферта %s (через %d дн.): у держателя есть право предъявить бумагу к выкупу" % (ds, left)
    if kind == "call":
        return "Колл-опцион %s (через %d дн.): эмитент может досрочно погасить выпуск, заявку подавать не нужно" % (ds, left)
    if kind == "both":
        return "Пут-оферта и колл-опцион %s (через %d дн.): проверьте условия в карточке выпуска" % (ds, left)
    return "Оферта %s (через %d дн.): тип не указан, проверьте условия в документах выпуска" % (ds, left)


OF_KIND_RU = {"put": "пут-оферта", "call": "колл-опцион эмитента", "unknown": "оферта (тип не указан)"}


def _of_days(a, b):
    return (datetime.strptime(b, "%Y-%m-%d") - datetime.strptime(a, "%Y-%m-%d")).days


def _of_med(xs):
    xs = sorted(xs)
    n = len(xs)
    return None if not n else (xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2.0)


def _of_date(s):
    return s if s and len(s) == 10 and not s.startswith("0000") else None


def _of_aci(bz, flows, d):
    """НКД на дату d на одну облигацию: линейно внутри купонного периода (по ближайшему будущему купону потоков)."""
    prev = [c["coupondate"] for c in bz["coupons"] if c.get("coupondate") and c["coupondate"] <= d]
    nxt = [(x[0], x[1]) for x in flows if x[0] > d and x[1] > 0]
    if not prev or not nxt:
        return 0.0
    p0, (n0, amt) = max(prev), min(nxt)
    span = _of_days(p0, n0)
    return amt * _of_days(p0, d) / span if span > 0 else 0.0


def _of_cut(bz, flows, face, od, op):
    """Потоки до оферты: покупатель по оферте получает op x остаток номинала и НКД на дату оферты."""
    head = [x for x in flows if x[0] < od]
    remain = face - sum(x[2] for x in head)
    c_od = sum(x[1] for x in flows if x[0] == od)
    acc = 0.0 if c_od else _of_aci(bz, flows, od)
    return head + [(od, c_od + acc, remain * op)], remain


def _of_peers(me, rating, floating, dur):
    """Медиана доходности и число аналогов: тот же рейтинг +/-1 ступень (если мало, +/-2), дюрация близка к dur."""
    if not dur or not rating or rating not in RATING_SCALE:
        return None, 0
    ri = RATING_SCALE.index(rating)
    uni = _bc_universe()
    for width in (1, 2):
        pool = []
        for e in uni:
            rt = e.get("_rt")
            if e["cur"] != "RUB" or not (0 < e["yield"] < 40) or not e.get("dur") or not rt or rt["v"] not in RATING_SCALE:
                continue
            if bool((e["_ci"] or {}).get("floating")) != bool(floating):
                continue
            if abs(RATING_SCALE.index(rt["v"]) - ri) > width or (me and e["_isin"] == me["_isin"]):
                continue
            if me and me.get("_iss") and e["_iss"] and e["_iss"] == me["_iss"]:
                continue
            if abs(e["dur"] - dur) > max(0.4, dur * 0.4):
                continue
            pool.append((abs(e["dur"] - dur) + 0.5 * abs(RATING_SCALE.index(rt["v"]) - ri), e["yield"]))
        if len(pool) >= 3:
            pool.sort()
            return _of_med([y for _, y in pool[:12]]), min(len(pool), 12)
    return None, 0


def _of_pct(x):
    return ("%.1f" % x).replace(".", ",")


def of_new_coupon(coupons, od, face, floating=False):
    """Купон на период после пут-оферты od по купонам Мосбиржи. Объявленным считается первый купон с датой ПОСЛЕ оферты,
    у которого указан размер (value или valueprc).
    -> {'status': 'announced'|'pending'|'formula', 'date', 'rate' (% годовых), 'value'};
    'pending' — эмитент ещё не объявил ставку; 'formula' — у флоатера размера нет: купон считается по формуле (ключевая ставка + спред)."""
    cps = sorted(((c.get("coupondate"), c.get("value"), c.get("valueprc")) for c in coupons or [] if c.get("coupondate")),
                 key=lambda x: x[0])
    nxt = next(((d, v, vp) for d, v, vp in cps if d > od), None)
    if nxt and (nxt[1] or nxt[2]):
        prev = max([d for d, _, _ in cps if d <= od] or [od])
        rate = nxt[2] if nxt[2] else nxt[1] / max(face, 1e-9) * 365.0 / max(_of_days(prev, nxt[0]), 1) * 100.0
        return {"status": "announced", "date": nxt[0], "rate": rate, "value": nxt[1]}
    return {"status": "formula" if floating else "pending", "date": nxt[0] if nxt else None, "rate": None, "value": None}


def of_outcome(hold_yield, peer_median, margin=None):
    """Сравнение доходности бумаги с новым купоном и медианы аналогов -> ('below'|'fair'|'above', разница в п. п.) или (None, None).
    below: ниже рынка больше чем на margin; above: выше рынка больше чем на margin; иначе fair (граница включается в fair)."""
    if hold_yield is None or peer_median is None:
        return None, None
    m = OF_MARGIN if margin is None else margin
    gap = hold_yield - peer_median
    return ("below" if gap < -m else "above" if gap > m else "fair"), gap


def _of_dm(d):
    return "%s.%s" % (d[8:10], d[5:7])


def of_helper(rec):
    """Помощник по пут-оферте (справочно): статус купона, итог сравнения с рынком, даты подачи заявки. rec — запись _of_one.
    Сравнение строится только когда эмитент объявил купон на период после оферты."""
    if rec.get("kind") != "put":
        return None
    ps, pe = rec.get("period_start"), rec.get("period_end")
    window = ("с %s по %s" % (_of_dm(ps), _of_dm(pe))) if ps and pe else None
    h = {"status": rec.get("coupon_status") or "pending", "outcome": None, "gap": None, "window": window, "title": "", "text": "",
         "numbers": "", "apply": "", "risk_notes": list(rec.get("risk_notes") or []), "kb": "offers",
         "disclaimer": "Справочная информация, не инвестиционная рекомендация."}
    if rec.get("period_status") == "closed":
        h.update(status="closed", title="Период приёма заявок прошёл", text="Приём заявок завершён: бумага остаётся у держателя.")
        return h
    h["apply"] = ("Подать заявку через брокера %s (дата выкупа %s)." % (window, _of_dm(rec["date"]))) if window else \
        ("Период приёма заявок пока не опубликован. Дата выкупа по оферте: %s." % _of_dm(rec["date"]))
    if h["status"] == "pending":
        h.update(title="Новый купон ещё не объявлен",
                 text="Новый купон ещё не объявлен. Обычно его публикуют примерно за день до открытия приёма заявок — тогда здесь появится подсказка.")
        if window:
            h["text"] += " Ожидаемый приём заявок: %s." % window
        return h
    if h["status"] == "formula":
        h.update(title="Купон по формуле",
                 text="Купон по формуле: плавающая ставка зависит от ключевой ставки, отдельного объявления нет. Сравнение с рынком здесь "
                      "не строится; решайте по условиям выпуска и своим целям.")
        return h
    nr, hy, med = rec.get("new_rate"), rec.get("hold_yield"), rec.get("peer_median")
    h["numbers"] = "Новый купон %s %% годовых" % _of_pct(nr or 0)
    if hy is not None:
        h["numbers"] += "; доходность при текущей цене %s %%" % _of_pct(hy)
    if med is not None:
        h["numbers"] += "; медиана похожих выпусков %s %% (%d шт.)" % (_of_pct(med), rec.get("peers_n") or 0)
    code, gap = of_outcome(hy, med)
    h["outcome"], h["gap"] = code, gap
    if code == "below":
        h.update(title="Доходность ниже медианы похожих выпусков на %s п. п." % _of_pct(-gap),
                 text="Цена оферты (%s %% номинала) при вложении под медианную доходность похожих выпусков даёт более высокую доходность." % _of_pct(rec["offer_price"]))
    elif code == "above":
        h.update(title="Доходность выше медианы похожих выпусков",
                 text="Доходность выше медианы похожих выпусков на %s п. п." % _of_pct(gap))
    elif code == "fair":
        h.update(title="Доходность на уровне медианы похожих выпусков", text="Доходность в пределах %s п. п. от медианы похожих выпусков." % _of_pct(OF_MARGIN))
    else:
        h.update(title="Купон объявлен", text="Сравнить с рынком не с чем: подходящих аналогов мало.")
    if rec.get("price") is not None and rec["price"] > rec["offer_price"] + OF_PRICE_EPS:
        h["text"] += " Но рыночная цена (%s %%) выше цены выкупа (%s %%): на бирже получите больше, чем по оферте." % (
            _of_pct(rec["price"]), _of_pct(rec["offer_price"]))
    return h


def _of_one(r, bz, offs, today, flags):
    """Оферты одной позиции (все будущие, put и call отдельными записями) -> список записей для страницы."""
    face = r.get("nominal") or 1000.0
    offs = [o for o in offs if o.get("status") != "cancelled"]
    if not offs:
        return []
    fl_ = bool(r.get("floating"))
    bz = bz or {"coupons": [], "amort": [], "offers": []}
    try:
        flows, _k, _e = bond_flows(bz, today, face, mode="maturity", floating=fl_)
    except Exception:  # noqa: BLE001
        flows = None
    cps = sorted((c["coupondate"], c.get("value"), c.get("valueprc")) for c in bz["coupons"] if c.get("coupondate"))
    rt = (r.get("rating") or {})
    rv = rt.get("v")
    me = next((e for e in _bc_universe() if e["_isin"] == r.get("isin")), None) if any(o["kind"] == "put" for o in offs) else None
    outlooks = " ".join((x.get("outlook") or "") for x in rt.get("all") or []).lower()
    risk_notes = []
    if flags.get("default"):
        risk_notes.append("по данным Мосбиржи, у выпуска был дефолт")
    elif flags.get("tech"):
        risk_notes.append("по данным Мосбиржи, у выпуска был технический дефолт")
    if "негатив" in outlooks:
        risk_notes.append("у рейтинга негативный прогноз")
    if "наблюден" in outlooks:
        risk_notes.append("рейтинг взят под наблюдение")
    price_pct = r.get("price_pct")
    out = []
    for o in offs:
        od, kind = o["date"], o["kind"]
        days = _of_days(today, od)
        ps, pe = o.get("period_start"), o.get("period_end")
        price = o.get("price") or 100.0
        status, days_left = "unknown", None
        if ps and pe:
            days_left = _of_days(today, pe)
            status = "open" if ps <= today <= pe else ("upcoming" if today < ps else "closed")
        urgent = kind == "put" and (status == "open" or (status == "upcoming" and days_left is not None and days_left <= 7) or
                                    (status == "unknown" and days <= 7))
        rec = {"isin": r.get("isin"), "uid": r.get("uid"), "name": r["name"], "logo": r.get("logo"), "color": r.get("color"),
               "qty": r.get("qty"), "value_rub": r.get("value_rub"), "rating": rv, "floating": fl_,
               "kind": kind, "source": o.get("source"), "inferred": bool(o.get("inferred")), "date": od, "days": days,
               "period_start": ps, "period_end": pe,
               "period_status": status, "period_days_left": days_left, "urgent": urgent, "offer_price": price,
               "price_known": bool(o.get("price")),
               "price": price_pct, "ytm_now": r.get("ytm"), "to_offer_rub": (r.get("qty") or 0) * face * price / 100.0,
               "risk_notes": risk_notes, "yield_to_offer": None, "coupon_known": False, "coupon_status": None, "new_rate": None,
               "hold_yield": None, "peer_median": None, "peers_n": 0, "threshold": None}
        if kind != "put":
            rec["to_offer_rub"] = None
        after_cut = None
        try:
            if flows:
                cut, remain = _of_cut(bz, flows, face, od, price / 100.0)
                aci_now = _of_aci(bz, flows, today)
                if price_pct:
                    dirty = price_pct / 100.0 * face + aci_now
                    y = cf_ytm(dirty, cut, today)
                    rec["yield_to_offer"] = y * 100 if y is not None else None
                after = [x for x in flows if x[0] > od]
                if after and kind == "put":
                    after_cut = (after, remain, _of_aci(bz, flows, od))
        except Exception:  # noqa: BLE001
            after_cut = None
        if kind != "put":
            rec["hint"] = _of_hint_other(rec)
            out.append(rec)
            continue
        nc = of_new_coupon(bz["coupons"], od, face, fl_)
        known = nc["status"] == "announced"
        rec["coupon_known"], rec["coupon_status"], rec["new_rate"] = known, nc["status"], nc["rate"]
        mac = None
        if after_cut:
            after, remain, aci_od = after_cut
            y2 = cf_ytm(remain + aci_od, after, od)
            if y2 is not None:
                mac, _m, _c = cf_risk(after, od, y2)
                if known:
                    rec["hold_yield"] = y2 * 100          # запасной вариант: если оставить бумагу, а деньги по оферте вложить по номиналу
        if known and flows and price_pct:
            try:                                           # основной: доходность к погашению при ТЕКУЩЕЙ цене с новым купоном
                yn = cf_ytm(price_pct / 100.0 * face + _of_aci(bz, flows, today), flows, today)
                if yn is not None and 0 < yn * 100 < 100:
                    rec["hold_yield"] = yn * 100
            except Exception:  # noqa: BLE001
                pass
        med, n = _of_peers(me, rv, fl_, mac)
        if med is not None:
            rec["peer_median"], rec["peers_n"], rec["threshold"] = med, n, med - OF_MARGIN
        rec["hint"] = _of_hint(rec, risk_notes)
        rec["helper"] = of_helper(rec)
        out.append(rec)
    return out


def _of_hint_other(rec):
    """Подсказка для колл-опциона эмитента и для оферты неуказанного типа."""
    y = rec.get("yield_to_offer")
    if rec["kind"] == "call":
        yt = (" Доходность к этой дате при текущей цене — %s %% годовых (выкуп по %s)." % (
            _of_pct(y), "%s %%" % _of_pct(rec["offer_price"]) if rec.get("price_known") else "номиналу")) if y is not None and y <= 100 else ""
        src = (" Дата получена от брокера, на Мосбирже условия не найдены — уточните их в проспекте выпуска."
               if rec.get("source") == "broker" else "")
        return {"code": "call", "title": "Эмитент может погасить досрочно",
                "text": "Это право эмитента, а не ваше: заявку подавать не нужно. Если ставки к тому времени упадут, эмитент "
                        "может погасить выпуск и вам придётся вкладывать деньги под меньший доход (риск реинвестирования), "
                        "поэтому ориентируйтесь на доходность к этой дате, а не к погашению.%s%s" % (yt, src)}
    if rec.get("source") == "broker":
        return {"code": "unknown", "title": "Тип оферты не указан",
                "text": "Эту дату сообщает брокер, а на Мосбирже оферта по выпуску не опубликована. Чаще всего так выглядит право "
                        "эмитента досрочно погасить выпуск (call) — тогда делать ничего не нужно. Но это может быть и put: "
                        "проверьте условия в решении о выпуске или у брокера, прежде чем полагаться на эту дату."}
    return {"code": "unknown", "title": "Тип оферты не указан",
            "text": "Мосбиржа не сообщает, кто решает: держатель (put) или эмитент (call). Условия приведены "
                    "в документах выпуска и у брокера."}


def _of_hint(rec, risk_notes):
    price, op, med = rec["price"], rec["offer_price"], rec["peer_median"]
    hy, thr = rec["hold_yield"], rec["threshold"]
    how = ("Заявку на выкуп подаёт брокер; обычно он принимает поручения на несколько дней раньше окончания периода "
           "предъявления — уточните сроки у брокера.")
    if rec["period_status"] == "closed":
        return {"code": "closed", "title": "Период предъявления прошёл",
                "text": "Приём заявок на выкуп завершён: бумага остаётся у держателя, условия после оферты определяет эмитент."}
    if price is not None and price > op + OF_PRICE_EPS:
        return {"code": "sell_market", "title": "Биржевая цена выше цены оферты",
                "text": "Рыночная цена (%s %%) выше цены выкупа (%s %%): цена на бирже выше выкупной по оферте." % (_of_pct(price), _of_pct(op))}
    if risk_notes:
        low = (" Рыночная цена (%s %%) заметно ниже цены выкупа: рынок сомневается, что эмитент выкупит бумаги." % _of_pct(price)
               if price is not None and price < op - 10 else "")
        return {"code": "put", "title": "Есть признаки риска эмитента",
                "text": "Есть признаки повышенного риска эмитента: %s. Цена выкупа по оферте — %s %% номинала.%s %s" % ("; ".join(risk_notes), _of_pct(op), low, how)}
    if rec["floating"] and not rec["coupon_known"]:
        return {"code": "hold", "title": "Доходность к погашению не ниже рынка",
                "text": "Купон плавающий и следует за ключевой ставкой, поэтому после оферты он обычно остаётся на уровне рынка."}
    if rec["coupon_known"] and hy is not None:
        code = of_outcome(hy, med)[0]
        if code == "below":
            return {"code": "put", "title": "Есть признаки риска эмитента",
                    "text": "Новый купон (%s %% годовых) даёт доходность %s %% против %s %% у похожих выпусков (%d шт.): ниже "
                            "рынка больше чем на 0,5 п. п. Деньги по оферте (%s %%) можно вложить в бумагу с более высокой "
                            "доходностью. %s" % (_of_pct(rec["new_rate"] or 0), _of_pct(hy), _of_pct(med), rec["peers_n"],
                                                 _of_pct(op), how)}
        if med is None:
            return {"code": "hold", "title": "Доходность к погашению не ниже рынка",
                    "text": "Новый купон известен (%s %% годовых), доходность после оферты %s %%. Сравнить с рынком не с чем: "
                            "подходящих аналогов мало." % (_of_pct(rec["new_rate"] or 0), _of_pct(hy))}
        return {"code": "hold", "title": "Доходность к погашению не ниже рынка",
                "text": "Новый купон (%s %% годовых) даёт доходность %s %% против %s %% у похожих выпусков (%d шт.): %s. "
                        "Предъявлять нет смысла, если деньги не нужны." % (_of_pct(rec["new_rate"] or 0), _of_pct(hy), _of_pct(med),
                                                                            rec["peers_n"], "выше рынка" if code == "above" else "на уровне рынка")}
    t = "Новый купон ещё не объявлен."
    if rec["urgent"]:
        t += " Срок предъявления близко. " + how
    return {"code": "wait", "title": "Ставка ещё не объявлена", "text": t}


def offers_payload(cfg, acc):
    rep = build_bonds(cfg, acc)
    today = date.today().isoformat()
    rows = [r for r in rep["rows"] if r.get("isin") and r.get("qty")]

    def one(r):
        try:
            bz = moex_bondization(r["isin"])
            offs = offer_kinds(bz or {}, moex_bond_options(r["isin"]), r.get("call"), today)
            if not any(o["status"] != "cancelled" for o in offs):
                return [], None
            return _of_one(r, bz, offs, today, _mon_flags(r["isin"])), None
        except Exception as e:  # noqa: BLE001
            return [], "%s: %s" % (r.get("name"), str(e)[:100])
    res = pool_map(one, rows, workers=8)
    items = sorted([x for lst, _ in res for x in lst], key=lambda x: (x["date"], OF_KIND_ORDER[x["kind"]], x["name"]))
    errs = [e for _, e in res if e]
    puts = [x for x in items if x["kind"] == "put"]
    calls = [x for x in items if x["kind"] == "call"]
    by_isin = defaultdict(set)
    for x in items:
        by_isin[x["isin"]].add(x["kind"])
    return {"account": acc, "today": today, "items": items, "count": len(items), "put_count": len(puts),
            "call_count": len(calls), "unknown_count": len(items) - len(puts) - len(calls),
            "both_count": sum(1 for v in by_isin.values() if {"put", "call"} <= v),
            "urgent_count": sum(1 for x in puts if x["urgent"]),
            "value_rub": sum(x["value_rub"] or 0 for x in items), "to_offer_rub": sum(x["to_offer_rub"] or 0 for x in puts),
            "bonds_count": len(rows), "errors": errs,
            "empty_text": "По облигациям портфеля будущих оферт нет: выпуски погашаются по графику.",
            "notes": ["PUT — право держателя предъявить бумагу эмитенту к выкупу по заранее известной цене (обычно 100 % номинала). "
                      "Если вы ничего не делаете, бумага остаётся у вас, но купон после оферты эмитент может изменить.",
                      "CALL — право эмитента досрочно погасить или выкупить выпуск. Решение принимает эмитент, заявку подавать не "
                      "нужно; для вас это риск реинвестирования: деньги вернутся, когда ставки, возможно, уже ниже. Поэтому у такой "
                      "бумаги смотрят доходность к дате колл, а не к погашению.",
                      "У одного выпуска может быть несколько дат и оба типа сразу — каждая показана отдельной строкой. Тип берётся из "
                      "данных Мосбиржи (поля дат put/call и тип записи оферты); если определить его не удалось, строка помечена "
                      "«тип не указан». Дата от брокера без подтверждения Мосбиржи тоже помечена «тип не указан». "
                      "Период предъявления Мосбиржа публикует незадолго до оферты."]}


# ═══════════════════ конструктор лесенки облигаций ═══════════════════

LD_MAX_BONDS, LD_YTM_MAX, LD_NOTCH, LD_SPREAD_MAX = 20, 40.0, 0.5, 9.0      # максимум бумаг, предел доходности (аномалии), штраф за ступень рейтинга, п. п.


def _ld_int(v, lo, hi, d):
    try:
        x = int(float(str(v).replace(",", ".")))
    except (TypeError, ValueError):
        return d
    return max(lo, min(hi, x))


def _ld_flag(v, d):
    return d if v in (None, "") else str(v).lower() in ("1", "true", "on", "yes")


def _ld_add(d, years):
    return (datetime.strptime(d, "%Y-%m-%d") + timedelta(days=round(years * 365.25))).strftime("%Y-%m-%d")


def _ld_months(bz, today):
    """Месяцы (1-12), в которые бумага платит купон (по ближайшим 14 месяцам графика)."""
    lim = _ld_add(today, 14 / 12.0)
    return sorted({int(c["coupondate"][5:7]) for c in bz["coupons"] if c.get("coupondate") and today < c["coupondate"] <= lim})


_LD_IDS = {}


def _ld_bz(isin):
    """Потоки выпуска: по ISIN, а если пусто (так бывает у ОФЗ) — по коду бумаги на Мосбирже."""
    bz = _safe_call(moex_bondization, isin)
    sid = _LD_IDS.get(isin)
    if not bz and sid and sid != isin:
        bz = _safe_call(moex_bondization, sid)
    return bz


def _ld_cands(q_min_rating, floaters, amort, min_turn, today):
    """Вселенная -> кандидаты лесенки: (запись, рейтинг, дата окончания, вид окончания, годы до окончания)."""
    mi = RATING_SCALE.index(q_min_rating)
    out = []
    for e in _bc_universe():
        ci = e.get("_ci") or {}
        if e["cur"] != "RUB" or not (0 < e["yield"] <= LD_YTM_MAX) or not e.get("mat") or e["mat"] <= today:
            continue
        if ci.get("perpetual") or ci.get("subordinated") or e.get("sub") and "суборд" in str(e.get("sub")).lower():
            continue
        if bool(ci.get("floating")) and not floaters or bool(ci.get("amort")) and not amort:
            continue
        if (e.get("turn") or 0) < min_turn:
            continue
        if e.get("spread") is not None and e["spread"] > LD_SPREAD_MAX:      # слишком щедрая доходность — признак ловушки
            continue
        _LD_IDS[e["_isin"]] = e["id"]
        rt = e.get("_rt")
        rv = rt["v"] if rt else ("AAA" if e["kind"] == "ofz" else None)
        if rv not in RATING_SCALE or RATING_SCALE.index(rv) > mi:
            continue
        out.append({"e": e, "rv": rv, "end": e["mat"], "kind": "maturity", "t": _of_days(today, e["mat"]) / 365.25, "offs": []})
    # Срок до даты оферты только для ПУТ (решает держатель). Колл (решает эмитент) и «тип не указан» срок не меняют:
    # ступень стоит на погашении, а доходность считается к худшему (см. _ld_eval).
    wo = [c for c in out if c["e"].get("offer") and today < c["e"]["offer"] < c["e"]["mat"]]
    for c, offs in zip(wo, pool_map(lambda c: _safe_call(offers_of_isin, c["e"]["_isin"], c["e"]["offer"], today) or [], wo, workers=8)):
        c["offs"] = [o for o in offs if o["status"] != "cancelled"]
        pd = min([o["date"] for o in c["offs"] if o["kind"] == "put" and today < o["date"] < c["e"]["mat"]] or [""])
        if pd:
            c["end"], c["kind"], c["t"] = pd, "offer", _of_days(today, pd) / 365.25
    return out


def _ld_eval(c, bz, today):
    """Потоки и доходности кандидата с учётом типа оферты. None, если графика выплат нет.
    flows — потоки лесенки: до пут-оферты для пута, иначе до погашения; ytm (%) — доходность для отбора и показа:
    YTP для пута, YTW для колла, для «тип не указан» — меньшая из доходности к дате оферты и к погашению."""
    e = c["e"]
    fl_ = bool((e.get("_ci") or {}).get("floating"))
    face = float(e.get("nominal") or 1000.0)
    full = (_safe_call(bond_flows, bz, today, face, "maturity", fl_) or (None,))[0] if bz else None
    if not full:
        return None
    dirty = e["price"] / 100.0 * face + _of_aci(bz, full, today)
    yk = yields_by_kind(bz, today, face, dirty, c.get("offs") or [], floating=fl_)
    if not yk:
        return None
    b = yk["basis"]
    y = {"put": yk["ytp"], "call": yk["ytw"], "unknown": min([v for v in (yk["yto"], yk["ytm"]) if v is not None], default=None)}.get(b, yk["ytm"])
    put = b == "put"
    return {"face": face, "dirty": dirty, "yk": yk, "basis": b, "y": y, "flows": yk["flows"] if put else full,
            "end": yk["end"] if put else yk["maturity"], "kind": "offer" if put else "maturity"}


def ladder_payload(cfg, q=None):
    q = q or {}
    if q.get("mode") == "portfolio":
        return ladder_portfolio(cfg, q.get("account", "all") or "all")
    today = date.today().isoformat()
    total = _fnum(q.get("sum"), 1000.0, 1e10, 500000.0)
    years = _ld_int(q.get("years"), 1, 10, 5)
    rungs_n = _ld_int(q.get("rungs"), 1, 12, years) if q.get("rungs") not in (None, "") else years
    mr = (q.get("min_rating") or "A").upper()
    mr = mr if mr in RATING_SCALE else "A"
    floaters, amort = _ld_flag(q.get("floaters"), False), _ld_flag(q.get("amort"), True)
    monthly = _ld_flag(q.get("monthly"), False)
    _raw_cap = _fnum(q.get("max_issuer"), 0.0, 100.0, 100.0)
    cap = 100.0 if _raw_cap <= 0 else _raw_cap
    min_turn = _fnum(q.get("min_turnover"), 0.0, 1e12, 1000000.0)
    par = {"sum": total, "years": years, "rungs": rungs_n, "min_rating": mr, "floaters": floaters, "amort": amort,
           "max_issuer": cap, "min_turnover": min_turn, "monthly": monthly}
    warnings, notes = [], []
    cands = _ld_cands(mr, floaters, amort, min_turn, today)
    step = years / float(rungs_n)
    per_rung = total / rungs_n
    k_cap = int(-(-100.0 // (rungs_n * cap)))              # сколько бумаг на ступень нужно, чтобы доля эмитента не превысила лимит
    k = max(1, k_cap)
    if rungs_n * k > LD_MAX_BONDS:
        k = max(1, LD_MAX_BONDS // rungs_n)
        warnings.append("Лимит доли эмитента %s %% при таком числе ступеней потребовал бы больше %d бумаг; взято по %d на ступень, "
                        "доля одного эмитента может быть выше лимита." % (("%g" % cap).replace(".", ","), LD_MAX_BONDS, k))
    k = min(k, 3 if rungs_n * 3 <= LD_MAX_BONDS else k)
    if per_rung / k < 3000 and k > 1:
        k = max(1, int(per_rung // 3000))
    if per_rung < 1500:
        warnings.append("Сумма слишком мала для %d ступеней: на ступень приходится около %d ₽, а облигация стоит около 1 000 ₽ "
                        "и больше. Уменьшите число ступеней." % (rungs_n, round(per_rung)))
    win = []
    for i in range(rungs_n):
        mid = step * (i + 1)
        win.append((max(0.25, mid - step / 2.0), mid + step / 2.0 if i < rungs_n - 1 else min(mid + step / 2.0, years + 0.5), mid))
    # кандидаты по окнам; для «ровного дохода» подгружаем график купонов у лучших в каждом окне
    pools = []
    for lo, hi, mid in win:
        pl = [c for c in cands if lo <= c["t"] <= hi]
        for c in pl:
            ri = RATING_SCALE.index(c["rv"])
            c["score"] = c["e"]["yield"] - LD_NOTCH * ri - 0.3 * abs(c["t"] - mid) / max(step / 2.0, 0.25)
        pl.sort(key=lambda c: -c["score"])
        pools.append(pl)
    bzs = {}
    if monthly:
        want = [c["e"]["_isin"] for pl in pools for c in pl[:10]]
        for isin, bz in zip(want, pool_map(lambda x: _ld_bz(x), want, workers=8)):
            bzs[isin] = bz
    # колл и «тип не указан»: для отбора берём доходность к худшему, а не доходность Мосбиржи (она может быть к дате колла)
    risky = [c for pl in pools for c in pl[:12] if c["offs"] and c["kind"] != "offer"]
    need_ = sorted({c["e"]["_isin"] for c in risky if c["e"]["_isin"] not in bzs})
    for isin, bz in zip(need_, pool_map(lambda x: _ld_bz(x), need_, workers=8)):
        bzs[isin] = bz
    for c in risky:
        ev = _ld_eval(c, bzs.get(c["e"]["_isin"]), today)
        if ev and ev["y"] is not None:
            c["score"] += ev["y"] * 100.0 - c["e"]["yield"]
    for pl in pools:
        pl.sort(key=lambda c: -c["score"])
    chosen = [[] for _ in range(rungs_n)]
    used_iss, iss_share, covered = set(), defaultdict(float), set()

    def iss_key(c):
        e = c["e"]
        return e["_isin"] if e["kind"] == "ofz" or not e.get("_iss") else tuple(sorted(e["_iss"]))
    order = sorted(range(rungs_n), key=lambda i: len(pools[i]))        # сначала ступени с наименьшим выбором
    share = 100.0 / (rungs_n * k)
    for i in order:
        pl = pools[i]
        for strict in (True, False):
            while len(chosen[i]) < k:
                best = None
                for c in pl:
                    ik = iss_key(c)
                    if c in chosen[i] or any(iss_key(x) == ik for x in chosen[i]):
                        continue
                    if strict and ik in used_iss:
                        continue
                    if not strict and iss_share[ik] + share > cap + 1e-9:
                        continue
                    sc = c["score"]
                    if monthly and bzs.get(c["e"]["_isin"]):
                        c["months"] = _ld_months(bzs[c["e"]["_isin"]], today)
                        sc += 0.25 * len(set(c["months"]) - covered) + 0.0
                    if best is None or sc > best[0]:
                        best = (sc, c)
                if not best:
                    break
                c = best[1]
                chosen[i].append(c)
                used_iss.add(iss_key(c))
                iss_share[iss_key(c)] += share
                if monthly and c.get("months"):
                    covered |= set(c["months"])
            if len(chosen[i]) >= k:
                break
    # проверка дефолтных флагов у выбранных; замена на следующих в окне
    flat = [(i, c) for i in range(rungs_n) for c in chosen[i]]
    flg = dict(zip([c["e"]["_isin"] for _, c in flat], pool_map(lambda x: _mon_flags(x[1]["e"]["_isin"]), flat, workers=8)))
    for i in range(rungs_n):
        bad_ = [c for c in chosen[i] if (flg.get(c["e"]["_isin"]) or {}).get("default") or (flg.get(c["e"]["_isin"]) or {}).get("tech")]
        for c in bad_:
            chosen[i].remove(c)
            warnings.append("%s исключена: по данным Мосбиржи у выпуска был дефолт." % c["e"]["name"])
            have = {iss_key(x) for x in chosen[i]}
            for c2 in pools[i]:
                if c2 not in chosen[i] and c2 is not c and iss_key(c2) not in have and iss_key(c2) not in used_iss:
                    f2_ = _mon_flags(c2["e"]["_isin"])
                    if not (f2_.get("default") or f2_.get("tech")):
                        chosen[i].append(c2)
                        used_iss.add(iss_key(c2))
                        break
    sel = [c for i in range(rungs_n) for c in chosen[i]]
    for c in sel:
        if c["e"]["_isin"] not in bzs:
            bzs[c["e"]["_isin"]] = None
    need = [c["e"]["_isin"] for c in sel if bzs.get(c["e"]["_isin"]) is None]
    for isin, bz in zip(need, pool_map(lambda x: _ld_bz(x), need, workers=8)):
        bzs[isin] = bz
    # потоки и цена с НКД; бумаги без потоков отбрасываем, на их место ставим следующих кандидатов окна
    def prep(c):
        e = c["e"]
        bz = bzs.get(e["_isin"])
        if bz is None and e["_isin"] not in bzs:
            bz = bzs[e["_isin"]] = _ld_bz(e["_isin"])
        ev = _ld_eval(c, bz, today)
        if not ev:
            return "%s пропущена: нет данных о графике выплат." % e["name"]
        yk, y = ev["yk"], ev["y"]
        if y is not None and y * 100.0 > LD_YTM_MAX:
            return "%s пропущена: расчётная доходность выглядит аномальной." % e["name"]
        live = [o for o in c["offs"] if o["status"] != "cancelled"]
        c.update(flows=ev["flows"], face=ev["face"], dirty=ev["dirty"], ytm=(y * 100.0 if y is not None else e["yield"]),
                 end=ev["end"], kind=ev["kind"], months=_ld_months(bz, today), ybasis=ev["basis"],
                 ytm_mat=yk["ytm"] * 100.0 if yk["ytm"] is not None else None,
                 call_dates=sorted({o["date"] for o in live if o["kind"] == "call" and o["date"] < yk["maturity"]}),
                 unk_date=min([o["date"] for o in live if o["kind"] == "unknown" and o["date"] < yk["maturity"]] or [None], key=lambda x: x or "9"))
        return None
    for i in range(rungs_n):
        keep = []
        for c in chosen[i]:
            er = prep(c)
            if er:
                warnings.append(er)
            else:
                keep.append(c)
        if keep and len(keep) < k or (not keep and chosen[i]):
            have = {iss_key(x) for x in keep}
            tried = 0
            for c2 in pools[i]:
                if len(keep) >= k or tried >= 8:
                    break
                if c2 in chosen[i] or iss_key(c2) in have or iss_key(c2) in used_iss:
                    continue
                f2_ = _mon_flags(c2["e"]["_isin"])
                if f2_.get("default") or f2_.get("tech"):
                    continue
                tried += 1
                if not prep(c2):
                    keep.append(c2)
                    have.add(iss_key(c2))
                    used_iss.add(iss_key(c2))
        chosen[i] = keep
    # покупка: целые лоты, остаток — свободные деньги
    free = total
    for i in range(rungs_n):
        if not chosen[i]:
            continue
        tgt = per_rung / len(chosen[i])
        for c in chosen[i]:
            c["target"] = tgt
            c["lots"] = int(tgt // c["dirty"])
            free -= c["lots"] * c["dirty"]
    allc = [c for i in range(rungs_n) for c in chosen[i]]
    while allc:
        opts = [c for c in allc if c["dirty"] <= free + 1e-9 and c["target"] - c["lots"] * c["dirty"] + 0.5 * c["dirty"] > 0]
        if not opts:
            break
        c = max(opts, key=lambda c: c["target"] - c["lots"] * c["dirty"])
        c["lots"] += 1
        free -= c["dirty"]
    for i in range(rungs_n):
        if not chosen[i]:
            warnings.append("На ступень «около %s» не нашлось подходящих бумаг (рейтинг не ниже %s, оборот от %s ₽/день): "
                            "деньги ступени остались свободными. Смягчите рейтинг или ликвидность."
                            % (_ld_when(win[i][2]), mr, "{:,}".format(int(min_turn)).replace(",", " ")))
        elif len(chosen[i]) < k:
            warnings.append("На ступень «около %s» нашлось только %d из %d нужных бумаг." % (_ld_when(win[i][2]), len(chosen[i]), k))
    zero = [c for c in allc if c["lots"] <= 0]
    for c in zero:
        warnings.append("%s не куплена: цена лота выше выделенной суммы." % c["e"]["name"])
    allc = [c for c in allc if c["lots"] > 0]
    invested = sum(c["lots"] * c["dirty"] for c in allc)
    # денежный поток
    mon = defaultdict(lambda: [0.0, 0.0])
    agg = defaultdict(float)
    cp12 = 0.0
    lim12 = _ld_add(today, 1)
    for c in allc:
        for d, cp, pr in c["flows"]:
            mon[d[:7]][0] += cp * c["lots"]
            mon[d[:7]][1] += pr * c["lots"]
            agg[d] += (cp + pr) * c["lots"]
            if d <= lim12:
                cp12 += cp * c["lots"]
    cfm = []
    if mon:
        y0, m0 = int(today[:4]), int(today[5:7])
        last = max(mon)
        ym = "%04d-%02d" % (y0, m0)
        while ym <= last:
            v = mon.get(ym, [0.0, 0.0])
            cfm.append({"month": ym, "coupons": v[0], "principal": v[1]})
            yy, mm = int(ym[:4]), int(ym[5:7])
            ym = "%04d-%02d" % (yy + (mm == 12), mm % 12 + 1)
    yld = dur = None
    if invested > 0 and agg:
        fl_ = [(d, a, 0.0) for d, a in sorted(agg.items())]
        yv = cf_ytm(invested, fl_, today)
        if yv is not None:
            yld = yv * 100.0
            dur = cf_risk(fl_, today, yv)[0]
    rows = []
    for i in range(rungs_n):
        bl = []
        for c in chosen[i]:
            if c["lots"] <= 0:
                continue
            e = c["e"]
            bl.append({"isin": e["_isin"], "name": e["name"], "rating": c["rv"], "ytm": c["ytm"], "end_date": c["end"],
                       "end_kind": c["kind"], "yield_basis": c.get("ybasis"), "ytm_mat": c.get("ytm_mat"),
                       "call_dates": c.get("call_dates") or [], "unk_date": c.get("unk_date"), "price": e["price"], "price_dirty": c["dirty"], "lots": c["lots"],
                       "cost": c["lots"] * c["dirty"], "coupon_months": c["months"], "floating": bool((e["_ci"] or {}).get("floating")),
                       "amort": bool((e["_ci"] or {}).get("amort")), "share": c["lots"] * c["dirty"] / total * 100.0})
        rows.append({"target_date": _ld_add(today, win[i][2]), "target_years": win[i][2], "window": [_ld_add(today, win[i][0]), _ld_add(today, win[i][1])],
                     "bonds": bl, "cost": sum(b["cost"] for b in bl)})
    issuers = {iss_key(c) for c in allc}
    big = max([(iss_share_ := sum(c["lots"] * c["dirty"] for c in allc if iss_key(c) == ik) / total * 100.0) for ik in issuers] or [0])
    if big > cap + 0.5:
        warnings.append("Доля крупнейшего эмитента %s %% выше лимита %s %%: не хватило разных эмитентов." %
                        (("%.1f" % big).replace(".", ","), ("%g" % cap).replace(".", ",")))
    if any(c["kind"] == "offer" for c in allc):
        notes.append("Если у выпуска есть пут-оферта, срок считается до неё: к этой дате вы предъявляете бумагу эмитенту по цене выкупа "
                     "(обычно 100 %). Заявку подаёт брокер. Доходность таких бумаг — к пут-оферте.")
    callable_ = [c for c in allc if c.get("call_dates") or c.get("unk_date")]
    if any(c.get("call_dates") for c in callable_):
        notes.append("У части выпусков есть колл-опцион: эмитент может досрочно погасить бумагу. Ступень стоит на дате погашения, "
                     "а доходность показана к худшему (меньшая из доходности к погашению и к дате колла): если выпуск погасят раньше, "
                     "деньги вернутся раньше и их придётся реинвестировать.")
    if any(c.get("unk_date") and not c.get("call_dates") for c in callable_):
        notes.append("У части выпусков есть оферта, тип которой не указан. Консервативно ступень стоит на погашении, "
                     "доходность — меньшая из доходности к дате оферты и к погашению.")
    notes.append("Бумаги гасятся по очереди: деньги возвращаются каждый год, и их можно вложить по новой ставке. Если ставки "
                 "вырастут, вы реинвестируете дороже, если упадут, длинные ступени уже зафиксировали высокую доходность.")
    if monthly:
        notes.append("Включён ровный ежемесячный доход: при выборе бумаг учитывается, в какие месяцы они платят купоны.")
    if any(b["floating"] for r_ in rows for b in r_["bonds"]):
        notes.append("Купоны флоатеров оценены по прогнозу ключевой ставки Банка России: фактические выплаты могут отличаться.")
    if any(b["rating"] == "AAA" and next((c for c in allc if c["e"]["_isin"] == b["isin"]), {}).get("e", {}).get("kind") == "ofz"
           for r_ in rows for b in r_["bonds"]):
        notes.append("ОФЗ рейтинга не имеют; для отбора приравнены к AAA как государственный долг.")
    return {"params": par, "today": today, "rungs": rows,
            "totals": {"invested": invested, "free": total - invested, "ytm": yld, "dur": dur, "bonds": len(allc),
                       "issuers": len(issuers), "rungs_filled": sum(1 for r_ in rows if r_["bonds"]),
                       "callable_cost": sum(c["lots"] * c["dirty"] for c in callable_),
                       "callable_share": sum(c["lots"] * c["dirty"] for c in callable_) / invested * 100.0 if invested > 0 else 0.0,
                       "callable_bonds": len(callable_),
                       "coupon_12m": cp12, "monthly_avg": cp12 / 12.0, "max_issuer": big,
                       "months_with_coupon": sum(1 for m in cfm[:12] if m["coupons"] > 0)},
            "cashflow_by_month": cfm, "notes": notes, "warnings": warnings}


def _ld_when(y):
    return ("%.1f" % y).replace(".", ",") + " г."


def _safe_call(fn, *a):
    try:
        return fn(*a)
    except Exception:  # noqa: BLE001
        return None


# ───── лесенка текущего портфеля: сколько денег и когда возвращается ─────

LD_HEAVY = 1.5            # период «перегружен», если сумма больше среднего во столько раз
LD_QUARTERS_UNTIL = 1     # кварталами показываем текущий и следующий календарные годы, дальше — годами


def _ld_qkey(d):
    return "%s-Q%d" % (d[:4], (int(d[5:7]) - 1) // 3 + 1)


def _ld_pkey(d, today, gran):
    if gran == "quarter" and int(d[:4]) <= int(today[:4]) + LD_QUARTERS_UNTIL:
        return _ld_qkey(d)
    return d[:4]


def _ld_plabel(key):
    return ("%s кв. %s" % (key[6], key[:4])) if "-Q" in key else key


def _ld_pspan(today, gran, keys):
    """Все периоды от первого до последнего непрерывно: кварталы текущего и следующего года, затем годы."""
    if not keys:
        return []
    y0 = int(today[:4])
    out = []
    if gran == "quarter":
        q0 = (int(today[5:7]) - 1) // 3
        for y in range(y0, y0 + LD_QUARTERS_UNTIL + 1):
            for q in range(q0 if y == y0 else 0, 4):
                out.append("%d-Q%d" % (y, q + 1))
        last_y = max(int(k[:4]) for k in keys)
        last_q = max([k for k in keys if "-Q" in k] or [""])
        if last_y <= y0 + LD_QUARTERS_UNTIL:                       # хвост без событий не показываем
            out = [k for k in out if k <= last_q] or out[:1]
        out += [str(y) for y in range(y0 + LD_QUARTERS_UNTIL + 1, last_y + 1)]
        return out
    ys = sorted(int(k[:4]) for k in keys)
    return [str(y) for y in range(ys[0], ys[-1] + 1)]


def ld_buckets(items, today, gran="year"):
    """items: [{isin, name, ytm, events: [{date, type, amount}]}] -> периоды лесенки.
    Период: {key, label, kind, total, share, flag ('heavy'|'gap'|None), by_type, items}.
    heavy — сумма больше LD_HEAVY * среднего по периодам того же размера (между первым и последним непустым), gap — пустой период внутри."""
    grp = defaultdict(list)
    for it in items:
        for ev in it["events"]:
            if ev["date"] > today and ev["amount"] > 0:
                grp[_ld_pkey(ev["date"], today, gran)].append((it, ev))
    grand = sum(ev["amount"] for v in grp.values() for _, ev in v)
    periods = []
    for key in _ld_pspan(today, gran, list(grp)):
        rows, by, called = {}, {"redemption": 0.0, "offer": 0.0, "amort": 0.0}, 0.0
        for it, ev in grp.get(key, []):
            r = rows.setdefault((it["isin"], ev["type"]), {"isin": it["isin"], "name": it["name"], "date": ev["date"], "type": ev["type"],
                                                           "amount": 0.0, "n": 0, "ytm": it.get("ytm"), "call": None, "call_kind": None, "call_amount": 0.0})
            r["amount"] += ev["amount"]
            if ev.get("call"):                       # возможен досрочный возврат по колл (решает эмитент)
                r["call"], r["call_kind"] = ev["call"], ev.get("call_kind")
                r["call_amount"] += ev["amount"]
                called += ev["amount"]
            r["n"] += 1
            r["date"] = min(r["date"], ev["date"])
            by[ev["type"]] += ev["amount"]
        lst = sorted(rows.values(), key=lambda r: (r["date"], r["name"]))
        tot = sum(r["amount"] for r in lst)
        for r in lst:
            r["pct"] = r["amount"] / grand * 100.0 if grand else 0.0
        periods.append({"key": key, "label": _ld_plabel(key), "kind": "q" if "-Q" in key else "y", "total": tot,
                        "share": tot / grand * 100.0 if grand else 0.0, "flag": None, "by_type": by, "callable": called, "items": lst})
    first_any = next((i for i, p in enumerate(periods) if p["total"] > 0), len(periods))
    for kind in ("q", "y"):
        ps = [p for p in periods if p["kind"] == kind]
        nz = [i for i, p in enumerate(ps) if p["total"] > 0]
        if len(nz) < 1:
            continue
        span = ps[nz[0]:nz[-1] + 1]
        avg = sum(p["total"] for p in span) / float(len(span)) if span else 0.0
        for i, p in enumerate(ps):
            if p["total"] <= 0:
                if nz[0] < i < nz[-1] or (kind == "y" and first_any < periods.index(p) and i < nz[-1]):
                    p["flag"] = "gap"
            elif len(span) >= 3 and p["total"] > LD_HEAVY * avg:
                p["flag"] = "heavy"
    return periods


def ld_summary(items, today, years):
    """Плашки: средний срок (по сумме возврата), ближайшая выплата, самый тяжёлый год, пустые годы."""
    evs = [(ev["date"], ev["amount"], it["name"]) for it in items for ev in it["events"] if ev["date"] > today and ev["amount"] > 0]
    tot = sum(a for _, a, _ in evs)
    avg = sum(_of_days(today, d) / 365.25 * a for d, a, _ in evs) / tot if tot else None
    nxt = None
    if evs:
        d0 = min(d for d, _, _ in evs)
        nxt = {"date": d0, "amount": sum(a for d, a, _ in evs if d == d0), "names": sorted({n for d, _, n in evs if d == d0})}
    heavy = max([p for p in years if p["total"] > 0], key=lambda p: p["total"], default=None)
    cal = [(ev["amount"], ev.get("call_kind")) for it in items for ev in it["events"] if ev["date"] > today and ev["amount"] > 0 and ev.get("call")]
    callable_ = {"amount": sum(a for a, _ in cal), "share": sum(a for a, _ in cal) / tot * 100.0 if tot else 0.0,
                 "count": len({it["isin"] for it in items for ev in it["events"] if ev["date"] > today and ev.get("call")}),
                 "unknown_amount": sum(a for a, k in cal if k == "unknown")}
    return {"total": tot, "avg_years": avg, "next": nxt, "callable": callable_,
            "heavy": {"label": heavy["label"], "share": heavy["share"], "total": heavy["total"], "flag": heavy["flag"]} if heavy else None,
            "gaps": [p["label"] for p in years if p["flag"] == "gap"]}


def ld_events(maturity, call, nominal, qty, k, amort, today, use_offer):
    """События возврата денег по одной бумаге: амортизации + погашение, либо + оферта вместо погашения. Суммы в рублях.
    call — дата ПУТ-оферты (колл сюда не передаётся: эмитент может не воспользоваться правом, ступень стоит на погашении)."""
    cut = call if use_offer and call and today < call and (not maturity or call < maturity) else None
    end = cut or maturity
    if not end or end <= today:
        return []
    out, paid = [], 0.0
    for ad, av in sorted(amort or []):
        if not ad or not av or ad <= today or ad >= end:
            continue
        paid += av
        out.append({"date": ad, "type": "amort", "amount": av * qty * k})
    out.append({"date": end, "type": "offer" if cut else "redemption", "amount": max(nominal - paid, 0.0) * qty * k})
    return out


def ladder_portfolio(cfg, acc="all"):
    today = date.today().isoformat()
    try:
        rep = build_bonds(cfg, acc)
    except ApiError as e:
        if e.status != 404:
            raise
        return {"today": today, "empty": True, "value": 0.0, "variants": {}, "has_offers": False, "has_calls": False, "undated": []}
    rows = [r for r in rep.get("rows", []) if r.get("qty") and r.get("nominal") and (r.get("maturity") or r.get("call"))]
    value = sum(r.get("value_rub") or 0.0 for r in rep.get("rows", []))
    if not rows:
        return {"today": today, "empty": True, "value": value, "variants": {}, "has_offers": False, "has_calls": False, "undated": []}

    def bz_of(r):
        return _safe_call(moex_bondization, r["isin"]) if r.get("isin") else None
    bzs = pool_map(bz_of, rows, workers=8)
    has_offers, has_calls, undated, built = False, False, [], {"offer": [], "maturity": []}
    for r, bz in zip(rows, bzs):
        k = 1.0
        if (r.get("face_cur") or "rub") != "rub":                     # номинал в валюте -> рубли по курсу, выведенному из оценки позиции
            pp = r.get("price_pct")
            k = (r.get("value_rub") or 0.0) / (r["qty"] * pp / 100.0 * r["nominal"]) if pp else 0.0
            if k <= 0:
                continue
        am = [(a.get("amortdate"), a.get("value")) for a in (bz or {}).get("amort") or []]
        call = r.get("put_date") if r.get("put_date") and r["put_date"] > today else None       # срок до оферты — только пут
        if call and r.get("maturity") and call < r["maturity"]:
            has_offers = True
        cds = sorted(d for d in r.get("call_dates") or [] if d > today and (not r.get("maturity") or d < r["maturity"]))
        cflag = (cds[0], "call") if cds else ((r["unk_date"], "unknown") if r.get("unk_date") and r["unk_date"] > today else None)
        for v, use in (("offer", True), ("maturity", False)):
            if not use and not r.get("maturity"):
                if v == "maturity":
                    undated.append(r["name"])
                continue
            ev = ld_events(r.get("maturity"), call, r["nominal"], r["qty"], k, am, today, use)
            if ev and cflag and ev[-1]["date"] > cflag[0]:
                ev[-1]["call"], ev[-1]["call_kind"] = cflag
                has_calls = True
            if ev:
                built[v].append({"isin": r.get("isin") or r.get("ticker") or "", "name": r["name"], "ytm": r.get("ytm"), "events": ev})
    variants = {}
    for v, its in built.items():
        yr = ld_buckets(its, today, "year")
        variants[v] = {"year": yr, "quarter": ld_buckets(its, today, "quarter"), "summary": ld_summary(its, today, yr), "bonds": len(its)}
    return {"today": today, "empty": not any(built.values()), "value": value, "variants": variants, "has_offers": has_offers,
            "has_calls": has_calls, "undated": sorted(set(undated))}
# ═══════════════════════════════ эмитенты: отчётность, скоринг ═══════════════════════════════
# Источники (публичные, наружу уходят только ИНН/ISIN эмитентов, ничего о портфеле):
#   • Мосбиржа ISS: ISIN -> EMITTER_ID -> ИНН, список выпусков эмитента, флаги дефолта;
#   • ГИР БО ФНС (bo.nalog.gov.ru): бухгалтерская отчётность по РСБУ (отдельной компании, не группы).
# Суммы в отчётности — в тысячах рублей; в ответах API хранятся в млн ₽.

ISS_FNS = "https://bo.nalog.gov.ru"
ISS_FNS_TTL, ISS_FNS_NF_TTL = 7 * DAY, DAY
ISS_CODES_FR = ("2110", "2200", "2300", "2320", "2330", "2400")
ISS_CODES_BS = ("1200", "1240", "1250", "1300", "1410", "1500", "1510", "1600")
_iss_fns_lock = threading.Lock()
_iss_fns_last = [0.0]
_iss_jobs = {}
_iss_jobs_lock = threading.Lock()


def _iss_json(url, timeout=25):
    return json.loads(http_text(url, timeout=timeout))


def _iss_fns_get(path):
    """Запрос к ФНС: не чаще ~2 в секунду на всё приложение."""
    with _iss_fns_lock:
        wait = 0.5 - (time.time() - _iss_fns_last[0])
        if wait > 0:
            time.sleep(wait)
        _iss_fns_last[0] = time.time()
    return _iss_json(ISS_FNS + path, timeout=30)


def _iss_n(x, d=1):
    return "—" if x is None else ("%.*f" % (d, x)).replace(".", ",")


# ── эмитент по ISIN ──

def issuer_of(isin):
    """ISIN -> {emitter_id, inn, title, short} (кэш навсегда) или None, если определить не удалось."""
    isin = (isin or "").strip().upper()
    if not re.fullmatch(r"[A-Z0-9]{6,14}", isin):
        return None
    key = "iss_emit_v1_" + isin
    hit = store().get(key)
    if hit:
        return hit
    try:
        j = _iss_json("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description" % isin, 20)
        d = {r[0]: r[2] for r in j["description"]["data"]}
        if not d:
            return None
        eid = d.get("EMITTER_ID")
        out = {"emitter_id": int(eid) if eid else None, "inn": None, "title": d.get("ISSUENAME") or isin, "short": None}
        if eid:
            ek = "iss_emitter_v1_%s" % eid
            em = store().get(ek)
            if not em:
                e = _iss_json("https://iss.moex.com/iss/emitters/%s.json?iss.meta=off&iss.only=emitter" % eid, 15)
                row = dict(zip(e["emitter"]["columns"], (e["emitter"]["data"] or [[]])[0]))
                em = {"inn": str(row.get("INN") or "").strip() or None, "title": row.get("TITLE"), "short": row.get("SHORT_TITLE")}
                if row:
                    store().put(ek, em)
            out.update(inn=em.get("inn"), title=em.get("title") or out["title"], short=em.get("short"))
    except Exception:  # noqa: BLE001
        return None
    store().put(key, out)
    return out


# ── отчётность РСБУ из ГИР БО ──

def _iss_pick(rep, kind, code, off):
    """Значение строки code из отчёта: off 0 = текущий год, 1 = предыдущий, 2 = позапрошлый (только баланс)."""
    blk = rep.get(kind) or {}
    pre = ("current", "previous", "beforePrevious")[off]
    v = blk.get(pre + code)
    return float(v) if isinstance(v, (int, float)) else None


def _iss_parse_bfo(lst):
    """Список отчётов ФНС -> {год: {код: значение в тыс. ₽}}; свой год приоритетнее пересчитанных значений из следующих отчётов."""
    reps = []
    for y in lst or []:
        try:
            per = int(y.get("period"))
        except (TypeError, ValueError):
            continue
        tcs = y.get("typeCorrections") or []
        cor = None
        for tc in tcs:
            c = (tc or {}).get("correction")
            if isinstance(c, dict) and (c.get("balance") or c.get("financialResult")):
                cor = c
                if (c.get("periodType") in (12, None)):
                    break
        if cor:
            reps.append((per, cor))
    years = {}
    prio = {}
    for per, c in reps:
        for off in (0, 1, 2):
            yr = per - off
            for kind, codes in (("financialResult", ISS_CODES_FR), ("balance", ISS_CODES_BS)):
                if kind == "financialResult" and off == 2:
                    continue
                for code in codes:
                    v = _iss_pick(c, kind, code, off)
                    if v is None:
                        continue
                    k = (yr, code)
                    if k not in prio or off < prio[k]:
                        prio[k] = off
                        years.setdefault(yr, {})[code] = v
    return years


def _iss_ratio(a, b):
    return a / b if a is not None and b not in (None, 0) else None


def _iss_year_row(y, v, prev):
    g = v.get
    rev, np_, ebt, int_ = g("2110"), g("2400"), g("2300"), g("2330")
    int_ = abs(int_) if int_ is not None else None
    if ebt is not None:
        ebit = ebt + (int_ or 0)
    else:
        ebit = g("2200")
    parts = [g("1410"), g("1510")]
    debt = None if all(p is None for p in parts) else sum(p or 0 for p in parts)
    cp = [g("1250"), g("1240")]
    cash = None if all(p is None for p in cp) else sum(p or 0 for p in cp)
    nd = None if debt is None else debt - (cash or 0)
    eq, assets = g("1300"), g("1600")
    r = lambda x: None if x is None else round(x / 1000.0, 1)      # noqa: E731  тыс. ₽ -> млн ₽
    row = {"y": y, "rev": r(rev), "ebit": r(ebit), "interest": r(int_), "net": r(np_), "debt": r(debt), "cash": r(cash),
           "net_debt": r(nd), "equity": r(eq), "assets": r(assets),
           "cover": None, "nd_ebit": None, "cur_liq": _iss_ratio(g("1200"), g("1500")),
           "eq_ratio": _iss_ratio(eq, assets), "margin": _iss_ratio(ebit, rev), "growth": None, "debt_eq": None}
    if ebit is not None and int_ and int_ > 0:
        row["cover"] = ebit / int_
    if nd is not None and ebit is not None and ebit > 0:
        row["nd_ebit"] = nd / ebit
    if debt is not None and eq is not None and eq > 0:
        row["debt_eq"] = debt / eq
    if prev and prev.get("2110") and rev is not None:
        row["growth"] = rev / prev["2110"] - 1
    for k in ("cover", "nd_ebit", "cur_liq", "eq_ratio", "margin", "growth", "debt_eq"):
        if row[k] is not None:
            row[k] = round(row[k], 4)
    # годовая выручка 0/пустая и нет баланса — строка бесполезна
    row["has"] = any(row[k] is not None for k in ("rev", "assets", "equity"))
    return row


def issuer_fin(inn, name=""):
    """Отчётность эмитента по ИНН: {status, years:[...], org_id, name, note}. Кэш 7 суток (ненайденные — 1 сутки)."""
    inn = re.sub(r"\D", "", inn or "")
    if len(inn) not in (10, 12):
        return {"status": "noinn", "years": [], "note": "ИНН эмитента неизвестен (возможно, иностранный эмитент или государство)."}
    key = "iss_fin_v1_" + inn
    hit = store().get(key)
    if hit and time.time() - hit.get("ts", 0) < (ISS_FNS_TTL if hit.get("status") == "ok" else ISS_FNS_NF_TTL):
        return hit
    res = {"status": "nf", "years": [], "inn": inn, "ts": time.time(), "org_id": None, "name": name or ""}
    s = _iss_fns_get("/advanced-search/organizations/search?query=%s&page=0" % inn)
    org = None
    for it in s.get("content") or []:
        if re.sub(r"<[^>]+>", "", str(it.get("inn") or "")).strip() == inn:
            org = it
            if it.get("bfo"):
                break
    nm = (org or {}).get("shortName") or name or ""
    res["name"] = nm
    if not org:
        res["note"] = _iss_nodata_note(nm or name, "Организация не найдена в ГИР БО ФНС (с 2022 года часть компаний вправе не раскрывать отчётность).")
        store().put(key, res)
        return res
    res["org_id"] = org.get("id")
    if not org.get("bfo"):
        res["status"] = "nobfo"
        res["note"] = _iss_nodata_note(nm, "В ГИР БО нет бухгалтерской отчётности этой организации.")
        store().put(key, res)
        return res
    lst = _iss_fns_get("/nbo/organizations/%s/bfo/" % org["id"])
    ys = _iss_parse_bfo(lst if isinstance(lst, list) else [])
    rows = []
    for y in sorted(ys):
        row = _iss_year_row(y, ys[y], ys.get(y - 1))
        if row["has"]:
            rows.append(row)
    res["years"] = rows[-5:]
    if rows:
        res["status"] = "ok"
    else:
        res["status"] = "nobfo"
        res["note"] = _iss_nodata_note(nm, "Отчётность в ГИР БО пустая или в нестандартной форме.")
    store().put(key, res)
    return res


def _iss_nodata_note(name, base):
    if re.search(r"банк|страхов|\bНКО\b|кредитн\w+ организац", name or "", re.I):
        return "Нет данных по РСБУ: банки и страховые компании сдают отчётность в Банк России (формы 0409806 и др.), в ГИР БО её нет."
    return base + " Возможные причины: новая компания, отчётность не публикуется, нестандартная форма."


# ── скоринг ──
# Шесть показателей последнего года, каждый даёт баллы от 0 до максимума линейно между «плохо» и «хорошо»:
#   покрытие процентов EBIT/проценты   25 б.:  ≤ 1,5 — 0,  ≥ 4 — полный балл
#   чистый долг / EBIT                 25 б.:  ≥ 4 — 0,    ≤ 2 — полный (нет чистого долга — полный; EBIT ≤ 0 при долге — 0)
#   доля капитала в активах            15 б.:  ≤ 5 % — 0,  ≥ 30 % — полный
#   текущая ликвидность                10 б.:  ≤ 0,8 — 0,  ≥ 1,5 — полный
#   рентабельность по EBIT             10 б.:  ≤ 0 — 0,    ≥ 12 % — полный
#   рост выручки                       15 б.:  ≤ −15 % — 0, ≥ +5 % — полный
# Для лизинга и прочих финансовых компаний долг — это «сырьё» бизнеса, поэтому вместо чистого долга/EBIT
# берётся долг/капитал (≥ 8 — 0, ≤ 3 — полный), капитал/активы: 5 % — 0, 15 % — полный, ликвидность не считается.
# Итог = набранные баллы / максимум по доступным показателям × 100, затем штрафы:
#   убыток по итогам года −8 (два года подряд ещё −7), отрицательный капитал −15, отчётность старше двух лет −10.
# Метки: ≥ 70 устойчивое, 50–69 среднее, 30–49 слабое, < 30 тревожное.
ISS_FIN_RE = re.compile(r"лизинг|факторинг|финанс|микрофин|МФК|МКК|кредитн|ипотечн|коллектор|ломбард", re.I)
ISS_LABELS = [(70, "strong", "устойчивое"), (50, "mid", "среднее"), (30, "weak", "слабое"), (-1, "alarm", "тревожное")]


def _iss_t(x, bad, good):
    if x is None:
        return None
    return max(0.0, min(1.0, (x - bad) / float(good - bad)))


def _iss_label(sc):
    for lim, k, t in ISS_LABELS:
        if sc >= lim:
            return k, t
    return "alarm", "тревожное"


def _iss_grade(t):
    return "good" if t >= 0.75 else "mid" if t >= 0.35 else "bad"


def iss_score_fin(fin, is_fin=False):
    """Скоринг по готовой отчётности (issuer_fin). Возвращает {ok, score, key, label, year, parts, penalties, note}."""
    yrs = (fin or {}).get("years") or []
    if not yrs:
        return {"ok": False, "reason": (fin or {}).get("note") or "Нет отчётности."}
    c = yrs[-1]
    prev = yrs[-2] if len(yrs) > 1 and yrs[-2]["y"] == c["y"] - 1 else None
    parts = []

    def add(pid, name, w, t, value, text):
        if t is not None:
            parts.append({"id": pid, "name": name, "max": w, "pts": round(w * t, 1), "grade": _iss_grade(t), "value": value, "text": text})

    ebit, intr = c.get("ebit"), c.get("interest")
    if intr is not None and intr > 0:
        if ebit is not None and ebit > 0 and c.get("cover") is not None:
            add("cover", "Покрытие процентов", 25, _iss_t(c["cover"], 1.5, 4.0), c["cover"], "прибыль покрывает проценты в %s раза" % _iss_n(c["cover"], 1))
        elif ebit is not None:
            add("cover", "Покрытие процентов", 25, 0.0, None, "операционной прибыли нет, проценты платятся из других источников")
    elif ebit is not None and ebit > 0 and c.get("debt") is not None and c["debt"] <= 0.02 * (c.get("assets") or 1e18):
        add("cover", "Покрытие процентов", 25, 1.0, None, "заёмных средств практически нет")
    nd, ebit_ok = c.get("net_debt"), ebit is not None and ebit > 0
    if is_fin:
        if c.get("debt") is not None and c.get("equity") is not None:
            if c["equity"] <= 0:
                add("lev", "Долг / капитал", 25, 0.0, None, "капитал отрицательный")
            elif c.get("debt_eq") is not None:
                add("lev", "Долг / капитал", 25, _iss_t(c["debt_eq"], 8, 3), c["debt_eq"], "долг в %s раза больше капитала" % _iss_n(c["debt_eq"], 1))
    elif nd is not None:
        if nd <= 0:
            add("lev", "Чистый долг / EBIT", 25, 1.0, None, "денег больше, чем долга")
        elif not ebit_ok:
            add("lev", "Чистый долг / EBIT", 25, 0.0, None, "есть чистый долг, а операционной прибыли нет")
        else:
            add("lev", "Чистый долг / EBIT", 25, _iss_t(c["nd_ebit"], 4, 2), c["nd_ebit"], "чистый долг = %s годовой прибыли" % _iss_n(c["nd_ebit"], 1))
    if c.get("eq_ratio") is not None:
        hi = 0.15 if is_fin else 0.30
        add("eq", "Доля капитала", 15, _iss_t(c["eq_ratio"], 0.05, hi), c["eq_ratio"], "капитал — %s %% активов" % _iss_n(c["eq_ratio"] * 100, 0))
    if c.get("cur_liq") is not None and not is_fin:
        add("liq", "Текущая ликвидность", 10, _iss_t(c["cur_liq"], 0.8, 1.5), c["cur_liq"], "оборотные активы = %s× краткосрочных обязательств" % _iss_n(c["cur_liq"], 2))
    holding = c.get("margin") is not None and c["margin"] > 1.0       # EBIT больше выручки: доход в основном от дивидендов и финансовых вложений
    if c.get("margin") is not None and not holding:
        add("margin", "Рентабельность по EBIT", 10, _iss_t(c["margin"], 0.0, 0.12), c["margin"], "EBIT — %s %% выручки" % _iss_n(c["margin"] * 100, 1))
    if c.get("growth") is not None:
        add("growth", "Динамика выручки", 15, _iss_t(c["growth"], -0.15, 0.05), c["growth"], "выручка %s на %s %%" % ("выросла" if c["growth"] >= 0 else "упала", _iss_n(abs(c["growth"]) * 100, 0)))
    mx = sum(p["max"] for p in parts)
    if mx < 40:
        return {"ok": False, "reason": "Слишком мало показателей для оценки (в отчётности не хватает строк)."}
    base = sum(p["pts"] for p in parts) / mx * 100
    pen = []
    if c.get("net") is not None and c["net"] < 0:
        pen.append({"name": "Убыток по итогам года", "pts": -8})
        if prev and prev.get("net") is not None and prev["net"] < 0:
            pen.append({"name": "Убыток второй год подряд", "pts": -7})
    if c.get("equity") is not None and c["equity"] < 0:
        pen.append({"name": "Отрицательный капитал", "pts": -15})
    if c["y"] < date.today().year - 2:
        pen.append({"name": "Отчётность старше двух лет (%d)" % c["y"], "pts": -10})
    sc = max(0, min(100, int(round(base + sum(p["pts"] for p in pen)))))
    k, t = _iss_label(sc)
    return {"ok": True, "score": sc, "key": k, "label": t, "year": c["y"], "base": round(base, 1), "parts": parts, "penalties": pen,
            "n_years": len(yrs), "fin_mode": bool(is_fin),
            "holding": holding,
            "note": ("Есть отчётность только за один год: динамику оценить нельзя. " if len(yrs) == 1 else "")
            + ("Прибыль до налогов больше выручки: компания, судя по всему, холдинговая (доход — дивиденды и проценты от дочерних структур). "
               "Её отдельная отчётность плохо отражает группу, оценка ориентировочная." if holding else "")}


def _iss_is_fin(title, sector=None):
    return bool(ISS_FIN_RE.search(title or "")) or sector == "financial"


def issuer_score(isin):
    """Публичная функция для других модулей: скоринг эмитента облигации по ISIN.
    Возвращает {ok, score 0–100, key (strong/mid/weak/alarm), label, year, parts, penalties, issuer, inn, basis, rsbu, ifrs} или {ok: False, reason}.
    basis = "ifrs" (консолидированная отчётность группы по smart-lab, если нашлась) или "rsbu" (отдельная компания, ГИР БО);
    s["rsbu"] — скоринг РСБУ, s["ifrs"] — скоринг МСФО (или None)."""
    try:
        em = issuer_of(isin)
        if not em or not em.get("inn"):
            return {"ok": False, "reason": "Не удалось определить эмитента (нет ИНН)."}
        fin = issuer_fin(em["inn"], em.get("title") or "")
        ci = tcat_info(isin) or {}
        rs = iss_score_fin(fin, _iss_is_fin(em.get("title"), ci.get("sector")))
        try:
            ib = ifrs_bundle(isin, em)
        except Exception:  # noqa: BLE001
            ib = None
        if ib and ib["score"].get("ok"):
            s = dict(ib["score"])
            s["ifrs"] = dict(ib["score"], ticker=ib["ticker"], how=ib["how"])
        else:
            s = dict(rs)
            s["ifrs"] = None
        s["basis"] = "ifrs" if s["ifrs"] else "rsbu"
        s["rsbu"] = rs
        s["issuer"], s["inn"] = em.get("short") or em.get("title"), em["inn"]
        return s
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "reason": "Ошибка получения отчётности: %s" % str(e)[:100]}


# ── сопоставление с рынком ──

_ISS_SPREAD_PTS = [(0, 92), (1, 80), (2.5, 65), (4.5, 45), (7, 28), (12, 10), (25, 0)]
_ISS_RATING_PTS = [(0, 92), (3, 82), (5, 72), (8, 55), (11, 40), (14, 25), (16, 12), (19, 0)]


def _iss_interp(x, pts):
    if x <= pts[0][0]:
        return float(pts[0][1])
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x <= x1:
            return y0 + (y1 - y0) * (x - x0) / float(x1 - x0)
    return float(pts[-1][1])


def iss_market(score, spread, rating):
    """Сравнивает «баллы по отчётности» с тем, что закладывает рынок (спред к КБД) и рейтинговые агентства."""
    out = {"spread": spread, "rating": rating, "market_score": None, "rating_score": None, "key": None, "text": ""}
    if spread is not None:
        out["market_score"] = round(_iss_interp(max(0.0, spread), _ISS_SPREAD_PTS))
    if rating in RATING_SCALE:
        out["rating_score"] = round(_iss_interp(RATING_SCALE.index(rating), _ISS_RATING_PTS))
    if score is None:
        out["text"] = "Для сопоставления нужна отчётность эмитента."
        return out
    refs = [x for x in (out["market_score"], out["rating_score"]) if x is not None]
    if not refs:
        out["text"] = "Нет ни спреда к КБД, ни рейтинга — сопоставить с рынком нечего."
        return out
    ref = out["market_score"] if out["market_score"] is not None else out["rating_score"]
    diff = score - ref
    src = "спред к КБД %s п.п." % _iss_n(spread, 1) if out["market_score"] is not None else "рейтинг %s" % rating
    if diff >= 20:
        out["key"] = "mkt_higher"
        out["text"] = ("Рынок оценивает риск выше, чем следует из отчётности (%s). Либо облигации недооценены, либо есть риски, которых "
                       "не видно в РСБУ: долги группы, зависимость от одного заказчика, корпоративные события." % src)
    elif diff <= -20:
        out["key"] = "mkt_lower"
        out["text"] = ("Рынок оценивает риск ниже, чем следует из отчётности (%s). Возможно, закладывается поддержка владельца или государства, "
                       "либо слабые места отчётности пока не замечены. Стоит присмотреться внимательнее." % src)
    else:
        out["key"] = "match"
        out["text"] = "Оценка рынка (%s) в целом соответствует отчётности." % src
    return out


# ── кредитная история эмитента ──

def _iss_bonds_of(inn):
    """Все выпуски облигаций эмитента, известные Мосбирже (в обращении и погашенные), кэш сутки."""
    key = "iss_bonds_v1_" + inn
    hit = store().get(key, ttl=DAY)
    if hit is not None:
        return hit
    out, seen = [], set()
    for start in (0, 100, 200, 300):
        j = _iss_json("https://iss.moex.com/iss/securities.json?iss.meta=off&q=%s&limit=100&start=%d" % (inn, start), 25)
        rows = _iss_table(j, "securities")
        for r in rows:
            if str(r.get("emitent_inn") or "") != inn or r.get("group") != "stock_bonds":
                continue
            k = r.get("isin") or r.get("secid")
            if k in seen:
                continue
            seen.add(k)
            out.append({"isin": k, "secid": r.get("secid"), "name": r.get("shortname") or r.get("name"), "traded": bool(r.get("is_traded"))})
        if len(rows) < 100:
            break
    store().put(key, out)
    return out


def iss_history(inn):
    """Выпуски эмитента и флаги дефолта/технического дефолта (проверяется до 30 выпусков, сначала торгуемые)."""
    bonds = _iss_bonds_of(inn)
    order = sorted(bonds, key=lambda b: (not b["traded"], b["name"] or ""))
    chk = [b for b in order if b["isin"] and str(b["isin"]).startswith("RU")][:30]
    fl = pool_map(lambda b: _mon_flags(b["isin"]), chk, workers=5)
    items = []
    for b, f in zip(chk, fl):
        items.append({"isin": b["isin"], "name": b["name"], "traded": b["traded"], "default": bool(f.get("default")), "tech": bool(f.get("tech"))})
    nd = sum(1 for x in items if x["default"])
    nt = sum(1 for x in items if x["tech"] and not x["default"])
    if nd:
        verdict = "В истории эмитента есть дефолт по облигациям (%d из %d проверенных выпусков)." % (nd, len(items))
    elif nt:
        verdict = "Был технический дефолт (%d из %d проверенных выпусков): выплата задержана, но затем произведена." % (nt, len(items))
    elif items:
        verdict = "Дефолтов и технических дефолтов по проверенным выпускам не отмечено."
    else:
        verdict = "Выпусков эмитента на Мосбирже не найдено."
    return {"total": len(bonds), "traded": sum(1 for b in bonds if b["traded"]), "checked": len(items), "defaults": nd, "tech": nt,
            "items": items, "verdict": verdict}


# ── карточка эмитента ──

def _iss_market_bonds(inn, isin):
    """Выпуски эмитента, торгуемые в скринере: список для карточки, спред и рейтинг выбранной бумаги."""
    uni = {e["_isin"]: e for e in _bc_universe()}
    out = []
    for b in _iss_bonds_of(inn):
        e = uni.get(b["isin"])
        if e and e.get("cur") == "RUB":
            rt = e.get("_rt")
            out.append({"isin": e["_isin"], "name": e["name"], "yield": e.get("yield"), "spread": e.get("spread"), "dur": e.get("dur"),
                        "rating": rt["v"] if rt else None, "mat": e.get("mat"), "turn": e.get("turn"), "me": e["_isin"] == isin})
    out.sort(key=lambda x: (x["dur"] or 0))
    return out


def _iss_pick_spread(own, others):
    """Спред для сопоставления с отчётностью: собственный, а если он выброс (< −5 или > 40 п.п.: флоатеры, короткие выпуски
    у оферты) — медиана остальных выпусков эмитента. Если все выбросы — спреда нет, сравнение идёт по рейтингу."""
    ok = lambda v: v is not None and -5 <= v <= 40      # noqa: E731
    if ok(own):
        return own
    sp = sorted(v for v in others if ok(v))
    if sp:
        return sp[len(sp) // 2]
    return None


def _iss_spread_rating(mb, isin):
    me = next((x for x in mb if x["me"]), None)
    spread = _iss_pick_spread(me.get("spread") if me else None, [x.get("spread") for x in mb if x is not me])
    rts = [x["rating"] for x in mb if x.get("rating") in RATING_SCALE]
    rating = (me or {}).get("rating") or (max(rts, key=RATING_SCALE.index) if rts else None)
    return spread, rating


def issuer_card(isin):
    isin = (isin or "").strip().upper()
    card = {"ok": False, "isin": isin, "errors": []}
    em = issuer_of(isin)
    if not em:
        card["errors"].append("Не удалось определить эмитента по ISIN (Мосбиржа недоступна или бумага не найдена).")
        return card
    card["issuer"] = {"title": em.get("title"), "short": em.get("short") or em.get("title"), "inn": em.get("inn"), "emitter_id": em.get("emitter_id")}
    inn = em.get("inn")
    if not inn:
        card["errors"].append("У эмитента нет ИНН в справочнике Мосбиржи (иностранный эмитент, государство).")
        card["fin"] = {"status": "noinn", "years": []}
        card["score"] = {"ok": False, "reason": "ИНН эмитента неизвестен."}
        return card

    def run(fn):
        try:
            return fn(), None
        except Exception as e:  # noqa: BLE001
            return None, str(e)[:120]
    (fin, e1), (hist, e2), (mb, e3), (ifr, e4) = pool_map(run, [lambda: issuer_fin(inn, em.get("title") or ""), lambda: iss_history(inn),
                                                                lambda: _iss_market_bonds(inn, isin), lambda: ifrs_bundle(isin, em)], workers=4)
    for lab, er in (("отчётность ФНС", e1), ("история выпусков", e2), ("рыночные данные", e3), ("отчётность МСФО", e4)):
        if er:
            card["errors"].append("%s: %s" % (lab, er))
    ci = tcat_info(isin) or {}
    card["fin"] = fin or {"status": "err", "years": [], "note": "Отчётность временно недоступна."}
    card["score"] = iss_score_fin(fin, _iss_is_fin(em.get("title"), ci.get("sector"))) if fin else {"ok": False, "reason": "Отчётность недоступна."}
    card["ifrs"] = ifr                       # {ticker, how, group, kind, fin, score, url} или None
    card["basis"] = "ifrs" if ifr and ifr["score"].get("ok") else "rsbu"
    main_sc = ifr["score"] if card["basis"] == "ifrs" else card["score"]
    card["history"] = hist
    card["bonds"] = mb or []
    spread, rating = _iss_spread_rating(card["bonds"], isin)
    if not rating:
        try:
            rt = best_rating(isin, em.get("title") or "")
            rating = rt["v"] if rt else None
        except Exception:  # noqa: BLE001
            rating = None
    card["market"] = iss_market(main_sc.get("score") if main_sc.get("ok") else None, spread, rating)
    card["ok"] = True
    return card


# ── эмитенты портфеля ──

def _iss_empty():
    return {"empty": True, "rows": [], "n": 0, "n_scored": 0, "share_scored": 0, "share_bad": 0,
            "avg_score": None, "dist": {k: 0 for _, k, _t in ISS_LABELS},
            "gov_share": 0, "gov_n": 0, "updated": datetime.now().strftime("%H:%M")}


def _iss_portfolio(cfg, acc, job):
    try:
        rep_ = build_bonds(cfg, acc)
    except ApiError as e:
        if e.status != 404:
            raise
        return _iss_empty()
    rows = [r for r in rep_.get("rows", []) if r.get("isin") and r.get("value_rub")]
    gov = [r for r in rows if r.get("sector") == "government"]
    work = [r for r in rows if r.get("sector") != "government"]
    job["total"] = len(work)
    # 1) эмитент по ISIN (кэш навсегда), 2) группировка по ИНН
    ems = pool_map(lambda r: issuer_of(r["isin"]), work, workers=4)
    groups = {}
    for r, em in zip(work, ems):
        k = (em or {}).get("inn") or ("isin:" + r["isin"])
        g = groups.setdefault(k, {"inn": (em or {}).get("inn"), "emitter_id": (em or {}).get("emitter_id"), "title": (em or {}).get("short") or (em or {}).get("title") or r.get("name"),
                                  "full": (em or {}).get("title"), "rows": [], "known": bool(em)})
        g["rows"].append(r)
    glist = list(groups.values())
    job["total"] = len(glist)
    uni = {}
    try:
        uni = {e["_isin"]: e for e in _bc_universe()}
    except Exception:  # noqa: BLE001
        pass

    def one(g):
        try:
            rs = sorted(g["rows"], key=lambda r: -(r.get("value_rub") or 0))
            top = rs[0]
            val = sum(r.get("value_rub") or 0 for r in rs)
            res = {"inn": g["inn"], "title": g["title"], "full": g["full"], "isin": top["isin"], "logo": top.get("logo"), "color": top.get("color"),
                   "value_rub": val, "share": sum(r.get("share") or 0 for r in rs), "n_bonds": len(rs), "bonds": [r["name"] for r in rs][:4]}
            ci = tcat_info(top["isin"]) or {}
            rts = []
            for r in rs:
                try:
                    b = best_rating(r["isin"], r.get("name") or "")      # заново: рейтинг в кэшированном отчёте мог быть посчитан до загрузки рейтингов
                    if b and b.get("v") in RATING_SCALE:
                        rts.append(b["v"])
                except Exception:  # noqa: BLE001
                    pass
            rating = max(rts, key=RATING_SCALE.index) if rts else None
            sps = [uni[r["isin"]].get("spread") for r in rs if r["isin"] in uni]
            spread = _iss_pick_spread(None, sps)
            res["rating"] = rating
            res["spread"] = spread
            if not g["inn"]:
                res.update(status="noinn", note="ИНН эмитента неизвестен.", score=None)
                return res
            fin = issuer_fin(g["inn"], g["full"] or "")
            try:
                ib = ifrs_bundle(top["isin"], {"emitter_id": g.get("emitter_id"), "inn": g["inn"], "title": g["full"], "short": g["title"]})
            except Exception:  # noqa: BLE001
                ib = None
            res["status"] = fin["status"]
            res["note"] = fin.get("note")
            sc = iss_score_fin(fin, _iss_is_fin(g["full"] or g["title"], ci.get("sector")))
            res["fin_mode"] = bool(sc.get("fin_mode"))
            res["rsbu_score"] = sc["score"] if sc.get("ok") else None
            if ib:
                res["ifrs_ticker"], res["ifrs_how"] = ib["ticker"], ib["how"]
                res["ifrs_score"] = ib["score"]["score"] if ib["score"].get("ok") else None
                if not ib["score"].get("ok"):
                    res["ifrs_note"] = ib["score"].get("reason")
            if ib and ib["score"].get("ok"):
                isc = ib["score"]
                c_ = ib["fin"].get("ltm") or ib["fin"]["years"][-1]
                res.update(basis="ifrs", score=isc["score"], key=isc["key"], label=isc["label"], year=isc["year"], period=isc["period"], holding=False,
                           fin_mode=False, bank=isc.get("bank"), nd_ebit=c_.get("nd_ebitda"), cover=c_.get("cover"), eq_ratio=c_.get("eq_ratio"),
                           rev=c_.get("rev"), net_debt=c_.get("net_debt"), debt_eq=None)
                res["market"] = iss_market(isc["score"], spread, rating)
            elif sc.get("ok"):
                res["basis"] = "rsbu"
                last = fin["years"][-1]
                res.update(score=sc["score"], key=sc["key"], label=sc["label"], year=sc["year"], holding=sc.get("holding"),
                           nd_ebit=last.get("nd_ebit"), cover=last.get("cover"), eq_ratio=last.get("eq_ratio"), cur_liq=last.get("cur_liq"),
                           rev=last.get("rev"), net_debt=last.get("net_debt"), debt_eq=last.get("debt_eq"))
                res["market"] = iss_market(sc["score"], spread, rating)
            else:
                res.update(score=None, note=sc.get("reason") or res.get("note"))
            return res
        except Exception as e:  # noqa: BLE001
            return {"inn": g["inn"], "title": g["title"], "isin": g["rows"][0]["isin"], "value_rub": sum(r.get("value_rub") or 0 for r in g["rows"]),
                    "share": sum(r.get("share") or 0 for r in g["rows"]), "n_bonds": len(g["rows"]), "score": None, "status": "err",
                    "note": "Ошибка: %s" % str(e)[:100]}
        finally:
            job["done"] += 1
    out = pool_map(one, glist, workers=4)
    out.sort(key=lambda x: -(x.get("value_rub") or 0))
    scored = [x for x in out if x.get("score") is not None]
    sh_s = sum(x["share"] for x in scored)
    bad = sum(x["share"] for x in scored if x["key"] in ("weak", "alarm"))
    dist = {k: sum(1 for x in scored if x["key"] == k) for _, k, _t in ISS_LABELS}
    return {"rows": out, "n": len(out), "n_scored": len(scored), "share_scored": sh_s, "share_bad": bad,
            "avg_score": (sum(x["score"] * x["share"] for x in scored) / sh_s) if sh_s else None, "dist": dist,
            "gov_share": sum(r.get("share") or 0 for r in gov), "gov_n": len(gov), "updated": datetime.now().strftime("%H:%M")}


def issuers_payload(cfg, acc, q, force):
    if not ((cfg or {}).get("token") or "").strip() and not imports_list():
        return _iss_empty()
    key = (token_key(cfg), acc)
    with _iss_jobs_lock:
        job = _iss_jobs.get(key)
        fresh = job and job["state"] == "done" and time.time() - job["t"] < 1800 and job.get("rs") == ratings_stamp()
        if job and job["state"] == "run":
            return {"pending": True, "done": job["done"], "total": job["total"]}
        if fresh and not force:
            return job["res"]
        job = {"state": "run", "done": 0, "total": 0, "t": time.time(), "res": None, "rs": ratings_stamp()}   # рейтинги сменились — пересчёт
        _iss_jobs[key] = job

    def work():
        try:
            job["res"] = _iss_portfolio(cfg, acc, job)
            job["state"] = "done"
        except Exception as e:  # noqa: BLE001
            job["res"] = {"error": str(e)[:200] or "Не удалось собрать эмитентов"}
            job["state"] = "done"
        job["t"] = time.time()
    threading.Thread(target=work, daemon=True).start()
    return {"pending": True, "done": 0, "total": 0}


def _iss_api_one(cfg, acc, q, force):
    isin = (q.get("isin") or "").strip().upper()
    key = "iss_card_v3_" + isin
    if not force:
        hit = store().get(key, ttl=6 * 3600)
        if hit:
            return hit
    c = issuer_card(isin)
    if c.get("ok") and not c["errors"]:
        store().put(key, c)
    return c


API_GET["/api/issuer"] = _iss_api_one
API_GET["/api/issuers"] = issuers_payload
