# ═══════════════════════════════ «Сегодня»: дневная сводка на «Обзоре» ═══════════════════════════════
# Выплаты на 7 дней, ближайшие оферты, рейтинговые действия за неделю и число тревог мониторинга.
# Чистые функции (td_*) не ходят в сеть; сеть и кэши трогает только td_build/today_get. Кэш 10 минут.

TD_PAY_DAYS, TD_OFFER_DAYS, TD_RATING_DAYS, TD_TTL = 7, 30, 7, 600
TD_PAY_KINDS = ("coupon", "dividend", "amortization")


def td_add_days(d, n):
    return (datetime.strptime(d, "%Y-%m-%d") + timedelta(days=n)).strftime("%Y-%m-%d")


def td_payments(pays, today, days=TD_PAY_DAYS):
    """Купоны, дивиденды и амортизации в окне [today, today+days]: сумма, число, разбивка по видам и 5 ближайших."""
    end = td_add_days(today, days)
    sel = sorted((p for p in pays or [] if p.get("kind") in TD_PAY_KINDS and today <= (p.get("date") or "") <= end and p.get("amount")),
                 key=lambda p: (p["date"], -(p.get("amount") or 0)))
    by = {}
    for p in sel:
        by[p["kind"]] = by.get(p["kind"], 0) + p["amount"]
    return {"count": len(sel), "sum": sum(p["amount"] for p in sel), "days": days, "by_kind": by,
            "next_date": sel[0]["date"] if sel else None,
            "items": [{"date": p["date"], "kind": p["kind"], "name": p.get("name"), "amount": p["amount"]} for p in sel[:5]]}


def td_offer_status(o, today):
    """Статус оферты: open (идёт приём заявок) | upcoming (приём ещё не начался) | closed | unknown (период не опубликован)."""
    ps, pe = o.get("period_start"), o.get("period_end")
    if ps and pe:
        return "open" if ps <= today <= pe else ("upcoming" if today < ps else "closed")
    return "unknown"


def td_offers(pairs, today, days=TD_OFFER_DAYS):
    """pairs: [(строка облигации, список оферт offer_kinds)]. Оферты в ближайшие days дней, без отменённых, по возрастанию даты."""
    end = td_add_days(today, days)
    out = []
    for r, offs in pairs or []:
        for o in offs or []:
            if o.get("status") == "cancelled" or not (today <= (o.get("date") or "") <= end):
                continue
            st = td_offer_status(o, today) if o["kind"] == "put" else "unknown"
            if st == "closed":
                continue
            out.append({"isin": r.get("isin"), "name": r.get("name"), "kind": o["kind"], "date": o["date"],
                        "days": (datetime.strptime(o["date"], "%Y-%m-%d") - datetime.strptime(today, "%Y-%m-%d")).days,
                        "status": st, "period_start": o.get("period_start"), "period_end": o.get("period_end")})
    out.sort(key=lambda x: (x["date"], {"put": 0, "call": 1}.get(x["kind"], 2), x["name"] or ""))
    return {"count": len(out), "days": days, "put": sum(1 for x in out if x["kind"] == "put"),
            "call": sum(1 for x in out if x["kind"] == "call"), "items": out[:5]}


def td_ratings(events, rows_keys, today, days=TD_RATING_DAYS):
    """Рейтинговые действия за days дней по эмитентам портфеля (та же логика, что у тревог монитора)."""
    al = _mon_rating_alerts(rows_keys, events or [], td_add_days(today, -days))
    return {"count": len(al), "days": days, "negative": sum(1 for a in al if a["severity"] in ("high", "medium")),
            "items": [{"date": a["date"], "name": a["name"], "message": a["message"], "severity": a["severity"]} for a in al[:5]]}


TD_MV_N, TD_MV_TURN = 5, 1_000_000


def td_movers(rows, n=TD_MV_N, min_turn=TD_MV_TURN):
    """Лидеры падения облигаций за день: топ-n по падению цены среди выпусков с оборотом >= min_turn ₽ (отсекаем шум)."""
    down = sorted((r for r in rows or [] if (r.get("chg") or 0) < 0 and (r.get("turn") or 0) >= min_turn), key=lambda r: r["chg"])
    return {"count": len(down), "n": n, "min_turn": min_turn,
            "items": [{"name": r.get("name"), "isin": r.get("isin") or r.get("id"), "chg": r["chg"], "price": r.get("price"),
                       "turnover": r.get("turn")} for r in down[:n]]}


def td_digest(pays, pairs, events, rows_keys, today, alerts=None, movers=None):
    """Собирает сводку; пустые разделы выбрасываются, empty=True — показывать карточку нечего."""
    d = {"today": today, "payments": td_payments(pays, today), "offers": td_offers(pairs, today),
         "ratings": td_ratings(events, rows_keys, today)}
    if alerts is not None:
        d["alerts"] = {"count": sum(1 for a in alerts if a.get("severity") in ("high", "medium")),
                       "high": sum(1 for a in alerts if a.get("severity") == "high")}
    if movers is not None:
        d["movers"] = movers
    for k in ("payments", "offers", "ratings", "alerts", "movers"):
        if k in d and not d[k]["count"]:
            del d[k]
    d["empty"] = not any(k in d for k in ("payments", "offers", "ratings", "alerts", "movers"))
    return d


def td_empty():
    return {"today": date.today().isoformat(), "empty": True}


def _td_warm_monitor(cfg, acc):
    try:
        build_monitor(cfg, acc)
    except Exception:  # noqa: BLE001
        pass


def _td_warm_screener():
    try:
        screener_rows()
    except Exception:  # noqa: BLE001
        pass


def td_build(cfg, acc):
    today = date.today().isoformat()
    rep = build_bonds(cfg, acc)
    rows = [r for r in rep.get("rows") or [] if r.get("isin") and r.get("qty")]

    def one(r):
        try:
            return r, offers_of_isin(r["isin"], r.get("call"), today)
        except Exception:  # noqa: BLE001
            return r, []
    pairs = pool_map(one, rows, workers=8)
    events = (store().get(RT_LOG_KEY) or {}).get("events") or []
    rows_keys = [(r, _mon_issuer_keys(r)) for r in rows]
    alerts = None
    try:                                  # мониторинг тяжёлый: берём только готовый результат, а прогрев запускаем в фоне
        th = mon_thresholds(cfg)
        mon = mem_get(("monitor", token_key(cfg), acc, tuple(sorted(th.items()))), 900)
        if mon is not None:
            alerts = mon.get("alerts") or []
        else:
            threading.Thread(target=_td_warm_monitor, args=(cfg, acc), daemon=True).start()
    except Exception:  # noqa: BLE001
        alerts = None
    movers = None
    try:                                  # рынок: берём готовые строки скринера; если их ещё нет — прогреваем в фоне
        if _scr["rows"] and time.time() - _scr["t"] < 6 * 3600:
            movers = td_movers(_scr["rows"])
        else:
            threading.Thread(target=_td_warm_screener, daemon=True).start()
    except Exception:  # noqa: BLE001
        movers = None
    return td_digest(rep.get("payments") or [], pairs, events, rows_keys, today, alerts, movers)


def today_get(cfg, acc, q, force):
    if not cfg.get("token") and not imports_list():
        return td_empty()
    key = ("today", token_key(cfg), acc)
    if not force:
        hit = mem_get(key, TD_TTL)
        if hit:
            return hit
    try:
        res = td_build(cfg, acc)
    except Exception:  # noqa: BLE001
        return td_empty()
    return mem_put(key, res)


API_GET["/api/today"] = today_get
# ═══════════════ раскрытие информации эмитентов: клиент (факты с сервера данных, объём в рынке, потоки эмитента, техдефолты) ═══════════════
# Факты разбирает сервер данных (disclosure/facts, disclosure/defaults); здесь — только потребление: объём выпуска в обращении,
# рублёвый эквивалент будущих выплат эмитента по всем его выпускам, лента дефолтов. Сервер выключен/недоступен -> пустые списки.

DISC_TTL, DISC_ERR_TTL = 6 * 3600, 15 * 60
DISC_KIND_RU = {"coupon_paid": "Выплата купона", "coupon_declared": "Ставка купона", "default": "Неисполнение обязательства",
                "buyback_result": "Итоги выкупа", "placement_result": "Размещение / доразмещение"}
DISC_OBL_RU = {"coupon": "Купон", "amortization": "Амортизация", "redemption": "Погашение", "offer": "Выкуп по оферте", "other": "Обязательство"}
DISC_FX_RUB = ("", "RUB", "RUR", "SUR")


def _disc_num(x):
    try:
        return None if x is None or isinstance(x, bool) else float(x)
    except (TypeError, ValueError):
        return None


def _disc_ru(n):
    return ("{:,.0f}".format(n)).replace(",", " ")


def disc_facts(isin=None, inn=None, kind=None):
    """Факты раскрытия по ISIN или ИНН, новые сверху: [{doc_id, title, published, url, isin, inn, kind, event_date, due_date, conf, data}].
    Кэш в kv: 6 ч, ошибка/выключенный сервер — 15 мин. Пусто, если сервер данных недоступен."""
    isin = (isin or "").strip().upper() or None
    inn = (inn or "").strip() or None
    if not isin and not inn:
        return []
    params = {"isin": isin} if isin else {"inn": inn}
    if kind:
        params["kind"] = kind
    key = "disc1:%s:%s" % (isin or inn, kind or "")
    st = store()
    hit = st.get(key)
    if isinstance(hit, dict) and time.time() - hit.get("ts", 0) < (DISC_TTL if hit.get("ok") else DISC_ERR_TTL):
        return hit.get("data") or []
    try:
        res = ds_parsed("disclosure/facts", params)
    except Exception:  # noqa: BLE001
        res = None
    ok = isinstance(res, list)
    data = [x for x in res if isinstance(x, dict)] if ok else []
    st.put(key, {"ok": ok, "ts": time.time(), "data": data})
    return data


def _disc_issue_desc(isin):
    """Объём выпуска из описания Мосбиржи: {issue_size, placed, issue_date, face, cur, name}; кэш сутки. {} при ошибке."""
    isin = (isin or "").strip().upper()
    if not isin:
        return {}
    key = "disc_desc2:" + isin
    hit = store().get(key, ttl=DAY)
    if hit is not None:
        return hit
    try:
        j = json.loads(http_text("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description" % isin, 20))
        d = {r[0]: r[2] for r in j["description"]["data"]}
    except Exception:  # noqa: BLE001
        return {}
    n = lambda k: (int(_disc_num(d.get(k))) if _disc_num(d.get(k)) else None)      # noqa: E731
    out = {"issue_size": n("ISSUESIZE"), "placed": n("ISSUESIZEPLACED"), "issue_date": d.get("ISSUEDATE") or None,
           "face": _disc_num(d.get("FACEVALUE")), "cur": d.get("FACEUNIT") or "SUR",
           "name": d.get("SHORTNAME") or d.get("NAME") or isin}
    if d:
        store().put(key, out)
    return out


def _disc_fdate(f):
    d = f.get("data") or {}
    return d.get("due_date") or d.get("date") or f.get("due_date") or f.get("event_date") or (f.get("published") or "")[:10] or None


def _disc_conf(f):
    d = f.get("data") or {}
    c = d.get("conf") if d.get("conf") is not None else f.get("conf")
    return _disc_num(c) or 0.0


def _disc_paid_qty(f):
    """Извлекает (qty, method) из факта coupon_paid. При несовпадении п. 2.6 с суммой выплаты (total_matches=False)
    приоритет отдаётся qty_derived = total / per_bond (реальный объём в рынке без казначейских бумаг).
    Частичные выплаты (paid_pct < 99.5) пропускаются."""
    if _disc_conf(f) < 0.5:
        return None
    d = f["data"]
    pp = _disc_num(d.get("paid_pct"))
    if pp is not None and pp < 99.5:
        return None
    ck = d.get("checks") or {}
    q_exp = int(_disc_num(d["qty"])) if d.get("qty") is not None and _disc_num(d["qty"]) is not None else None
    q_der = (int(_disc_num(d["qty_derived"]))
             if d.get("qty_derived") is not None and _disc_num(d["qty_derived"]) is not None and ck.get("qty_integer")
             else None)
    if q_der is not None and q_der > 0 and ck.get("total_matches") is False and not ck.get("split_currency"):
        return q_der, "coupon_derived"
    if q_exp is not None:
        return q_exp, "coupon_explicit"
    if q_der is not None and q_der > 0:
        return q_der, "coupon_derived"
    return None


def bond_outstanding(isin, today=None, desc=None):
    """Сколько бумаг выпуска в обращении: по последнему раскрытию (купон -> число бумаг), иначе по объёму выпуска Мосбиржи.
    Возвращает также историю выпуска, доразмещений, выкупов на офертах и расчётных дельт между купонами."""
    isin = (isin or "").strip().upper()
    today = today or date.today().isoformat()
    try:
        facts = disc_facts(isin=isin)
    except Exception:  # noqa: BLE001
        facts = []
    try:
        desc = desc or _disc_issue_desc(isin) or {}
    except Exception:  # noqa: BLE001
        desc = {}
    size, placed = desc.get("issue_size"), desc.get("placed")
    issue_date = desc.get("issue_date") or desc.get("ISSUEDATE") or None
    if desc.get("ISSUESIZE") is not None or desc.get("ISSUESIZEPLACED") is not None:       # передан сырой словарь ISS (_bc_desc)
        size = int(_disc_num(desc.get("ISSUESIZE")) or 0) or None
        placed = int(_disc_num(desc.get("ISSUESIZEPLACED")) or 0) or None
    out = {"qty": None, "issue_size": size, "placed": placed, "issue_date": issue_date, "share": None,
           "method": None, "as_of": None, "coupon_no": None, "doc_url": None, "buybacks_after": 0, "conf": None,
           "over_issue_size": False, "buybacks": [], "buybacks_total": 0, "placements": [], "added_total": 0,
           "coupon_history": [], "events": []}

    def dated(kind):
        rows = [f for f in facts if f.get("kind") == kind and isinstance(f.get("data"), dict)]
        rows = [f for f in rows if (_disc_fdate(f) or "") <= today]
        return sorted(rows, key=lambda f: _disc_fdate(f) or "", reverse=True)

    # Все валидные купонные точки для хронологии и дельт
    paid_valid = []
    for f in dated("coupon_paid"):
        res = _disc_paid_qty(f)
        if res:
            paid_valid.append((f, res[0], res[1]))
    pick = paid_valid[0] if paid_valid else None
    if not pick:
        for f in dated("coupon_declared"):
            d = f["data"]
            if d.get("qty_derived") is not None and (d.get("checks") or {}).get("qty_integer"):
                pick = (f, int(d["qty_derived"]), "declared_derived")
                break

    as_of = _disc_fdate(pick[0]) if pick else None

    # Все выкупы (buyback_result) и размещения/допвыпуски (placement_result) в хронологическом порядке
    bb_list = []
    for b in reversed(dated("buyback_result")):
        bd = b["data"].get("date") or b.get("event_date") or (b.get("published") or "")[:10]
        qb = _disc_num(b["data"].get("qty_bought"))
        bb_list.append({"date": bd, "qty": int(qb) if qb else None, "basis": b["data"].get("basis"),
                        "url": b.get("url"), "after_coupon": bool(as_of and bd and bd > as_of)})
    pl_list = []
    for p in reversed(dated("placement_result")):
        pd = p["data"].get("date") or p.get("event_date") or (p.get("published") or "")[:10]
        qp = _disc_num(p["data"].get("qty_placed"))
        sk = p["data"].get("subkind") or "primary"
        pl_list.append({"date": pd, "qty": int(qp) if qp else None, "subkind": sk,
                        "url": p.get("url"), "after_coupon": bool(as_of and pd and pd > as_of)})

    bb_total = sum(x["qty"] for x in bb_list if x["qty"])
    added_total = sum(x["qty"] for x in pl_list if x["qty"] and x["subkind"] in ("additional", "secondary"))

    if pick:
        f, qty, method = pick
        n_bb = 0
        for b in bb_list:
            if b["after_coupon"]:
                n_bb += 1
                if b["qty"]:
                    qty = max(0, qty - b["qty"])
        for p in pl_list:
            if p["after_coupon"] and p["subkind"] in ("additional", "secondary") and p["qty"]:
                qty += p["qty"]
        confirmed_over = bool((f["data"].get("checks") or {}).get("total_matches") or added_total > 0)
        if size and qty > size:
            if confirmed_over and qty <= size * 5:
                out["over_issue_size"] = True
            else:
                qty = size
        out.update(qty=qty, method=method, as_of=as_of, coupon_no=f["data"].get("coupon_no"), doc_url=f.get("url"),
                   buybacks_after=n_bb, conf=_disc_conf(f))
    elif placed:
        out.update(qty=placed, method="issue_placed", conf=0.3)
    elif size:
        out.update(qty=size, method="issue_size", conf=0.2)

    # Хронология купонов (от старых к новым) и события изменения объёма
    chist = [{"date": _disc_fdate(f), "coupon_no": f["data"].get("coupon_no"), "qty": q, "method": m, "doc_url": f.get("url")}
             for f, q, m in reversed(paid_valid)]
    events = []
    if size or placed or issue_date:
        events.append({"date": issue_date, "kind": "issue", "qty": placed or size, "issue_size": size, "placed": placed,
                       "delta": placed or size, "label": "Выпуск / первичное размещение", "url": None})
    for p in pl_list:
        lbl = {"additional": "Дополнительный выпуск / доразмещение",
               "secondary": "Реализация ранее выкупленных бумаг"}.get(p["subkind"], "Первичное размещение")
        events.append({"date": p["date"], "kind": p["subkind"], "qty": p["qty"], "delta": p["qty"], "label": lbl, "url": p["url"]})
    for b in bb_list:
        blbl = {"put": "Выкуп по оферте (PUT)", "issuer": "Выкуп по соглашению эмитента"}.get(b["basis"], "Выкуп облигаций")
        events.append({"date": b["date"], "kind": "buyback", "basis": b["basis"], "qty": b["qty"],
                       "delta": (-b["qty"] if b["qty"] else None), "label": blbl, "url": b["url"]})

    # Расчётные дельты между соседними купонами, не покрытые явными сообщениями о выкупе/размещении
    inferred_bb, inferred_add = 0, 0
    for idx in range(1, len(chist)):
        prev_c, cur_c = chist[idx - 1], chist[idx]
        delta = cur_c["qty"] - prev_c["qty"]
        if not delta:
            continue
        d0, d1 = prev_c["date"] or "", cur_c["date"] or ""
        if delta < 0:
            covered = sum(x["qty"] for x in bb_list if x["qty"] and d0 < (x["date"] or "") <= d1)
            if covered < abs(delta) * 0.5:
                inferred_bb += abs(delta)
                events.append({"date": cur_c["date"], "kind": "inferred_buyback", "qty": abs(delta), "delta": delta,
                               "from_qty": prev_c["qty"], "to_qty": cur_c["qty"], "coupon_no": cur_c["coupon_no"],
                               "label": "Сокращение объёма к купону №%s (вероятно выкуп/оферта)" % (cur_c["coupon_no"] or "?"),
                               "url": cur_c["doc_url"]})
        else:
            covered = sum(x["qty"] for x in pl_list if x["qty"] and d0 < (x["date"] or "") <= d1)
            if covered < delta * 0.5:
                inferred_add += delta
                events.append({"date": cur_c["date"], "kind": "inferred_placement", "qty": delta, "delta": delta,
                               "from_qty": prev_c["qty"], "to_qty": cur_c["qty"], "coupon_no": cur_c["coupon_no"],
                               "label": "Рост объёма к купону №%s (доразмещение / реализация)" % (cur_c["coupon_no"] or "?"),
                               "url": cur_c["doc_url"]})

    # Сравниваем первый купон с первичным объёмом (если до первого купона уже был выкуп или доразмещение)
    base_init = placed or size
    if chist and base_init:
        first_c = chist[0]
        d_first = first_c["date"] or ""
        init_delta = first_c["qty"] - base_init
        if init_delta < 0:
            covered = sum(x["qty"] for x in bb_list if x["qty"] and (x["date"] or "") <= d_first)
            if covered < abs(init_delta) * 0.5:
                inferred_bb += abs(init_delta)
                events.append({"date": first_c["date"], "kind": "inferred_buyback", "qty": abs(init_delta), "delta": init_delta,
                               "from_qty": base_init, "to_qty": first_c["qty"], "coupon_no": first_c["coupon_no"],
                               "label": "Выбытие до купона №%s (выкуп/неполное размещение)" % (first_c["coupon_no"] or "?"),
                               "url": first_c["doc_url"]})
        elif init_delta > 0 and placed and size and first_c["qty"] <= size:
            covered = sum(x["qty"] for x in pl_list if x["qty"] and (x["date"] or "") <= d_first)
            if covered < init_delta * 0.5:
                inferred_add += init_delta
                events.append({"date": first_c["date"], "kind": "inferred_placement", "qty": init_delta, "delta": init_delta,
                               "from_qty": base_init, "to_qty": first_c["qty"], "coupon_no": first_c["coupon_no"],
                               "label": "Доразмещение до купона №%s" % (first_c["coupon_no"] or "?"),
                               "url": first_c["doc_url"]})

    events.sort(key=lambda e: (e.get("date") or "0000-00-00", 0 if e["kind"] == "issue" else 1))
    out.update(buybacks=bb_list, buybacks_total=bb_total + inferred_bb,
               placements=pl_list, added_total=added_total + inferred_add,
               coupon_history=chist, events=events)
    if out["qty"] is not None and size:
        out["share"] = round(out["qty"] / float(size), 4)
    return out


def disc_brief(f):
    """Краткая строка по факту для карточки: {date, kind, label, text, url, title}."""
    d = f.get("data") or {}
    k = f.get("kind")
    bits = []
    if k == "coupon_paid":
        if d.get("coupon_no"):
            bits.append("купон №%s" % d["coupon_no"])
        if d.get("total") is not None:
            bits.append("выплачено %s ₽" % _disc_ru(d["total"]))
        q = d.get("qty") if d.get("qty") is not None else d.get("qty_derived")
        if q is not None:
            bits.append("%s шт." % _disc_ru(q))
    elif k == "coupon_declared":
        if d.get("coupon_no"):
            bits.append("купон №%s" % d["coupon_no"])
        if d.get("undetermined"):
            bits.append("ставка не определена" + (": " + d["formula"] if d.get("formula") else ""))
        elif d.get("per_bond") is not None:
            bits.append("%s ₽ на бумагу" % ("%.2f" % d["per_bond"]).replace(".", ","))
        elif d.get("rate") is not None:
            bits.append("ставка %s %%" % ("%g" % d["rate"]).replace(".", ","))
    elif k == "default":
        bits.append("технический дефолт" if d.get("status") == "technical" else "дефолт")
        bits.append(DISC_OBL_RU.get(d.get("obligation"), "обязательство").lower() + (" №%s" % d["coupon_no"] if d.get("coupon_no") else ""))
        if d.get("amount") is not None:
            bits.append("%s ₽" % _disc_ru(d["amount"]))
    elif k == "buyback_result":
        if d.get("qty_bought") is not None:
            bits.append("выкуплено %s шт." % _disc_ru(d["qty_bought"]))
        bits.append({"put": "по требованию владельцев", "issuer": "по соглашению"}.get(d.get("basis"), ""))
    elif k == "placement_result":
        verb = {"additional": "доразмещено", "secondary": "реализовано"}.get(d.get("subkind"), "размещено")
        if d.get("qty_placed") is not None:
            bits.append("%s %s шт." % (verb, _disc_ru(d["qty_placed"])))
        else:
            bits.append(verb)
    return {"date": (f.get("published") or "")[:10] or _disc_fdate(f), "kind": k, "label": DISC_KIND_RU.get(k, k),
            "text": ", ".join(b for b in bits if b), "url": f.get("url"), "title": f.get("title")}


def disclosure_for_bond(isin, desc=None, n=5):
    facts = [f for f in disc_facts(isin=isin) if f.get("kind") in DISC_KIND_RU]
    return {"outstanding": bond_outstanding(isin, desc=desc), "facts": [disc_brief(f) for f in facts[:n]], "n_facts": len(facts)}


# ───────────────────────── денежные потоки эмитента ─────────────────────────

def _disc_add_month(ym, k):
    y, m = int(ym[:4]), int(ym[5:7]) - 1 + k
    return "%04d-%02d" % (y + m // 12, m % 12 + 1)


def _disc_days(a, b):
    return (datetime.strptime(b, "%Y-%m-%d") - datetime.strptime(a, "%Y-%m-%d")).days


def _disc_bond_flows(isin, today, last_ym, warns):
    """Будущие потоки одного выпуска в рублях на ВСЕ бумаги: [{d, t: coupon|amort|redemption|put|call, amt, est}] + qty/method."""
    bz = moex_bondization(isin)
    if not bz:
        warns.append("%s: нет графика выплат Мосбиржи" % isin)
        return None
    o = bond_outstanding(isin, today)
    qty = o.get("qty")
    if not qty:
        warns.append("%s: не удалось определить число бумаг" % isin)
        return None
    desc = _disc_issue_desc(isin) or {}
    face = desc.get("face") or 0.0
    cur = (desc.get("cur") or "SUR").upper()
    fx = 1.0
    if cur not in DISC_FX_RUB:
        fx = tax_cbr_rate(cur, today)
        if not fx:
            warns.append("%s: нет курса ЦБ для %s, выпуск пропущен" % (isin, cur))
            return None
    decl = {}
    try:
        for f in disc_facts(isin=isin, kind="coupon_declared"):
            d = f.get("data") or {}
            dd = d.get("due_date") or f.get("due_date")
            if dd and not d.get("undetermined") and _disc_conf(f) >= 0.5:
                pb = _disc_num(d.get("per_bond"))
                if pb is None and d.get("rate") and d.get("period_from") and d.get("period_to") and face:
                    pb = face * d["rate"] / 100.0 * max(_disc_days(d["period_from"], d["period_to"]), 0) / 365.0
                if pb:
                    decl.setdefault(dd, pb)
    except Exception:  # noqa: BLE001
        pass
    try:
        est = fl_estimates(bz, today, float(face), None) if face else {}
    except Exception:  # noqa: BLE001
        est = {}
    in_h = lambda d: bool(d) and today <= d and d[:7] <= last_ym        # noqa: E731
    am = sorted((a["amortdate"], _disc_num(a.get("value"))) for a in bz.get("amort") or [] if a.get("amortdate"))
    last_am = am[-1][0] if am else None
    cps = sorted((c["coupondate"], _disc_num(c.get("value"))) for c in bz.get("coupons") or [] if c.get("coupondate"))
    flows, known = [], [v for _, v in cps if v]
    last_known = [v for d, v in cps if v and d <= today]
    prev = last_known[-1] if last_known else (known[-1] if known else None)
    for d, v in cps:
        if not in_h(d):
            if v:
                prev = v
            continue
        e = False
        if not v:
            near = [x for x in decl if abs(_disc_days(x, d)) <= 4]
            if near:
                v = decl[near[0]]
            elif d in est:
                v, e = est[d]["amt"], True
            elif prev:
                v, e = prev, True
        else:
            prev = v
        if v:
            flows.append({"d": d, "t": "coupon", "amt": v * qty * fx, "est": e})
    for d, v in am:
        if in_h(d) and v:
            flows.append({"d": d, "t": "redemption" if d == last_am else "amort", "amt": v * qty * fx, "est": False})

    def face_on(d):
        return max(face - sum(v for da, v in am if v and today < da < d), 0.0)
    try:
        opt = moex_bond_options(isin) or {}
    except Exception:  # noqa: BLE001
        opt = {}
    calls = [d for d in opt.get("call") or [] if in_h(d)]
    put_seen = set()
    for of in bz.get("offers") or []:
        d = of.get("offerdate")
        if not in_h(d) or d in put_seen:
            continue
        if d in (opt.get("call") or []) and d not in (opt.get("put") or []):       # дата только колл — не пут
            continue
        put_seen.add(d)
        px = _disc_num(of.get("price")) or 100.0
        flows.append({"d": d, "t": "put", "amt": face_on(d) * px / 100.0 * qty * fx, "est": False})
    for d in calls:
        flows.append({"d": d, "t": "call", "amt": face_on(d) * qty * fx, "est": False})
    return {"flows": flows, "qty": qty, "method": o.get("method"), "call_date": min(calls) if calls else None}


def issuer_cashflows(inn, horizon_months=25, today=None):
    """Месячный ряд будущих выплат эмитента по всем торгуемым выпускам в рублях (число бумаг x выплата на бумагу)."""
    inn = (inn or "").strip()
    today = today or date.today().isoformat()
    n = max(1, int(horizon_months))
    first = today[:7]
    mkeys = [_disc_add_month(first, i) for i in range(n)]
    months = {m: {"m": m, "coupon": 0.0, "amort": 0.0, "redemption": 0.0, "put": 0.0, "call": 0.0, "est": False, "est_amt": 0.0,
                  "after_call": False, "by_bond": {}, "call_by_bond": {}, "parts": {t: {} for t in ("coupon", "amort", "redemption", "put")},
                  "est_by_bond": {}} for m in mkeys}
    warns, bonds, dates = [], [], set()
    try:
        lst = [b for b in _iss_bonds_of(inn) if b.get("traded") and b.get("isin")]
    except Exception as e:  # noqa: BLE001
        lst = []
        warns.append("список выпусков эмитента недоступен: %s" % str(e)[:80])

    def one(b):
        w = []
        try:
            return b, _disc_bond_flows(b["isin"], today, mkeys[-1], w), w
        except Exception as e:  # noqa: BLE001
            return b, None, w + ["%s: %s" % (b["isin"], str(e)[:80])]
    for b, res, w in pool_map(one, lst, workers=4) if lst else []:
        warns += w
        if not res:
            continue
        bonds.append({"isin": b["isin"], "secid": b.get("secid"), "name": b.get("name") or b["isin"], "qty": res["qty"],
                      "method": res["method"], "call_date": res["call_date"]})
        for f in res["flows"]:
            m = months.get(f["d"][:7])
            if not m:
                continue
            a = round(f["amt"], 2)
            dates.add(f["d"])
            m[f["t"]] += a
            if f["t"] == "call":
                m["call_by_bond"][b["isin"]] = round(m["call_by_bond"].get(b["isin"], 0.0) + a, 2)
                continue
            m["by_bond"][b["isin"]] = round(m["by_bond"].get(b["isin"], 0.0) + a, 2)
            pt = m["parts"][f["t"]]
            pt[b["isin"]] = round(pt.get(b["isin"], 0.0) + a, 2)
            if f["est"]:
                m["est_by_bond"][b["isin"]] = round(m["est_by_bond"].get(b["isin"], 0.0) + a, 2)
                m["est"] = True
                m["est_amt"] += a
            if res["call_date"] and f["d"] > res["call_date"]:
                m["after_call"] = True
    series = []
    for k in mkeys:
        m = months[k]
        for x in ("coupon", "amort", "redemption", "put", "call", "est_amt"):
            m[x] = round(m[x], 2)
        series.append(m)
    name = None
    try:
        em = issuer_of(bonds[0]["isin"]) if bonds else None
        name = (em or {}).get("short") or (em or {}).get("title")
    except Exception:  # noqa: BLE001
        pass
    pay = sum(m["coupon"] + m["amort"] + m["redemption"] for m in series)
    return {"inn": inn, "name": name or inn, "months": series, "bonds": bonds, "warnings": warns,
            "totals": {"payments": round(pay, 2), "call": round(sum(m["call"] for m in series), 2),
                       "put": round(sum(m["put"] for m in series), 2)},
            "dates": len(dates), "n_months": sum(1 for m in series if m["coupon"] or m["amort"] or m["redemption"] or m["put"] or m["call"]),
            "today": today}


# ───────────────────────── лента техдефолтов ─────────────────────────

_DFL_PAY_OF = {"coupon": ("coupon", "coupon+amortization", "coupon+redemption"),
               "amortization": ("amortization", "coupon+amortization"),
               "redemption": ("redemption", "coupon+redemption")}


def _dfl_executed(isin, f):
    """Дата исполнения просроченного обязательства по раскрытию о выплате (coupon_paid) того же ISIN, вышедшему не раньше
    сообщения о неисполнении. Купон: тот же номер и paid_pct >= 100 (или не указан). Амортизация/погашение: payment того же вида
    (в т.ч. «купон + амортизация»), выплата не позднее срока не считается — нужна публикация после срока обязательства.
    None — не найдено."""
    d = f.get("data") or {}
    ob = d.get("obligation")
    if ob not in _DFL_PAY_OF:
        return None
    if ob == "coupon" and not d.get("coupon_no"):
        return None
    due = d.get("due_date") or f.get("due_date") or ""
    since = (f.get("published") or "")[:10]
    for p in sorted(disc_facts(isin=isin, kind="coupon_paid"), key=lambda x: x.get("published") or ""):
        pd_ = p.get("data") or {}
        pub = (p.get("published") or "")[:10]
        if pd_.get("paid_pct") is not None and pd_["paid_pct"] < 100:
            continue
        if ob == "coupon":
            if pd_.get("coupon_no") == d["coupon_no"] and pub >= since:
                return pub or _disc_fdate(p)
        elif pd_.get("payment") in _DFL_PAY_OF[ob] and pub and pub >= since and (not due or pub >= due):
            return pub
    return None


def _dfl_ok_date(d):
    return bool(d) and isinstance(d, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", d) is not None and not d.startswith("0000")


def dfl_last_due(bz, qty, today):
    """Последнее обязательство по графику Мосбиржи с датой строго раньше today (выплата в сам день ещё не просрочена): {date, obligation, amount, parts}.
    bz — moex_bondization (coupons/amort/offers), qty — число бумаг в обращении (None -> суммы не считаем).
    Несколько выплат в один день склеиваются («Купон №5 + амортизация»); последняя амортизация (или последний купон, если
    амортизаций нет) = «Погашение». None, если ни одной даты в прошлом нет."""
    bz = bz or {}
    cps = sorted((c["coupondate"], c.get("value")) for c in bz.get("coupons") or [] if _dfl_ok_date(c.get("coupondate")))
    ams = sorted((a["amortdate"], a.get("value")) for a in bz.get("amort") or [] if _dfl_ok_date(a.get("amortdate")))
    ofs = sorted({o["offerdate"] for o in bz.get("offers") or [] if _dfl_ok_date(o.get("offerdate"))})
    mat = ams[-1][0] if ams else (cps[-1][0] if cps else None)
    days = [d for d, _ in cps if d < today] + [d for d, _ in ams if d < today] + [d for d in ofs if d < today]
    if not days:
        return None
    d = max(days)
    parts, amt, known = [], 0.0, False
    for i, (cd, v) in enumerate(cps):
        if cd == d:
            parts.append("Купон №%d" % (i + 1))
            if v and qty:
                amt += float(v) * qty
                known = True
    for ad, v in ams:
        if ad == d:
            parts.append("Погашение" if ad == mat else "Амортизация")
            if v and qty:
                amt += float(v) * qty
                known = True
    if d in ofs:
        parts.append("Оферта")
    txt = parts[0]
    for x in parts[1:]:
        txt += " + " + (x[0].lower() + x[1:] if x != "Оферта" else "оферта")
    return {"date": d, "obligation": txt, "amount": round(amt, 2) if known else None, "parts": parts}


def _dfl_schedule_row(isin, today=None):
    """Просроченное обязательство по графику Мосбиржи для бумаги с флагом: dfl_last_due с числом бумаг из описания выпуска."""
    today = today or date.today().isoformat()
    bz = moex_bondization(isin)
    if not bz:
        return None
    desc = _disc_issue_desc(isin) or {}
    qty = desc.get("placed") or desc.get("issue_size")
    return dfl_last_due(bz, qty, today)


DFL_MSG_URL = "https://e-disclosure.azipi.ru/messages/%d/"
_DFL_URL_RX = re.compile(r"https://e-disclosure\.(?:azipi\.)?ru/[^\s\"'<>]+")


def dfl_msg_url(f):
    """Ссылка на первоисточник — сообщение эмитента на e-disclosure. Берём url сервера, если он ведёт на раскрытие;
    иначе собираем по номеру сообщения (doc_id). None, если нечего показать."""
    u = str(f.get("url") or "").strip()
    if _DFL_URL_RX.fullmatch(u):
        return u
    try:
        did = int(f.get("doc_id"))
    except (TypeError, ValueError):
        return None
    return DFL_MSG_URL % did if did > 0 else None


def _dfl_issuer_name(isin):
    """Наименование эмитента по ISIN: карточка эмитента Мосбиржи, затем название выпуска; тему сообщения сюда не подставляем
    (она уходит в отдельное поле subject). None, если определить не удалось."""
    if not isin:
        return None
    try:
        em = issuer_of(isin) or {}
        n = em.get("short") or em.get("title")
        if n and str(n).strip().upper() != str(isin).upper():
            return str(n).strip()
    except Exception:  # noqa: BLE001
        pass
    try:
        n = (_disc_issue_desc(isin) or {}).get("name")
        if n:
            return str(n).strip()
    except Exception:  # noqa: BLE001
        pass
    return None


def defaults_feed(since=None, isins=None, schedule=False):
    """Лента неисполненных обязательств: сообщения эмитентов (сервер данных) + флаги Мосбиржи по бумагам из isins.
    [{date, status, issuer, inn, isin, obligation, amount, executed, basis, url, date_est}], новые сверху.
    schedule=True: строки по флагу Мосбиржи получают дату/обязательство/сумму из графика выплат (date_est=True); без него даты нет
    (так ленту берут тревоги — их ключи дедупликации не должны меняться с датой)."""
    since = since or (date.today() - timedelta(days=30)).isoformat()
    try:
        raw = ds_parsed("disclosure/defaults", {"since": since})
    except Exception:  # noqa: BLE001
        raw = None
    raw = [f for f in raw if isinstance(f, dict)] if isinstance(raw, list) else []

    def one(f):
        d = f.get("data") or {}
        isin = f.get("isin")
        name = _dfl_issuer_name(isin)
        subject = re.sub(r"\s+", " ", str(f.get("title") or "")).strip() or None
        url = dfl_msg_url(f)
        try:
            ex = _dfl_executed(isin, f) if isin else None
        except Exception:  # noqa: BLE001
            ex = None
        obls = d.get("obligations") or [{"obligation": d.get("obligation"), "amount": d.get("amount")}]
        out = []
        for o in obls:            # одно сообщение может описывать несколько обязательств (купон + частичное погашение) — по строке на каждое
            ob = DISC_OBL_RU.get(o.get("obligation"), "Обязательство")
            num = " №%s" % d["coupon_no"] if d.get("coupon_no") and o.get("obligation") == "coupon" else ""
            out.append({"date": (f.get("published") or "")[:10] or None, "due_date": d.get("due_date") or f.get("due_date"),
                        "status": "default" if d.get("status") == "default" else "technical", "issuer": name or isin or "",
                        "subject": subject, "inn": f.get("inn"), "isin": isin, "obligation": ob + num,
                        "amount": o.get("amount"), "executed": ex, "basis": "Сообщение эмитента", "url": url, "date_est": False})
        return out
    rows = [r for part in (pool_map(one, raw[:300], workers=6) if raw else []) for r in part]
    have = {r["isin"] for r in rows if r.get("isin")}
    extra = [i for i in dict.fromkeys(isins or []) if i and i not in have]

    def flag(isin):
        try:
            fl = _mon_flags(isin)
            if not (fl.get("tech") or fl.get("default")):
                return None
            em = issuer_of(isin) or {}
            row = {"date": None, "due_date": None, "status": "default" if fl.get("default") else "technical",
                   "issuer": _dfl_issuer_name(isin) or isin, "subject": None, "inn": em.get("inn"), "isin": isin, "obligation": "",
                   "amount": None, "executed": None, "basis": "Флаг Мосбиржи", "url": None, "date_est": False}
            if schedule:
                try:
                    due = _dfl_schedule_row(isin)
                except Exception:  # noqa: BLE001
                    due = None
                if due:
                    row.update(date=due["date"], due_date=due["date"], obligation=due["obligation"], amount=due["amount"], date_est=True)
            return row
        except Exception:  # noqa: BLE001
            return None
    rows += [r for r in (pool_map(flag, extra, workers=6) if extra else []) if r]
    rows.sort(key=lambda r: r["date"] or "", reverse=True)
    return rows


# ── фоновый обход всего рынка: у Мосбиржи нет списка бумаг с флагом дефолта, поэтому проверяем описание каждого выпуска ──

DFL_MKT_KEY, DFL_MKT_TTL, DFL_UNI_KEY = "dfl_market_v1", 12 * 3600, "dfl_universe_v1"
_DFL_SCAN = {"running": False, "done": 0, "total": 0, "err": None}
_DFL_LOCK = threading.Lock()


def _dfl_universe():
    """ISIN всех рублёвых/валютных облигаций с RU-ISIN, торгуемых на bonds (без ОФЗ SU...). Кэш сутки."""
    hit = store().get(DFL_UNI_KEY, ttl=DAY)
    if hit:
        return hit
    j = json.loads(http_text("https://iss.moex.com/iss/engines/stock/markets/bonds/securities.json?iss.meta=off"
                             "&iss.only=securities&securities.columns=SECID,ISIN", timeout=90))
    out = []
    for r in j["securities"]["data"]:
        sec, isin = str(r[0] or ""), str(r[1] or "")
        if isin.startswith("RU") and not sec.startswith("SU") and isin not in out:
            out.append(isin)
    if out:
        store().put(DFL_UNI_KEY, out)
    return out


def _dfl_scan_run(isins):
    found = []
    try:
        for i in range(0, len(isins), 60):
            part = isins[i:i + 60]
            for isin, fl in zip(part, pool_map(lambda x: _mon_flags(x), part, workers=6)):
                if fl.get("tech") or fl.get("default"):
                    found.append(isin)
            with _DFL_LOCK:
                _DFL_SCAN["done"] = min(len(isins), i + len(part))
            time.sleep(0.15)
        store().put(DFL_MKT_KEY, {"ts": time.time(), "isins": found, "total": len(isins)})
    except Exception as e:  # noqa: BLE001
        with _DFL_LOCK:
            _DFL_SCAN["err"] = str(e)
    finally:
        with _DFL_LOCK:
            _DFL_SCAN["running"] = False


def dfl_market(force=False):
    """Список ISIN с флагом (тех)дефолта по всему рынку + состояние обхода {running, done, total}. Запускает фоновый обход,
    если сохранённый результат старше 12 ч (или force). Пока идёт обход, isins — пусто/прошлый результат."""
    saved = store().get(DFL_MKT_KEY)
    fresh = bool(saved) and time.time() - saved.get("ts", 0) < DFL_MKT_TTL
    with _DFL_LOCK:
        if (force or not fresh) and not _DFL_SCAN["running"]:
            try:
                uni = _dfl_universe()
            except Exception as e:  # noqa: BLE001
                _DFL_SCAN["err"] = str(e)
                uni = []
            if uni:
                _DFL_SCAN.update(running=True, done=0, total=len(uni), err=None)
                threading.Thread(target=_dfl_scan_run, args=(uni,), daemon=True).start()
        scan = {"running": _DFL_SCAN["running"], "done": _DFL_SCAN["done"], "total": _DFL_SCAN["total"], "error": _DFL_SCAN["err"]}
    return {"isins": list((saved or {}).get("isins") or []), "scan": scan, "ts": (saved or {}).get("ts")}


def _disc_own_isins(cfg, acc):
    out = []
    try:
        out += list(watch_isins())
    except Exception:  # noqa: BLE001
        pass
    try:
        if cfg.get("token") or imports_list():
            out += [r["isin"] for r in (build_bonds(cfg, acc).get("rows") or []) if r.get("isin") and r.get("qty")]
    except Exception:  # noqa: BLE001
        pass
    return list(dict.fromkeys(out))


# ───────────────────────── маршруты ─────────────────────────

def issuer_flows_get(cfg, acc, q, force):
    inn = (q.get("inn") or "").strip()
    if not re.fullmatch(r"\d{10,12}", inn):
        return {"error": "некорректный ИНН"}
    try:
        h = max(1, min(60, int(q.get("months") or 25)))
    except ValueError:
        h = 25
    key = ("issflows", inn, h, date.today().isoformat())
    if not force:
        hit = mem_get(key, 1800)
        if hit:
            return hit
    return mem_put(key, issuer_cashflows(inn, h))


DFL_FEED_TTL, DFL_FEED_MAXAGE = 30 * 60, 24 * 3600
_DFL_BG, _DFL_BG_LOCK = set(), threading.Lock()


def _dfl_compute(cfg, acc, since, own, scope, mk):
    """Сборка ответа ленты: {since, scope, rows, configured[, scan]}. mk — результат dfl_market (для scope=market)."""
    mine = _disc_own_isins(cfg, acc) if own else []
    if scope == "market":
        isins = list(dict.fromkeys(mine + mk["isins"]))
    else:
        isins = mine
    rows = defaults_feed(since, isins if (own or scope == "market") else None, schedule=True)
    mineset = set(mine)
    for r in rows:
        r["mine"] = r.get("isin") in mineset
    if scope == "my" and own:         # «мой портфель»: сообщения других эмитентов из общей ленты сюда не попадают
        rows = [r for r in rows if r.get("mine")]
    out = {"since": since, "scope": scope, "rows": rows, "configured": bool(ds_conf()[0])}
    if mk is not None:
        out["scan"] = mk["scan"]
    return out


def _dfl_cache_key(since_q, days, own, scope, cfg, acc):
    tok = hashlib.sha1(((cfg.get("token") or "") + "|" + str(bool(cfg.get("sandbox")))).encode("utf-8")).hexdigest()[:10]
    return "dfl_feed_v2:%s:%s:%d:%s:%s" % (scope, since_q or days, int(own), tok, acc)


def _dfl_refresh_bg(ckey, cfg, acc, since, own, scope):
    """Фоновое обновление ленты: один поток на ключ, результат пишется в kv."""
    with _DFL_BG_LOCK:
        if ckey in _DFL_BG:
            return
        _DFL_BG.add(ckey)

    def run():
        try:
            mk = dfl_market(False) if scope == "market" else None
            out = _dfl_compute(cfg, acc, since, own, scope, mk)
            if not (mk and mk["scan"]["running"]):
                store().put(ckey, {"ts": time.time(), "mk_ts": (mk or {}).get("ts"), "out": out})
        except Exception:  # noqa: BLE001
            pass
        finally:
            with _DFL_BG_LOCK:
                _DFL_BG.discard(ckey)
    threading.Thread(target=run, daemon=True).start()


def defaults_get(cfg, acc, q, force):
    """Лента техдефолтов. Готовый результат хранится в kv: открытие экрана отдаёт его сразу (cached_at — время сборки),
    а устаревший (старше 30 мин или после нового обхода рынка) обновляется в фоне (refreshing=True)."""
    try:
        days = max(1, min(365, int(q.get("days") or 30)))
    except ValueError:
        days = 30
    since_q = (q.get("since") or "").strip()
    since = since_q if re.fullmatch(r"\d{4}-\d{2}-\d{2}", since_q) else (date.today() - timedelta(days=days)).isoformat()
    own = str(q.get("own", "1")) != "0"
    scope = "market" if str(q.get("scope") or "my").strip().lower() == "market" else "my"
    ckey = _dfl_cache_key(since_q if since_q == since else "", days, own, scope, cfg, acc)
    mk = dfl_market(bool(force)) if scope == "market" else None
    now = time.time()
    if not force:
        try:
            hit = store().get(ckey)
        except Exception:  # noqa: BLE001
            hit = None
        if isinstance(hit, dict) and isinstance(hit.get("out"), dict) and now - float(hit.get("ts") or 0) < DFL_FEED_MAXAGE:
            scanning = bool(mk and mk["scan"]["running"])
            stale = (now - float(hit["ts"]) > DFL_FEED_TTL or hit["out"].get("since") != since
                     or (mk is not None and hit.get("mk_ts") != mk.get("ts")))
            if stale and not scanning:      # пока идёт обход рынка, пересборка бессмысленна: дождёмся его конца
                _dfl_refresh_bg(ckey, cfg, acc, since, own, scope)
            out = dict(hit["out"], cached_at=hit["ts"], refreshing=bool(stale))
            if mk is not None:
                out["scan"] = mk["scan"]
            return out
    out = _dfl_compute(cfg, acc, since, own, scope, mk)
    if not (mk and mk["scan"]["running"]):      # промежуточный результат не кэшируем: он меняется по мере обхода
        store().put(ckey, {"ts": now, "mk_ts": (mk or {}).get("ts"), "out": out})
        out = dict(out, cached_at=now)
    return out


API_GET["/api/issuer_flows"] = issuer_flows_get
API_GET["/api/defaults"] = defaults_get
# ── недельная инфляция (Росстат): еженедельные заметки «Об оценке индекса потребительских цен с … по …» ──
# Источник: https://rosstat.gov.ru/central-news (постраничный список «Новости статистики», ?page=N, новые сверху).
# Заметка — PDF (с 2026 г.) или HTML; в тексте: «индекс потребительских цен, по оценке Росстата, составил 100,12%».
# Прошлые недели не меняются: разобранные заметки хранятся в kv навсегда, свежие страницы перечитываются раз в 12 ч,
# история докачивается в фоне (≤1 запрос/с). Мёртвые ссылки старых заметок запоминаются и не перезапрашиваются.

import html
import urllib.parse

ROSSTAT_NEWS = "https://rosstat.gov.ru/central-news"
_WI_KEY = "weekly_cpi_notes_v1"
_WI_TTL = 12 * 3600
_WI_FLOOR = date(2017, 1, 1)
_WI_MAX_PAGES = 100
_WI_DEAD_STOP = 8            # подряд недоступных старых заметок — дальше архив не углубляем
_WI_PACE = 1.0
_wi_lock = threading.Lock()
_wi = {"running": False, "err": None, "last": 0}
_RU_MONTHS = {"января": 1, "февраля": 2, "марта": 3, "апреля": 4, "мая": 5, "июня": 6, "июля": 7, "августа": 8,
              "сентября": 9, "октября": 10, "ноября": 11, "декабря": 12}
_MON_RE = "|".join(_RU_MONTHS)


# --- минимальное извлечение текста из PDF (Flate + ToUnicode, без сторонних библиотек) ---

def _pdf_stream(body):
    m = re.search(rb"stream\r?\n(.*)endstream", body, re.S)
    if not m:
        return b""
    d = m.group(1)
    if b"FlateDecode" in body[:m.start()]:
        try:
            d = zlib.decompressobj().decompress(d)
        except Exception:  # noqa: BLE001
            return b""
    return d


def _cpi_pdf_cmap(data):
    mp, t = {}, data.decode("latin1")
    for blk in re.findall(r"beginbfchar(.*?)endbfchar", t, re.S):
        for a, c in re.findall(r"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", blk):
            mp[int(a, 16)] = bytes.fromhex(c).decode("utf-16-be", "replace")
    for blk in re.findall(r"beginbfrange(.*?)endbfrange", t, re.S):
        for a, c, d in re.findall(r"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", blk):
            a, c, d = int(a, 16), int(c, 16), int(d, 16)
            for i in range(a, c + 1):
                mp[i] = chr(d + i - a)
    return mp


def pdf_first_page_text(b):
    objs = {int(m.group(1)): m.group(2) for m in re.finditer(rb"(\d+)\s+0\s+obj\b(.*?)endobj", b, re.S)}
    page = next((body for body in objs.values() if re.search(rb"/Type\s*/Page\b", body) and b"/Contents" in body), None)
    if page is None:
        return ""
    fonts = {}
    fm = re.search(rb"/Font\s*<<(.*?)>>", page, re.S)
    for name, num in re.findall(rb"/(\w+)\s+(\d+)\s+0\s+R", fm.group(1) if fm else b""):
        tu = re.search(rb"/ToUnicode\s+(\d+)\s+0\s+R", objs.get(int(num), b""))
        fonts[name.decode()] = _cpi_pdf_cmap(_pdf_stream(objs[int(tu.group(1))])) if tu and int(tu.group(1)) in objs else None
    cm = re.search(rb"/Contents\s*(\[[^\]]*\]|\d+\s+0\s+R)", page)
    out = []
    for r in [int(x) for x in re.findall(rb"(\d+)\s+0\s+R", cm.group(1))] if cm else []:
        c, cur = _pdf_stream(objs.get(r, b"")), None
        for tok in re.finditer(rb"/(\w+)\s+[\d.]+\s+Tf|\[(.*?)\]\s*TJ|<([0-9A-Fa-f]*)>\s*Tj|\((.*?)(?<!\\)\)\s*Tj|(ET)", c, re.S):
            if tok.group(1):
                cur = fonts.get(tok.group(1).decode())
                continue
            if tok.group(5):
                out.append(" ")
                continue
            if tok.group(2) is not None:
                parts = re.findall(rb"<([0-9A-Fa-f]*)>|\(((?:\\.|[^\\)])*)\)", tok.group(2))
            elif tok.group(3) is not None:
                parts = [(tok.group(3), b"")]
            else:
                parts = [(b"", tok.group(4))]
            for h, lit in parts:
                if h and cur is not None:
                    hb = bytes.fromhex(h.decode())
                    out.append("".join(cur.get(int.from_bytes(hb[i:i + 2], "big"), "") for i in range(0, len(hb), 2)))
                elif h:
                    out.append(bytes.fromhex(h.decode()).decode("cp1251", "replace"))
                else:
                    out.append(re.sub(rb"\\(.)", rb"\1", lit).decode("cp1252", "replace"))
    return "".join(out)


# --- разбор заметки и списка ---

def _wi_num(a, b):
    return float(a + "." + b)


def weekly_note_parse(data, title=""):
    """Заметка (PDF или HTML, bytes) -> {date, pct, ytd} либо None. pct — недельный прирост в %, ytd — с начала года."""
    if data[:4] == b"%PDF":
        text = pdf_first_page_text(data)
    else:
        text = re.sub(r"<script.*?</script>|<style.*?</style>", " ", data.decode("utf-8", "replace"), flags=re.S | re.I)
        text = html.unescape(re.sub(r"<[^>]+>", " ", text))
    t = re.sub(r"\s+", " ", text.replace("\xa0", " "))
    # индекс потребительских цен (сноска-цифра), по оценке Росстата, составил 100,12%  /  цены выросли на 0,12%
    m = re.search(r"индекс\s+потребительских\s+цен[^.]{0,40}?составил\s*(\d{2,3})\s*[,.]\s*(\d{1,2})\s*%", t, re.I)
    pct = round(_wi_num(m.group(1), m.group(2)) - 100.0, 2) if m else None
    if pct is None:
        m = re.search(r"(?:цены|потребительские цены)\s+(выросли|снизились|увеличились|сократились)\s+на\s*(\d+)\s*[,.]\s*(\d{1,2})\s*%", t, re.I)
        if m:
            pct = _wi_num(m.group(2), m.group(3)) * (1 if m.group(1).lower() in ("выросли", "увеличились") else -1)
    if pct is None:
        return None
    my = re.search(r"с\s+начала\s+года\s*[–—-]?\s*(\d{2,3})\s*[,.]\s*(\d{1,2})\s*%", t, re.I)
    ytd = round(_wi_num(my.group(1), my.group(2)) - 100.0, 2) if my else None
    d = weekly_end_date(t) or weekly_end_date(title)
    return {"date": d.isoformat(), "pct": pct, "ytd": ytd} if d else None


def weekly_end_date(text):
    """Дата конца недели: «… по 9 ноября 2026 г.» (год может быть разорван пробелом: «202 6»)."""
    m = re.search(r"\bпо\s+(\d{1,2})\s+(%s)\s+(20\d)\s?(\d)\b" % _MON_RE, text, re.I)
    if not m:
        return None
    try:
        return date(int(m.group(3) + m.group(4)), _RU_MONTHS[m.group(2).lower()], int(m.group(1)))
    except ValueError:
        return None


def weekly_listing_parse(page_html):
    """Страница списка новостей -> [(url, заголовок)] только заметок «Об оценке индекса потребительских цен …», новые сверху."""
    out = []
    for h, t in re.findall(r'<a[^>]*href="([^"]+)"[^>]*>(.*?)</a>', page_html, re.S):
        t = re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", t)).replace("\xa0", " ")).strip()
        if re.match(r"Об\s+оценке\s+индекса\s+потребительских\s+цен", t, re.I):
            u = urllib.parse.urljoin(ROSSTAT_NEWS, h)
            if all(u != x[0] for x in out):
                out.append((u, t))
    return out


def weekly_avg_by_week(rows, y0=2017, y1=2021):
    """Среднее по номеру недели за y0..y1: ([(неделя, среднее)], [годы, по которым есть данные])."""
    acc, ys = {}, set()
    for r in rows:
        if y0 <= r["year"] <= y1:
            acc.setdefault(r["week"], []).append(r["pct"])
            ys.add(r["year"])
    return [(w, round(sum(v) / len(v), 3)) for w, v in sorted(acc.items())], sorted(ys)


def _wi_state():
    st = store().get(_WI_KEY) or {}
    st.setdefault("weeks", {})
    st.setdefault("dead", [])
    st.setdefault("t", 0)
    st.setdefault("deep", False)       # история докачана до конца архива
    return st


def weekly_collect(fetch=None, pace=_WI_PACE, deep=False, max_pages=_WI_MAX_PAGES, save=None):
    """Обходит страницы списка (новые -> старые) и разбирает ещё неизвестные заметки.
    deep=False: только свежие страницы — останов, когда на странице нет новых заметок.
    deep=True: пока не упрёмся в _WI_FLOOR, конец списка или _WI_DEAD_STOP недоступных заметок подряд."""
    fetch = fetch or (lambda u: http_bytes(u, timeout=60))
    st = _wi_state()
    known = {v["url"] for v in st["weeks"].values()}
    dead = set(st["dead"])
    dead_run = 0
    for p in range(1, max_pages + 1):
        try:
            page = fetch(ROSSTAT_NEWS + ("?page=%d" % p if p > 1 else "")).decode("utf-8", "replace")
        except Exception:  # noqa: BLE001
            break
        items = weekly_listing_parse(page)
        fresh = 0
        for u, title in items:
            if u in known or u in dead:
                dead_run = dead_run + 1 if u in dead else 0
                continue
            time.sleep(pace)
            try:
                rec = weekly_note_parse(fetch(u), title)
            except Exception:  # noqa: BLE001
                rec = None
            fresh += 1
            if rec is None:
                dead.add(u)
                dead_run += 1
                continue
            dead_run = 0
            rec["url"] = u
            st["weeks"][rec["date"]] = rec
            known.add(u)
        st["dead"] = sorted(dead)
        if save:
            save(st)
        if not items and p > 1:
            st["deep"] = True
            break
        if not deep and not fresh:
            break
        if deep and (dead_run >= _WI_DEAD_STOP or (st["weeks"] and min(st["weeks"]) < _WI_FLOOR.isoformat())):
            st["deep"] = True
            break
        time.sleep(pace)
    if deep and not st["deep"] and p >= max_pages:
        st["deep"] = True
    st["t"] = time.time()
    return st


def _wi_run():
    try:
        st = weekly_collect(deep=not _wi_state()["deep"], save=lambda s: store().put(_WI_KEY, s))
        store().put(_WI_KEY, st)
        _wi["err"] = None
    except Exception as e:  # noqa: BLE001
        _wi["err"] = str(e)[:200]
    finally:
        with _wi_lock:
            _wi["running"] = False


def weekly_payload(st, loading=False, err=None):
    rows = []
    for d, v in sorted(st["weeks"].items()):
        dt = date.fromisoformat(d)
        rows.append({"year": dt.year, "date": d, "week": min(52, dt.isocalendar()[1]), "pct": v["pct"], "ytd": v.get("ytd")})
    years = {}
    for r in rows:
        years.setdefault(str(r["year"]), []).append(r)
    avg, ys = weekly_avg_by_week(rows)
    label = ("%d–%d" % (ys[0], ys[-1]) if ys[0] != ys[-1] else str(ys[0])) if ys else "2017–2021"
    return {"years": years, "avg": avg, "avg_label": label, "avg_years": ys, "empty": not rows, "loading": loading,
            "history_from": rows[0]["date"] if rows else None, "updated": st.get("t") or None, "error": err,
            "sources": [ROSSTAT_NEWS]}


def weekly_inflation_calc():
    """Для calc_worker на сервере: докачать недостающее синхронно и вернуть готовый ответ экрана."""
    st = weekly_collect(deep=not _wi_state()["deep"], save=lambda s: store().put(_WI_KEY, s))
    store().put(_WI_KEY, st)
    return weekly_payload(st)


def weekly_inflation(force=False):
    """Отдаёт то, что уже разобрано; недостающее (свежие недели раз в 12 ч, история при первом запуске) докачивается в фоне."""
    st = _wi_state()
    if not force and (time.time() - st["t"] > _WI_TTL or not st["deep"]):
        got = ds_calc("inflation")                    # сервер уже собрал всю историю: не качаем её у себя
        if got and isinstance(got[0], dict) and got[0].get("years") and not got[0].get("empty"):
            return dict(got[0], loading=False)
    with _wi_lock:
        stale = force or (time.time() - st["t"] > _WI_TTL or not st["deep"]) and time.time() - _wi["last"] > 600
        if stale and not _wi["running"]:
            _wi["running"] = True
            _wi["last"] = time.time()
            threading.Thread(target=_wi_run, daemon=True).start()
        running = _wi["running"]
    return weekly_payload(st, running, _wi["err"])


API_GET["/api/inflation_weekly"] = lambda cfg, acc, q, force: weekly_inflation(force)
# ═══════════════════════════════ биржевые фонды (БПИФ): паспорт фонда и состав ═══════════════════════════════
# Карточка фонда строится тем же stock_card (13s_stocks.py): котировка, свечи, индикаторы. Здесь — то, что есть только у фондов:
#   fund_meta(secid)      — вид бумаги, полное название, дата начала торгов, управляющая компания (ISS: description + emitters);
#   fund_holdings(secid)  — состав фонда для отдельного запроса GET /api/fund/holdings (карточка не ждёт его).
# Источники состава (оба публичные, без авторизации):
#   1) T-Bank: web/v2/etf/assets/<тикер>/structure — фактический состав и СЧА. Отдаёт данные по фондам «Т-Капитала»;
#      по фондам других УК приходит пустой список. Даты среза в ответе нет — показываем дату получения.
#   2) Мосбиржа ISS: веса бумаг в индексе, за которым следует фонд (таблица FND_INDEX_OF). Это не фактический портфель,
#      а «состав индекса, за которым следует фонд» — так и подписывается.
# СЧА и расчётная цена пая (fund_nav, поле fund.nav карточки) — Мосбиржа ISS, те же запросы, что у карточки фонда на moex.com:
#   apps/infogrid/ppif/rates.json?q=<тикер> — NAV (СЧА, руб.) и NAV_DATE (обычно раз в несколько дней, по отчётам УК);
#   securities/<тикер>/inavs.json — коды индикативной цены пая (iNAV) на доске INAV, по валютам (TGLD: TGLDA в USD, TGLDB в RUB);
#   engines/stock/markets/index/boards/INAV/securities/<код>.json — текущее значение iNAV (CURRENTVALUE), закрытие прошлого дня.
# Поэлементного состава фондов в открытых данных Мосбиржи нет (страница фонда на moex.com его тоже не показывает).
# Кэш: удачный ответ — сутки, ошибка источника — 15 минут. Модуль загружается раньше 13s_stocks.py: на уровне модуля
# нельзя ссылаться на имена оттуда (только внутри функций). Префикс имён fnd_ / FND_.

FND_TB_URL = "https://www.tbank.ru/api/invest-gw/fireg-advisory/api/web/v2/etf/assets/%s/structure?idKind=ticker"
FND_TB_PAGE = "https://www.tbank.ru/invest/etfs/%s/"
FND_ISS_IDX = "https://iss.moex.com/iss/statistics/engines/stock/markets/index/analytics/%s.json?iss.meta=off&limit=100&start=%d"
FND_ISS_IDX_PAGE = "https://www.moex.com/ru/index/%s/constituents"
FND_ISS_DESC = "https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description"
FND_ISS_EMIT = "https://iss.moex.com/iss/emitters/%s.json?iss.meta=off"
FND_ISS_RATES = "https://iss.moex.com/iss/apps/infogrid/ppif/rates.json?iss.meta=off&q=%s"
FND_ISS_INAVS = "https://iss.moex.com/iss/securities/%s/inavs.json?iss.meta=off"
FND_ISS_INAV = ("https://iss.moex.com/iss/engines/stock/markets/index/boards/INAV/securities/%s.json?iss.meta=off&iss.only=securities,marketdata"
                "&securities.columns=SECID,NAME,CURRENCYID,DECIMALS&marketdata.columns=SECID,CURRENTVALUE,LASTVALUE,CAPITALIZATION,TRADEDATE,UPDATETIME")
FND_MOEX_PAGE = "https://www.moex.com/ru/issue.aspx?code=%s"
FND_INAV_PAGE = "https://www.moex.com/ru/index/%s?index=inav"
FND_INAV_TTL = 10 * 60                             # iNAV меняется в течение торгов
FND_TTL = DAY
FND_ERR_TTL = 15 * 60
FND_META_TTL = 7 * DAY
# Фонды других УК, которые следуют за индексом Мосбиржи, и сам индекс. Только бумаги, где индекс прямо указан в правилах фонда.
FND_INDEX_OF = {"SBMX": "IMOEX", "EQMX": "IMOEX", "TMOS": "IMOEX", "SBGB": "RGBITR", "SBRB": "RUCBTRNS"}
FND_INDEX_NAMES = {"IMOEX": "Индекс МосБиржи", "RGBITR": "Индекс гособлигаций RGBITR", "RUCBTRNS": "Индекс корпоративных облигаций RUCBTRNS"}
FND_INDEX_SHARES = {"IMOEX"}                       # индексы акций: бумаги из состава открываются карточкой акции
FND_NO_DATA_NOTE = {
    "Денежный рынок": "Фонды денежного рынка обычно вкладывают в сделки репо с центральным контрагентом; поэлементный состав "
                      "публикует управляющая компания в отчётах фонда.",
    "Золото и металлы": "Фонды на золото обычно держат биржевое золото или фьючерсы на него; подробный состав — в отчётах управляющей компании.",
}
_FND_TYPE_RU = {"Stock": "Акция", "Bond": "Облигация", "Currency": "Валюта", "Etf": "Фонд", "Futures": "Фьючерс"}


def _fnd_f(v):
    try:
        x = float(v)
    except (TypeError, ValueError):
        return None
    return x if x == x and x not in (float("inf"), float("-inf")) else None


def _fnd_secid(secid):
    s = (secid or "").strip().upper()
    if not re.fullmatch(r"[A-Z0-9._-]{1,16}", s):
        raise ApiError("Некорректный тикер.", 400)
    return s


def fnd_tb_parse(j):
    """Ответ T-Bank (structure) -> {items, nav, nav_cur, count} или None, если состава нет (фонд другой УК или пустой ответ).
    items: [{name, ticker, isin, type, type_ru, weight, value, stock}], weight — доля в процентах, по убыванию."""
    if not isinstance(j, dict):
        return None
    items = []
    for x in j.get("items") or []:
        if not isinstance(x, dict):
            continue
        w = _fnd_f(x.get("relativeValue"))
        name = str(x.get("name") or x.get("ticker") or "").strip()
        if w is None or not name:
            continue
        t = str(x.get("type") or "")
        items.append({"name": name, "ticker": x.get("ticker") or None, "isin": None, "type": t,
                      "type_ru": x.get("typeRu") or _FND_TYPE_RU.get(t) or "", "weight": round(w, 4),
                      "value": _fnd_f(x.get("value")), "stock": t == "Stock" and bool(x.get("ticker"))})
    if not items:
        return None
    items.sort(key=lambda r: -r["weight"])
    nav = _fnd_f(j.get("netAssetValue"))
    return {"items": items, "nav": nav or None, "nav_cur": (j.get("currency") or "RUB").upper() if nav else None,
            "count": int(j.get("structureCount") or len(items))}


def fnd_iss_index_parse(j):
    """Страница ISS analytics индекса -> (rows, total, tradedate). rows: [{name, ticker, isin, weight}]."""
    t = (j or {}).get("analytics") or {}
    cols = t.get("columns") or []
    rows, day = [], None
    for r in t.get("data") or []:
        d = dict(zip(cols, r))
        w = _fnd_f(d.get("weight"))
        sec = d.get("secids") or d.get("ticker")
        if w is None or not sec:
            continue
        day = day or d.get("tradedate")
        isin = sec if re.fullmatch(r"[A-Z]{2}[A-Z0-9]{9}\d", str(sec)) and not str(sec).startswith("SU") else None   # SU…RMFS — код ОФЗ на бирже, не ISIN
        rows.append({"name": d.get("shortnames") or sec, "ticker": d.get("ticker") or sec, "isin": isin, "weight": round(w, 4)})
    cur = (j or {}).get("analytics.cursor") or {}
    cd = dict(zip(cur.get("columns") or [], (cur.get("data") or [[]])[0])) if cur.get("data") else {}
    total = int(cd.get("TOTAL") or len(rows))
    return rows, total, day


def fnd_index_holdings(index):
    """Все бумаги индекса с весами (страницы по 100)."""
    j = json.loads(http_text(FND_ISS_IDX % (index, 0), timeout=20))
    rows, total, day = fnd_iss_index_parse(j)
    start = len(rows)
    while rows and start < min(total, 1000):
        part, _, _ = fnd_iss_index_parse(json.loads(http_text(FND_ISS_IDX % (index, start), timeout=20)))
        if not part:
            break
        rows.extend(part)
        start += len(part)
    rows.sort(key=lambda r: -r["weight"])
    return rows, day


def _fnd_from_tb(secid):
    try:
        raw = http_text(FND_TB_URL % urllib.parse.quote(secid), timeout=15)
    except urllib.error.HTTPError as e:
        if e.code in (400, 404):                   # фонд не из линейки T-Bank: «record not found» — состава там нет, это не сбой
            return None
        raise
    return fnd_tb_parse(json.loads(raw))


def fund_holdings_build(secid, category=None):
    """Состав фонда из доступных источников -> словарь ответа /api/fund/holdings (без кэша)."""
    today = date.today().isoformat()
    base = {"secid": secid, "items": [], "as_of": None, "as_of_kind": None, "nav": None, "nav_cur": None, "source": None,
            "basis": None, "index": None, "status": "none", "note": None, "fetched": time.time()}
    errs = []
    tb = None
    try:
        tb = _fnd_from_tb(secid)
    except Exception as e:  # noqa: BLE001 — сеть, JSON, HTTP-ошибка источника
        errs.append("T-Bank: " + str(e)[:80])
    if tb:
        base.update(items=tb["items"], nav=tb["nav"], nav_cur=tb["nav_cur"], as_of=today, as_of_kind="fetched", status="ok", basis="fund",
                    source={"name": "T-Bank (Т-Капитал)", "url": FND_TB_PAGE % secid})
        return base
    idx = FND_INDEX_OF.get(secid)
    if idx:
        rows, day = [], None
        try:
            rows, day = fnd_index_holdings(idx)
        except Exception as e:  # noqa: BLE001
            errs.append("Мосбиржа: " + str(e)[:80])
        if rows:
            shares = idx in FND_INDEX_SHARES
            for r in rows:
                r.update(type="Stock" if shares else "Bond", type_ru="Акция" if shares else "Облигация", value=None, stock=shares)
            base.update(items=rows, as_of=day, as_of_kind="index", status="ok", basis="index",
                        index={"id": idx, "name": FND_INDEX_NAMES.get(idx, idx)},
                        source={"name": "Мосбиржа", "url": FND_ISS_IDX_PAGE % idx})
            return base
    if errs:                                       # хотя бы один источник не ответил — не запоминаем «состава нет» надолго
        base.update(status="err", note="Источник состава сейчас недоступен. " + "; ".join(errs))
        return base
    base["note"] = FND_NO_DATA_NOTE.get(category or "", "Открытого источника с составом этого фонда нет; состав публикует управляющая компания "
                                                       "в отчётах фонда.")
    return base


def fund_holdings(secid, force=False, category=None):
    """Состав фонда с кэшем в store: удачный ответ — сутки, ошибка источника — 15 минут."""
    secid = _fnd_secid(secid)
    key = "fnd_hold_v1_" + secid
    if not force:
        hit = store().get(key, FND_TTL)
        if hit is not None and (hit.get("status") != "err" or time.time() - (hit.get("fetched") or 0) < FND_ERR_TTL):
            return hit
    with key_lock(key):
        res = fund_holdings_build(secid, category)
        store().put(key, res)
    return res


def _fnd_rows(j, name):
    t = (j or {}).get(name) or {}
    cols = t.get("columns") or []
    return [dict(zip(cols, r)) for r in t.get("data") or [] if isinstance(r, list)]


def fnd_rates_parse(j, secid):
    """ISS apps/infogrid/ppif/rates.json -> {nav, nav_date, nav_cur, issue_date, manager, manager_url} для точного тикера или None.
    Поиск q= может вернуть несколько фондов — берём строку с тем же SECID."""
    r = next((x for x in _fnd_rows(j, "rates") if str(x.get("SECID") or "").upper() == secid), None)
    if r is None:
        return None
    nav = _fnd_f(r.get("NAV"))
    cur = str(r.get("FACEUNIT") or "RUB").upper().replace("SUR", "RUB").replace("RUR", "RUB")
    return {"nav": nav if nav and nav > 0 else None, "nav_date": r.get("NAV_DATE") if nav else None, "nav_cur": cur,
            "issue_date": r.get("ISSUEDATE") or None, "manager": r.get("EMITENT_SHORT_NAME") or None, "manager_url": r.get("EMITENT_URL") or None}


def fnd_inavs_pick(j, cur="RUB"):
    """ISS securities/<тикер>/inavs.json -> код iNAV в валюте фонда (иначе первый) или None: {code, cur}."""
    rows = [r for r in _fnd_rows(j, "inavs") if r.get("secid")]
    if not rows:
        return None
    r = next((x for x in rows if str(x.get("currencyid") or "").upper() == cur), rows[0])
    return {"code": r["secid"], "cur": str(r.get("currencyid") or "RUB").upper()}


def fnd_inav_parse(j):
    """ISS доска INAV, одна бумага -> {value, prev, date, time, cur} или None. value — текущее значение (иначе закрытие прошлого дня)."""
    md = (_fnd_rows(j, "marketdata") or [{}])[0]
    sec = (_fnd_rows(j, "securities") or [{}])[0]
    cur_v, prev = _fnd_f(md.get("CURRENTVALUE")), _fnd_f(md.get("LASTVALUE"))
    v = cur_v if cur_v and cur_v > 0 else (prev if prev and prev > 0 else None)
    if v is None:
        return None
    return {"value": v, "prev": prev if prev and prev > 0 else None, "date": md.get("TRADEDATE") or None,
            "time": (md.get("UPDATETIME") or None) if cur_v else None, "cur": str(sec.get("CURRENCYID") or "RUB").upper()}


def _fnd_cached(key, ttl, fn):
    """Значение из store (ttl) или fn(); ошибка источника запоминается в памяти на FND_ERR_TTL. -> (значение, ошибка-строка | None)."""
    hit = store().get(key, ttl)
    if hit is not None:
        return hit.get("v"), None
    err = mem_get(("fnd_err", key), FND_ERR_TTL)
    if err is not None:
        return None, err
    try:
        v = fn()
    except Exception as e:  # noqa: BLE001 — сеть, JSON, HTTP-ошибка источника
        err = str(e)[:80] or e.__class__.__name__
        mem_put(("fnd_err", key), err)
        return None, err
    store().put(key, {"v": v})
    return v, None


def fund_nav(secid, price=None):
    """СЧА и расчётная цена пая с Мосбиржи. -> {nav, nav_date, nav_cur, inav, inav_prev, inav_cur, inav_date, inav_time, inav_code,
    premium (биржевая цена к iNAV, %), issue_date, manager, manager_url, source_url, inav_url, errors}. Нет данных — поля None."""
    secid = _fnd_secid(secid)
    q = urllib.parse.quote(secid)
    out = {"nav": None, "nav_date": None, "nav_cur": None, "inav": None, "inav_prev": None, "inav_cur": None, "inav_date": None,
           "inav_time": None, "inav_code": None, "premium": None, "issue_date": None, "manager": None, "manager_url": None,
           "source_url": FND_MOEX_PAGE % q, "inav_url": None, "errors": []}
    rates, err = _fnd_cached("fnd_rates_v1_" + secid, FND_TTL, lambda: fnd_rates_parse(json.loads(http_text(FND_ISS_RATES % q, timeout=15)), secid))
    if err:
        out["errors"].append("СЧА: " + err)
    if rates:
        out.update(rates)
    cur = (rates or {}).get("nav_cur") or "RUB"
    pick, err = _fnd_cached("fnd_inavs_v1_" + secid, FND_META_TTL, lambda: fnd_inavs_pick(json.loads(http_text(FND_ISS_INAVS % q, timeout=15)), cur))
    if err:
        out["errors"].append("iNAV: " + err)
    if pick:
        code = pick["code"]
        iv, err = _fnd_cached("fnd_inav_v1_" + code, FND_INAV_TTL,
                              lambda: fnd_inav_parse(json.loads(http_text(FND_ISS_INAV % urllib.parse.quote(code), timeout=15))))
        if err:
            out["errors"].append("iNAV: " + err)
        if iv:
            out.update(inav=iv["value"], inav_prev=iv["prev"], inav_cur=iv["cur"] or pick["cur"], inav_date=iv["date"], inav_time=iv["time"],
                       inav_code=code, inav_url=FND_INAV_PAGE % urllib.parse.quote(code))
            p = _fnd_f(price)
            if p and p > 0 and out["inav_cur"] == "RUB" and cur == "RUB":
                out["premium"] = round((p / iv["value"] - 1) * 100, 2)
    return out


def fund_meta(secid, category=None):
    """Паспорт фонда из ISS: {category, type_name, full_name, issue_name, issue_date, manager, manager_url}. Ошибки сети не критичны (поля None)."""
    secid = _fnd_secid(secid)
    key = "fnd_meta_v2_" + secid
    hit = store().get(key, FND_META_TTL)
    if hit is None:
        hit = mem_get(("fnd_meta_err", secid), FND_ERR_TTL)
    if hit is None:
        hit, ok = {"type_name": None, "full_name": None, "issue_name": None, "issue_date": None, "manager": None, "manager_url": None}, True
        try:
            j = json.loads(http_text(FND_ISS_DESC % urllib.parse.quote(secid), timeout=10))
            t = j.get("description") or {}
            d = {r[0]: r[2] for r in t.get("data") or [] if r}
            hit.update(type_name=d.get("TYPENAME"), full_name=d.get("NAME") or d.get("ISSUENAME"), issue_name=d.get("ISSUENAME"),
                       issue_date=d.get("ISSUEDATE"))
            em = d.get("EMITTER_ID")
            if em:
                e = json.loads(http_text(FND_ISS_EMIT % urllib.parse.quote(str(em)), timeout=10))
                et = e.get("emitter") or {}
                er = dict(zip(et.get("columns") or [], (et.get("data") or [[]])[0])) if et.get("data") else {}
                hit.update(manager=er.get("SHORT_TITLE") or er.get("TITLE"), manager_url=er.get("URL") or None)
        except Exception:  # noqa: BLE001
            ok = False
        if ok:
            store().put(key, hit)
        else:
            mem_put(("fnd_meta_err", secid), hit)
    return dict(hit, category=category)


def fund_holdings_get(cfg, acc, q, force):
    secid = q.get("secid") or ""
    if not secid.strip():
        raise ApiError("Не указан тикер фонда.", 400)
    s = _fnd_secid(secid)
    try:
        cat = stk_fund_category(s)
    except Exception:  # noqa: BLE001
        cat = None
    return fund_holdings(s, bool(force), cat)


API_GET["/api/fund/holdings"] = fund_holdings_get
