def mm_f(v):
    try:
        x = float(v)
    except (TypeError, ValueError):
        return None
    return x if x == x and x not in (float("inf"), float("-inf")) else None


def mm_d(s):
    try:
        return datetime.strptime(str(s)[:10], "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None


# ── расчёты (чистые функции) ──

def mm_ann(p0, p1, days):
    """Годовая доходность по росту цены, %: (P1/P0)^(365/дни) − 1. Дневная капитализация подразумевается самим законом роста цены."""
    if not p0 or not p1 or p0 <= 0 or p1 <= 0 or not days or days <= 0:
        return None
    return ((p1 / p0) ** (365.0 / days) - 1) * 100


def mm_window_return(closes, days, max_gap=7):
    """closes — [(ISO-дата, цена)] по возрастанию. Окно в days календарных дней, оканчивающееся последней точкой.
    Начальная точка — последнее закрытие не позже (конец − days); если истории не хватает (первая точка позже этой даты
    больше чем на max_gap дней) — None. Возвращает {ret, total, days, start, end} (ret — годовая, %)."""
    pts = [(mm_d(d), p) for d, p in closes if mm_d(d) and mm_f(p)]
    if len(pts) < 2:
        return None
    end_d, p1 = pts[-1]
    target = end_d - timedelta(days=days)
    p0 = None
    for d, p in pts:
        if d <= target:
            p0 = (d, p)
        else:
            break
    if p0 is None:
        first = pts[0]
        if (first[0] - target).days > max_gap or first[0] >= end_d:
            return None
        p0 = first
    d0, v0 = p0
    n = (end_d - d0).days
    if n < max(5, days // 3):
        return None
    return {"ret": mm_ann(v0, p1, n), "total": (p1 / v0 - 1) * 100, "days": n, "start": d0.isoformat(), "end": end_d.isoformat()}


def mm_rate_factor(rates, d0, d1):
    """Накопленный множитель при размещении по ставке (% годовых, ежедневная капитализация на календарный день) от d0 (искл.) до d1 (вкл.).
    rates — [(ISO-дата, ставка %)] по возрастанию; между точками ставка переносится вперёд. None — ставки на d0 нет в данных."""
    rs = [(mm_d(d), mm_f(v)) for d, v in rates]
    rs = [(d, v) for d, v in rs if d and v is not None]
    if not rs or rs[0][0] > d0 + timedelta(days=7):
        return None
    j, cur, f, d = 0, rs[0][1], 1.0, d0
    while j < len(rs) and rs[j][0] <= d0:
        cur = rs[j][1]
        j += 1
    while d < d1:
        d += timedelta(days=1)
        while j < len(rs) and rs[j][0] <= d:
            cur = rs[j][1]
            j += 1
        f *= 1 + cur / 100.0 / 365.0
    return f


def mm_bench_ann(rates, d0, d1):
    """Годовая доходность ставки за окно [d0, d1] с ежедневной капитализацией, %."""
    n = (d1 - d0).days
    f = mm_rate_factor(rates, d0, d1)
    if f is None or n <= 0:
        return None
    return (f ** (365.0 / n) - 1) * 100


def mm_gap(fund_ann, bench_ann):
    """Отставание от ставки, п.п.: доходность фонда минус ставка (отрицательное — фонд отстаёт). Неявные издержки (комиссия, проскальзывание)."""
    if fund_ann is None or bench_ann is None:
        return None
    return fund_ann - bench_ann


def mm_after_tax(amount, days, gross_ann, fee_pct=0.0, year=None, allow_ldv=True):
    """Результат вложения amount ₽ на days календарных дней при годовой доходности gross_ann (эффективная, %).
    Комиссия брокера fee_pct % берётся с оборота покупки и продажи; налог по tx_ndfl (13 %, 15 % с превышения порога) с дохода
    после вычета комиссий; ЛДВ (только при allow_ldv=True — для паёв/ценных бумаг) — если срок больше трёх лет:
    освобождается доход до 3 млн ₽ за каждый полный год владения (приближённо)."""
    if not amount or amount <= 0 or not days or days <= 0 or gross_ann is None or gross_ann <= -100:
        return None
    year = year or date.today().year
    f = max(0.0, fee_pct or 0.0) / 100.0
    invested = amount / (1 + f)
    proceeds = invested * (1 + gross_ann / 100.0) ** (days / 365.0)
    sell_fee = proceeds * f
    base = proceeds - sell_fee - amount
    full_years = days // 365
    ldv = bool(allow_ldv and days > 3 * 365)
    exempt = 3e6 * full_years if ldv else 0.0
    taxable = max(0.0, base - exempt)
    tax = tx_ndfl(taxable, year)[0]
    net = proceeds - sell_fee - tax
    net_total = net / amount - 1
    ann = ((net / amount) ** (365.0 / days) - 1) * 100 if net > 0 else None
    return {"amount": amount, "days": days, "gross_gain": proceeds - invested, "fees": (amount - invested) + sell_fee, "tax": tax,
            "net_gain": net - amount, "net_total_pct": net_total * 100, "net_ann": ann, "ldv": ldv, "ldv_exempt": min(exempt, max(0.0, base))}


def mm_contract_rub(price, step_price, min_step):
    """Стоимость контракта в рублях по котировке: цена × (стоимость шага / шаг цены). Для акций это сама цена (шаг 1 ₽ = 1 ₽),
    для юаня (шаг 0,001 = 1 ₽) — цена × 1000, для золота и Si — через курс, заложенный биржей в стоимость шага."""
    p, sp, ms = mm_f(price), mm_f(step_price), mm_f(min_step)
    if p is None or not sp or not ms:
        return None
    return p * sp / ms


def mm_basis(fut_rub, lot, spot_unit, days, divs=0.0, margin=None):
    """Cash & carry: купить lot единиц базового актива по spot_unit ₽ за единицу и продать фьючерс (fut_rub ₽ за контракт).
    divs — ожидаемые дивиденды на единицу до экспирации. Базис = F − S·lot; доходность годовых по простой формуле (F/S − 1)·365/дни.
    Доходность на капитал с ГО: прибыль / (стоимость актива + ГО)."""
    if not fut_rub or not lot or not spot_unit or not days or days <= 0 or spot_unit <= 0:
        return None
    f_unit = fut_rub / lot
    spot_val = spot_unit * lot
    basis = fut_rub - spot_val
    basis_pct = (f_unit / spot_unit - 1) * 100
    k = 365.0 / days
    raw_ann = basis_pct * k
    div_total = (divs or 0.0) * lot
    pnl = basis + div_total
    adj_ann = pnl / spot_val * 100 * k
    cap = spot_val + (margin or 0.0)
    roc_ann = pnl / cap * 100 * k if margin else None
    return {"f_unit": f_unit, "spot_unit": spot_unit, "basis": basis, "basis_pct": basis_pct, "ann_raw": raw_ann, "div_unit": divs or 0.0,
            "div_total": div_total, "ann_adj": adj_ann, "pnl": pnl, "capital": cap, "ann_roc": roc_ann, "days": days}


# ── фонды: поиск, история, ставки ──

def mm_fund_names():
    """{тикер: название} кандидатов по названию в списке бумаг ISS (фонды денежного рынка, рублёвые), кэш на сутки; при сбое — известные тикеры."""
    key = "mm_fund_names_v1"
    hit = store().get(key, 24 * 3600)
    if hit:
        return hit
    out = {}
    try:
        j = json.loads(http_text(MM_ISS + "engines/stock/markets/shares/securities.json?iss.meta=off&iss.only=securities&securities.columns=SECID,SECNAME,SHORTNAME", timeout=40))
        for r in _iss_table(j, "securities"):
            sid, nm = r.get("SECID") or "", r.get("SECNAME") or ""
            if sid and len(sid) <= 5 and not sid.startswith("RU0") and MM_FUND_IN.search(nm) and not MM_FUND_OUT.search(nm):
                out[sid] = nm
            elif sid in MM_FUND_SEED:
                out[sid] = nm or sid
    except Exception:  # noqa: BLE001
        return {s: s for s in MM_FUND_SEED[:4]}
    for s in MM_FUND_SEED[:4]:
        out.setdefault(s, s)
    if out:
        store().put(key, out)
    return out


def mm_rate_series():
    """(rusfar, key): RUSFAR [(дата, %)] и ключевая ставка [(дата, %)]; недоступное — []."""
    rf, kr = [], []
    try:
        rf = sorted(bench_history("RUSFAR", (date.today() - timedelta(days=430)).isoformat()).items())
    except Exception:  # noqa: BLE001
        pass
    try:
        kr = [(d, v) for d, v in key_rate_series()]
    except Exception:  # noqa: BLE001
        pass
    return rf, kr


def mm_fund_row(secid, name):
    try:
        cs = stock_candles(secid, 24, 400)
    except Exception:  # noqa: BLE001
        return None
    closes = [(c["t"], c["c"]) for c in cs if c.get("c")]
    if len(closes) < 10:
        return None
    return {"secid": secid, "name": name, "closes": closes}


def mm_funds_base():
    """Тяжёлая часть (сеть): список фондов с доходностями по окнам и отставанием от ставки. Кэш в памяти 10 минут."""
    key = ("mm_funds_base",)
    hit = mem_get(key, 600)
    if hit is not None:
        return hit
    with key_lock("mm_funds_base"):
        hit = mem_get(key, 600)
        if hit is not None:
            return hit
        names = mm_fund_names()
        rows = [r for r in pool_map(lambda kv: mm_fund_row(kv[0], kv[1]), sorted(names.items()), workers=6) if r]
        rf, kr = mm_rate_series()
        out = []
        for r in rows:
            last = mm_d(r["closes"][-1][0])
            if not last or (date.today() - last).days > 10:
                continue
            wins = {}
            for wk, n in MM_WINDOWS:
                w = mm_window_return(r["closes"], n)
                if w and w["ret"] is not None:
                    d0, d1 = mm_d(w["start"]), mm_d(w["end"])
                    b_rf, b_kr = mm_bench_ann(rf, d0, d1), mm_bench_ann(kr, d0, d1)
                    b, bn = (b_rf, "RUSFAR") if b_rf is not None else (b_kr, "ключевая ставка")
                    w.update(bench=b, bench_name=bn if b is not None else None, gap=mm_gap(w["ret"], b),
                             key=b_kr, rusfar=b_rf)
                wins[wk] = w
            if not any(wins.values()):
                continue
            out.append({"secid": r["secid"], "name": r["name"], "last": r["closes"][-1][1], "last_date": r["closes"][-1][0], "wins": wins})
        out.sort(key=lambda x: -((x["wins"].get("3m") or {}).get("ret") or -999))
        return mem_put(key, {"funds": out, "rusfar": rf[-1][1] if rf else None, "rusfar_date": rf[-1][0] if rf else None,
                             "key": kr[-1][1] if kr else None, "key_date": kr[-1][0] if kr else None})


def mm_funds_payload(q):
    def num(k, d, lo, hi):
        v = mm_f(str(q.get(k, "")).replace(",", "."))
        return d if v is None else max(lo, min(hi, v))
    amount = num("amount", 1000000.0, 1000.0, 1e10)
    days = int(num("days", 365, 1, 3650))
    fee = num("fee", 0.0, 0.0, 5.0)
    win = q.get("win") if q.get("win") in ("1m", "3m", "6m", "1y") else "3m"
    base = mm_funds_base()
    funds = base["funds"]
    if not funds:
        return {"error": "Не удалось загрузить историю цен фондов с Мосбиржи. Повторите позже.", "funds": []}
    fund = (q.get("fund") or "").strip().upper()
    sel = next((f for f in funds if f["secid"] == fund), None) or next((f for f in funds if f["secid"] == "LQDT"), funds[0])
    key_now = base["key"]
    save = num("save", (key_now - 2.0) if key_now is not None else 10.0, 0.0, 100.0)
    year = date.today().year
    fw = (sel["wins"].get(win) or next((w for w in sel["wins"].values() if w), None))
    cmp_rows = []

    def add(kind, title, gross, note=""):
        at = (mm_after_tax(amount, days, gross, fee if kind in ("fund", "ofz") else 0.0, year, allow_ldv=(kind == "fund"))
              if gross is not None else None)
        cmp_rows.append({"kind": kind, "title": title, "gross": gross, "after": at, "note": note})

    if fw:
        add("fund", "Фонд %s (доходность за %s)" % (sel["secid"], {"1m": "месяц", "3m": "3 месяца", "6m": "6 месяцев", "1y": "год"}[win]), fw["ret"],
            "реализованная доходность, прошлое не гарантирует будущее")
    add("save", "Накопительный счёт (ставка введена вами)", save, "ставка принята эффективной годовой; необлагаемый лимит процентов не учтён")
    for y in (0.25, 0.5, 1.0):
        v = None
        for _ in range(2):
            try:
                v = kbd_at(y)
            except Exception:  # noqa: BLE001
                v = None
            if v is not None:
                break
        add("ofz", "ОФЗ со сроком до %s г. (кривая бескупонной доходности)" % ("%g" % y).replace(".", ","), v,
            "ориентир по КБД: реальные выпуски торгуются с отклонением; купонный доход и цена облагаются так же")
    if base["rusfar"] is not None:
        add("rate", "Ставка RUSFAR (ориентир)", base["rusfar"], "не инструмент: показывает уровень денежного рынка")
    if key_now is not None:
        add("rate", "Ключевая ставка (ориентир)", key_now, "не инструмент")
    # ставки-ориентиры без комиссии
    return {"funds": [{"secid": f["secid"], "name": f["name"], "last": f["last"], "last_date": f["last_date"], "wins": f["wins"]} for f in funds],
            "selected": sel["secid"], "win": win, "amount": amount, "days": days, "fee": fee, "save": save,
            "rusfar": base["rusfar"], "rusfar_date": base["rusfar_date"], "key": key_now, "key_date": base["key_date"],
            "compare": cmp_rows, "note": MM_NOTE_FUNDS, "ldv_note": "Льгота долгосрочного владения (ЛДВ) применяется при владении более трёх лет, до 3 млн ₽ дохода за каждый полный год; "
                                                                      "выше порога годового дохода (в 2025 и позже — 2,4 млн ₽) налог 15 % вместо 13 %."}


# ── базис фьючерсов ──

def mm_pick_price(md):
    """Цена контракта из marketdata: LAST при наличии сделок сегодня, иначе расчётная цена, иначе None. Возвращает (цена, источник)."""
    last, settle, vol = mm_f(md.get("LAST")), mm_f(md.get("SETTLEPRICE")), mm_f(md.get("VOLTODAY")) or 0
    if last and vol > 0:
        return last, "последняя сделка"
    if settle:
        return settle, "расчётная цена"
    return None, None


def mm_nearest(secs, md, assets, today):
    """Два ближайших ещё не истёкших срочных контракта по коду актива -> [{secid, expiry, ...}]."""
    rows = []
    for s in secs:
        if s.get("ASSETCODE") not in assets:
            continue
        exp = mm_d(s.get("LASTTRADEDATE"))
        if not exp or exp.year > 2090 or exp <= today:
            continue
        m = md.get(s.get("SECID")) or {}
        price, src = mm_pick_price(m)
        if price is None:
            price, src = mm_f(s.get("PREVSETTLEPRICE")), "прошлая расчётная цена"
        rows.append({"secid": s["SECID"], "short": s.get("SHORTNAME") or s["SECID"], "expiry": exp, "price": price, "src": src,
                     "lot": mm_f(s.get("LOTVOLUME")), "margin": mm_f(s.get("INITIALMARGIN")), "step_price": mm_f(s.get("STEPPRICE")),
                     "min_step": mm_f(s.get("MINSTEP")), "oi": mm_f(m.get("OPENPOSITION"))})
    rows.sort(key=lambda r: r["expiry"])
    return rows[:2]


def mm_spots():
    """Спот: {тикер: цена ₽} — акции TQBR, валютная секция (CETS: USD000UTSTOM, CNYRUB_TOM, GLDRUB_TOM) + фолбэк USD на курс ЦБ."""
    out = {}
    try:
        for r in stocks_universe():
            if r["secid"] in ("SBER", "GAZP", "LKOH"):
                out[r["secid"]] = r["price"]
    except Exception:  # noqa: BLE001
        pass
    try:
        j = json.loads(http_text(MM_ISS + "engines/currency/markets/selt/boards/CETS/securities.json?iss.meta=off&iss.only=marketdata"
                                 "&marketdata.columns=SECID,LAST,WAPRICE,MARKETPRICE,NUMTRADES", timeout=30))
        for r in _iss_table(j, "marketdata"):
            sid = r.get("SECID")
            if sid in ("USD000UTSTOM", "CNYRUB_TOM", "GLDRUB_TOM"):
                nt = mm_f(r.get("NUMTRADES")) or 0
                if sid == "USD000UTSTOM" and nt <= 0:
                    continue
                v = mm_f(r.get("LAST")) or mm_f(r.get("MARKETPRICE")) or mm_f(r.get("WAPRICE"))
                if v:
                    out[sid] = v
    except Exception:  # noqa: BLE001
        pass
    if "USD000UTSTOM" not in out:
        try:
            cbr_usd = tax_cbr_rate("USD", date.today().isoformat())
            if cbr_usd:
                out["USD000UTSTOM"] = cbr_usd
        except Exception:  # noqa: BLE001
            pass
    return out


def mm_divs_until(secid, price, today, expiry, cfg=None):
    """Объявленные дивиденды с датой фиксации в (сегодня, экспирация], ₽ на акцию: (сумма, [{record, value}], есть_ли_данные_о_дивидендах)."""
    try:
        uid = (stk_api_map(cfg) or {}).get(secid, {}).get("uid") if cfg and (cfg.get("token") or "").strip() else None
        res = stock_dividends(secid, price, uid, cfg)
    except Exception:  # noqa: BLE001
        return 0.0, [], False
    its = res.get("items") or []
    items = [{"record": x["record"], "value": x["value"]} for x in its
             if x.get("cur") in ("RUB", "RUR") and today.isoformat() < x["record"] <= expiry.isoformat()]
    return sum(i["value"] for i in items), sorted(items, key=lambda i: i["record"]), bool(its)


def mm_basis_build(secs, md, spots, rate_ref, today, divs_fn=None):
    """Строки базиса по набору базовых активов. Контракты с несошедшимися единицами (|базис| > MM_BASIS_SANITY %) пропускаются."""
    rows, skipped = [], []
    divs_fn = divs_fn or mm_divs_until
    for u in MM_UNDERLYINGS:
        futs = mm_nearest(secs, md, u["asset"], today)
        spot = spots.get(u["spot"])
        if not futs or not spot:
            skipped.append("%s: нет данных (%s)" % (u["name"], "котировки спота" if not spot else "контрактов"))
            continue
        spot_unit = spot * MM_OZ_G if u["kind"] == "gold" else spot
        for f in futs:
            fr = mm_contract_rub(f["price"], f["step_price"], f["min_step"])
            days = (f["expiry"] - today).days
            if fr is None or not f["lot"] or days < 1:
                continue
            dsum, ditems, dknown = divs_fn(u["spot"], spot, today, f["expiry"]) if u["kind"] == "share" else (0.0, [], True)
            b = mm_basis(fr, f["lot"], spot_unit, days, dsum, f["margin"])
            if not b:
                continue
            if abs(b["basis_pct"]) > MM_BASIS_SANITY:
                skipped.append("%s %s: базис %.1f %% — единицы контракта не удалось согласовать, строка скрыта" % (u["name"], f["short"], b["basis_pct"]))
                continue
            b.update(asset=u["name"], kind=u["kind"], secid=f["secid"], short=f["short"], expiry=f["expiry"].isoformat(), price=f["price"], price_src=f["src"],
                     lot=f["lot"], margin=f["margin"], contract_rub=fr, divs=ditems, divs_known=dknown,
                     unit={"share": "акция", "gold": "унция", "fx": "ед. валюты"}[u["kind"]],
                     excess=(b["ann_adj"] - rate_ref) if rate_ref is not None else None)
            rows.append(b)
    return rows, skipped


def mm_basis_payload(force=False, cfg=None):
    key = ("mm_basis",)
    if not force:
        hit = mem_get(key, MM_BASIS_TTL)
        if hit is not None:
            return hit
    with key_lock("mm_basis"):
        if not force:
            hit = mem_get(key, MM_BASIS_TTL)
            if hit is not None:
                return hit
        try:
            j = json.loads(http_text(MM_ISS + "engines/futures/markets/forts/securities.json?iss.meta=off&iss.only=securities,marketdata"
                                     "&securities.columns=SECID,SHORTNAME,ASSETCODE,LASTTRADEDATE,PREVSETTLEPRICE,LOTVOLUME,INITIALMARGIN,MINSTEP,STEPPRICE"
                                     "&marketdata.columns=SECID,LAST,SETTLEPRICE,VOLTODAY,OPENPOSITION", timeout=45))
            secs = _iss_table(j, "securities")
            md = {r["SECID"]: r for r in _iss_table(j, "marketdata")}
        except Exception as e:  # noqa: BLE001
            return {"error": "Не удалось загрузить срочный рынок Мосбиржи: %s" % e, "rows": [], "note": MM_NOTE_BASIS}
        spots = mm_spots()
        rf, kr = mm_rate_series()
        today = date.today()
        rusfar = rf[-1][1] if rf else None
        keyr = kr[-1][1] if kr else None
        ref = rusfar if rusfar is not None else keyr
        rows, skipped = mm_basis_build(secs, md, spots, ref, today, lambda sid, p, t, e: mm_divs_until(sid, p, t, e, cfg))
        out = {"rows": rows, "skipped": skipped, "rusfar": rusfar, "key": keyr, "ref": ref, "ref_name": "RUSFAR" if rusfar is not None else "ключевая ставка",
               "asof": datetime.now().strftime("%Y-%m-%d %H:%M"), "note": MM_NOTE_BASIS}
        if not rows:
            out["error"] = "Нет данных для расчёта базиса (биржа не отдала котировки)."
            return out
        return mem_put(key, out)


def mm_api_funds(cfg, acc, q, force):
    try:
        return mm_funds_payload(q)
    except Exception as e:  # noqa: BLE001
        return {"error": "Не удалось рассчитать фонды ликвидности: %s" % e, "funds": []}


def mm_api_basis(cfg, acc, q, force):
    try:
        return mm_basis_payload(bool(force), cfg)
    except Exception as e:  # noqa: BLE001
        return {"error": "Не удалось рассчитать базис: %s" % e, "rows": [], "note": MM_NOTE_BASIS}


API_GET["/api/mm/funds"] = mm_api_funds
API_GET["/api/mm/basis"] = mm_api_basis
# ═══════════════════ устойчивость эмитентов: банкротные модели, расширенный долг, риск размытия ═══════════════════
# Всё считается по РСБУ из ГИР БО (суммы в тыс. ₽). Это приближённая модель, а не заключение о платёжеспособности.

CRP_CODES_BS = ("1100", "1200", "1300", "1400", "1410", "1450", "1500", "1510", "1540", "1550", "1600")
CRP_CODES_FR = ("2110", "2200", "2400")
CRP_TTL = 7 * 86400
_crp_jobs = {}
_crp_jobs_lock = threading.Lock()

CRP_DILUTION = [
    ("spo", "Допэмиссия / SPO", re.compile(r"допол\w*\s+(?:выпуск\w*|эмисси\w*)\s*(?:обыкн\w*\s+|привилег\w*\s+)?(?:акци|ценных)|допол\w+\s+эмисси|\bSPO\b|вторичн\w+\s+(?:публичн\w+\s+)?размещени\w+\s+акци|размещени\w+\s+(?:допол\w+\s+)?акци|увеличени\w+\s+уставн\w+\s+капитал", re.I)),
    ("convert", "Конвертируемые бумаги", re.compile(r"конвертируем\w+\s+(?:облигац|ценн|бумаг)|конвертаци\w+\s+(?:облигац|в\s+акци)|облигац\w+,?\s+конвертируем", re.I)),
    ("option", "Опционная программа", re.compile(r"опцион\w*\s+(?:программ|план)|программ\w+\s+опцион|мотивационн\w+\s+программ|\bESOP\b|\bMSOP\b|\bLTI\b", re.I)),
    ("buyback", "Выкуп / размещение акций", re.compile(r"выкуп\w*\s+(?:собственн\w+\s+)?акци|buy-?back|обратн\w+\s+выкуп|приобретени\w+\s+(?:эмитентом\s+)?собственн\w+\s+акци", re.I)),
    ("lockup", "Ограничение продажи (lock-up)", re.compile(r"lock-?up|лок-?ап|локап|ограничени\w+\s+на\s+продаж\w+\s+акци", re.I)),
]


def crp_dilution_match(text):
    """Список ключей категорий риска размытия, найденных в заголовке/тексте раскрытия."""
    t = text or ""
    return [k for k, _n, rx in CRP_DILUTION if rx.search(t)]


def crp_dilution_scan(items):
    """items: [{title, date, url}] -> совпадения [{kind, label, title, date, url}], свежие сверху."""
    names = {k: n for k, n, _rx in CRP_DILUTION}
    out = []
    for it in items or []:
        for k in crp_dilution_match(it.get("title") or ""):
            out.append({"kind": k, "label": names[k], "title": it.get("title"), "date": it.get("date"), "url": it.get("url")})
    out.sort(key=lambda x: x.get("date") or "", reverse=True)
    return out


def _crp_div(a, b):
    return a / b if a is not None and b not in (None, 0) else None


def _crp_sub(a, b):
    return None if a is None or b is None else a - b


def crp_savitskaya(c, prev=None):
    """Модель Савицкой. c, prev — {код РСБУ: значение}. Возвращает {ok, z, x:{X1..X5}, zone, key}."""
    ca, nca, eq, assets = c.get("1200"), c.get("1100"), c.get("1300"), c.get("1600")
    pa = (prev or {}).get("1600")
    avg = (assets + pa) / 2.0 if assets is not None and pa is not None else assets
    x = {"X1": _crp_div(_crp_sub(eq, nca), ca), "X2": _crp_div(ca, nca), "X3": _crp_div(c.get("2110"), avg),
         "X4": _crp_div(c.get("2400"), assets), "X5": _crp_div(eq, assets)}
    if any(v is None for v in x.values()):
        return {"ok": False, "x": x, "reason": "не хватает строк отчётности"}
    z = 0.111 * x["X1"] + 13.239 * x["X2"] + 1.676 * x["X3"] + 0.515 * x["X4"] + 3.80 * x["X5"]
    hi = z < 8
    return {"ok": True, "z": z, "x": x, "key": "high" if hi else "ok", "zone": "высокий риск (Z < 8)" if hi else "ниже высокого риска (Z ≥ 8)",
            "avg_prev": pa is not None}


def crp_saifullin(c, prev=None):
    """Модель Сайфуллина–Кадыкова: R = 2K1 + 0,1K2 + 0,08K3 + 0,45K4 + K5."""
    ca, nca, eq, assets = c.get("1200"), c.get("1100"), c.get("1300"), c.get("1600")
    pa = (prev or {}).get("1600")
    avg = (assets + pa) / 2.0 if assets is not None and pa is not None else assets
    rev = c.get("2110")
    np_val = c.get("2400")
    k5 = _crp_div(np_val, eq)
    if eq is not None and eq < 0 and k5 is not None and k5 > 0:
        k5 = -k5                       # убыток при отрицательном капитале не может давать положительную рентабельность
    k = {"K1": _crp_div(_crp_sub(eq, nca), ca), "K2": _crp_div(ca, c.get("1500")), "K3": _crp_div(rev, avg),
         "K4": _crp_div(c.get("2200"), rev), "K5": k5}
    if any(v is None for v in k.values()):
        return {"ok": False, "x": k, "reason": "не хватает строк отчётности"}
    r = 2 * k["K1"] + 0.1 * k["K2"] + 0.08 * k["K3"] + 0.45 * k["K4"] + k["K5"]
    neg_eq = eq is not None and eq <= 0
    bad = neg_eq or r < 1
    zone = ("неудовлетворительное состояние (отрицательный капитал)" if neg_eq
            else "неудовлетворительное состояние (R < 1)" if bad else "удовлетворительное состояние (R ≥ 1)")
    return {"ok": True, "r": r, "x": k, "key": "high" if bad else "ok", "zone": zone, "avg_prev": pa is not None}


CRP_EXT_FLAG = 0.25


def crp_ext_debt(c):
    """Расширенная долговая нагрузка по балансу (тыс. ₽). Возвращает компоненты, итоги и коэффициенты."""
    g = c.get
    if g("1410") is None and g("1510") is None and all(g(k) is None for k in ("1450", "1550", "1540")):
        return {"ok": False}
    rep = (g("1410") or 0) + (g("1510") or 0)
    extra = sum(g(k) or 0 for k in ("1450", "1550", "1540"))
    ext = rep + extra
    ebit, eq = g("2200"), g("1300")
    flag = extra > 0 and ext >= rep * (1 + CRP_EXT_FLAG)
    names = [("1410", "Долгосрочные заимствования"), ("1510", "Краткосрочные заимствования"), ("1450", "Прочие долгосрочные обязательства"),
             ("1550", "Прочие краткосрочные обязательства"), ("1540", "Оценочные обязательства")]
    return {"ok": True, "reported": rep, "extra": extra, "extended": ext,
            "uplift": (ext / rep - 1) if rep > 0 else None, "flag": bool(flag),
            "components": [{"code": k, "name": n, "value": g(k)} for k, n in names],
            "ext_ebit": ext / ebit if ebit and ebit > 0 else None, "rep_ebit": rep / ebit if ebit and ebit > 0 else None,
            "ext_eq": ext / eq if eq and eq > 0 else None, "rep_eq": rep / eq if eq and eq > 0 else None,
            "ebit": ebit, "equity": eq}


def crp_is_fin(name, sector=None):
    return bool(ISS_FIN_RE.search(name or "") or re.search(r"банк|страхов|\bНКО\b", name or "", re.I) or sector == "financial")


def crp_analyze_years(years, is_fin):
    """years: {год: {код: значение}} -> строки по годам (последние 5)."""
    rows = []
    for y in sorted(years)[-5:]:
        c, prev = years[y], years.get(y - 1)
        row = {"y": y, "debt": crp_ext_debt(c), "fin": bool(is_fin)}
        if is_fin:
            na = {"ok": False, "na": True, "reason": "неприменимо к банкам, лизингу, МФО и другим финансовым компаниям"}
            row["sav"], row["sk"] = dict(na), dict(na)
        else:
            row["sav"], row["sk"] = crp_savitskaya(c, prev), crp_saifullin(c, prev)
        rows.append(row)
    return rows


def _crp_parse(lst):
    """Список отчётов ФНС -> {год: {код: тыс. ₽}} с расширенным набором строк (логика как в _iss_parse_bfo)."""
    years, prio = {}, {}
    for y in lst or []:
        try:
            per = int(y.get("period"))
        except (TypeError, ValueError, AttributeError):
            continue
        cor = None
        for tc in y.get("typeCorrections") or []:
            c = (tc or {}).get("correction")
            if isinstance(c, dict) and (c.get("balance") or c.get("financialResult")):
                cor = c
                if c.get("periodType") in (12, None):
                    break
        if not cor:
            continue
        for off in (0, 1, 2):
            for kind, codes in (("financialResult", CRP_CODES_FR), ("balance", CRP_CODES_BS)):
                if kind == "financialResult" and off == 2:
                    continue
                for code in codes:
                    v = _iss_pick(cor, kind, code, off)
                    if v is None:
                        continue
                    k = (per - off, code)
                    if k not in prio or off < prio[k]:
                        prio[k] = off
                        years.setdefault(per - off, {})[code] = v
    return years


def crp_raw(inn, name=""):
    """Сырые строки РСБУ по годам из ГИР БО (кэш 7 суток). {status, years:{y:{код:знач}}, note}."""
    key = "crp_raw_v1_" + inn
    hit = store().get(key, ttl=CRP_TTL)
    if hit:
        return {"status": hit["status"], "years": {int(k): v for k, v in hit["years"].items()}, "note": hit.get("note")}
    fin = issuer_fin(inn, name)
    if fin.get("status") != "ok" or not fin.get("org_id"):
        return {"status": fin.get("status") or "nf", "years": {}, "note": fin.get("note") or "Отчётность не найдена."}
    lst = _iss_fns_get("/nbo/organizations/%s/bfo/" % fin["org_id"])
    ys = _crp_parse(lst if isinstance(lst, list) else [])
    res = {"status": "ok" if ys else "nobfo", "years": ys, "note": None if ys else "Отчётность в ГИР БО пустая или в нестандартной форме."}
    store().put(key, {"status": res["status"], "years": {str(k): v for k, v in ys.items()}, "note": res["note"]})
    return res


def crp_events(isin, inn):
    """Факты раскрытия эмитента (при наличии ИНН — по ИНН, плюс по ISIN для полноты) -> ([{title, date, url}], источники). Без дублей."""
    lst = []
    try:
        if inn:
            lst.extend(disc_facts(None, inn) or [])
        if isin:
            lst.extend(disc_facts(isin, None) or [])
    except Exception:  # noqa: BLE001
        if not lst:
            return [], []
    out, seen = [], set()
    for it in lst:
        if not isinstance(it, dict):
            continue
        k = it.get("doc_id") or (it.get("title"), it.get("published"))
        if k in seen:
            continue
        seen.add(k)
        out.append({"title": it.get("title") or "", "date": it.get("published") or it.get("event_date"), "url": it.get("url")})
    return out, ["раскрытие информации (disc_facts)"]


def crp_resolve(q):
    """ISIN / тикер / ИНН -> {inn, name, isin} или {error}."""
    s = (q or "").strip().upper()
    if not s:
        return {"error": "Введите ISIN, тикер или ИНН эмитента."}
    if s.isdigit() and len(s) in (10, 12):
        return {"inn": s, "name": "", "isin": None}
    em = issuer_of(s)
    if not em or not em.get("inn"):
        return {"error": "Не удалось определить эмитента (нужен ИНН: иностранные эмитенты и государство не поддерживаются)."}
    return {"inn": em["inn"], "name": em.get("short") or em.get("title") or "", "isin": s if re.fullmatch(r"[A-Z]{2}[A-Z0-9]{9}\d", s) else None,
            "full": em.get("title")}


def crp_card(q):
    r = crp_resolve(q)
    if r.get("error"):
        return {"ok": False, "error": r["error"]}
    inn, name, isin = r["inn"], r.get("full") or r.get("name") or "", r.get("isin")
    sector = (tcat_info(isin or (q or "").strip().upper()) or {}).get("sector")
    is_fin = crp_is_fin(name, sector)
    raw = crp_raw(inn, name)
    out = {"ok": True, "inn": inn, "name": r.get("name") or name, "is_fin": is_fin, "status": raw["status"], "note": raw.get("note"), "years": []}
    if raw["years"]:
        out["years"] = crp_analyze_years(raw["years"], is_fin)
    items, srcs = crp_events(isin, inn)
    out["dilution"] = {"matches": crp_dilution_scan(items), "n_scanned": len(items), "sources": srcs,
                       "links": bond_doc_links(isin or "", None, inn)}
    return out


def crp_api(cfg, acc, q, force):
    s = (q.get("q") or "").strip()
    key = "crp_card_v1_" + s.upper()
    if not force:
        hit = store().get(key, ttl=6 * 3600)
        if hit:
            return hit
    try:
        c = crp_card(s)
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "error": "Ошибка расчёта: %s" % str(e)[:120]}
    if c.get("ok") and c["years"]:
        store().put(key, c)
    return c


def crp_summary_row(c):
    """Краткая строка пакетного режима из карточки."""
    ys = c.get("years") or []
    last = ys[-1] if ys else None
    return {"inn": c.get("inn"), "name": c.get("name"), "is_fin": c.get("is_fin"), "year": last and last["y"],
            "sav": last and last["sav"].get("z"), "sav_key": last and last["sav"].get("key"),
            "sk": last and last["sk"].get("r"), "sk_key": last and last["sk"].get("key"),
            "uplift": last and last["debt"].get("uplift"), "flag": bool(last and last["debt"].get("flag")),
            "ext_ebit": last and last["debt"].get("ext_ebit"), "n_dil": len((c.get("dilution") or {}).get("matches") or []),
            "note": c.get("note") or c.get("error")}


def _crp_my_issuers(cfg, acc):
    """Эмитенты облигаций и акций портфеля: [(идентификатор для разбора, название)]."""
    out, seen = [], set()
    try:
        for r in build_bonds(cfg, acc).get("rows", []):
            if r.get("isin") and r.get("sector") != "government" and r["isin"] not in seen:
                seen.add(r["isin"])
                out.append((r["isin"], r.get("name") or r["isin"]))
    except Exception:  # noqa: BLE001
        pass
    try:
        for r in build_summary(cfg, acc, "all")["portfolio"]["positions"]:
            if r.get("type") == "share" and (r.get("qty") or 0) > 0:
                k = r.get("isin") or r.get("ticker")
                if k and k not in seen:
                    seen.add(k)
                    out.append((k, r.get("name") or k))
    except Exception:  # noqa: BLE001
        pass
    return out


def crp_batch(cfg, acc, q, force):
    key = (token_key(cfg), acc)
    with _crp_jobs_lock:
        job = _crp_jobs.get(key)
        if job and job["state"] == "run":
            return {"pending": True, "done": job["done"], "total": job["total"]}
        if job and job["state"] == "done" and not force and time.time() - job["t"] < 1800:
            return job["res"]
        job = {"state": "run", "done": 0, "total": 0, "t": time.time(), "res": None}
        _crp_jobs[key] = job

    def work():
        try:
            lst = _crp_my_issuers(cfg, acc)
            job["total"] = len(lst)
            rows, seen = [], set()
            for ident, nm in lst:           # последовательно: ГИР БО и так ограничен по частоте
                try:
                    c = crp_card(ident)
                    if c.get("ok"):
                        if c["inn"] in seen:
                            job["done"] += 1
                            continue
                        seen.add(c["inn"])
                        row = crp_summary_row(c)
                        row["name"] = row["name"] or nm
                    else:
                        row = {"name": nm, "note": c.get("error")}
                    row["q"] = ident
                    rows.append(row)
                except Exception as e:  # noqa: BLE001
                    rows.append({"name": nm, "q": ident, "note": "Ошибка: %s" % str(e)[:80]})
                job["done"] += 1
            job["res"] = {"rows": rows, "n": len(rows), "updated": datetime.now().strftime("%H:%M")}
        except Exception as e:  # noqa: BLE001
            job["res"] = {"error": str(e)[:200] or "Не удалось собрать эмитентов"}
        job["state"] = "done"
        job["t"] = time.time()
    threading.Thread(target=work, daemon=True).start()
    return {"pending": True, "done": 0, "total": 0}


API_GET["/api/crp"] = crp_api
API_GET["/api/crp/batch"] = crp_batch
# ═══════════════════════════════ налоговая оптимизация: сбор убытков по лотам FIFO и планировщик ИИС-3 ═══════════════════════════════
# Справочный расчёт по модели; налог удерживает брокер, итог за год определяется декларацией. Не индивидуальная рекомендация.

# ИИС-3 (НК РФ ст. 219.1 — вычет на взносы; ст. 219.2 — освобождение положительного финансового результата).
TXO_IIS_LIMIT = 400000.0          # взносы, с которых предоставляется вычет, за год
TXO_IIS_EXEMPT_CAP = 30000000.0   # предел освобождаемого финансового результата за всё время
TXO_IIS_RATE_LO, TXO_IIS_RATE_HI = 0.13, 0.15
TXO_HI_THRESHOLD = 2400000.0      # доход в год, выше которого применяется ставка 15 %
TXO_IIS_TERMS = ((2024, 2026, 5), (2027, 2027, 6), (2028, 2028, 7), (2029, 2029, 8), (2030, 2030, 9))   # (с года, по год, срок лет); с 2031 — 10
TXO_MIN_LOSS = 50.0


def txo_iis3_term(open_year):
    """Минимальный срок ИИС-3 (лет) по году открытия: 2024–2026 — 5, 2027 — 6, 2028 — 7, 2029 — 8, 2030 — 9, с 2031 — 10."""
    for a, b, t in TXO_IIS_TERMS:
        if a <= open_year <= b:
            return t
    return 10 if open_year > 2030 else 5


def txo_num(q, key, dflt, lo, hi):
    try:
        v = float(str(q.get(key)).replace(",", ".").replace(" ", ""))
    except (TypeError, ValueError):
        return dflt
    return min(hi, max(lo, v))


def txo_tax(base, year, rate15):
    """Налог с положительной базы: при ставке 15 % плательщика — плоско 15 %, иначе прогрессия tx_ndfl."""
    base = max(0.0, base)
    return base * TXO_IIS_RATE_HI if rate15 else tx_ndfl(base, year)[0]


# ── сбор убытков ──

def txo_best_prefix(lots, price, fee_rate):
    """Лоты продаются от старых к новым (FIFO), поэтому доступны только префиксы. Результат кусочно-линеен по количеству,
    значит минимум достигается на границе лота. Возвращает (количество, результат) префикса с наибольшим убытком."""
    best_q, best_r, cq, cr = 0.0, 0.0, 0.0, 0.0
    for l in sorted(lots, key=lambda l: l["date"] or date(1970, 1, 1)):
        cq += l["qty"]
        cr += l["qty"] * (price * (1.0 - fee_rate) - l["unit"])
        if cr < best_r - 1e-9:
            best_q, best_r = cq, cr
    return best_q, best_r


def txo_ldv_flags(rows, lots, today, rate):
    out = []
    blind = {l["date"] for l in lots if l.get("blind")}
    for r in rows:
        if r["result"] <= 0 or r["type"] not in TAX_LDV_TYPES or r["bdate"] is None or r["bdate"] in blind or r["bdate"] < TAX_LDV_FROM:
            continue
        if r["ldv"]:
            out.append({"status": "reached", "bdate": r["bdate"].isoformat(), "days": 0, "qty": r["qty"], "gain": r["result"], "tax_at_stake": 0.0})
            continue
        days = (tx_add_years(r["bdate"], 3) + timedelta(days=1) - today).days
        if 0 < days <= 365:
            out.append({"status": "close", "bdate": r["bdate"].isoformat(), "days": days, "qty": r["qty"], "gain": r["result"], "tax_at_stake": r["result"] * rate})
    return out


TXO_LDV_WARN_DAYS = 730      # с этого стажа продажа «сбрасывает» накопленный срок для ЛДВ
TXO_LDV_CRIT_LEFT = 182      # до ЛДВ осталось не больше стольких дней — предупреждение усиливается
TXO_FIFO_NOTE = "Продажа идёт по FIFO с самых старых лотов, поэтому продать только «молодые» лоты нельзя."


def txo_hold_text(bdate, today):
    m = (today.year - bdate.year) * 12 + today.month - bdate.month - (1 if today.day < bdate.day else 0)
    y, m = divmod(max(0, m), 12)
    return "%d г. %d мес." % (y, m)


def txo_ldv_class(rows, lots, today, rate):
    """Оценка проданных (по FIFO) лотов префикса относительно ЛДВ. Учитываются только ЛДВ-типы и покупки с TAX_LDV_FROM без «слепых» лотов.
    status: n/a | young | warn | critical | reached; hold_days_max — возраст самого старого проданного лота; ldv_cost — потеря освобождения
    на прибыльных лотах warn/critical (прибыль × ставка)."""
    blind = {l["date"] for l in lots if l.get("blind")}
    res = {"status": "n/a", "hold_days_max": 0, "ldv_days_left": None, "ldv_badge": "", "ldv_cost": 0.0, "ldv_lots": 0}
    seen, worst, oldest_warn = set(), 0, None
    for r in rows:
        bd = r["bdate"]
        if r["type"] not in TAX_LDV_TYPES or bd is None or bd in blind or bd < TAX_LDV_FROM:
            continue
        age = (today - bd).days
        left = (tx_add_years(bd, 3) - today).days
        res["hold_days_max"] = max(res["hold_days_max"], age)
        if left < 0:
            seen.add("reached")
            continue
        if age < TXO_LDV_WARN_DAYS:
            seen.add("young")
            continue
        lvl = 2 if left <= TXO_LDV_CRIT_LEFT else 1
        res["ldv_lots"] += 1
        if res["ldv_days_left"] is None or left < res["ldv_days_left"]:
            res["ldv_days_left"] = left
        if oldest_warn is None or bd < oldest_warn:
            oldest_warn = bd
        worst = max(worst, lvl)
        if r["result"] > 0:
            res["ldv_cost"] += r["result"] * rate
    if worst:
        res["status"] = "critical" if worst == 2 else "warn"
        if worst == 2:
            res["ldv_badge"] = "до ЛДВ осталось %d дн. — продажа почти наверняка невыгодна" % res["ldv_days_left"]
        else:
            res["ldv_badge"] = "стаж %s: продажа сбросит срок владения для ЛДВ" % txo_hold_text(oldest_warn, today)
    elif "young" in seen:
        res["status"] = "young"
    elif "reached" in seen:
        res["status"] = "reached"
    return res


def txo_harvest_calc(st, settings, fee_rate=None, min_loss=TXO_MIN_LOSS, holidays=(), skip_ldv2=False):
    today, cy = st["today"], st["today"].year
    fee_src = "заданная" if fee_rate is not None else "по истории сделок"
    if fee_rate is None:
        fee_rate = st["eng"]["fee_rate"]
    sale_day, last_day = tx_last_sale_day(cy, holidays)
    out = {"available": False, "year": cy, "today": today.isoformat(), "fee_rate": fee_rate, "fee_source": fee_src, "candidates": [], "iis_excluded": [], "ldv_skipped": [], "skip_ldv2": bool(skip_ldv2), "ldv_note": "",
           "ldv_summary": {"young": 0, "warn": 0, "critical": 0, "reached": 0, "na": 0, "ldv_cost": 0.0, "net_ldv": 0.0},
           "deadline": {"sale_day": sale_day.isoformat(), "last_trading_day": last_day.isoformat(), "days": (sale_day - today).days, "passed": today > sale_day},
           "totals": {"saving": 0.0, "fees": 0.0, "net": 0.0, "n": 0}, "warnings": list(st["eng"].get("warnings") or []), "reason": "",
           "iis_prefill": txo_iis_prefill(st)}
    for g in st["groups"]:
        if g["kind"] == "iis":
            out["iis_excluded"].append({"name": g["name"], "reason": "ИИС — отдельная налоговая база: убыток внутри счёта не уменьшает налог по обычным счетам "
                                        "(тип А — налог считается при закрытии счёта, тип Б и ИИС-3 при соблюдённом сроке освобождены), поэтому сбор убытков здесь не моделируется."})
    gen = [g for g in st["groups"] if g["kind"] == "gen"]
    if not gen:
        out["reason"] = "Среди выбранных счетов нет обычных брокерских счетов (только ИИС)."
        return out
    if not st["pos"]:
        out["reason"] = "Нет данных о текущих позициях и ценах (нет токена, пустой портфель или демо-режим без позиций)."
        return out
    g = gen[0]
    out["available"] = True
    t0, row0 = tx_cur_tax(g, [], cy, settings)
    base0 = (row0 or {}).get("base", 0.0)
    thr = TXO_HI_THRESHOLD if cy >= 2025 else 5000000.0
    rate0 = 0.15 if base0 > thr else 0.13
    out.update(tax_before=t0, base_before=base0, rate_now=rate0, threshold=thr)
    cands = []
    for uid, lots in tx_group_open(st, g).items():
        pr = tx_pos_price(st["pos"].get(uid))
        if not pr or lots[0]["type"] in TAX_SKIP_TYPES or lots[0]["type"] == "option":
            continue
        q, res = txo_best_prefix(lots, pr, fee_rate)
        if q <= 0 or res > -min_loss:
            continue
        base = {"acc": lots[0]["acc"], "uid": uid, "name": lots[0]["name"], "ticker": lots[0]["ticker"], "type": lots[0]["type"], "bucket": "sec",
                "kind": "sell", "bdate": None}
        rows = tx_fee_sim(lots, q, pr, fee_rate, today, base)
        res = sum(r["result"] for r in rows)
        total_q = sum(l["qty"] for l in lots)
        value = q * pr
        t1, row1 = tx_cur_tax(g, rows, cy, settings)
        base1 = (row1 or {}).get("base", 0.0)
        fee_sell = sum(r["fee"] for r in rows)
        fee_buy = value * fee_rate
        saving = t0 - t1
        lc = txo_ldv_class(rows, lots, today, rate0)
        if skip_ldv2 and lc["hold_days_max"] >= TXO_LDV_WARN_DAYS:
            out["ldv_skipped"].append({"uid": uid, "name": base["name"], "ticker": base["ticker"], "loss": -res, "hold_days_max": lc["hold_days_max"],
                                       "reason": "Самый старый из продаваемых лотов держится %d дн. (≥ %d). %s" % (lc["hold_days_max"], TXO_LDV_WARN_DAYS, TXO_FIFO_NOTE)})
            continue
        carry = max(0.0, ((row1 or {}).get("loss_new", 0.0)) - ((row0 or {}).get("loss_new", 0.0)))
        cands.append({"uid": uid, "name": base["name"], "ticker": base["ticker"], "type": base["type"], "qty": q, "qty_total": total_q, "partial": q < total_q - 1e-9,
                      "price": pr, "value": value, "loss": -res, "gain_in_prefix": sum(r["result"] for r in rows if r["result"] > 0),
                      "base_before": base0, "base_after": base1, "tax_before": t0, "tax_after": t1, "saving": saving,
                      "marginal_rate": (saving / (base0 - base1)) if base0 - base1 > 1 else None, "carry_forward": carry,
                      "fees": fee_sell + fee_buy, "net": saving - fee_sell - fee_buy, "ldv": txo_ldv_flags(rows, lots, today, rate0),
                      "ldv_status": lc["status"], "hold_days_max": lc["hold_days_max"], "ldv_days_left": lc["ldv_days_left"], "ldv_badge": lc["ldv_badge"],
                      "ldv_cost": lc["ldv_cost"], "net_ldv": saving - fee_sell - fee_buy - lc["ldv_cost"],
                      "blind": any(l.get("blind") for l in lots), "rows": rows})
    cands.sort(key=lambda c: -c["net"])
    extra, tot_fee = [], 0.0
    for c in cands:
        c["selected"], c["saving_marginal"] = False, 0.0
        if c["net"] <= 1:
            continue
        tp, _ = tx_cur_tax(g, extra, cy, settings)
        tn, _ = tx_cur_tax(g, extra + c["rows"], cy, settings)
        c["saving_marginal"] = tp - tn
        if c["saving_marginal"] - c["fees"] > 1:
            c["selected"] = True
            extra = extra + c["rows"]
            tot_fee += c["fees"]
    t_all, _ = tx_cur_tax(g, extra, cy, settings)
    n_sel = sum(1 for c in cands if c["selected"])
    out["totals"] = {"saving": t0 - t_all, "fees": tot_fee, "net": (t0 - t_all) - tot_fee, "n": n_sel, "tax_after": t_all}
    sm = out["ldv_summary"]
    for c in cands:
        c.pop("rows", None)
        if c["selected"]:
            sm[c["ldv_status"] if c["ldv_status"] in sm else "na"] += 1
            sm["ldv_cost"] += c["ldv_cost"]
    sm["net_ldv"] = out["totals"]["net"] - sm["ldv_cost"]
    if skip_ldv2:
        out["ldv_note"] = TXO_FIFO_NOTE
    out["candidates"] = cands[:30]
    out["assumptions"] = [
        "Продажа списывает лоты по FIFO (старые первыми), поэтому для каждой бумаги берётся такой префикс лотов, при котором реализованный убыток наибольший; прибыльные лоты внутри префикса уже учтены в расчёте.",
        "Экономия = налог года до сделок минус налог после (по движку страницы «Налоги»: сальдирование внутри группы обычных счетов, ставки 13 % и 15 %, ЛДВ, перенос убытков). Убыток сверх налоговой базы налог года не снижает, а переносится на будущие годы — показан отдельно.",
        "Расходы: комиссия на продажу и на обратную покупку по ставке %s (%s); спред не учтён." % (txo_pct(fee_rate), fee_src),
        "Запрета на «мнимые» сделки (wash sale) в российском налоговом праве нет, но обратная покупка обнуляет срок владения: ЛДВ по новым бумагам отсчитывается заново.",
        "Продажа должна рассчитаться в текущем году: при расчётах T+1 последний день сделки показан выше; календарь торгов определяет биржа."]
    if not settings.get("offset_coupons") and t0 > 0 and cands:
        out["assumptions"].insert(0, "Убытки от продаж сейчас не уменьшают налог с купонов: в настройках страницы «Налоги» выключен зачёт убытков "
                                     "против купонного дохода. Если брокер или декларация его применяют, включите настройку — экономия пересчитается.")
    return out


def txo_pct(x):
    return ("%.2f %%" % (x * 100.0)).replace(".", ",")


def txo_iis_prefill(st):
    for i in st.get("iis") or []:
        if i.get("opened"):
            return {"open_year": int(i["opened"][:4]), "type": i["type"], "name": i["name"], "opened": i["opened"]}
    return None


def txo_harvest_get(cfg, acc, q, force):
    st, settings = tax_state(cfg, acc, force)
    fr = txo_num(q, "fee", -1.0, -1.0, 5.0) if q.get("fee") not in (None, "") else -1.0
    return txo_harvest_calc(st, settings, fr / 100.0 if fr >= 0 else None, txo_num(q, "min_loss", TXO_MIN_LOSS, 0.0, 1e9),
                            skip_ldv2=str(q.get("skip_ldv2") or "").lower() in ("1", "true", "on", "yes"))


# ── планировщик ИИС-3 ──

def txo_iis3_calc(open_year, contrib, yield_pct, years, income=0.0, rate15=None, reinvest=True, coupon_share=0.5, ldv=True):
    """Сравнение ИИС-3 и обычного брокерского счёта. Модель: взнос в начале года, доходность начисляется в конце года, вычет за год i
    поступает в начале года i+1 (вычет последнего года — наличными после горизонта). Реинвестированный вычет считается взносом сверх плана.
    income > 0 — годовой доход плательщика: определяет ставку (15 % выше 2,4 млн) и ограничивает вычет уплаченным НДФЛ."""
    years = max(1, int(years))
    open_year = int(open_year)
    y = yield_pct / 100.0
    if income > 0:
        rate15 = income > TXO_HI_THRESHOLD
    rate15 = bool(rate15)
    rate = TXO_IIS_RATE_HI if rate15 else TXO_IIS_RATE_LO
    term = txo_iis3_term(open_year)
    ded_base = min(contrib, TXO_IIS_LIMIT)
    # ИИС
    cap, dep, cash, refunds, rows, ref_prev = 0.0, 0.0, 0.0, [], [], 0.0
    # обычный счёт: лоты (стоимость, оценка, год покупки)
    lots, paid_tax = [], 0.0
    for i in range(1, years + 1):
        yr = open_year + i - 1
        if ref_prev > 0:
            if reinvest:
                cap += ref_prev
                dep += ref_prev
            else:
                cash += ref_prev
        cap += contrib
        dep += contrib
        cap *= 1.0 + y
        ref = ded_base * rate
        if income > 0:
            ref = min(ref, tx_ndfl(income, yr)[0])
        refunds.append(ref)
        ref_prev = ref
        # обычный счёт: налог с купонов считается на суммарный годовой доход по всем лотам (а не по каждому лоту отдельно),
        # реинвестированные купоны образуют новый лот текущего года i (не наследуя старый срок владения для ЛДВ)
        lots.append([contrib, contrib, i])
        coupons = [l[1] * y * coupon_share for l in lots]
        total_cp = sum(coupons)
        cp_tax = txo_tax(total_cp, yr, rate15)
        for l in lots:
            l[1] += l[1] * y * (1.0 - coupon_share)
        net_cp = total_cp - cp_tax
        if net_cp > 0:
            lots.append([net_cp, net_cp, i])
        paid_tax += cp_tax
        rows.append({"year": yr, "n": i, "contribution": contrib, "deduct_base": ded_base, "refund": ref, "iis_capital": cap, "iis_deposits": dep,
                     "broker_capital": sum(l[1] for l in lots), "broker_coupon_tax": cp_tax, "own": contrib * i})

    def broker_exit(k, cur_lots):
        gain_all, gain_ldv, wy_num, wy_den = 0.0, 0.0, 0.0, 0.0
        for cost, val, i0 in cur_lots:
            g = max(0.0, val - cost)
            gain_all += g
            held = k - i0 + 1      # покупка в начале года, продажа в конце года k: срок больше 3 лет только при held >= 4
            if ldv and held > 3:
                gain_ldv += g
                wy_num += max(cost, 0.0) * held
                wy_den += max(cost, 0.0)
        wy = (wy_num / wy_den) if wy_den > 0 else 0.0
        exempt = min(gain_ldv, TAX_LDV_LIMIT * wy)
        return txo_tax(gain_all - exempt, open_year + k - 1, rate15), exempt

    fin_year = open_year + years - 1
    own = contrib * years
    bt, bex = broker_exit(years, lots)
    broker_net = sum(l[1] for l in lots) - bt
    met = years >= term
    gain = cap - dep
    if met:
        over = max(0.0, gain - TXO_IIS_EXEMPT_CAP)
        iis_tax = txo_tax(over, fin_year, rate15)
        returned = 0.0
        iis_net = cap + cash + refunds[-1] - iis_tax      # вычет последнего года приходит наличными после горизонта
    else:
        iis_tax = txo_tax(gain, fin_year, rate15)
        returned = sum(refunds[:-1])                      # полученные вычеты возвращаются, вычет последнего года не заявляется
        iis_net = cap + cash - iis_tax - returned
    # досрочное закрытие в каждый год до срока
    early = []
    for k in range(1, min(years, term - 1) + 1):
        r = rows[k - 1]
        cap_k, dep_k = r["iis_capital"], r["iis_deposits"]
        ref_got = sum(refunds[:k - 1])
        cash_k = 0.0 if reinvest else ref_got
        tax_k = txo_tax(cap_k - dep_k, open_year + k - 1, rate15)
        early.append({"year": r["year"], "n": k, "capital": cap_k, "deposits": dep_k, "refunds_returned": ref_got, "tax": tax_k,
                      "net": cap_k + cash_k - tax_k - ref_got, "own": contrib * k, "extra_cost": tax_k + ref_got})
    out = {"inputs": {"open_year": open_year, "contribution": contrib, "yield_pct": yield_pct, "years": years, "income": income, "rate15": rate15,
                      "reinvest": bool(reinvest), "coupon_share": coupon_share, "ldv": bool(ldv)},
           "rules": {"limit": TXO_IIS_LIMIT, "rate": rate, "max_refund": TXO_IIS_LIMIT * rate, "exempt_cap": TXO_IIS_EXEMPT_CAP, "term": term,
                     "term_ok": met, "term_end_year": open_year + term - 1,
                     "terms": [{"from": a, "to": b, "years": t} for a, b, t in TXO_IIS_TERMS] + [{"from": 2031, "to": None, "years": 10}]},
           "rows": rows, "early": early, "warnings": [],
           "iis": {"capital": cap, "deposits": dep, "tax": iis_tax, "refunds_total": sum(refunds), "refunds_returned": returned, "net": iis_net,
                   "result_over_own": iis_net - own, "term_met": met},
           "broker": {"capital": sum(l[1] for l in lots), "coupon_tax": paid_tax, "exit_tax": bt, "ldv_exempt": bex, "net": broker_net,
                      "result_over_own": broker_net - own},
           "own": own, "advantage": iis_net - broker_net}
    if open_year < 2024:
        out["warnings"].append("ИИС-3 открывают с 2024 года: для более ранних лет срок принят как для 2024–2026 (5 лет).")
    if contrib > TXO_IIS_LIMIT:
        out["warnings"].append("Взносы свыше 400 000 ₽ в год вычет не увеличивают: в расчёт вычета идёт только 400 000 ₽.")
    if not met:
        out["warnings"].append("Горизонт короче минимального срока (%d лет): счёт закрывается досрочно, вычеты возвращаются, налог платится с дохода." % term)
    return out


def txo_iis3_get(cfg, acc, q, force):
    now = date.today().year
    rate15 = None
    if q.get("bracket") in ("13", "15"):
        rate15 = q.get("bracket") == "15"
    flag = lambda k, d: (q.get(k) if q.get(k) not in (None, "") else d) not in ("0", "false", "")
    return txo_iis3_calc(int(txo_num(q, "open_year", now, 2000, 2100)), txo_num(q, "contribution", 400000.0, 0.0, 1e9),
                         txo_num(q, "yield", 12.0, -50.0, 100.0), int(txo_num(q, "years", 10, 1, 40)), txo_num(q, "income", 0.0, 0.0, 1e10), rate15,
                         flag("reinvest", "1"), txo_num(q, "coupon_share", 50.0, 0.0, 100.0) / 100.0, flag("ldv", "1"))


API_GET["/api/txo/harvest"] = txo_harvest_get
API_GET["/api/txo/iis3"] = txo_iis3_get
# ═══════════════ «Стакан: ликвидность»: проскальзывание крупной заявки и эвристика скрытой (айсберг) ликвидности ═══════════════
# Стакан и сделки — те же источники, что у «Кто покупает» (сервер данных md/* либо собственный токен T-Invest); бесплатные данные
# Мосбиржи (ISS) для стакана не используются. Окно снимков стакана и сделок хранится в памяти и копится только пока экран опрашивают.

MIC_PRESETS = (1e6, 5e6, 10e6)
MIC_BAND = (0.005, 0.01)                   # глубина в пределах ±0,5 % и ±1 % от середины
MIC_WINDOW = 600                           # окно наблюдения за стаканом и сделками, с
MIC_IDLE = 120                             # без опроса столько секунд — бумагу перестаём отслеживать
MIC_MAX_TRACKED = 5
MIC_TOP_LEVELS = 5
MIC_FACTOR = 2.0                           # исполнено не менее чем в 2 раза больше максимального видимого размера уровня
MIC_PERSIST = 0.7                          # доля снимков, в которых уровень присутствовал
MIC_MIN_SNAPS, MIC_MIN_SPAN = 3, 20        # минимум снимков и секунд наблюдения для вывода
MIC_DEPTH = 50
_mic_state, _mic_lock = {}, threading.Lock()


def _mic_rub(x):
    return format(int(round(x)), ",").replace(",", " ")


def _mic_f(x):
    try:
        return ("%.2f" % float(x)).rstrip("0").rstrip(".")
    except (TypeError, ValueError):
        return "—"


# ───────────────────────── параметры бумаги ─────────────────────────
def _mic_screener_hit(secid):
    try:
        rows = screener_rows() or []
    except Exception:  # noqa: BLE001
        return None
    u = secid.upper()
    return next((r for r in rows if str(r.get("id") or "").upper() == u or str(r.get("isin") or "").upper() == u), None)


def _mic_mdur(secid):
    """Модифицированная дюрация (годы) по строке скринера облигаций или None."""
    r = _mic_screener_hit(secid)
    if not r or not r.get("dur"):
        return None
    y = r.get("yield")
    return float(r["dur"]) / (1 + (float(y) / 100 if y is not None else 0))


def _mic_meta(cfg, secid):
    """{lot, face, is_bond[, face_assumed]} или None, если размер лота определить нельзя."""
    if cfg.get("token"):
        try:
            m = _flw_own_meta(TInvest(cfg), secid)
        except ApiError:
            m = None
        if m:
            m = dict(m)
            if m.get("is_bond") and not m.get("face"):
                m["face"], m["face_assumed"] = 1000.0, True
            return m
    hit = _mic_screener_hit(secid)
    if hit:
        return {"lot": 1, "face": float(hit.get("nominal") or 1000), "is_bond": True, "face_assumed": not hit.get("nominal")}
    try:
        u = globals().get("stocks_universe")
        h = next((r for r in (u() if u else []) if r.get("secid") == secid.upper()), None)
        if h and h.get("lot"):
            return {"lot": max(1, int(h["lot"])), "face": None, "is_bond": False}
    except Exception:  # noqa: BLE001
        pass
    return None


def _mic_norm_trades(rows, lot):
    """Сделки -> [{ts, side, price, lots}]; qty в штуках делится на лот."""
    out = []
    for t in rows or []:
        try:
            ts, p, q = t.get("ts"), float(t.get("price")), float(t.get("qty"))
        except (TypeError, ValueError, AttributeError):
            continue
        if ts is None or t.get("side") not in ("buy", "sell") or q <= 0:
            continue
        out.append({"ts": float(ts), "side": t["side"], "price": p, "lots": q / max(1, lot)})
    return out


def _mic_fetch(cfg, secid, depth=MIC_DEPTH):
    """Стакан и сделки. -> {ok, bids, asks, trades (в лотах, None — сделки недоступны), source, source_label, ts, meta}."""
    meta = _mic_meta(cfg, secid)
    book = _flw_ds("md/orderbook", {"secid": secid, "depth": depth}, FLW_BOOK_TTL)
    trades, src = None, ""
    if book:
        tr = _flw_ds("md/trades", {"secid": secid, "minutes": 60}, FLW_BOOK_TTL)
        if tr is not None:
            trades = _mic_norm_trades(tr.get("trades"), (meta or {}).get("lot") or 1)   # _md_trades отдаёт штуки (pieces = qty * lot)
        src = "server"
    else:
        try:
            own = _flw_own(cfg, secid, depth)
        except ApiError as e:
            return {"ok": False, "error": str(e)}
        if own:
            book, raw = own
            trades = _mic_norm_trades(raw, (meta or {}).get("lot") or 1) if hasattr(TInvest, "last_trades") else None
            src = "own"
    if not book:
        return {"ok": False, "error": "Стакан недоступен: на сервере данных нет токена T-Invest, а собственный токен не задан. "
                                       "Бесплатные данные Мосбиржи (ISS) стакан не содержат."}
    label = {"server": "T-Invest через сервер данных, реальное время", "own": "T-Invest по вашему токену, реальное время"}[src]
    return {"ok": True, "bids": _flw_levels(book.get("bids")), "asks": _flw_levels(book.get("asks")), "trades": trades,
            "source": src, "source_label": label, "ts": book.get("ts") or time.time(), "meta": meta}


# ───────────────────────── проскальзывание ─────────────────────────
def mic_rub_per_lot(meta):
    """Рублей на один лот при цене 1: акции — штук в лоте; облигации — лот × номинал / 100 (цена в % от номинала)."""
    lot = max(1, int(meta.get("lot") or 1))
    if meta.get("is_bond"):
        return lot * float(meta.get("face") or 1000.0) / 100.0
    return float(lot)


def mic_walk(levels, target_rub, k):
    """Проход по видимым уровням от лучшего; levels — [[цена, лоты]], k — рублей на лот при цене 1. Заявка — целое число лотов."""
    remaining, lots, spent, steps = float(target_rub), 0, 0.0, []
    stopped = False
    for p, q in levels:
        per = p * k
        if per <= 0:
            continue
        n = min(int(q), int(remaining // per))
        if n > 0:
            lots += n
            spent += n * per
            remaining -= n * per
            steps.append({"price": p, "lots": n, "rub": round(n * per, 2)})
        if n < int(q):
            stopped = True                      # на этом уровне денег хватило не на весь объём: заявка исполнена
            break
    min_per = min((p * k for p, _ in levels if p > 0), default=0.0)
    complete = lots > 0 and (stopped or remaining < min_per)
    return {"lots": lots, "rub": round(spent, 2), "unfilled_rub": round(max(0.0, remaining), 2), "complete": complete,
            "levels_used": len(steps), "steps": steps, "visible_lots": sum(int(q) for _, q in levels),
            "vwap": (spent / (lots * k)) if lots else None}


def mic_impact(book, meta, side, target_rub, mdur=None):
    """Расчёт заявки по стакану {bids, asks}: покупка идёт по продавцам (asks), продажа — по покупателям (bids)."""
    bids = sorted(book.get("bids") or [], key=lambda x: -x[0])
    asks = sorted(book.get("asks") or [], key=lambda x: x[0])
    if not bids or not asks:
        return {"ok": False, "error": "В стакане нет заявок с одной из сторон."}
    if side not in ("buy", "sell"):
        return {"ok": False, "error": "Сторона заявки: покупка или продажа."}
    k = mic_rub_per_lot(meta)
    bb, ba = bids[0][0], asks[0][0]
    mid = (bb + ba) / 2.0
    levels = asks if side == "buy" else bids
    w = mic_walk(levels, target_rub, k)
    out = {"ok": True, "side": side, "target_rub": target_rub, "mid": mid, "best_bid": bb, "best_ask": ba,
           "spread": ba - bb, "spread_bp": (ba - bb) / mid * 1e4, "crossed": bb >= ba, "is_bond": bool(meta.get("is_bond")),
           "lot": meta.get("lot"), "face": meta.get("face"), "filled_lots": w["lots"], "filled_rub": w["rub"],
           "unfilled_rub": w["unfilled_rub"], "complete": w["complete"], "levels_used": w["levels_used"], "steps": w["steps"],
           "visible_lots": w["visible_lots"], "visible_levels": len(levels), "vwap": w["vwap"]}
    if w["lots"]:
        sg = 1 if side == "buy" else -1
        out["slip_mid_bp"] = sg * (w["vwap"] - mid) / mid * 1e4
        out["slip_mid_rub"] = sg * (w["vwap"] - mid) * w["lots"] * k
        out["slip_best_bp"] = sg * (w["vwap"] - levels[0][0]) / levels[0][0] * 1e4
        out["depth_share"] = w["lots"] / w["visible_lots"] if w["visible_lots"] else None
        if meta.get("is_bond") and mdur:
            out["yield_bp"] = out["slip_mid_bp"] / mdur         # Δдоходности ≈ Δцены% / модифицированная дюрация
            out["mdur"] = mdur
    if not w["complete"]:
        total = sum(p * q * k for p, q in levels)
        out["warning"] = "Видимой ликвидности не хватает: исполнится %s из %s ₽ (видно %d ур., всего %s ₽ на этой стороне)." % (
            _mic_rub(w["rub"]), _mic_rub(target_rub), len(levels), _mic_rub(total))
    band = {}
    for x in MIC_BAND:
        band[str(x)] = {"bid_lots": sum(q for p, q in bids if p >= mid * (1 - x)), "ask_lots": sum(q for p, q in asks if p <= mid * (1 + x)),
                        "bid_rub": round(sum(p * q * k for p, q in bids if p >= mid * (1 - x))),
                        "ask_rub": round(sum(p * q * k for p, q in asks if p <= mid * (1 + x)))}
    out["depth_band"] = band
    return out


def mic_impact_get(cfg, acc, q, force):
    secid = _flw_secid(q)
    if not secid:
        raise ApiError("Не указана бумага.", 400)
    side = q.get("side") if q.get("side") in ("buy", "sell") else "buy"
    try:
        rub = float(str(q.get("rub") or 1e6).replace(",", "."))
    except ValueError:
        rub = 1e6
    rub = min(max(rub, 1000.0), 1e10)
    f = _mic_fetch(cfg, secid)
    if not f["ok"]:
        return {"ok": False, "secid": secid, "error": f["error"]}
    meta = f.get("meta")
    if not meta:
        return {"ok": False, "secid": secid, "error": "Не удалось определить размер лота бумаги: пересчёт в рубли невозможен."}
    mdur = _mic_mdur(secid) if meta.get("is_bond") else None
    book = {"bids": f["bids"], "asks": f["asks"]}
    res = mic_impact(book, meta, side, rub, mdur)
    if not res["ok"]:
        return dict(res, secid=secid, source_label=f["source_label"])
    keep = ("complete", "vwap", "slip_mid_bp", "slip_mid_rub", "depth_share", "filled_rub", "yield_bp")
    presets = []
    for p in MIC_PRESETS:
        r = mic_impact(book, meta, side, p, mdur)
        presets.append(dict({k: r.get(k) for k in keep}, rub=p))
    notes = ["Расчёт по видимому стакану (до %d уровней) на момент запроса: скрытый объём и изменение стакана при исполнении не учтены; комиссия не учтена. "
             "Проскальзывание — отклонение средневзвешенной цены исполнения от середины между лучшей покупкой и лучшей продажей." % MIC_DEPTH]
    if meta.get("is_bond"):
        notes.append("Облигации: цена в %% от номинала (%s ₽), сумма = цена × номинал / 100 × количество; накопленный купонный доход оплачивается сверху." % _mic_f(meta.get("face")))
        if meta.get("face_assumed"):
            notes.append("Номинал не получен, принят 1000 ₽.")
        if mdur is None:
            notes.append("Влияние на доходность не показано: модифицированная дюрация выпуска не найдена в скринере.")
    return dict(res, secid=secid, source=f["source"], source_label=f["source_label"], ts=f["ts"], presets=presets, notes=notes)


# ───────────────────────── эвристика скрытой ликвидности ─────────────────────────
def mic_ice_update(secid, book, trades, now=None):
    """Добавляет снимок стакана и сделки в окно бумаги. trades=None — сделки недоступны. Вызывается только при опросе."""
    now = time.time() if now is None else now
    with _mic_lock:
        for s in [s for s, st in _mic_state.items() if now - st["polled"] > MIC_IDLE]:
            del _mic_state[s]
        st = _mic_state.get(secid)
        if st is None:
            if len(_mic_state) >= MIC_MAX_TRACKED:
                del _mic_state[min(_mic_state, key=lambda s: _mic_state[s]["polled"])]
            st = _mic_state[secid] = {"snaps": [], "trades": {}, "polled": now, "have_trades": True}
        st["polled"] = now
        st["have_trades"] = trades is not None
        st["snaps"].append({"ts": now, "bids": {p: q for p, q in book.get("bids") or []}, "asks": {p: q for p, q in book.get("asks") or []}})
        first = st["snaps"][0]["ts"]
        cnt = {}
        for t in trades or []:
            if t["ts"] < first - 1 or t["ts"] > now + 5:
                continue
            key = (t["ts"], t["side"], t["price"], t["lots"])
            cnt[key] = cnt.get(key, 0) + 1
        for key, n in cnt.items():
            st["trades"][key] = max(st["trades"].get(key, 0), n)
        cut = now - MIC_WINDOW
        st["snaps"] = [s for s in st["snaps"] if s["ts"] >= cut]
        st["trades"] = {k: n for k, n in st["trades"].items() if k[0] >= cut}
    return st


def mic_ice_report(secid, now=None):
    """Разбор окна. Статусы: unavailable (нет сделок), collecting (мало данных), ready."""
    now = time.time() if now is None else now
    with _mic_lock:
        st = _mic_state.get(secid)
        if not st or now - st["polled"] > MIC_IDLE:
            return {"status": "collecting", "snapshots": 0, "observed_sec": 0, "window_sec": MIC_WINDOW, "candidates": []}
        snaps, trades, have = list(st["snaps"]), dict(st["trades"]), st["have_trades"]
    span = snaps[-1]["ts"] - snaps[0]["ts"]
    base = {"snapshots": len(snaps), "observed_sec": round(span), "window_sec": MIC_WINDOW, "candidates": []}
    if not have:
        return dict(base, status="unavailable", message="Детектор недоступен: для этого источника нет ленты сделок.")
    if len(snaps) < MIC_MIN_SNAPS or span < MIC_MIN_SPAN:
        return dict(base, status="collecting", message="Накапливаю наблюдения: нужно не менее %d снимков за %d с." % (MIC_MIN_SNAPS, MIC_MIN_SPAN))
    last = snaps[-1]
    cands, checked = [], 0
    for side, key, aggr in (("ask", "asks", "buy"), ("bid", "bids", "sell")):
        for p in sorted(last[key], reverse=(side == "bid"))[:MIC_TOP_LEVELS]:
            checked += 1
            series = [(s["ts"], s[key].get(p)) for s in snaps]
            i0 = next(i for i, (_, q) in enumerate(series) if q)
            tail = series[i0:]
            frac = sum(1 for _, q in tail if q) / len(tail)
            vmax = max(q for _, q in tail if q)
            drops, prev = 0, None
            for _, q in tail:
                qv = q or 0
                if prev is not None and qv < prev:
                    drops += prev - qv
                prev = qv
            ex = sorted((k[0], k[3]) for k, n in trades.items() if k[1] == aggr and k[2] == p and k[0] >= series[i0][0] - 1 for _ in range(n))
            executed = sum(l for _, l in ex)
            hidden = max(0.0, executed - drops)
            if executed >= MIC_FACTOR * vmax and frac >= MIC_PERSIST and hidden > 0:
                cands.append({"side": side, "price": p, "executed_lots": round(executed, 2), "visible_max_lots": vmax,
                              "visible_now_lots": series[-1][1], "visible_consumed_lots": round(drops, 2),
                              "hidden_est_lots": round(hidden, 2), "factor": round(executed / vmax, 1), "persist": round(frac, 2),
                              "first_seen": series[i0][0], "last_seen": series[-1][0],
                              "evidence": {"book": [[round(ts, 1), q] for ts, q in tail[-8:]], "trades": [[round(ts, 1), round(l, 2)] for ts, l in ex[-8:]]}})
    cands.sort(key=lambda c: -c["hidden_est_lots"])
    return dict(base, status="ready", candidates=cands, levels_checked=checked)


def mic_iceberg_get(cfg, acc, q, force):
    secid = _flw_secid(q)
    if not secid:
        raise ApiError("Не указана бумага.", 400)
    f = _mic_fetch(cfg, secid, 10)
    if not f["ok"]:
        return {"ok": False, "secid": secid, "error": f["error"]}
    mic_ice_update(secid, {"bids": f["bids"], "asks": f["asks"]}, f["trades"])
    rep = mic_ice_report(secid)
    return dict(rep, ok=True, secid=secid, source=f["source"], source_label=f["source_label"], ts=f["ts"],
                note="Эвристика, а не факт: уровень, на котором исполнено не менее чем в %d раза больше его максимального видимого размера и который держался "
                     "не менее %d %% снимков, может скрывать часть объёма. Результат зависит от свежести данных и частоты опроса; "
                     "окно — до %d мин и копится только пока экран открыт." % (MIC_FACTOR, MIC_PERSIST * 100, MIC_WINDOW // 60))


API_GET["/api/mic/impact"] = mic_impact_get
API_GET["/api/mic/iceberg"] = mic_iceberg_get
# ═══════════════════ арбитраж внутри кривой эмитента, инверсия кривой (EWS) и рубль vs валюта ═══════════════════
# Детерминированный анализ скринера облигаций Мосбиржи без ИИ:
# 1) перекосы доходности внутри кривой одного эмитента при близкой дюрации + срок окупаемости перекладки;
# 2) инверсия кривой одного эмитента (короткий выпуск заметно дороже по YTM длинного — ранний сигнал стресса);
# 3) сравнение рублёвых и валютных (USD/EUR/CNY) выпусков того же эмитента — безубыточная девальвация рубля после НДФЛ.


def _arb_key(r):
    """Ключ группировки эмитента для облигаций скринера."""
    k = issuer_group_key(r.get("name") or "")
    if k:
        return k
    toks = sorted(name_tokens(r.get("name") or ""))
    return " ".join(toks[:2]) if toks else ""


def _arb_rating_str(r):
    rt = r.get("rating")
    if isinstance(rt, dict):
        return rt.get("v")
    return rt if isinstance(rt, str) else None


def arb_compute(rows, fx_rates=None, fee_pct=0.05, tax_rate=0.13):
    """Чистый расчёт по строкам скринера -> {pairs, inversions, fx_vs_rub, stats}."""
    fx_rates = fx_rates or {}
    rub_groups = {}
    fx_groups = {}
    for r in rows or []:
        y = r.get("yield")
        dur = r.get("dur") or r.get("macdur")
        if y is None or dur is None or not (0.5 <= y <= 120.0) or dur < 0.15:
            continue
        if r.get("floating") or r.get("kind") != "corp":
            continue
        cur = (r.get("cur") or "RUB").upper()
        gk = _arb_key(r)
        if not gk:
            continue
        item = {"isin": r.get("isin") or r.get("id"), "name": r.get("name") or r.get("id"),
                "yield": float(y), "dur": float(dur), "price": r.get("price"), "cur": cur,
                "turn": float(r.get("turn") or 0.0), "rating": _arb_rating_str(r),
                "offer": r.get("offer"), "mat": r.get("mat"), "group": gk}
        if cur == "RUB":
            rub_groups.setdefault(gk, []).append(item)
        elif cur in ("USD", "EUR", "CNY"):
            fx_groups.setdefault(gk, []).append(item)

    # 1. Арбитраж внутри кривой одного эмитента (близкая дюрация, разница YTM >= 0.8 п.п.)
    switch_cost_pct = 2.0 * max(0.0, float(fee_pct)) + 0.20    # комиссия продажи+покупки + оценка бид-аск спреда 0.2%
    pairs = []
    for gk, bs in rub_groups.items():
        if len(bs) < 2:
            continue
        best = None
        for i in range(len(bs)):
            for j in range(len(bs)):
                if i == j:
                    continue
                cheap, rich = bs[i], bs[j]
                if cheap["yield"] > 60 or rich["yield"] > 60:
                    continue
                dy = cheap["yield"] - rich["yield"]
                dd = abs(cheap["dur"] - rich["dur"])
                if dy < 0.8 or dd > 1.2:
                    continue
                if cheap["turn"] <= 0 and rich["turn"] <= 0:
                    continue
                net_dy = dy * (1.0 - tax_rate)
                payback_mo = round(switch_cost_pct / net_dy * 12.0, 1) if net_dy > 0 else None
                cand = {"issuer": gk, "rating": cheap["rating"] or rich["rating"],
                        "buy": cheap, "sell": rich,
                        "spread_bp": int(round(dy * 100)), "dur_diff": round(dd, 2),
                        "switch_cost_pct": round(switch_cost_pct, 2), "payback_mo": payback_mo}
                if best is None or cand["spread_bp"] > best["spread_bp"]:
                    best = cand
        if best:
            pairs.append(best)
    pairs.sort(key=lambda x: -x["spread_bp"])

    # 2. Детектор инверсии кривой эмитента (короткий выпуск заметно выше длинного по YTM — стресс ликвидности / EWS)
    inversions = []
    for gk, bs in rub_groups.items():
        if len(bs) < 2:
            continue
        by_d = sorted(bs, key=lambda b: b["dur"])
        short_b = next((b for b in by_d if b["dur"] <= 1.5 and b["yield"] >= 18.0), None)
        if not short_b:
            continue
        long_cands = [b for b in by_d if b["dur"] >= short_b["dur"] + 0.7]
        if not long_cands:
            continue
        long_b = min(long_cands, key=lambda b: b["yield"])
        inv = short_b["yield"] - long_b["yield"]
        if inv >= 2.5:
            inv_bp = int(round(inv * 100))
            sev = "high" if (inv_bp >= 500 or short_b["yield"] >= 30.0) else "warn"
            inversions.append({"issuer": gk, "rating": short_b["rating"] or long_b["rating"],
                               "short": short_b, "long": long_b, "inv_bp": inv_bp,
                               "severity": sev, "n_bonds": len(bs)})
    inversions.sort(key=lambda x: -x["inv_bp"])

    # 3. Рубль vs Валюта у одного эмитента (безубыточная девальвация рубля после НДФЛ)
    fx_vs_rub = []
    for gk, fbs in fx_groups.items():
        rbs = [b for b in rub_groups.get(gk, []) if b["yield"] <= 45.0]
        if not rbs:
            continue
        for cur in ("USD", "CNY", "EUR"):
            cfs = [b for b in fbs if b["cur"] == cur and b["yield"] <= 30.0]
            if not cfs:
                continue
            # Берём пару с минимальной разницей по дюрации
            best_pair = min(((rb, fb, abs(rb["dur"] - fb["dur"])) for rb in rbs for fb in cfs), key=lambda x: x[2])
            rb, fb, dd = best_pair
            if dd > 2.5:
                continue
            yr = rb["yield"] / 100.0
            yf = fb["yield"] / 100.0
            # Без ЛДВ (единая ставка НДФЛ 13% на купон и валютную переоценку): множитель (1-t) сокращается
            be_pre = ((1.0 + yr) / (1.0 + yf) - 1.0) * 100.0
            # С ЛДВ (> 3 лет): валютная переоценка тела освобождается от НДФЛ, а купоны облагаются по 13% -> порог девальвации ниже
            yr_n = yr * (1.0 - tax_rate)
            yf_n = yf * (1.0 - tax_rate)
            be_ldv = ((1.0 + yr_n) / (1.0 + yf_n) - 1.0) * 100.0
            spot = fx_rates.get(cur)
            target_fx = round(spot * (1.0 + be_pre / 100.0), 2) if spot else None
            fx_vs_rub.append({"issuer": gk, "rating": rb["rating"] or fb["rating"], "cur": cur,
                              "rub": rb, "fx": fb, "dur_diff": round(dd, 2),
                              "be_pre_pct": round(be_pre, 2), "be_ldv_pct": round(be_ldv, 2),
                              "fx_now": round(spot, 2) if spot else None, "fx_breakeven_1y": target_fx})
    fx_vs_rub.sort(key=lambda x: x["be_pre_pct"])

    return {"pairs": pairs[:40], "inversions": inversions[:30], "fx_vs_rub": fx_vs_rub[:30],
            "stats": {"issuers_rub": len(rub_groups), "pairs": len(pairs), "inversions": len(inversions), "fx_pairs": len(fx_vs_rub)},
            "fee_pct": fee_pct, "tax_rate": tax_rate}


def _api_arb(cfg, acc, q, force):
    try:
        rows = screener_rows()
    except Exception as e:  # noqa: BLE001
        return {"error": "Не удалось загрузить скринер облигаций: %s" % str(e)[:140], "pairs": [], "inversions": [], "fx_vs_rub": []}
    today = date.today().isoformat()
    fx_rates = {}
    for c in ("USD", "CNY", "EUR"):
        try:
            v = tax_cbr_rate(c, today)
            if v:
                fx_rates[c] = v
        except Exception:  # noqa: BLE001
            pass
    try:
        fee = max(0.0, min(2.0, float(str(q.get("fee", "0.05")).replace(",", "."))))
    except ValueError:
        fee = 0.05
    return arb_compute(rows, fx_rates=fx_rates, fee_pct=fee)


API_GET["/api/arb"] = _api_arb
# ═══════════════════ разбор сделок (Trade Post-Mortem по FIFO) и призрачный портфель (Cashflow-Matched) ═══════════════════
# Детерминированный анализ истории операций без ИИ:
# 1) Trade Post-Mortem: Win Rate, Profit Factor, средний выигрыш/убыток, Disposition Effect (срок удержания убытков vs прибыли);
# 2) Призрачный портфель: моделирование тех же пополнений и выводов в те же даты в фондах LQDT и TMOS.


def pm_trades_stats(sales):
    """Статистика по закрытым сделкам FIFO из tax_state (g['sales']). Группирует частичные исполнения одной продажи (uid, sdate)."""
    grouped = {}
    for s in sales or []:
        if s.get("bucket") != "sec":
            continue
        sd = s.get("sdate")
        bd = s.get("bdate")
        if sd is None:
            continue
        sd_iso = sd.isoformat() if hasattr(sd, "isoformat") else str(sd)[:10]
        key = (s.get("uid") or s.get("ticker") or s.get("name"), sd_iso, s.get("kind") or "sell")
        g = grouped.get(key)
        hold = (sd - bd).days if (bd is not None and hasattr(sd, "__sub__")) else None
        if g is None:
            g = grouped[key] = {"name": s.get("name") or s.get("ticker") or "", "ticker": s.get("ticker") or "",
                                "type": s.get("type") or "other", "sdate": sd_iso, "qty": 0.0,
                                "cost": 0.0, "proceeds": 0.0, "result": 0.0, "hold_num": 0.0, "hold_den": 0.0}
        q = float(s.get("qty") or 0.0)
        c = float(s.get("cost") or 0.0)
        g["qty"] += q
        g["cost"] += c
        g["proceeds"] += float(s.get("proceeds") or 0.0)
        g["result"] += float(s.get("result") or 0.0)
        if hold is not None and hold >= 0:
            w = max(abs(c), q, 1.0)
            g["hold_num"] += hold * w
            g["hold_den"] += w

    trades = []
    for g in grouped.values():
        res = round(g["result"], 2)
        cost = round(g["cost"], 2)
        pct = round(res / cost * 100.0, 2) if cost > 1.0 else None
        hold = round(g["hold_num"] / g["hold_den"], 1) if g["hold_den"] > 0 else None
        trades.append({"name": g["name"], "ticker": g["ticker"], "type": g["type"], "sdate": g["sdate"],
                       "cost": cost, "proceeds": round(g["proceeds"], 2), "result": res, "pct": pct, "hold_days": hold})

    if not trades:
        return {"n": 0, "wins": 0, "losses": 0, "win_rate": None, "profit_factor": None, "net_pnl": 0.0,
                "gross_profit": 0.0, "gross_loss": 0.0, "avg_win": None, "avg_loss": None,
                "avg_hold_win": None, "avg_hold_loss": None, "disposition_ratio": None, "disposition_flag": False,
                "by_type": [], "best": [], "worst": []}

    wins = [t for t in trades if t["result"] > 0.01]
    losses = [t for t in trades if t["result"] < -0.01]
    gp = sum(t["result"] for t in wins)
    gl = sum(t["result"] for t in losses)
    n_dec = len(wins) + len(losses)
    wr = round(len(wins) / n_dec * 100.0, 1) if n_dec else None
    pf = round(gp / abs(gl), 2) if abs(gl) > 1.0 else (None if not wins else 99.9)
    hw = [t["hold_days"] for t in wins if t["hold_days"] is not None]
    hl = [t["hold_days"] for t in losses if t["hold_days"] is not None]
    avg_hw = round(sum(hw) / len(hw), 1) if hw else None
    avg_hl = round(sum(hl) / len(hl), 1) if hl else None
    disp = round(avg_hl / avg_hw, 2) if (avg_hl is not None and avg_hw and avg_hw >= 1.0) else None

    by_t = {}
    for t in trades:
        b = by_t.setdefault(t["type"], {"type": t["type"], "n": 0, "wins": 0, "result": 0.0})
        b["n"] += 1
        if t["result"] > 0.01:
            b["wins"] += 1
        b["result"] += t["result"]
    by_type = sorted((dict(v, result=round(v["result"], 2), win_rate=round(v["wins"] / v["n"] * 100.0, 1))
                      for v in by_t.values()), key=lambda x: -x["n"])

    trades_by_res = sorted(trades, key=lambda t: t["result"])
    return {"n": len(trades), "wins": len(wins), "losses": len(losses), "win_rate": wr,
            "profit_factor": pf, "net_pnl": round(gp + gl, 2), "gross_profit": round(gp, 2), "gross_loss": round(gl, 2),
            "avg_win": round(gp / len(wins), 2) if wins else None,
            "avg_loss": round(gl / len(losses), 2) if losses else None,
            "avg_hold_win": avg_hw, "avg_hold_loss": avg_hl,
            "disposition_ratio": disp, "disposition_flag": bool(disp is not None and disp >= 1.35 and len(losses) >= 3),
            "by_type": by_type,
            "best": list(reversed(trades_by_res[-8:])), "worst": trades_by_res[:8]}


def pm_ghost_portfolio(hist):
    """Призрачный портфель (Cashflow-Matched): те же внешние пополнения/выводы (изменение invested),
    вложенные в те же даты в бенчмарки (LQDT, TMOS)."""
    days = (hist or {}).get("days") or []
    vals = (hist or {}).get("value") or []
    invs = (hist or {}).get("invested") or []
    bench = (hist or {}).get("bench") or {}
    if len(days) < 2 or len(vals) != len(days) or len(invs) != len(days):
        return {"ok": False, "items": [], "days": [], "real": [], "series": {}}

    real_end = float(vals[-1])
    inv_end = float(invs[-1])
    items = []
    series = {}
    for code in ("LQDT", "TMOS"):
        prices = bench.get(code)
        if not prices or len(prices) != len(days):
            continue
        units = 0.0
        cash_wait = 0.0
        curve = []
        valid = False
        for i in range(len(days)):
            flow = float(invs[i]) - (float(invs[i - 1]) if i > 0 else 0.0)
            p = prices[i]
            if p and p > 0:
                valid = True
                if cash_wait:
                    units = max(0.0, units + cash_wait / p)     # минус = выводы до первой цены: продаём юниты (не ниже 0)
                    cash_wait = 0.0
                units = max(0.0, units + flow / p)      # вывод больше стоимости бенчмарка не делает его шортом
                gv = max(0.0, units * p)
            else:
                cash_wait += flow
                gv = max(0.0, cash_wait)
            curve.append(round(gv, 2))
        if not valid:
            continue
        g_end = curve[-1]
        diff = round(real_end - g_end, 2)
        diff_pct = round(diff / g_end * 100.0, 2) if g_end > 100 else None
        items.append({"code": code, "name": "Денежный рынок (LQDT)" if code == "LQDT" else "Индекс МосБиржи (TMOS)",
                      "ghost_val": round(g_end, 2), "real_val": round(real_end, 2), "invested": round(inv_end, 2),
                      "diff_rub": diff, "diff_pct": diff_pct})
        series[code] = curve

    # Прореживаем до ~180 точек для лёгкого графика
    step = max(1, len(days) // 180)
    idx = list(range(0, len(days), step))
    if idx[-1] != len(days) - 1:
        idx.append(len(days) - 1)
    return {"ok": bool(items), "real_val": round(real_end, 2), "invested": round(inv_end, 2),
            "items": items, "days": [days[i] for i in idx], "real": [vals[i] for i in idx],
            "series": {k: [v[i] for i in idx] for k, v in series.items()}}


def _api_postmortem(cfg, acc, q, force):
    try:
        st, _ = tax_state(cfg, acc, force)
        sales = [s for g in st.get("groups") or [] for s in (g.get("sales") or [])]
        trades = pm_trades_stats(sales)
    except Exception as e:  # noqa: BLE001
        trades = {"n": 0, "error": str(e)[:140]}
    try:
        hist = build_history_for(cfg, acc, force)
        ghost = pm_ghost_portfolio(hist)
    except Exception:  # noqa: BLE001
        ghost = {"ok": False, "items": [], "days": [], "real": [], "series": {}}
    return {"trades": trades, "ghost": ghost}


API_GET["/api/postmortem"] = _api_postmortem
# ═══════════════════ дивидендные гэпы: лаборатория отсечки, радар по портфелю, оценка надёжности дивидендов ═══════════════════
# Чистая математика (без сети): dl_gaps / dl_stats / dl_payoff / dl_safety. Сеть — только в _dl_analyze (свечи ISS, дивиденды T-Invest/сервер, МСФО).
# Описательная статистика по прошлым отсечкам, не инвестиционная рекомендация.

DL_HORIZON = 250                      # торговых дней на закрытие гэпа
DL_WINDOWS = (30, 60, 90)
DL_T1_FROM = "2023-07-31"            # Мосбиржа перешла с расчётов T+2 на T+1
DL_TTL = 12 * 3600
DL_HIST = [("в день отсечки", 0, 0), ("1–5 дн.", 1, 5), ("6–20 дн.", 6, 20), ("21–60 дн.", 21, 60), ("61–120 дн.", 61, 120), ("121–250 дн.", 121, 250)]


def _dl_num(v):
    try:
        x = float(v)
    except (TypeError, ValueError):
        return None
    return x if x == x and x not in (float("inf"), float("-inf")) else None


def dl_median(vals):
    v = sorted(x for x in vals if x is not None)
    if not v:
        return None
    n = len(v)
    return float(v[n // 2]) if n % 2 else (v[n // 2 - 1] + v[n // 2]) / 2.0


def dl_gaps(divs, candles, horizon=DL_HORIZON):
    """Прошлые рублёвые дивиденды × дневные свечи -> гэпы отсечки.
    divs: [{record, value, cur?, last_buy?}], candles: [{t, o, h, l, c}] (t — ГГГГ-ММ-ДД). Результат — по возрастанию даты фиксации."""
    cs = sorted((c for c in candles or [] if c.get("t") and _dl_num(c.get("c")) is not None), key=lambda c: c["t"])
    if len(cs) < 3:
        return []
    ds = [c["t"][:10] for c in cs]
    out, seen = [], set()
    for d in sorted(divs or [], key=lambda x: x.get("record") or ""):
        rec, val = (d.get("record") or "")[:10], _dl_num(d.get("value"))
        if not rec or not val or val <= 0 or str(d.get("cur") or "RUB").upper() not in ("RUB", "RUR") or rec in seen:
            continue
        seen.add(rec)
        if rec > ds[-1] or rec <= ds[0]:
            continue
        lb = (d.get("last_buy") or "")[:10]
        if lb and ds[0] <= lb < rec and rec >= DL_T1_FROM:   # для отсечек эпохи T+2 T-Invest отдаёт last_buy по правилу T+1 — не верим
            i_last = bisect.bisect_right(ds, lb) - 1          # последний торговый день не позже last_buy
        else:
            # последний день покупки: за 1 торговый день до фиксации (T+1 с 31.07.2023), раньше — за 2 (T+2)
            i_last = bisect.bisect_left(ds, rec) - (1 if rec >= DL_T1_FROM else 2)
        if i_last < 0 or i_last + 1 >= len(cs):
            continue
        try:
            if (datetime.strptime(rec, "%Y-%m-%d") - datetime.strptime(ds[i_last], "%Y-%m-%d")).days > 10:
                continue                                      # дыра в данных: свечи не покрывают отсечку
        except ValueError:
            continue
        pre = _dl_num(cs[i_last]["c"])
        i_gap = i_last + 1
        post = _dl_num(cs[i_gap].get("o")) or _dl_num(cs[i_gap]["c"])
        if not pre or not post:
            continue
        gap = pre - post
        n_after = len(cs) - 1 - i_gap                         # торговых дней после дня гэпа в данных
        closed, days, mx = False, None, post
        for k in range(0, min(horizon, n_after) + 1):
            h = _dl_num(cs[i_gap + k].get("h")) or _dl_num(cs[i_gap + k]["c"])
            if h is not None and h > mx:
                mx = h
            if h is not None and h >= pre:
                closed, days = True, k
                break
        rec_pct = 100.0 if closed else (round((mx - post) / gap * 100.0, 1) if gap > 0 else 0.0)
        out.append({"record": rec, "last_buy": ds[i_last], "gap_day": ds[i_gap], "div": val, "p_pre": round(pre, 4), "p_post": round(post, 4),
                    "gap": round(gap, 4), "gap_pct": round(gap / pre * 100.0, 2), "div_pct": round(val / pre * 100.0, 2), "k": round(gap / val, 3),
                    "closed": closed, "days": days, "recovery_pct": rec_pct, "n_after": n_after})
    return out


def dl_stats(gaps, horizon=DL_HORIZON):
    """Сводка по гэпам: медиана дней до закрытия (только закрытые), доли закрытых за 30/60/90 дней (среди событий, по которым уже можно судить),
    число «ещё открытых» (слишком свежих), средняя k = гэп / дивиденд, гистограмма сроков закрытия."""
    gs = gaps or []
    closed = [g for g in gs if g["closed"]]
    win = {}
    for w in DL_WINDOWS:
        den = [g for g in gs if g["closed"] or g["n_after"] >= w]
        num = [g for g in den if g["closed"] and g["days"] <= w]
        win[str(w)] = {"n": len(num), "of": len(den), "pct": round(len(num) / len(den) * 100.0, 1) if den else None}
    still_open = [g for g in gs if not g["closed"] and g["n_after"] < DL_WINDOWS[-1]]
    ks = [g["k"] for g in gs]
    hist = [{"label": lb, "n": sum(1 for g in closed if lo <= g["days"] <= hi)} for lb, lo, hi in DL_HIST]
    hist.append({"label": "не закрыт", "n": sum(1 for g in gs if not g["closed"] and g["n_after"] >= DL_WINDOWS[-1])})
    hist.append({"label": "ещё открыт", "n": len(still_open)})
    return {"count": len(gs), "closed": len(closed), "median_days": dl_median([g["days"] for g in closed]), "within": win, "still_open": len(still_open),
            "avg_k": round(sum(ks) / len(ks), 3) if ks else None, "median_k": round(dl_median(ks), 3) if ks else None,
            "avg_gap_pct": round(sum(g["gap_pct"] for g in gs) / len(gs), 2) if gs else None, "hist": hist}


def dl_payoff(div, p_pre, p_post_est, cost, tax_rate, fee_rate):
    """На одну акцию, изменение стоимости от цены накануне p_pre: удержание = дивиденд после налога − гэп;
    продажа накануне и обратная покупка по p_buy (на 0,1 гэпа выше открытия) = −(p_buy − p_post) − комиссии − налог с продажи."""
    div, p_pre, p_post_est = float(div), float(p_pre), float(p_post_est)
    tax, fee = float(tax_rate or 0.0), float(fee_rate or 0.0)
    gap = p_pre - p_post_est
    hold = div * (1.0 - tax) - gap
    p_buy = p_post_est + 0.1 * gap
    tax_sale = tax * max(0.0, p_pre - cost) if cost is not None else 0.0
    sell = (p_post_est - p_buy) - 2.0 * fee * p_pre - tax_sale   # продали по p_pre, откупили по p_buy: в итоге та же акция по p_post_est плюс разница
    return {"div": round(div, 4), "p_pre": round(p_pre, 4), "p_post_est": round(p_post_est, 4), "gap": round(gap, 4),
            "gap_pct": round(gap / p_pre * 100.0, 2) if p_pre else None, "p_buy": round(p_buy, 4), "hold": round(hold, 4),
            "sell_rebuy": round(sell, 4), "diff": round(sell - hold, 4), "tax_sale": round(tax_sale, 4), "fees": round(2.0 * fee * p_pre, 4),
            "cost_known": cost is not None, "tax_rate": tax, "fee_rate": fee}


def dl_streak(years, today_year):
    """Подряд идущие календарные годы с выплатами, оканчивающиеся текущим или прошлым годом."""
    ys = set(years)
    y = today_year if today_year in ys else today_year - 1
    n = 0
    while y in ys:
        n += 1
        y -= 1
    return n


DL_ZONES = [(80, "надёжно", "pos"), (50, "умеренно", "warn"), (0, "высокий риск", "neg")]


def dl_zone(score):
    if score is None:
        return None
    return next(z for z in DL_ZONES if score >= z[0])


def dl_safety(fin):
    """Оценка надёжности дивиденда 0–100. fin: {fcf, div_total (оба млн ₽), nd_ebitda, roe (%), pay_years (подряд), bank}.
    Компонент без данных исключается, баллы пересчитываются на доступный вес; при доступных <50 % веса оценки нет."""
    fin = fin or {}
    comps, flags = [], []

    def add(cid, name, w, pts, val, note):
        comps.append({"id": cid, "name": name, "weight": w, "points": pts, "value": val, "note": note, "available": pts is not None})

    fcf, dt = _dl_num(fin.get("fcf")), _dl_num(fin.get("div_total"))
    if fin.get("bank"):
        net = _dl_num(fin.get("net"))
        if net is None or dt is None or dt <= 0:
            add("fcf", "Покрытие дивидендов прибылью", 40, None, None, "нет данных" if dt is None or net is None else "нет выплат за 12 мес.")
        elif net <= 0:
            flags.append("дивиденды выплачиваются при убытке")
            add("fcf", "Покрытие дивидендов прибылью", 40, 0, None, "чистая прибыль не положительна")
        else:
            po = dt / net
            pts = 40 if po <= 0.5 else 28 if po <= 0.7 else 16 if po <= 0.9 else 8 if po <= 1.0 else 0
            if pts == 0:
                flags.append("дивиденды больше чистой прибыли")
            add("fcf", "Покрытие дивидендов прибылью", 40, pts, round(po, 2), "дивиденды / чистая прибыль = %d %%" % round(po * 100))
    elif fcf is None or dt is None or dt <= 0:
        add("fcf", "Покрытие дивидендов свободным денежным потоком", 40, None, None, "нет данных" if dt is None or fcf is None else "нет выплат за 12 мес.")
    else:
        cov = fcf / dt
        pts = 40 if cov >= 1.3 else 30 if cov >= 1.0 else 15 if cov >= 0.7 else 0
        if pts == 0:
            flags.append("дивиденды больше свободного денежного потока")
        add("fcf", "Покрытие дивидендов свободным денежным потоком", 40, pts, round(cov, 2), "FCF / дивиденды = ×%.2f" % cov)
    nd = _dl_num(fin.get("nd_ebitda"))
    if fin.get("bank"):
        add("nd", "Чистый долг / EBITDA", 30, None, None, "не применимо к банкам и финансовым компаниям")
    elif nd is None:
        add("nd", "Чистый долг / EBITDA", 30, None, None, "нет данных")
    else:
        pts = 30 if nd < 1.5 else 20 if nd < 2.5 else 10 if nd < 3.5 else 0
        add("nd", "Чистый долг / EBITDA", 30, pts, round(nd, 2), "×%.2f" % nd)
    py = fin.get("pay_years")
    if py is None:
        add("track", "Стабильность выплат", 20, None, None, "нет данных")
    else:
        pts = 20 if py >= 5 else 15 if py >= 3 else 5
        add("track", "Стабильность выплат", 20, pts, py, "лет подряд с выплатами: %d" % py)
    roe = _dl_num(fin.get("roe"))
    if roe is None:
        add("roe", "Рентабельность капитала (ROE)", 10, None, None, "нет данных")
    else:
        pts = 10 if roe >= 20 else 5 if roe >= 10 else 0
        add("roe", "Рентабельность капитала (ROE)", 10, pts, round(roe, 1), "%.1f %%" % roe)
    avail = sum(c["weight"] for c in comps if c["available"])
    if avail < 50:
        return {"score": None, "zone": None, "label": None, "available_weight": avail, "components": comps, "flags": flags,
                "note": "Недостаточно данных для оценки (доступно %d %% веса)." % avail}
    score = int(round(sum(c["points"] for c in comps if c["available"]) / float(avail) * 100.0))
    z = dl_zone(score)
    return {"score": score, "zone": z[2], "label": z[1], "available_weight": avail, "components": comps, "flags": flags, "note": None}


def dl_cagr(a, b, years):
    """Среднегодовой рост от a к b за years лет, % (None, если базы нет)."""
    if not a or not b or a <= 0 or b <= 0 or years <= 0:
        return None
    return round(((b / a) ** (1.0 / years) - 1.0) * 100.0, 1)


def dl_regularity(counts):
    """Сколько выплат в год обычно (по последним полным годам с выплатами): {per_year, label}."""
    c = [n for n in counts if n]
    if not c:
        return {"per_year": None, "label": "нет выплат"}
    m = int(round(dl_median(c)))
    same = sum(1 for n in c if n == m) / float(len(c))
    lab = {1: "раз в год", 2: "два раза в год", 3: "три раза в год", 4: "раз в квартал"}.get(m, "%d раз в год" % m)
    if len(c) >= 3 and same < 0.6:
        lab = "нерегулярно (обычно %s)" % lab
    return {"per_year": m, "label": lab}


def dl_div_profile(divs, price, today=None, qty=None, tax=0.13):
    """Сводный анализ дивидендов бумаги по полной истории (рублёвые выплаты, по году даты фиксации реестра).
    divs: [{record, value, ...}]. Годовые суммы, рост за 5/10 лет (CAGR), доходности, серии лет с выплатами и с ростом,
    регулярность, пропущенные годы, ближайшая выплата на позицию qty (до и после налога)."""
    today = today or date.today().isoformat()
    ty = int(today[:4])
    rows = sorted((d for d in divs or [] if d.get("record") and _dl_num(d.get("value"))), key=lambda d: d["record"])
    by = {}
    for d in rows:
        y = int(d["record"][:4])
        b = by.setdefault(y, {"year": y, "sum": 0.0, "n": 0, "announced": 0.0})
        if d["record"] >= today:
            b["announced"] += float(d["value"])
        else:
            b["sum"] += float(d["value"])
            b["n"] += 1
    years = []
    if by:
        for y in range(min(by), max(max(by), ty) + 1):
            b = by.get(y) or {"year": y, "sum": 0.0, "n": 0, "announced": 0.0}
            years.append({"year": y, "sum": round(b["sum"], 4), "n": b["n"], "announced": round(b["announced"], 4),
                          "yield_pct": round((b["sum"] + b["announced"]) / price * 100.0, 2) if price else None})
    sums = {r["year"]: r["sum"] for r in years}
    last_full = ty - 1
    paid_years = {y for y, v in sums.items() if v > 0}
    grow = 0
    y = last_full
    while sums.get(y, 0) > 0 and sums.get(y - 1, 0) > 0 and sums[y] > sums[y - 1] * 1.0001:
        grow += 1
        y -= 1
    nodecl = 0
    y = last_full
    while sums.get(y, 0) > 0 and sums.get(y - 1, 0) > 0 and sums[y] >= sums[y - 1] * 0.9999:
        nodecl += 1
        y -= 1
    first = min(paid_years) if paid_years else None
    skipped = [y for y in range(first, last_full + 1) if y not in paid_years] if first else []
    y1 = (datetime.strptime(today, "%Y-%m-%d") - timedelta(days=365)).strftime("%Y-%m-%d")
    y1f = (datetime.strptime(today, "%Y-%m-%d") + timedelta(days=365)).strftime("%Y-%m-%d")
    ttm = sum(float(d["value"]) for d in rows if y1 < d["record"] < today)
    fwd = sum(float(d["value"]) for d in rows if today <= d["record"] <= y1f)
    cnt = {r["year"]: r["n"] for r in years}
    recent = [cnt.get(y, 0) for y in range(last_full - 4, last_full + 1)]
    pct = lambda v: round(v / price * 100.0, 2) if price and v else None  # noqa: E731
    nx = _dl_next(rows, today) if rows else None
    nx_pos = None
    if nx and nx.get("upcoming") and qty:
        g = float(nx["value"]) * float(qty)
        nx_pos = {"qty": qty, "gross": round(g, 2), "net": round(g * (1.0 - tax), 2), "tax_rate": tax}
    return {"years": years, "first_year": first, "count": len([d for d in rows if d["record"] < today]),
            "ttm": round(ttm, 4), "yield_ttm": pct(ttm), "last_year": round(sums.get(last_full, 0.0), 4), "yield_last_year": pct(sums.get(last_full, 0.0)),
            "forward": round(fwd, 4) if fwd else None, "yield_forward": pct(fwd),
            "cagr5": dl_cagr(sums.get(last_full - 5), sums.get(last_full), 5), "cagr10": dl_cagr(sums.get(last_full - 10), sums.get(last_full), 10),
            "streak_paid": dl_streak(paid_years, ty) if paid_years else 0, "streak_growth": grow, "streak_nodecline": nodecl,
            "skipped": skipped, "regularity": dl_regularity(recent), "last_full_year": last_full, "next": nx, "next_pos": nx_pos}


def dl_received(ops, secid, alt=None, names=()):
    """Полученные дивиденды по бумаге из операций сводки (строки [дата, тип, вид, имя, тикер, кол-во, цена, сумма, валюта, …]).
    Налог с дивидендов вычитается; группировка по дате зачисления и по годам. Только рубли.
    alt — второй идентификатор (ISIN); names — полные названия: для строк импорта без тикера сверяем название."""
    ids = {x.upper() for x in (secid, alt) if x}
    nms = {str(n).strip().lower() for n in names or () if n}
    by = {}
    for o in ops or []:
        try:
            dt, kind, tk, amt, cur = (o[0] or "")[:10], o[2], (o[4] or "").upper(), float(o[7] or 0), (o[8] or "rub").lower()
        except (IndexError, TypeError, ValueError):
            continue
        if not (tk in ids or (not tk and str(o[3] or "").strip().lower() in nms)) or cur != "rub" or kind not in ("dividends", "tax_dividend") or not dt:
            continue
        b = by.setdefault(dt, {"date": dt, "gross": 0.0, "tax": 0.0})
        if kind == "dividends":
            b["gross"] += amt
        else:
            b["tax"] += -amt
    items = sorted(by.values(), key=lambda b: b["date"], reverse=True)
    yrs = {}
    for b in items:
        b["gross"], b["tax"] = round(b["gross"], 2), round(b["tax"], 2)
        b["net"] = round(b["gross"] - b["tax"], 2)
        y = yrs.setdefault(b["date"][:4], {"year": int(b["date"][:4]), "gross": 0.0, "net": 0.0})
        y["gross"] = round(y["gross"] + b["gross"], 2)
        y["net"] = round(y["net"] + b["net"], 2)
    return {"items": items, "years": sorted(yrs.values(), key=lambda y: y["year"]), "gross": round(sum(b["gross"] for b in items), 2),
            "tax": round(sum(b["tax"] for b in items), 2), "net": round(sum(b["net"] for b in items), 2)}


# ── сеть: сбор данных по бумаге ──

def _dl_rub_divs(items):
    return [d for d in items or [] if str(d.get("cur") or "RUB").upper() in ("RUB", "RUR") and _dl_num(d.get("value"))]


def _dl_fin_inputs(secid, q, dv, divs, cfg):
    """Входы dl_safety: МСФО (FCF, долг) + мультипликаторы (ND/EBITDA, ROE) + число лет подряд с выплатами. Любой сбой -> компонент без данных."""
    today = date.today()
    out = {"fcf": None, "net": None, "div_total": None, "nd_ebitda": None, "roe": None, "bank": (q or {}).get("sector") == "Банки и финансы", "pay_years": None}
    years = {int(d["record"][:4]) for d in divs if d.get("record") and d["record"] <= today.isoformat()}
    if years:
        out["pay_years"] = dl_streak(years, today.year)
    try:
        fin = ifrs_fin(secid)
        if fin.get("bank"):
            out["bank"] = True
        c = (fin.get("ltm") or (fin.get("years") or [None])[-1]) if fin.get("status") == "ok" else None
        if c:
            out["fcf"] = c.get("fcf")
            out["net"] = c.get("net")
            out["nd_ebitda"] = c.get("nd_ebitda")
            if c.get("roe") is not None:
                out["roe"] = c["roe"] * 100
    except Exception:  # noqa: BLE001
        pass
    try:
        m = stock_multiples(secid, (q or {}).get("cap"), (q or {}).get("asset_uid"), cfg) or {}
        if m.get("nd_ebitda") is not None:
            out["nd_ebitda"] = m["nd_ebitda"]
        if m.get("roe") is not None:
            out["roe"] = m["roe"]
    except Exception:  # noqa: BLE001
        pass
    price, cap, ttm = (q or {}).get("price"), (q or {}).get("cap"), (dv or {}).get("ttm_value")
    if price and cap and ttm:
        out["div_total"] = ttm * (cap / price) / 1e6
    return out


def _dl_analyze(secid, cfg, q=None, force=False):
    """Тяжёлый расчёт по одной бумаге (кэш 12 ч): дивиденды, гэпы, надёжность. Ошибки сети — в поле error, не исключением."""
    secid = (secid or "").strip().upper()
    key = "dl_v6_%s_%d" % (secid, 1 if (cfg or {}).get("token") else 0)
    if not force:
        hit = store().get(key, DL_TTL)
        if hit:
            return hit
    err = []
    kind = "share"
    if q is None:
        try:
            q, kind = stk_lookup(secid, cfg)                 # акции, затем биржевые фонды (у фонда дивиденды — с сервера данных и dohod.ru)
        except Exception as e:  # noqa: BLE001
            q = None
            err.append("список акций недоступен: %s" % str(e)[:80])
    q = q or {}
    kind = kind or "share"
    candles = []
    try:
        candles = stock_candles(secid, 24, days=2400)
    except Exception as e:  # noqa: BLE001
        err.append("свечи Мосбиржи недоступны: %s" % str(e)[:80])
    price = q.get("price") or (candles[-1]["c"] if candles else None)
    dv = {}
    try:
        dv = stock_dividends(secid, price, q.get("uid"), cfg, history=True) or {}
    except Exception as e:  # noqa: BLE001
        err.append("дивиденды недоступны: %s" % str(e)[:80])
    divs = sorted(_dl_rub_divs(dv.get("items")), key=lambda d: d["record"])
    gaps = dl_gaps(divs, candles)
    safety = dl_safety(_dl_fin_inputs(secid, q, dv, divs, cfg)) if kind != "fund" else None   # у фонда нет отчётности эмитента
    res = {"secid": secid, "kind": kind, "isin": q.get("isin"), "full_name": q.get("name"), "name": q.get("shortname") or q.get("name") or secid, "sector": q.get("sector"), "price": price,
           "divs": [{k: d.get(k) for k in ("record", "payment", "last_buy", "declared", "value", "src")} for d in divs], "gaps": gaps, "safety": safety,
           "div_source": dv.get("source"), "div_hist": dv.get("hist"), "candles_to": candles[-1]["t"][:10] if candles else None, "candles_n": len(candles), "error": "; ".join(err) or None}
    if candles and divs and not err:
        try:
            store().put(key, res)
        except Exception:  # noqa: BLE001
            pass
    return res


def _dl_next(divs, today):
    """Ближайший будущий дивиденд (по дате фиксации); если нет — последний прошедший."""
    fut = sorted((d for d in divs if d["record"] >= today), key=lambda d: d["record"])
    past = sorted((d for d in divs if d["record"] < today), key=lambda d: d["record"])
    x = dict(fut[0], upcoming=True) if fut else dict(past[-1], upcoming=False) if past else None
    if x and not x.get("last_buy"):
        try:                                                  # оценка: предыдущий будний день (праздники не учтены)
            d = datetime.strptime(x["record"], "%Y-%m-%d") - timedelta(days=1)
            while d.weekday() > 4:
                d -= timedelta(days=1)
            x["last_buy"], x["last_buy_est"] = d.strftime("%Y-%m-%d"), True
        except ValueError:
            pass
    return x


def _dl_cost_map(cfg, acc, summ=None):
    """Позиции-акции (и фонды) счёта: {тикер: {qty, avg, name}}. Без токена/счёта — пусто. summ — готовая сводка build_summary."""
    out = {}
    try:
        for r in (summ or build_summary(cfg, acc, "all"))["portfolio"]["positions"]:
            if r.get("type") in ("share", "etf") and (r.get("qty") or 0) > 0 and r.get("ticker"):
                o = out.setdefault(r["ticker"], {"qty": 0.0, "cost": 0.0, "name": r.get("name") or r["ticker"], "price": r.get("price")})
                o["qty"] += r["qty"]
                o["cost"] += (r.get("avg") or 0.0) * r["qty"]
    except Exception:  # noqa: BLE001
        return None
    for o in out.values():
        o["avg"] = o["cost"] / o["qty"] if o["qty"] else None
    return out


def _dl_stock_view(secid, cfg, acc, tax, fee, force):
    secid = (secid or "").strip().upper()
    if not re.fullmatch(r"[A-Z0-9._-]{1,16}", secid):
        raise ApiError("Некорректный тикер.", 400)
    a = _dl_analyze(secid, cfg, force=force)
    gaps = a["gaps"]
    st = dl_stats(gaps)
    today = date.today().isoformat()
    nx = _dl_next(a["divs"], today)
    summ = None
    if acc:
        try:
            summ = build_summary(cfg, acc, "all")
        except Exception:  # noqa: BLE001 — нет токена/счёта: анализ без позиции
            summ = None
    cmap = (_dl_cost_map(cfg, acc, summ) or {}) if summ else {}
    pos = cmap.get(secid) or (cmap.get(a["isin"]) if a.get("isin") else None)    # импортированные отчёты: тикер бывает равен ISIN
    received = dl_received(summ.get("ops"), secid, a.get("isin"), (a.get("full_name"),)) if summ else None
    profile = dl_div_profile(a["divs"], a.get("price"), today, pos["qty"] if pos else None, tax)
    px = a.get("price")
    divs = [dict(d, future=d["record"] >= today, yield_pct=round(d["value"] / px * 100.0, 2) if px else None) for d in reversed(a["divs"])]
    payoff = None
    if nx and a.get("price"):
        k = st["median_k"] if st["median_k"] is not None else 1.0
        payoff = dl_payoff(nx["value"], a["price"], a["price"] - k * nx["value"], pos["avg"] if pos else None, tax, fee)
        payoff.update(record=nx["record"], upcoming=nx["upcoming"], k_used=round(k, 3), k_fallback=st["median_k"] is None,
                      qty=pos["qty"] if pos else None, held=bool(pos))
    return {"ok": True, "mode": "stock", "secid": secid, "name": a["name"], "sector": a["sector"], "price": a["price"], "gaps": list(reversed(gaps)),
            "stats": st, "safety": a["safety"], "next": nx, "payoff": payoff, "tax": tax, "fee": fee, "div_source": a["div_source"], "div_hist": a.get("div_hist"),
            "candles_to": a["candles_to"], "error": a["error"], "kind": a.get("kind") or "share", "divs": divs, "profile": profile,
            "position": {"qty": pos["qty"], "avg": pos["avg"]} if pos else None, "received": received if received and received["items"] else None}


def _dl_portfolio_view(cfg, acc, tax, force):
    pos = _dl_cost_map(cfg, acc)
    if pos is None:
        return {"ok": True, "mode": "portfolio", "rows": [], "held": 0, "error": "Не удалось получить позиции счёта.", "token": bool(cfg.get("token"))}
    if not pos:
        return {"ok": True, "mode": "portfolio", "rows": [], "held": 0, "error": None, "token": bool(cfg.get("token"))}
    try:
        uni = {r["secid"]: r for r in stocks_universe(cfg=cfg)}
    except Exception:  # noqa: BLE001
        uni = {}
    by_isin = {r.get("isin"): k for k, r in uni.items() if r.get("isin")}
    for t in [t for t in pos if t not in uni and t in by_isin]:   # импортированные отчёты: вместо тикера ISIN
        o = pos.pop(t)
        k = by_isin[t]
        if k in pos:
            q0 = pos[k]
            q0["cost"] = q0.get("cost", 0.0) + o.get("cost", 0.0)
            q0["qty"] += o["qty"]
            q0["avg"] = q0["cost"] / q0["qty"] if q0["qty"] else None
        else:
            pos[k] = o
    tickers = sorted(pos)

    def one(t):
        try:
            return _dl_analyze(t, cfg, uni.get(t), force)
        except Exception as e:  # noqa: BLE001
            return {"secid": t, "divs": [], "gaps": [], "safety": {"score": None}, "error": str(e)[:100], "name": pos[t]["name"], "price": pos[t].get("price")}
    res = pool_map(one, tickers, workers=6)
    today = date.today().isoformat()
    rows = []
    for t, a in zip(tickers, res):
        if not a.get("divs") and not a.get("gaps") and not a.get("price") and uni and t not in uni:
            continue                                            # не акция TQBR (например, зарубежная) — радар её не видит
        nx = _dl_next(a.get("divs") or [], today)
        st = dl_stats(a.get("gaps") or [])
        p = pos[t]
        row = {"secid": t, "name": a.get("name") or p["name"], "qty": p["qty"], "avg": p["avg"], "price": a.get("price") or p.get("price"),
               "next": nx if nx and nx["upcoming"] else None, "last": nx if nx and not nx["upcoming"] else None,
               "safety": (a.get("safety") or {}).get("score"), "zone": (a.get("safety") or {}).get("zone"), "label": (a.get("safety") or {}).get("label"),
               "median_days": st["median_days"], "events": st["count"], "median_k": st["median_k"], "within90": st["within"]["90"]["pct"], "error": a.get("error")}
        if row["next"]:
            row["net_total"] = round(row["next"]["value"] * p["qty"] * (1.0 - tax), 2)
            row["gross_total"] = round(row["next"]["value"] * p["qty"], 2)
        rows.append(row)
    rows.sort(key=lambda r: (0 if r["next"] else 1, r["next"]["record"] if r["next"] else "", r["secid"]))
    return {"ok": True, "mode": "portfolio", "rows": rows, "held": len(pos), "tax": tax, "error": None, "token": bool(cfg.get("token"))}


def _api_divlab(cfg, acc, q, force):
    def num(k, d, lo, hi):
        v = _dl_num(str(q.get(k) or "").replace(",", "."))
        return d if v is None else min(hi, max(lo, v))
    tax = num("tax", 13.0, 0.0, 35.0) / 100.0
    fee = num("fee", 0.05, 0.0, 2.0) / 100.0
    secid = (q.get("secid") or "").strip()
    try:
        if secid:
            return _dl_stock_view(secid, cfg, acc if q.get("account") else None, tax, fee, bool(force))
        return _dl_portfolio_view(cfg, acc, tax, bool(force))
    except ApiError:
        raise
    except Exception as e:  # noqa: BLE001
        return {"ok": True, "mode": "stock" if secid else "portfolio", "rows": [], "gaps": [], "error": "Данные временно недоступны: %s" % str(e)[:120]}


API_GET["/api/divlab"] = _api_divlab
# ═══════════════════ длинная история дивидендов: dohod.ru (с 2000-х) + слияние с данными T-Invest / сервера ═══════════════════
# T-Invest GetDividends отдаёт ~6 лет, у компаний история 20+ лет. Добираем более ранние годы со страницы
# https://www.dohod.ru/ik/analytics/dividend/<тикер> (публичная, без входа; robots.txt разрешает /ik/). Запрос — обычный GET без личных данных,
# через сервер данных (белый список хостов) или напрямую. Разбор устойчив к смене порядка колонок (колонки ищутся по заголовкам).
# Строки «прогноз» и «рекомендовано» (запись реестра ещё не утверждена) в историю не смешиваются — они лежат отдельно в upcoming.
# Описательная статистика по прошлым выплатам, не инвестиционная рекомендация.

DH_BASE = "https://www.dohod.ru/ik/analytics/dividend/%s"
DH_TTL = 7 * 86400                    # история прошлых лет неизменна: неделя
DH_ERR_TTL = 3600                     # сбой сети: повтор не чаще раза в час, пока отдаём прошлый успешный ответ
DH_NF_TTL = 3 * 86400                 # на dohod.ru нет страницы тикера (облигации, ETF, новые бумаги)
DH_SRC = "dohod"
DH_SRC_NAME = "dohod.ru"
DH_DATE_TOL = 3                       # дедупликация: даты фиксации реестра ±3 дня
DH_SUM_TOL = 0.01                     # ... и суммы ±1 %
DH_LIMIT = 200                        # строк в сводке с полной историей
_dh_lock = threading.Lock()
_dh_last = [0.0]
_DH_CUR = {"руб": "RUB", "rub": "RUB", "usd": "USD", "$": "USD", "долл": "USD", "eur": "EUR", "€": "EUR", "cny": "CNY", "юан": "CNY",
           "hkd": "HKD", "гонкон": "HKD", "kzt": "KZT", "тенге": "KZT"}


def dh_slug(secid):
    s = (secid or "").strip()
    return s.lower() if re.fullmatch(r"[A-Za-z0-9]{1,12}", s) else None


def _dh_text(frag):
    t = re.sub(r"<[^>]+>", " ", frag or "")
    t = t.replace("&nbsp;", " ").replace("&#160;", " ").replace("\xa0", " ").replace("&amp;", "&").replace("&quot;", '"')
    return re.sub(r"\s+", " ", t).strip()


def _dh_date(t):
    m = re.search(r"(\d{1,2})\.(\d{1,2})\.(\d{4})", t or "")
    if not m:
        return None
    try:
        return date(int(m.group(3)), int(m.group(2)), int(m.group(1))).isoformat()
    except ValueError:
        return None


def _dh_amount(t):
    m = re.search(r"-?\d[\d ]*(?:[.,]\d+)?", (t or "").replace(" ", " "))
    if not m:
        return None
    try:
        v = float(m.group(0).replace(" ", "").replace(",", "."))
    except ValueError:
        return None
    return v if v == v and v not in (float("inf"), float("-inf")) else None


def _dh_currency(page):
    """Валюта из заголовков вида «Дивиденд (руб.)»; по умолчанию рубли."""
    for m in re.finditer(r"Дивиденд[^<]{0,12}\(([^)<]{1,12})\)", page or "", re.I):
        c = m.group(1).strip().lower()
        for k, v in _DH_CUR.items():
            if k in c:
                return v
    return "RUB"


def dh_parse(page, today=None):
    """HTML страницы dohod.ru -> {rows, upcoming, currency, title} или None (страница в неожиданном формате).
    rows — фактические и утверждённые выплаты [{record, declared, value, cur, status paid|approved, src}], от новых к старым;
    upcoming — рекомендации и прогнозы (status recommended|forecast), в историю не идут."""
    if not page or not isinstance(page, str):
        return None
    today = today or date.today().isoformat()
    cur = _dh_currency(page)
    tbl = None
    for m in re.finditer(r"<table\b[^>]*>(.*?)</table>", page, re.S | re.I):
        body = m.group(1)
        head = _dh_text(" ".join(re.findall(r"<th\b[^>]*>(.*?)</th>", body, re.S | re.I))).lower()
        if "закрытия реестра" in head and "дивиденд" in head:
            tbl = body
            break
    if tbl is None:
        return None
    cols = {"declared": 0, "record": 1, "amount": 3}
    for tr in re.finditer(r"<tr\b([^>]*)>(.*?)</tr>", tbl, re.S | re.I):
        ths = [_dh_text(x).lower() for x in re.findall(r"<th\b[^>]*>(.*?)</th>", tr.group(2), re.S | re.I)]
        if ths:
            for i, h in enumerate(ths):
                if "закрытия реестра" in h:
                    cols["record"] = i
                elif "объявлен" in h:
                    cols["declared"] = i
                elif h.startswith("дивиденд"):
                    cols["amount"] = i
            break
    rows, upcoming, seen = [], [], set()
    for tr in re.finditer(r"<tr\b([^>]*)>(.*?)</tr>", tbl, re.S | re.I):
        cells = re.findall(r"<td\b[^>]*>(.*?)</td>", tr.group(2), re.S | re.I)
        if len(cells) <= max(cols.values()):
            continue
        rec = _dh_date(_dh_text(cells[cols["record"]]))
        val = _dh_amount(_dh_text(cells[cols["amount"]]))
        if not rec or not val or val <= 0:
            continue
        decl = _dh_date(_dh_text(cells[cols["declared"]]))
        raw = tr.group(2).lower()
        is_fc = "forecast" in tr.group(1).lower() or "(прогноз)" in raw
        if is_fc:
            status = "recommended" if ("рекоменд" in raw and "(прогноз)" not in raw) else "forecast"
        elif rec >= today:
            status = "approved" if decl else "recommended"
        else:
            status = "paid"
        item = {"record": rec, "declared": decl, "value": round(val, 6), "cur": cur, "status": status, "src": DH_SRC}
        if status in ("paid", "approved"):
            k = (rec, item["value"])
            if k in seen:
                continue                                      # у источника встречаются дубли строк
            seen.add(k)
            rows.append(item)
        else:
            upcoming.append(item)
    if not rows and not upcoming and "<td" not in tbl:
        return None
    rows.sort(key=lambda x: x["record"], reverse=True)
    upcoming.sort(key=lambda x: x["record"])
    h1 = re.search(r"<h1[^>]*>(.*?)</h1>", page, re.S | re.I)
    return {"rows": rows, "upcoming": upcoming, "currency": cur, "title": _dh_text(h1.group(1)) if h1 else ""}


def _dh_http(url):
    with _dh_lock:                                            # не чаще одного запроса в секунду на всё приложение
        wait = 1.0 - (time.time() - _dh_last[0])
        if wait > 0:
            time.sleep(wait)
        _dh_last[0] = time.time()
    return ext_open(url, timeout=20)[1].decode("utf-8", "replace")


def dh_history(secid, today=None, fetch=None):
    """Тикер -> {status ok|nodata|parse|err, rows, upcoming, fetched, ...}. Кэш в store: 7 суток; сбой сети отдаёт прошлый успешный ответ.
    Не бросает исключений. fetch(url) -> html подменяется в тестах."""
    slug = dh_slug(secid)
    empty = {"status": "nodata", "rows": [], "upcoming": [], "currency": "RUB", "url": None, "source": DH_SRC_NAME}
    if not slug:
        return empty
    key = "dh_v1_" + slug
    now = time.time()
    try:
        hit = store().get(key)
    except Exception:  # noqa: BLE001
        hit = None
    if hit:
        age = now - (hit.get("fetched") or 0)
        ttl = DH_TTL if hit.get("status") == "ok" else DH_NF_TTL if hit.get("status") == "nodata" else DH_ERR_TTL
        if age < ttl and now >= (hit.get("retry_at") or 0):
            return hit
        if hit.get("status") == "ok" and now < (hit.get("retry_at") or 0):
            return hit                                        # недавний сбой при обновлении: пока отдаём прошлую историю
    url = DH_BASE % slug
    try:
        page = (fetch or _dh_http)(url)
        parsed = dh_parse(page, today)
        if parsed is None:
            res = dict(empty, status="parse", url=url, fetched=now, note="Страница dohod.ru в неожиданном формате.")
        else:
            res = {"status": "ok" if parsed["rows"] or parsed["upcoming"] else "nodata", "rows": parsed["rows"], "upcoming": parsed["upcoming"],
                   "currency": parsed["currency"], "title": parsed["title"], "url": url, "source": DH_SRC_NAME, "fetched": now}
    except urllib.error.HTTPError as e:
        if e.code == 404:
            res = dict(empty, url=url, fetched=now, note="На dohod.ru нет страницы дивидендов этого тикера.")
        else:
            res = dh_err(hit, empty, url, now, "dohod.ru временно недоступен (HTTP %s)." % e.code)
    except Exception as e:  # noqa: BLE001
        res = dh_err(hit, empty, url, now, "dohod.ru недоступен: %s" % str(e)[:80])
    if res["status"] == "parse" and hit and hit.get("status") == "ok":
        res = dict(hit, retry_at=now + DH_ERR_TTL)            # разметка поменялась, а старая история есть — не затираем
    try:
        store().put(key, res)
    except Exception:  # noqa: BLE001
        pass
    return res


def dh_err(hit, empty, url, now, note):
    """Сетевая ошибка: есть прошлая успешная история — отдаём её (повтор через час), иначе запись об ошибке."""
    if hit and hit.get("status") == "ok":
        return dict(hit, retry_at=now + DH_ERR_TTL, note=note)
    return dict(empty, status="err", url=url, fetched=now, note=note)


def _dh_days(a, b):
    try:
        return abs((datetime.strptime(a[:10], "%Y-%m-%d") - datetime.strptime(b[:10], "%Y-%m-%d")).days)
    except (TypeError, ValueError):
        return 10 ** 6


def _dh_same(a, b):
    """Одна и та же выплата: дата фиксации ±3 дня и сумма ±1 % (валюта, если указана, совпадает)."""
    if _dh_days(a["record"], b["record"]) > DH_DATE_TOL:
        return False
    if str(a.get("cur") or "RUB").upper() != str(b.get("cur") or "RUB").upper():
        return False
    x, y = float(a["value"]), float(b["value"])
    return abs(x - y) <= DH_SUM_TOL * max(abs(x), abs(y))


def dh_merge(items, hist_rows, today=None):
    """Слияние: items (T-Invest / сервер данных) сохраняются как есть; из hist_rows добираются выплаты вне периода, который покрывают items
    (раньше самой ранней и позже самой поздней с запасом ±3 дня). Внутри покрытого периода дубликаты по дате/сумме отбрасываются и
    ничего нового не добавляется (данные брокера точнее). Если единицы расходятся целым коэффициентом (сплит акций) — на совпавших датах
    он определяется и применяется к добираемым строкам. Возвращает (items + новые, сколько добавлено, коэффициент пересчёта или None)."""
    today = today or date.today().isoformat()
    base = [dict(x) for x in items or []]
    hist = [h for h in hist_rows or [] if h.get("record") and h.get("value") and h.get("status", "paid") in ("paid", "approved")]
    if not hist:
        return base, 0, None
    scale = None
    pairs = []
    for h in hist:
        for b in base:
            if _dh_days(h["record"], b["record"]) <= DH_DATE_TOL and str(b.get("cur") or "RUB").upper() == str(h.get("cur") or "RUB").upper() and b.get("value"):
                pairs.append(float(b["value"]) / float(h["value"]))
                break
    if pairs and all(abs(r - 1) > DH_SUM_TOL for r in pairs):
        lo, hi = min(pairs), max(pairs)
        if hi / lo <= 1.03 and (lo >= 2 or hi <= 0.5):
            scale = sorted(pairs)[len(pairs) // 2]
    if base:
        lo_d = min(b["record"] for b in base)
        hi_d = max(b["record"] for b in base)
        cover = (( datetime.strptime(lo_d[:10], "%Y-%m-%d") - timedelta(days=DH_DATE_TOL)).strftime("%Y-%m-%d"),
                 (datetime.strptime(hi_d[:10], "%Y-%m-%d") + timedelta(days=DH_DATE_TOL)).strftime("%Y-%m-%d"))
    else:
        cover = None
    added = []
    for h in sorted(hist, key=lambda x: x["record"]):
        x = dict(h)
        if scale:
            x["value"] = round(float(x["value"]) * scale, 6)
            x["scaled"] = round(scale, 6)
        if cover and cover[0] <= x["record"] <= cover[1]:
            continue                                          # покрыто основным источником
        if any(_dh_same(x, b) for b in base + added):
            continue
        x["src"] = DH_SRC
        x.setdefault("payment", None)
        x.setdefault("last_buy", None)
        added.append(x)
    return base + added, len(added), scale


def dh_enrich(items, secid, today=None, fetch=None):
    """items основного источника + история dohod.ru -> (items, meta). meta: {src, added, from, years, status, note}. Не бросает исключений."""
    meta = {"src": DH_SRC_NAME, "added": 0, "status": "off", "from": None, "years": None, "url": None, "note": None, "scaled": None}
    try:
        h = dh_history(secid, today, fetch)
        meta.update(status=h.get("status"), url=h.get("url"), note=h.get("note"))
        if h.get("status") != "ok":
            return items, meta
        merged, n, scale = dh_merge(items, h.get("rows"), today)
        meta.update(added=n, scaled=scale)
        if n:
            recs = [x["record"] for x in merged if x.get("src") == DH_SRC]
            meta["from"] = min(recs)
        return merged, meta
    except Exception as e:  # noqa: BLE001
        meta.update(status="err", note=str(e)[:80])
        return items, meta
# ═══════════════════════════════ бегущая строка котировок ═══════════════════════════════
# /api/ticker -> {"items":[{id,label,price,chg,unit,kind}], "updated": ts}. Проценты — в процентных пунктах.
# Каждый источник тянется независимо: сбой одного не убирает остальные.

TK_ISS = "https://iss.moex.com/iss/"
TK_BLUE = ("SBER", "GAZP", "LKOH", "ROSN", "NVTK", "GMKN", "YDEX", "T", "PLZL", "VTBR", "MGNT", "TATN", "CHMF", "MTSS")
TK_UA = "Mozilla/5.0 (compatible; tanalytic)"


def tk_f(x):
    try:
        v = float(x)
    except (TypeError, ValueError):
        return None
    return v if v == v else None


def tk_table(j, name):
    t = (j or {}).get(name) or {}
    cols = t.get("columns") or []
    return [dict(zip(cols, r)) for r in (t.get("data") or [])]


def tk_item(id_, label, price, chg, unit, kind):
    price = tk_f(price)
    if not price:
        return None
    chg = tk_f(chg)
    return {"id": id_, "label": label, "price": price, "chg": None if chg is None else round(chg, 2), "unit": unit, "kind": kind}


def tk_parse_index(j):
    for r in tk_table(j, "marketdata"):
        it = tk_item("IMOEX", "IMOEX", r.get("CURRENTVALUE"), r.get("LASTCHANGEPRC"), "", "index")
        if it:
            return it
    return None


def tk_parse_stocks(rows):
    by = {r.get("secid"): r for r in rows or []}
    out = []
    for s in TK_BLUE:
        r = by.get(s)
        it = r and tk_item(s, s, r.get("price"), r.get("chg_d"), "₽", "stock")
        if it:
            out.append(it)
    return out


TK_CETS = (("USD000UTSTOM", "USD/RUB", "USD", "fx"), ("CNYRUB_TOM", "CNY/RUB", "CNY", "fx"),
           ("EUR_RUB__TOM", "EUR/RUB", "EUR", "fx"), ("GLDRUB_TOM", "Золото, ₽/г", "GOLD", "metal"))


def tk_parse_cets(j):
    """{id: item}; бумаги без сделок за сессию (USD после санкций) пропускаем — для них есть запасной ЦБ."""
    out = {}
    names = {c[0]: c for c in TK_CETS}
    prev = {r.get("SECID"): tk_f(r.get("PREVPRICE")) for r in tk_table(j, "securities")}
    for r in tk_table(j, "marketdata"):
        c = names.get(r.get("SECID"))
        if not c:
            continue
        nt = tk_f(r.get("NUMTRADES"))
        last = tk_f(r.get("LAST"))
        if not last or (nt is not None and nt <= 0):
            continue
        chg = tk_f(r.get("LASTCHANGEPRC"))
        if chg is None and prev.get(r.get("SECID")):
            chg = (last / prev[r["SECID"]] - 1) * 100
        it = tk_item(c[2], c[1], last, chg, "₽", c[3])
        if it:
            out[c[2]] = it
    return out


def tk_parse_cbr(xml):
    """XML_daily ЦБ -> {'USD': 90.5, ...} (курс за единицу)."""
    out = {}
    for m in re.finditer(r"<Valute[^>]*>(.*?)</Valute>", xml or "", re.S):
        b = m.group(1)
        code = re.search(r"<CharCode>(\w+)</CharCode>", b)
        nom = re.search(r"<Nominal>(\d+)</Nominal>", b)
        val = re.search(r"<Value>([\d.,]+)</Value>", b)
        if code and nom and val:
            out[code.group(1)] = float(val.group(1).replace(",", ".")) / float(nom.group(1))
    return out


def tk_cbr_items(cur, prev, want):
    out = {}
    labels = {"USD": "USD/RUB", "CNY": "CNY/RUB", "EUR": "EUR/RUB"}
    for code in want:
        v = cur.get(code)
        if not v:
            continue
        p = prev.get(code)
        out[code] = tk_item(code, labels[code] + " (ЦБ)", v, (v / p - 1) * 100 if p else None, "₽", "fx")
    return {k: v for k, v in out.items() if v}


def tk_parse_btc(j, src):
    """coingecko: {'bitcoin':{'usd':..,'usd_24h_change':..}}; binance: {'lastPrice','priceChangePercent'}."""
    if src == "coingecko":
        b = (j or {}).get("bitcoin") or {}
        return tk_item("BTC", "Bitcoin", b.get("usd"), b.get("usd_24h_change"), "$", "crypto")
    return tk_item("BTC", "Bitcoin", (j or {}).get("lastPrice"), (j or {}).get("priceChangePercent"), "$", "crypto")


def _tk_get(url, timeout=12):
    return ext_open(url, headers={"User-Agent": TK_UA, "Accept": "application/json"}, timeout=timeout)[1].decode("utf-8", "replace")


def tk_fetch_index():
    return tk_parse_index(json.loads(http_text(TK_ISS + "engines/stock/markets/index/securities/IMOEX.json?iss.meta=off&iss.only=marketdata"
                                               "&marketdata.columns=SECID,CURRENTVALUE,LASTCHANGEPRC", timeout=15)))


def tk_fetch_cets():
    return tk_parse_cets(json.loads(http_text(TK_ISS + "engines/currency/markets/selt/boards/CETS/securities.json?iss.meta=off&iss.only=marketdata,securities"
                                              "&marketdata.columns=SECID,LAST,LASTCHANGEPRC,NUMTRADES&securities.columns=SECID,PREVPRICE", timeout=15)))


def tk_fetch_cbr(want):
    def get(d):
        url = "https://www.cbr.ru/scripts/XML_daily.asp" + ("?date_req=" + d.strftime("%d/%m/%Y") if d else "")
        return tk_parse_cbr(http_bytes(url, 15).decode("windows-1251", "replace"))
    cur = get(None)
    try:
        prev = get(date.today() - timedelta(days=1))
    except Exception:  # noqa: BLE001
        prev = {}
    return tk_cbr_items(cur, prev, want)


def tk_fetch_btc():
    mem = mem_get(("tk_btc",), 60)
    if mem is not None:
        return mem or None
    it = None
    try:
        it = tk_parse_btc(json.loads(_tk_get("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd,rub&include_24hr_change=true")), "coingecko")
    except Exception:  # noqa: BLE001
        pass
    if not it:
        try:
            it = tk_parse_btc(json.loads(_tk_get("https://api.binance.com/api/v3/ticker/24hr?symbol=BTCUSDT")), "binance")
        except Exception:  # noqa: BLE001
            pass
    mem_put(("tk_btc",), it or {})
    return it


_tk_btc_lock = threading.Lock()
_tk_btc_running = [False]


def _tk_btc_async():
    """Запускает фоновый запрос курса BTC (не чаще одного потока одновременно), возвращает Event или None."""
    with _tk_btc_lock:
        if _tk_btc_running[0]:
            return None
        _tk_btc_running[0] = True
    ev = threading.Event()

    def job():
        try:
            it = tk_fetch_btc()
            if it and mem_get(("tk_btc",), 60) is None:
                mem_put(("tk_btc",), it)
        except Exception:  # noqa: BLE001
            pass
        finally:
            with _tk_btc_lock:
                _tk_btc_running[0] = False
            ev.set()

    threading.Thread(target=job, daemon=True, name="tk-btc").start()
    return ev


def ticker_payload(force=False):
    ttl = 60 if _stk_trading() else 600
    key = ("tk_payload",)
    hit = None if force else mem_get(key, ttl)
    if hit is not None:
        res = dict(hit)
        btc_raw = mem_get(("tk_btc",), 60)
        if btc_raw is None:
            _tk_btc_async()          # не блокируем ответ: обновим BTC в фоне к следующему запросу
            return res
        btc = btc_raw or None
        res["items"] = [btc if i["id"] == "BTC" and btc else i for i in hit["items"]]
        if btc and not any(i["id"] == "BTC" for i in res["items"]):
            res["items"].append(btc)
        return res

    def _run(fn):
        try:
            return fn()
        except Exception:  # noqa: BLE001
            return None

    if force:
        idx_it, stk_rows, cets_raw, btc_it = pool_map(
            _run,
            [tk_fetch_index, lambda: tk_parse_stocks(stocks_universe(force)), tk_fetch_cets, tk_fetch_btc],
            workers=4,
        )
    else:
        ev = _tk_btc_async() if mem_get(("tk_btc",), 60) is None else None
        idx_it, stk_rows, cets_raw = pool_map(
            _run,
            [tk_fetch_index, lambda: tk_parse_stocks(stocks_universe(force)), tk_fetch_cets],
            workers=3,
        )
        if mem_get(("tk_btc",), 60) is None and ev is not None:
            ev.wait(0.4)
        btc_it = mem_get(("tk_btc",), 60) or None

    items = []
    if idx_it:
        items.append(idx_it)
    if stk_rows:
        items += stk_rows
    cets = dict(cets_raw or {})
    miss = [c for c in ("USD", "CNY", "EUR") if c not in cets]
    if miss:
        cbr = _run(lambda: tk_fetch_cbr(miss))
        if cbr:
            cets.update(cbr)
    for c in ("USD", "CNY", "EUR", "GOLD"):
        if c in cets:
            items.append(cets[c])
    if btc_it:
        items.append(btc_it)
    res = {"items": items, "updated": time.time()}
    if items:
        mem_put(key, res)
    return res


def _api_ticker(cfg, acc, q, force):
    return ticker_payload(bool(force))


API_GET["/api/ticker"] = _api_ticker
# ═══════════════════════════════ блокировка экрана (PIN / биометрия) ═══════════════════════════════
# По умолчанию выключена (lock_enabled=False). При включённой блокировке все /api/* (кроме /api/ping, /api/lock/status,
# /api/lock/unlock, /api/app/shutdown) возвращают HTTP 423 до разблокировки в текущей сессии сервера.

_lock_unlocked = [False]
_lock_state_lock = threading.Lock()
_bio_runner = None
_LOCK_PBKDF_ROUNDS = 120000

_BIO_SWIFT_SRC = (
    'import Foundation\n'
    'import LocalAuthentication\n'
    'let ctx = LAContext()\n'
    'var err: NSError?\n'
    'let reason = ProcessInfo.processInfo.environment["TA_BIO_REASON"] ?? "Unlock TAnalytic"\n'
    'guard ctx.canEvaluatePolicy(.deviceOwnerAuthentication, error: &err) else {\n'
    '    fputs(err?.localizedDescription ?? "unavailable", stderr)\n'
    '    exit(2)\n'
    '}\n'
    'let sem = DispatchSemaphore(value: 0)\n'
    'var ok = false\n'
    'var msg = ""\n'
    'ctx.evaluatePolicy(.deviceOwnerAuthentication, localizedReason: reason) { success, error in\n'
    '    ok = success\n'
    '    if let e = error { msg = e.localizedDescription }\n'
    '    sem.signal()\n'
    '}\n'
    'sem.wait()\n'
    'if !ok { fputs(msg, stderr) }\n'
    'exit(ok ? 0 : 1)\n'
)

_BIO_WIN_PS = (
    "$ErrorActionPreference = 'Stop'\n"
    "[void][Windows.Security.Credentials.UI.UserConsentVerifier, Windows.Security.Credentials.UI, ContentType = WindowsRuntime]\n"
    "Add-Type -AssemblyName System.Runtime.WindowsRuntime\n"
    "$asTaskGeneric = ([System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object { "
    "$_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' })[0]\n"
    "function Await($WinRtTask, $ResultType) {\n"
    "    $asTask = $asTaskGeneric.MakeGenericMethod($ResultType)\n"
    "    $netTask = $asTask.Invoke($null, @($WinRtTask))\n"
    "    $netTask.Wait(-1) | Out-Null\n"
    "    $netTask.Result\n"
    "}\n"
    "$avail = Await ([Windows.Security.Credentials.UI.UserConsentVerifier]::CheckAvailabilityAsync()) "
    "([Windows.Security.Credentials.UI.UserConsentVerifierAvailability])\n"
    "if ($avail -ne 'Available') { Write-Error \"unavailable:$avail\"; exit 2 }\n"
    "$reason = $env:TA_BIO_REASON\n"
    "if (-not $reason) { $reason = 'Unlock TAnalytic' }\n"
    "$res = Await ([Windows.Security.Credentials.UI.UserConsentVerifier]::RequestVerificationAsync($reason)) "
    "([Windows.Security.Credentials.UI.UserConsentVerificationResult])\n"
    "if ($res -eq 'Verified') { exit 0 } else { Write-Error \"$res\"; exit 1 }\n"
)


def _lock_hash_pin(pin, salt_bytes):
    return hashlib.pbkdf2_hmac("sha256", pin.encode("utf-8"), salt_bytes, _LOCK_PBKDF_ROUNDS).hex()


def _lock_verify_pin(cfg, pin):
    h, s = str(cfg.get("lock_pin_hash") or ""), str(cfg.get("lock_pin_salt") or "")
    if not h or not s:
        return False
    try:
        salt_bytes = bytes.fromhex(s)
    except ValueError:
        return False
    cand = _lock_hash_pin(str(pin or ""), salt_bytes)
    return hmac.compare_digest(cand, h)


def _lock_marker_sync(cfg):
    """Маркер рядом с конфигом отражает «блокировка включена» (см. lock_marker_path). Ошибки записи не критичны."""
    if cfg.get("_lock_corrupt"):
        return
    try:
        mp = lock_marker_path()
        if _lock_configured(cfg):
            if not os.path.exists(mp):
                _private_write(mp, ("TAnalytic: PIN-блокировка включена. Удалите этот файл вместе с PIN-настройками, "
                                   "чтобы снять блокировку.\n").encode("utf-8"))
        elif os.path.exists(mp):
            os.remove(mp)
    except OSError:
        pass


def _lock_configured(cfg):
    """Блокировка действует только с заданным PIN: биометрия — удобство поверх PIN, а не единственный ключ
    (иначе без Touch ID / Windows Hello в программу не войти)."""
    return bool(cfg.get("lock_enabled")) and bool(cfg.get("lock_pin_hash"))


# защита от перебора PIN: после LOCK_FREE_TRIES неудач — растущая пауза (в памяти процесса)
LOCK_FREE_TRIES = 5
LOCK_MAX_WAIT = 300
_lock_fails = {"n": 0, "until": 0.0}


def _lock_throttle_check(now=None):
    now = time.time() if now is None else now
    left = _lock_fails["until"] - now
    if left > 0:
        raise ApiError("Слишком много неверных попыток. Подождите %d с." % int(left + 0.999), 429)


def _lock_fail(now=None):
    now = time.time() if now is None else now
    _lock_fails["n"] += 1
    extra = _lock_fails["n"] - LOCK_FREE_TRIES
    if extra >= 0:
        _lock_fails["until"] = now + min(LOCK_MAX_WAIT, 2 ** min(extra, 9) * 2)


def _lock_ok():
    _lock_fails["n"] = 0
    _lock_fails["until"] = 0.0


def lock_is_locked(cfg):
    if not _lock_configured(cfg):
        return False
    return not _lock_unlocked[0]


def bio_available():
    if os.environ.get("TINVEST_NO_BIO") == "1":
        return False
    sysname = platform.system()
    if sysname == "Darwin":
        return os.path.exists("/System/Library/Frameworks/LocalAuthentication.framework")
    if sysname == "Windows":
        return bool(shutil.which("powershell"))
    return False


def _bio_mac_cmd():
    """Возвращает команду запуска macOS LocalAuthentication (кэшированный бинарник в APP_DIR/cache или swift -e)."""
    h = hashlib.sha256(_BIO_SWIFT_SRC.encode("utf-8")).hexdigest()[:12]
    cache_dir = os.path.join(APP_DIR, "cache")
    bin_path = os.path.join(cache_dir, "bio_helper_" + h)
    if os.path.isfile(bin_path) and os.access(bin_path, os.X_OK):
        return [bin_path]
    swiftc = shutil.which("swiftc")
    if swiftc:
        try:
            os.makedirs(cache_dir, exist_ok=True)
            src_path = bin_path + ".swift"
            with open(src_path, "w", encoding="utf-8") as f:
                f.write(_BIO_SWIFT_SRC)
            r = subprocess.run([swiftc, "-O", src_path, "-o", bin_path], timeout=30, capture_output=True, text=True)
            try:
                os.remove(src_path)
            except OSError:
                pass
            if r.returncode == 0 and os.path.isfile(bin_path):
                return [bin_path]
        except (OSError, subprocess.SubprocessError):
            pass
    return ["swift", "-e", _BIO_SWIFT_SRC]


def bio_verify(reason="Разблокировать TAnalytic"):
    """Нативная проверка биометрии / системного пароля -> (ok: bool, err: str)."""
    if _bio_runner is not None:
        return _bio_runner(reason)
    if not bio_available():
        return False, "Биометрия недоступна на этом устройстве"
    env = dict(os.environ, TA_BIO_REASON=str(reason or "Разблокировать TAnalytic"))
    sysname = platform.system()
    kw = {"env": env, "timeout": 30, "capture_output": True, "text": True}
    if sysname == "Darwin":
        cmd = _bio_mac_cmd()
    elif sysname == "Windows":
        cmd = ["powershell", "-NoProfile", "-Command", _BIO_WIN_PS]
        if hasattr(subprocess, "CREATE_NO_WINDOW"):
            kw["creationflags"] = subprocess.CREATE_NO_WINDOW
    else:
        return False, "Биометрия недоступна"
    try:
        proc = subprocess.run(cmd, **kw)
    except subprocess.TimeoutExpired:
        return False, "Время ожидания биометрии истекло"
    except OSError as e:
        return False, str(e)
    if proc.returncode == 0:
        return True, ""
    err = (proc.stderr or proc.stdout or "Проверка отклонена").strip()
    return False, err[:240]


def lock_status_dict(cfg):
    return {
        "enabled": bool(cfg.get("lock_enabled")),
        "unlocked": not lock_is_locked(cfg),
        "has_pin": bool(cfg.get("lock_pin_hash")),
        "bio": bool(cfg.get("lock_bio", True)),
        "bio_available": bio_available(),
        "config_corrupt": bool(cfg.get("_lock_corrupt")),
        "reset_hint": _lock_reset_hint(cfg),
    }


def _lock_reset_hint(cfg):
    mp = lock_marker_path()
    if cfg.get("_lock_corrupt"):
        return ("Файл настроек %s повреждён, поэтому программа осталась заблокированной. Закройте программу и удалите файл "
                "%s: блокировка снимется, данные портфеля не пострадают (удалять базу и сам config.json не нужно: "
                "исправьте его или восстановите из резервной копии)." % (CONFIG_PATH, mp))
    return ("Если PIN забыт: закройте программу и удалите строки lock_enabled, lock_pin_hash и lock_pin_salt из файла %s, "
            "а также файл-маркер %s. Данные портфеля при этом не удаляются." % (CONFIG_PATH, mp))


def lock_status_get(cfg, acc, q, force):
    return lock_status_dict(cfg)


def lock_setup_post(cfg, body):
    """Настройка блокировки. Поля: enabled, pin (новый), clear_pin, bio, current_pin.
    Если PIN уже задан, любое изменение требует текущий PIN (иначе блокировку снимет любой, кто сел за открытую программу)."""
    with _lock_state_lock:
        if _lock_configured(cfg) and not _lock_unlocked[0]:
            raise ApiError("Программа заблокирована", 423)
        if cfg.get("lock_pin_hash"):
            _lock_throttle_check()
            if not _lock_verify_pin(cfg, body.get("current_pin")):
                _lock_fail()
                raise ApiError("Неверный текущий PIN.", 403)
            _lock_ok()
        enabled = bool(body["enabled"]) if "enabled" in body else bool(cfg.get("lock_enabled"))
        if "bio" in body:
            cfg["lock_bio"] = bool(body["bio"])
        if body.get("clear_pin"):
            cfg["lock_pin_hash"] = ""
            cfg["lock_pin_salt"] = ""
            enabled = False                                  # без PIN блокировка не действует
        elif body.get("pin"):
            pin = str(body["pin"]).strip()
            if not (4 <= len(pin) <= 12) or not pin.isdigit():
                raise ApiError("PIN — от 4 до 12 цифр.", 400)
            salt = os.urandom(16)
            cfg["lock_pin_salt"] = salt.hex()
            cfg["lock_pin_hash"] = _lock_hash_pin(pin, salt)
        if enabled and not cfg.get("lock_pin_hash"):
            raise ApiError("Сначала задайте PIN-код: он нужен, даже если включена биометрия.", 400)
        cfg["lock_enabled"] = enabled
        _lock_unlocked[0] = True                             # текущую сессию сразу после настройки не блокируем
        save_config(cfg)
        _lock_marker_sync(cfg)
        return dict(lock_status_dict(cfg), ok=True)


def lock_unlock_post(cfg, body):
    with _lock_state_lock:
        if not lock_is_locked(cfg):
            return {"ok": True, "unlocked": True}
        _lock_throttle_check()
        method = str(body.get("method") or ("bio" if body.get("bio") else "pin"))
        if method == "bio":
            if cfg.get("_lock_corrupt") or not cfg.get("lock_bio", True):
                raise ApiError("Биометрическая разблокировка отключена.", 403)
            ok, err = bio_verify(str(body.get("reason") or "Разблокировать TAnalytic"))
            if not ok:
                raise ApiError(err or "Биометрическая проверка не пройдена.", 403)
            _lock_unlocked[0] = True
            return {"ok": True, "unlocked": True}
        pin = str(body.get("pin") or "")
        if not _lock_verify_pin(cfg, pin):
            _lock_fail()
            raise ApiError("Неверный PIN.", 403)
        _lock_ok()
        _lock_unlocked[0] = True
        return {"ok": True, "unlocked": True}


def lock_bio_post(cfg, body):
    """Проверка биометрии из Настроек (только в разблокированной программе: сюда не пускает проверка 423)."""
    ok, err = bio_verify(str(body.get("reason") or "Проверка биометрии TAnalytic"))
    return {"ok": bool(ok), "error": err or ""}


def lock_now_post(cfg, body):
    with _lock_state_lock:
        if _lock_configured(cfg):
            _lock_unlocked[0] = False
        return {"ok": True, "locked": lock_is_locked(cfg)}


def _lock_on_startup():
    with _lock_state_lock:
        _lock_unlocked[0] = False
        _lock_marker_sync(load_config())                     # включённая раньше блокировка получает маркер (после обновления)


API_GET["/api/lock/status"] = lock_status_get
API_POST["/api/lock/setup"] = lock_setup_post
API_POST["/api/lock/unlock"] = lock_unlock_post
API_POST["/api/lock/bio"] = lock_bio_post
API_POST["/api/lock/now"] = lock_now_post
STARTUP_HOOKS.append(_lock_on_startup)

# ── переезд со старой оболочки (pywebview/tk, 0.15–0.31) на оболочку Tauri ──
# Старые лаунчеры при каждом запуске сами скачивают свежий tinvest_analytics.py из последнего релиза (сверка SHA256SUMS)
# и выполняют его у себя в процессе, поэтому этот код попадает к каждому старому пользователю.
# Предлагаем перейти: программа сама скачивает установщик Tauri с GitHub, проверяет SHA256 по SHA256SUMS того же релиза,
# ставит его и перезапускается уже в новой оболочке. Данные пользователя (TINVEST_HOME, ~/.tinvest_analytics) не трогаются.
# Автозапуска нет: после переезда программа запускается один раз.
MIGRATE_REPO = "Kos5o4ka/tinvest-analytics"
MIGRATE_HOSTS = ("api.github.com", "github.com", "objects.githubusercontent.com", "release-assets.githubusercontent.com")
MIGRATE_SUMS = "SHA256SUMS"
MIGRATE_LIMIT = 150_000_000
MIGRATE_WIN_ASSET = "TAnalytic-Setup-win.exe"
MIGRATE_MAC_APP = "TAnalytic.app"


class MigrateError(Exception):
    pass


def migrate_old_shell(env=None, frozen=None, plat=None):
    """Программа запущена внутри старой оболочки: не Tauri и (собранный лаунчер или TINVEST_SHELL_REV задан),
    ревизия оболочки старше текущей. Запуск из исходников (python3 tinvest_analytics.py) — не старая оболочка."""
    env = os.environ if env is None else env
    plat = sys.platform if plat is None else plat
    frozen = bool(getattr(sys, "frozen", False)) if frozen is None else frozen
    if is_tauri_shell(env) or plat not in ("win32", "darwin"):
        return False
    if plat == "darwin" and not migrate_asset(plat):            # Mac на Intel: переезжать некуда, остаётся старая оболочка
        return False
    rev = shell_rev(env)
    return bool((frozen or rev > 0) and rev < SHELL_REV_LATEST)


def migrate_asset(plat=None, machine=None):
    plat = sys.platform if plat is None else plat
    if plat == "win32":
        return MIGRATE_WIN_ASSET
    if plat == "darwin":
        m = (platform.machine() if machine is None else machine).lower()
        return "TAnalytic-mac-arm64.dmg" if m in ("arm64", "aarch64") else None   # Mac на Intel: сборки нет с v0.31
    raise MigrateError("Переезд поддерживается только на Windows и macOS.")


def migrate_check_url(url):
    """Только HTTPS и только домены GitHub — и для исходного адреса, и для каждого редиректа."""
    u = urlparse(str(url))
    if u.scheme != "https" or u.hostname not in MIGRATE_HOSTS:
        raise MigrateError("Недопустимый адрес загрузки (разрешён только GitHub по HTTPS).")
    return url


class _MigrateRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        migrate_check_url(newurl)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def _migrate_opener():
    try:
        ctx = make_ssl_context(load_config().get("ca_file") or "", True)
    except Exception:  # noqa: BLE001
        ctx = make_ssl_context()
    return urllib.request.build_opener(_MigrateRedirect, urllib.request.HTTPSHandler(context=ctx))


def migrate_fetch(url, sink=None, limit=MIGRATE_LIMIT, progress=None, opener=None):
    """Скачивает url. sink — открытый для записи двоичный файл (иначе результат — bytes). Возвращает (bytes|None, sha256)."""
    migrate_check_url(url)
    opener = opener or _migrate_opener()
    req = urllib.request.Request(url, headers={"User-Agent": "tanalytic-migrate"})
    h, buf, n, last = hashlib.sha256(), bytearray(), 0, 0.0
    with opener.open(req, timeout=30) as r:
        total = int(r.headers.get("Content-Length") or 0)
        if total > limit:
            raise MigrateError("Файл слишком большой.")
        while True:
            chunk = r.read(65536)
            if not chunk:
                break
            n += len(chunk)
            if n > limit:
                raise MigrateError("Файл слишком большой.")
            h.update(chunk)
            if sink is not None:
                sink.write(chunk)
            else:
                buf += chunk
            now = time.time()
            if progress and now - last >= 0.2:
                last = now
                progress(n, total)
    if progress:
        progress(n, total or n)
    return (None if sink is not None else bytes(buf)), h.hexdigest()


def migrate_parse_sums(text, name):
    for line in str(text).splitlines():
        parts = line.split()
        if len(parts) == 2 and parts[1].lstrip("*") == name and re.fullmatch(r"[0-9a-fA-F]{64}", parts[0]):
            return parts[0].lower()
    raise MigrateError("В релизе нет контрольной суммы для %s." % name)


def migrate_pick(rel, name):
    """(адрес файла, адрес SHA256SUMS, тег) из описания релиза; оба адреса — только GitHub."""
    urls = {a.get("name"): a.get("browser_download_url") for a in (rel.get("assets") or []) if isinstance(a, dict)}
    if not urls.get(name) or not urls.get(MIGRATE_SUMS):
        raise MigrateError("В последнем релизе ещё нет установщика новой оболочки (%s)." % name)
    return migrate_check_url(urls[name]), migrate_check_url(urls[MIGRATE_SUMS]), str(rel.get("tag_name") or "")


def migrate_download(dest_dir, asset, progress=None, fetch=None):
    """Скачивает файл оболочки последнего релиза в dest_dir и сверяет SHA256 с SHA256SUMS того же релиза.
    Возвращает {"path", "tag", "sha"}; при несовпадении суммы файл удаляется."""
    fetch = fetch or migrate_fetch
    body, _ = fetch("https://api.github.com/repos/%s/releases/latest" % MIGRATE_REPO, limit=5_000_000)
    rel = json.loads(body.decode("utf-8"))
    url, sums_url, tag = migrate_pick(rel, asset)
    sums, _ = fetch(sums_url, limit=1_000_000)
    want = migrate_parse_sums(sums.decode("utf-8", "replace"), asset)
    path = os.path.join(dest_dir, asset)
    tmp = path + ".part"
    try:
        with open(tmp, "wb") as f:
            _, got = fetch(url, sink=f, progress=progress)
        if got != want:
            raise MigrateError("Не совпала контрольная сумма SHA256: файл отклонён.")
        os.replace(tmp, path)
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass
    return {"path": path, "tag": tag, "sha": want}


def _migrate_sha_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


# ── Windows ──
_CMD_BAD = set('"%^&|<>!`\r\n\0')


def _cmd_path(p):
    """Путь, безопасный для подстановки в .cmd в двойных кавычках: абсолютный и без метасимволов cmd."""
    p = str(p)
    if not re.match(r"^[A-Za-z]:\\", p) or any(c in _CMD_BAD for c in p):
        raise MigrateError("Путь содержит недопустимые символы: переезд невозможен.")
    return p


def win_old_exe(exe, env=None):
    """Старый одиночный TAnalytic*.exe (onefile из «Загрузок»), который нужно удалить после переезда, иначе None.
    Установка Inno (Program Files, AppData\\Local\\Programs, рядом unins000.exe) — её удаляет хук установщика NSIS."""
    env = os.environ if env is None else env
    exe = str(exe or "")
    norm = exe.replace("/", "\\")
    base = norm.rsplit("\\", 1)[-1]
    if not (base.lower().startswith("tanalytic") and base.lower().endswith(".exe")):
        return None
    low = norm.lower()
    for key in ("ProgramFiles", "ProgramFiles(x86)", "ProgramW6432"):
        pf = (env.get(key) or "").replace("/", "\\").lower().rstrip("\\")
        if pf and low.startswith(pf + "\\"):
            return None
    local = (env.get("LOCALAPPDATA") or "").replace("/", "\\").lower().rstrip("\\")
    if "\\appdata\\local\\programs\\" in low or (local and (low.startswith(local + "\\programs\\") or low.startswith(local + "\\tanalytic\\"))):
        return None
    if os.path.exists(os.path.join(os.path.dirname(exe), "unins000.exe")):
        return None
    return exe


def win_build_cmd(pid, installer, workdir, old_exe=None):
    """Текст .cmd: ждёт выхода старого процесса, тихо ставит NSIS (/S, без прав администратора), запускает новую
    программу, удаляет старый onefile-exe и себя вместе с рабочей папкой. Все пути проверены и стоят в кавычках."""
    pid = int(pid)
    inst, work = _cmd_path(installer), _cmd_path(workdir)
    old = _cmd_path(old_exe) if old_exe else ""
    q = lambda s: '"%s"' % s  # noqa: E731
    sm = "%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\TAnalytic\\TAnalytic.lnk"
    L = ["@echo off", "chcp 65001 >nul", "setlocal", "set n=0", ":wait",
         'tasklist /FI "PID eq %d" /FO CSV /NH 2>nul | find """%d""" >nul' % (pid, pid),
         "if errorlevel 1 goto gone", "set /a n+=1", "if %n% GEQ 90 goto gone", "ping -n 2 127.0.0.1 >nul", "goto wait", ":gone",
         "ping -n 2 127.0.0.1 >nul",
         'start "" /wait %s /S' % q(inst),
         "if errorlevel 1 goto failed",
         'set "NEW="',
         'if exist "%LOCALAPPDATA%\\TAnalytic\\TAnalytic.exe" set "NEW=%LOCALAPPDATA%\\TAnalytic\\TAnalytic.exe"',
         'if not defined NEW if exist "%LOCALAPPDATA%\\Programs\\TAnalytic\\TAnalytic.exe" set "NEW=%LOCALAPPDATA%\\Programs\\TAnalytic\\TAnalytic.exe"',
         'if not defined NEW if exist "%s" set "NEW=%s"' % (sm, sm),
         'if defined NEW start "" "%NEW%"']
    if old:
        L += ["set k=0", ":del", "del /f /q %s >nul 2>nul" % q(old), "if not exist %s goto cleanup" % q(old),
              "set /a k+=1", "if %k% GEQ 30 goto cleanup", "ping -n 2 127.0.0.1 >nul", "goto del"]
    L += [":cleanup", "(goto) 2>nul & rd /s /q %s" % q(work), ":failed"]
    if old:
        L += ['if exist %s start "" %s' % (q(old), q(old))]          # установка не удалась: возвращаем пользователю прежнюю программу
    L += ["(goto) 2>nul & rd /s /q %s" % q(work), ""]
    return "\r\n".join(L)


def win_spawn_cmd(cmd_file, popen=None):
    popen = popen or subprocess.Popen
    flags = 0x08000000 | 0x00000200                    # CREATE_NO_WINDOW | CREATE_NEW_PROCESS_GROUP: переживает выход программы, окна нет
    return popen(["cmd.exe", "/d", "/c", _cmd_path(cmd_file)], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                 stderr=subprocess.DEVNULL, close_fds=True, creationflags=flags)


def win_migrate(info, workdir, pid=None, exe=None, env=None, popen=None):
    if _migrate_sha_file(info["path"]) != info["sha"]:
        raise MigrateError("Файл установщика изменился после проверки: переезд отменён.")
    pid = os.getpid() if pid is None else pid
    text = win_build_cmd(pid, info["path"], workdir, win_old_exe(exe or sys.executable, env))
    cmd_file = os.path.join(workdir, "migrate.cmd")
    with open(cmd_file, "w", encoding="utf-8", newline="") as f:
        f.write(text)
    return win_spawn_cmd(cmd_file, popen)


# ── macOS ──
def mac_app_of(executable=None):
    parts = os.path.abspath(executable or sys.executable).split(os.sep)
    for i in range(len(parts) - 1, 0, -1):
        if parts[i].endswith(".app") and parts[i + 1:i + 3] == ["Contents", "MacOS"]:
            return os.sep.join(parts[:i + 1]) or os.sep
    return None


def mac_in_place_ok(app, access=os.access):
    if not app or not app.endswith(".app") or "/AppTranslocation/" in app or app.startswith("/private/var/folders/") \
            or app.startswith("/Volumes/"):
        return False
    return bool(access(app, os.W_OK) and access(os.path.dirname(app), os.W_OK))


def mac_target(current=None, access=os.access, exists=os.path.exists, home=None):
    """Куда ставить новое приложение: на место текущего (если можно), иначе /Applications, иначе ~/Applications."""
    if mac_in_place_ok(current, access):
        return current
    apps = "/Applications"
    tgt = os.path.join(apps, MIGRATE_MAC_APP)
    if access(apps, os.W_OK) and (not exists(tgt) or access(tgt, os.W_OK)):
        return tgt
    return os.path.join(home or os.path.expanduser("~"), "Applications", MIGRATE_MAC_APP)


def _mac_run(run, cmd, what, timeout=300):
    try:
        r = run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout)
    except Exception as e:  # noqa: BLE001
        raise MigrateError("%s: %s" % (what, e))
    if r.returncode != 0:
        tail = (r.stderr or b"").decode("utf-8", "replace").strip().splitlines()[-1:] or [""]
        raise MigrateError("%s (код %s) %s" % (what, r.returncode, tail[0]))
    return r


def mac_install(info, target, workdir, run=None, pid=None, exists=os.path.exists):
    """Ставит приложение из .dmg в target: копия рядом (ditto), снятие карантина, проверка подписи, затем
    прежнее (если есть) -> «.old», новое -> на место; при ошибке прежнее возвращается. Возвращает {"app","old"}."""
    run = run or subprocess.run
    if _migrate_sha_file(info["path"]) != info["sha"]:
        raise MigrateError("Файл образа изменился после проверки: переезд отменён.")
    pid = os.getpid() if pid is None else pid
    parent = os.path.dirname(target)
    os.makedirs(parent, exist_ok=True)
    new = os.path.join(parent, ".%s.new-%s" % (MIGRATE_MAC_APP, pid))
    old = os.path.join(parent, ".%s.old-%s" % (MIGRATE_MAC_APP, pid))
    mnt = os.path.join(workdir, "mnt")
    os.makedirs(mnt, mode=0o700, exist_ok=True)
    mounted, had_old = False, exists(target)
    try:
        _mac_run(run, ["hdiutil", "attach", "-nobrowse", "-readonly", "-noautoopen", "-mountpoint", mnt, info["path"]],
                 "Не удалось открыть образ диска")
        mounted = True
        src = os.path.join(mnt, MIGRATE_MAC_APP)
        if not os.path.isdir(src):
            raise MigrateError("В образе нет «%s»." % MIGRATE_MAC_APP)
        _mac_run(run, ["ditto", src, new], "Не удалось скопировать приложение")
        _mac_run(run, ["xattr", "-dr", "com.apple.quarantine", new], "Не удалось снять карантинную метку", 60)
        _mac_run(run, ["codesign", "--verify", "--deep", "--strict", new], "Подпись новой копии не прошла проверку", 120)
        if had_old:
            os.rename(target, old)
        try:
            os.rename(new, target)
        except OSError:
            if had_old:
                os.rename(old, target)
            raise
    except Exception as e:  # noqa: BLE001
        shutil.rmtree(new, ignore_errors=True)
        if isinstance(e, MigrateError):
            raise
        raise MigrateError("Не удалось установить приложение: %s" % e)
    finally:
        if mounted:
            try:
                _mac_run(run, ["hdiutil", "detach", mnt], "detach", 60)
            except MigrateError:
                try:
                    run(["hdiutil", "detach", "-force", mnt], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
                except Exception:  # noqa: BLE001
                    pass
    return {"app": target, "old": old if had_old else ""}


def mac_rollback(res):
    shutil.rmtree(res["app"], ignore_errors=True)
    if res.get("old"):
        os.rename(res["old"], res["app"])


MIGRATE_MAC_RELAUNCH = ('i=0; while kill -0 "$1" 2>/dev/null && [ $i -lt 150 ]; do sleep 0.2; i=$((i+1)); done; '
                        'open -n "$2"; [ -n "$3" ] && rm -rf "$3"')


def mac_spawn_relaunch(res, popen=None, pid=None):
    popen = popen or subprocess.Popen
    return popen(["/bin/sh", "-c", MIGRATE_MAC_RELAUNCH, "sh", str(os.getpid() if pid is None else pid), res["app"], res.get("old") or ""],
                 stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, close_fds=True, start_new_session=True)


# ── задача и API ──
_mig = {"state": "idle", "done": 0, "total": 0, "error": "", "tag": "", "where": ""}
_mig_lock = threading.Lock()


def _mig_set(**kw):
    with _mig_lock:
        _mig.update(kw)


def migrate_status():
    with _mig_lock:
        d = dict(_mig)
    d["supported"] = migrate_old_shell()
    d["url"] = SHELL_RELEASES
    return d


def migrate_exit():
    """Аккуратно завершает программу вместе со старым лаунчером (мы внутри его процесса)."""
    try:
        app_shutdown()
    except Exception:  # noqa: BLE001
        pass
    os._exit(0)


def migrate_run(exit_fn=None, plat=None, tmp=None, sleep=time.sleep):
    """Рабочий поток: скачать, проверить, поставить, перезапуститься. Любая ошибка — в статус, программа остаётся как была."""
    plat = sys.platform if plat is None else plat
    exit_fn = exit_fn or migrate_exit
    work = None
    try:
        asset = migrate_asset(plat)
        if not asset:
            raise MigrateError("Для Mac на Intel новой версии приложения нет.")
        work = tempfile.mkdtemp(prefix="tanalytic_migrate_", dir=tmp)
        _mig_set(state="downloading", done=0, total=0, error="")
        info = migrate_download(work, asset, progress=lambda d, t: _mig_set(done=d, total=t))
        _mig_set(state="installing", tag=info["tag"])
        if plat == "win32":
            win_migrate(info, work)
            work = None                                  # папку дальше убирает .cmd
        else:
            tgt = mac_target(mac_app_of())
            res = mac_install(info, tgt, work)
            try:
                mac_spawn_relaunch(res)
            except Exception:  # noqa: BLE001
                mac_rollback(res)
                raise
            _mig_set(where=tgt)
        _mig_set(state="restarting")
        sleep(1.5)                                       # баннер успевает показать «перезапуск»
        exit_fn()
    except Exception as e:  # noqa: BLE001
        msg = str(e) if isinstance(e, MigrateError) else "Не удалось связаться с GitHub или установить: %s" % (getattr(e, "reason", None) or e)
        _mig_set(state="error", error=msg)
    finally:
        if work:
            shutil.rmtree(work, ignore_errors=True)


def api_migrate_start(cfg, body):
    if not migrate_old_shell():
        raise ApiError("Переезд нужен только старой оболочке приложения.", 400)
    with _mig_lock:
        if _mig["state"] in ("downloading", "installing", "restarting"):
            return dict(_mig, supported=True, url=SHELL_RELEASES)
        _mig.update(state="downloading", done=0, total=0, error="", tag="", where="")
    threading.Thread(target=migrate_run, daemon=True).start()
    return migrate_status()


API_GET["/api/shell/migrate"] = lambda cfg, acc, q, force: migrate_status()
API_POST["/api/shell/migrate"] = api_migrate_start

# ── оболочка (собранное приложение .app/.exe): устарела ли она ──
# Автообновление меняет только tinvest_analytics.py; окно, иконка и экран обновления живут в самой оболочке.
# Оболочка сообщает свою ревизию через TINVEST_SHELL_REV (с ревизии 2); старые оболочки её не передают.
# Ревизия 3 — заставка на pywebview с бесшовным переходом в окно программы.
# Ревизия 4 — установщик Windows (onedir), значок в трее и обновление оболочки из программы;
# на macOS то же обновление из образа .dmg (ревизию не поднимали: сборка macOS с образом уже умеет обновляться).
# Ревизия 5 — оболочка Tauri (установщик NSIS на Windows и образ .dmg на macOS, автообновление через tauri-plugin-updater).
# Оболочки pywebview (ревизия 4 и ниже) получают баннер с предложением перейти на неё: скачать новый установщик.
SHELL_REV_LATEST = 5
SHELL_RELEASES = "https://github.com/Kos5o4ka/tinvest-analytics/releases/latest"


DEFAULT_CONFIG.setdefault("tray_close", False)      # «При закрытии окна сворачивать в трей» (Windows); по умолчанию выключено


def shell_rev(env=None):
    env = os.environ if env is None else env
    try:
        return int(env.get("TINVEST_SHELL_REV") or 0)
    except ValueError:
        return 0


def is_tauri_shell(env=None):
    """Сервер запущен как sidecar оболочки Tauri (она ставит TINVEST_SHELL=tauri)."""
    env = os.environ if env is None else env
    return (env.get("TINVEST_SHELL") or "").strip().lower() == "tauri"


def tray_supported(env=None, frozen=None, plat=None):
    """Трей — только у собранной оболочки pywebview ревизии 4+ на Windows (на macOS пункты скрыты).
    У оболочки Tauri настройки трея нет. Автозапуска в программе нет нигде."""
    if is_tauri_shell(env):
        return False
    frozen = bool(getattr(sys, "frozen", False)) if frozen is None else frozen
    return bool(frozen and (sys.platform if plat is None else plat) == "win32" and shell_rev(env) >= 4)


def tray_close_wanted():
    """Читает лаунчер при закрытии окна (sys.tanalytic_tray)."""
    try:
        return bool(load_config().get("tray_close"))
    except Exception:  # noqa: BLE001
        return False


def shell_status(env=None, frozen=None, cfg=None):
    env = os.environ if env is None else env
    frozen = bool(getattr(sys, "frozen", False)) if frozen is None else frozen
    rev = shell_rev(env)
    asset = {"darwin": "TAnalytic-mac-arm64.dmg" if platform.machine() == "arm64" else None,   # Intel: сборки нет с v0.31
             "win32": "TAnalytic-Setup-win.exe"}.get(sys.platform)
    tray = tray_supported(env, frozen)
    tauri = is_tauri_shell(env)
    return {"frozen": frozen, "rev": rev, "latest": SHELL_REV_LATEST, "tauri": tauri,
            "outdated": bool(frozen and not tauri and rev < SHELL_REV_LATEST and asset),
            "url": SHELL_RELEASES, "asset": asset, "migrate": migrate_old_shell(env, frozen),
            "tray": tray, "tray_close": bool(tray and (cfg or {}).get("tray_close"))}


def api_shell_tray(cfg, body):
    if not tray_supported():
        raise ApiError("Трей доступен только в установленной версии для Windows.", 400)
    if "tray_close" in body:
        cfg["tray_close"] = bool(body["tray_close"])
        save_config(cfg)
        hook = getattr(sys, "tanalytic_tray_sync", None)       # лаунчер показывает или убирает значок в трее
        if callable(hook):
            try:
                hook()
            except Exception:  # noqa: BLE001
                pass
    return shell_status(cfg=cfg)


API_GET["/api/shell"] = lambda cfg, acc, q, force: shell_status(cfg=cfg)
API_POST["/api/shell/tray"] = api_shell_tray
sys.tanalytic_tray = tray_close_wanted               # лаунчер спрашивает при закрытии окна: свернуть в трей или выйти
# ═══════════════════════════════ HTTP-сервер ═══════════════════════════════

_ping = [0.0]
_font_cache = []
_active_server = [None]
START_PAGES = {
    "dash", "ret", "bench", "pos", "bonds", "pay", "off", "ops", "fees", "tax", "reb", "calc", "lad",
    "mkt", "scr", "cmp", "map", "hm", "sig", "risk", "mon", "watch", "iss", "dfl", "flw", "pri", "fng",
    "cal", "kb", "imp", "set", "stk", "sst", "crp", "mic", "ofz", "pm", "txo", "dgap", "mm", "arb", "dbx", "rot",
}


def font_inter_bytes():
    """Встроенный шрифт Inter (variable woff2) для интерфейса: работает без сети и одинаково на Windows, macOS и Linux."""
    if not _font_cache:
        _font_cache.append(base64.b64decode(FONT_INTER_B64))
    return _font_cache[0]
# секреты, которые окно настроек может показать по кнопке «глаз» (GET /api/config/secret)
UI_SECRET_NAMES = ("token", "data_key", "backup_password")


class Handler(BaseHTTPRequestHandler):
    server_version = "TAnalytic/3.0"

    def log_message(self, *a):
        pass

    def send(self, code, body, ctype="application/json; charset=utf-8", headers=None):
        if isinstance(body, (dict, list)):
            body = json.dumps(body, ensure_ascii=False, separators=(",", ":"), default=str).encode()
        elif isinstance(body, str):
            body = body.encode()
        gz = len(body) > 2048 and ctype.startswith(("application/json", "text/")) and \
            "gzip" in (self.headers.get("Accept-Encoding") or "")
        if gz:
            body = gzip.compress(body, 5)
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "max-age=604800" if ctype in ("image/png", "font/woff2") else "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Content-Security-Policy",
                         "default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data:")
        if gz:
            self.send_header("Content-Encoding", "gzip")
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def ok_host(self):
        port = self.server.server_address[1]
        return self.headers.get("Host", "") in ("127.0.0.1:%d" % port, "localhost:%d" % port, "[::1]:%d" % port)

    def guard(self, fn):
        u = urlparse(self.path)
        t0, c0 = time.time(), (perf_snapshot() if u.path.startswith("/api/") else None)
        try:
            self._guard(fn)
        finally:
            if c0 is not None:
                perf_log(perf_label(u.path, u.query), time.time() - t0, c0)

    def _guard(self, fn):
        try:
            fn()
        except ApiError as e:
            self.send(e.status if 400 <= e.status < 600 else 502, {"error": str(e)})
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception as e:  # noqa: BLE001
            import traceback
            traceback.print_exc()
            self.send(500, {"error": "%s: %s" % (type(e).__name__, e)})

    def _reply(self, res):
        if isinstance(res, tuple):
            code, body = res[0], res[1]
            ctype = res[2] if len(res) > 2 and res[2] else "application/json; charset=utf-8"
            return self.send(code, body, ctype, res[3] if len(res) > 3 else None)
        return self.send(200, res)

    def do_GET(self):
        if not self.ok_host():
            return self.send(403, {"error": "forbidden"})
        u = urlparse(self.path)
        if u.path.startswith("/api/") and self.headers.get("Sec-Fetch-Site") not in (None, "same-origin", "none"):
            return self.send(403, {"error": "forbidden"})
        q = {k: v[0] for k, v in parse_qs(u.query).items()}

        def run():
            if u.path == "/":
                return self.send(200, PAGE, "text/html; charset=utf-8")
            if u.path == "/fonts/InterVariable.woff2":
                return self.send(200, font_inter_bytes(), "font/woff2")
            if u.path.startswith("/logo/"):
                data = logo_bytes(unquote(u.path[6:]))
                return self.send(200, data, "image/png") if data else self.send(404, {"error": "no logo"})
            if u.path == "/api/ping":
                _ping[0] = time.time()
                return self.send(200, {"ok": True, "app": APP_NAME})
            cfg = load_config()
            if u.path.startswith("/api/") and u.path not in ("/api/ping", "/api/lock/status") and lock_is_locked(cfg):
                return self.send(423, {"error": "Программа заблокирована", "locked": True})
            f = q.get("force") == "1"
            acc = q.get("account", "all") or "all"
            if u.path == "/api/config":
                pub = {k: v for k, v in cfg.items() if k not in SECRET_KEYS}
                pub["secret_set"] = {k: bool(cfg.get(k)) for k in SECRET_KEYS if k != "token"}
                pub.update(token_set=bool(cfg["token"]), token_hint=("…" + cfg["token"][-4:]) if cfg["token"] else "",
                           imports=[dict(x, broker_id=broker_of_account(x)[0]) for x in imports_list()],
                           brokers=BROKERS, data_dir=APP_DIR, version=APP_VERSION)
                return self.send(200, pub)
            if u.path == "/api/config/secret":
                # Сохранённый секрет — только своему окну: Host проверен выше, плюс собственный заголовок
                # (чужая страница не может его поставить без CORS-preflight, который мы не разрешаем). Не логируем.
                if self.headers.get("X-TA-Secret") != "1" or \
                        self.headers.get("Sec-Fetch-Site") not in (None, "same-origin"):
                    return self.send(403, {"error": "forbidden"})
                name = q.get("name", "")
                if name not in UI_SECRET_NAMES or name not in SECRET_KEYS:
                    return self.send(400, {"error": "unknown secret"})
                return self.send(200, {"name": name, "value": str(cfg.get(name) or "")})
            if u.path == "/api/summary":
                return self.send(200, build_summary(cfg, acc, q.get("period", "all"), f))
            if u.path == "/api/bonds":
                return self.send(200, build_bonds(cfg, acc, f))
            if u.path == "/api/history":
                return self.send(200, build_history_for(cfg, acc, f))
            if u.path == "/api/operations.csv":
                data = build_summary(cfg, acc, q.get("period", "all"))
                return self.send(200, operations_csv(data), "text/csv; charset=utf-8",
                                 {"Content-Disposition": 'attachment; filename="operations.csv"'})
            if u.path == "/api/screener":
                return self.send(200, screener_payload())
            if u.path == "/api/spark":
                try:
                    return self.send(200, spark_payload([x for x in (q.get("ids") or "").split(",") if x][:SPARK_MAX_IDS]))
                except Exception:  # noqa: BLE001
                    return self.send(200, {})
            if u.path == "/api/bond":
                return self.send(200, bond_card(q.get("isin", "")))
            if u.path == "/api/primary":
                return self.send(200, primary_payload())
            if u.path == "/api/ratings":
                return self.send(200, ratings_status())
            if u.path == "/api/keyrate":
                return self.send(200, keyrate_brief() or {"source": "none", "name": "", "yearly": []})
            if u.path == "/api/risk":
                return self.send(200, build_risk(cfg, acc, q))
            if u.path == "/api/signals":
                return self.send(200, signals_payload(cfg, acc, q))
            if u.path == "/api/monitor":
                return self.send(200, build_monitor(cfg, acc))
            if u.path == "/api/bench":
                return self.send(200, bench_payload(cfg, acc, q))
            if u.path == "/api/calc":
                return self.send(200, calc_params(cfg, acc))
            if u.path == "/api/offers":
                return self.send(200, offers_payload(cfg, acc))
            if u.path == "/api/ladder":
                return self.send(200, ladder_payload(cfg, q))
            if u.path == "/api/rates":
                return self.send(200, rates_payload(q.get("days", "365"), q.get("terms", "2")))
            if u.path == "/api/backup":
                return self.send(200, make_backup(), "application/zip",
                                 {"Content-Disposition": 'attachment; filename="tinvest_backup_%s.zip"' % date.today().isoformat()})
            if u.path == "/api/import/template.csv":
                return self.send(200, TEMPLATE_CSV.encode("utf-8-sig"), "text/csv; charset=utf-8",
                                 {"Content-Disposition": 'attachment; filename="import_template.csv"'})
            fn = API_GET.get(u.path)
            if fn:
                return self._reply(fn(cfg, acc, q, f))
            self.send(404, {"error": "not found"})
        self.guard(run)

    def do_POST(self):
        # Sec-Fetch-Site: запросы с чужих сайтов отклоняем (защита от CSRF; старые браузеры заголовок не шлют)
        if not self.ok_host() or "application/json" not in (self.headers.get("Content-Type") or "") \
                or self.headers.get("Sec-Fetch-Site") not in (None, "same-origin", "none"):
            return self.send(403, {"error": "forbidden"})
        path = urlparse(self.path).path

        def run():
            try:
                n = int(self.headers.get("Content-Length") or 0)
            except (TypeError, ValueError):
                raise ApiError("Некорректный заголовок Content-Length.", 400)
            if n < 0 or n > 80 * 1024 * 1024:
                raise ApiError("Файл слишком большой (больше 60 МБ)." if n > 0 else "Некорректный заголовок Content-Length.", 400)
            try:
                body = json.loads(self.rfile.read(n) or b"{}") if n else {}
            except (ValueError, UnicodeDecodeError):
                raise ApiError("Некорректный JSON.", 400)
            if not isinstance(body, dict):
                raise ApiError("Ожидался JSON-объект.", 400)
            cfg = load_config()
            if path.startswith("/api/") and path not in ("/api/lock/unlock", "/api/app/shutdown") and lock_is_locked(cfg):
                return self.send(423, {"error": "Программа заблокирована", "locked": True})
            if path == "/api/app/shutdown":
                def _stop():
                    time.sleep(0.05)
                    srv = _active_server[0]
                    if srv is not None:
                        try:
                            srv.shutdown()
                        except Exception:  # noqa: BLE001
                            pass
                    app_shutdown()
                threading.Thread(target=_stop, daemon=True, name="app-shutdown").start()
                return self.send(200, {"ok": True})
            if path == "/api/config":
                if body.get("token"):
                    cfg["token"] = "".join(str(body["token"]).split())
                if body.get("clear_token"):
                    cfg["token"] = ""
                for k in ("sandbox", "verify_ssl"):
                    if k in body:
                        cfg[k] = bool(body[k])
                if "ca_file" in body:
                    cfg["ca_file"] = str(body["ca_file"]).strip()
                if body.get("theme") in ("auto", "dark", "light"):
                    cfg["theme"] = body["theme"]
                if body.get("start_page") in START_PAGES:
                    cfg["start_page"] = body["start_page"]
                if isinstance(body.get("ui_prefs"), dict):
                    prefs = dict(cfg.get("ui_prefs") if isinstance(cfg.get("ui_prefs"), dict) else {})
                    for k, v in list(body["ui_prefs"].items())[:40]:
                        k = str(k)[:40]
                        if v is None:
                            prefs.pop(k, None)
                        elif isinstance(v, (bool, int, float)) and not (isinstance(v, float) and (v != v or abs(v) >= 1e15)):
                            prefs[k] = v
                        elif isinstance(v, str):
                            prefs[k] = v[:120]
                    cfg["ui_prefs"] = dict(list(prefs.items())[:60])
                if isinstance(body.get("targets"), dict):
                    tg = {}
                    for k, v in body["targets"].items():
                        try:
                            x = float(v)
                        except (TypeError, ValueError):
                            continue
                        if 0 < x <= 100:
                            tg[str(k)[:24]] = round(x, 2)
                    cfg["targets"] = tg
                if isinstance(body.get("ui_seen"), dict):
                    seen = dict(cfg.get("ui_seen") if isinstance(cfg.get("ui_seen"), dict) else {})
                    for k, v in body["ui_seen"].items():
                        k = str(k)[:40]
                        if isinstance(v, bool) or (isinstance(v, (int, float)) and abs(v) < 1e15):
                            seen[k] = v
                        elif isinstance(v, str):
                            seen[k] = v[:64]
                        elif isinstance(v, dict):
                            seen[k] = {str(a)[:40]: (1 if b else 0) for a, b in list(v.items())[:80]}
                    cfg["ui_seen"] = dict(list(seen.items())[:40])
                if isinstance(body.get("broker_tariffs"), dict):
                    bt = dict(cfg.get("broker_tariffs") if isinstance(cfg.get("broker_tariffs"), dict) else {})
                    for k, v in list(body["broker_tariffs"].items())[:200]:
                        k = str(k)[:64]
                        if not v:
                            bt.pop(k, None)
                        elif isinstance(v, str) and re.fullmatch(r"[a-z0-9_]{1,40}", v):
                            bt[k] = v
                    cfg["broker_tariffs"] = bt
                if body.get("keyrate_mode") in KR_MODES:
                    cfg["keyrate_mode"] = body["keyrate_mode"]
                if "notify_days" in body:
                    try:
                        cfg["notify_days"] = max(0, min(60, int(body["notify_days"])))
                    except (TypeError, ValueError):
                        pass
                for k, lo, hi in (("mon_drop5", 0.1, 50), ("mon_drop30", 0.1, 90), ("mon_spread30", 0.1, 50),
                                  ("mon_sell_days", 0.5, 365), ("mon_offer_days", 1, 365)):
                    if k in body:
                        try:
                            cfg[k] = max(lo, min(hi, float(body[k])))
                        except (TypeError, ValueError):
                            pass
                for k in ("hosts_prod", "hosts_sandbox"):
                    if isinstance(body.get(k), list):
                        hosts = [str(h).strip() for h in body[k] if str(h).strip()]
                        if hosts:
                            cfg[k] = hosts
                if str(cfg.get("data_server") or "").strip().lower() == "off":
                    cfg["data_server"] = ""         # «off» из прежних версий: сервер данных теперь не отключается
                if body.get("data_key"):
                    cfg["data_key"] = "".join(str(body["data_key"]).split())
                if body.get("clear_data_key"):
                    cfg["data_key"] = ""
                if cfg["ca_file"] and not os.path.isfile(cfg["ca_file"]):
                    raise ApiError("Файл сертификата не найден: " + cfg["ca_file"], 400)
                save_config(cfg)
                ds_reset()
                mem_clear(persist=False)        # сохранённые отчёты привязаны к токену (token_key): настройки их не портят
                if "targets" in body or "broker_tariffs" in body:
                    sync_kick_safe()
                return self.send(200, {"ok": True, "app": APP_NAME})
            if path == "/api/ratings/refresh":
                return self.send(200, {"started": ratings_start(force=True), **ratings_status()})
            client = TInvest(cfg)
            if path == "/api/test":
                tcli = client
                if body.get("token"):
                    tcfg = dict(cfg, token="".join(str(body["token"]).split()))
                    if "sandbox" in body:
                        tcfg["sandbox"] = bool(body["sandbox"])
                    tcli = TInvest(tcfg)
                return self.send(200, {"ok": True, "accounts": len(tcli.accounts())})
            if path == "/api/cache/clear":
                clear_local_cache()
                st = store()
                with st.wlock:
                    c = st.conn()
                    c.execute("DELETE FROM ops WHERE acc NOT LIKE 'imp-%'")
                    c.commit()
                mem_clear()
                return self.send(200, {"ok": True, "app": APP_NAME})
            if path == "/api/import/preview":
                raw = base64.b64decode(body.get("data") or "")
                pv = import_preview_any(body.get("filename") or "", raw)
                bid = broker_detect_import(body.get("filename") or "", raw, pv.get("format") or "")
                pv["broker_id"], pv["broker_name"] = bid, BROKERS[bid]
                return self.send(200, pv)
            if path == "/api/import/parse":
                return self.send(200, import_parse_info(body))
            if path == "/api/import/commit":
                with _man_lock:
                    res = import_commit(client, body)
                return self.send(200, res)
            if path == "/api/import/broker":
                bid = str(body.get("broker_id") or "")
                if bid not in BROKERS:
                    raise ApiError("Неизвестный брокер.", 400)
                with _man_lock:
                    lst = imports_list()
                    ex = next((x for x in lst if x["id"] == body.get("id")), None)
                    if ex is None:
                        raise ApiError("Импортированный счёт не найден.", 404)
                    ex["broker_id"] = bid
                    store().put("imports", lst)
                mem_clear()
                return self.send(200, {"ok": True, "broker_id": bid})
            if path == "/api/import/delete":
                with _man_lock:
                    lst = [x for x in imports_list() if x["id"] != body.get("id")]
                    store().put("imports", lst)
                    store().ops_clear(body.get("id") or "")
                    sync_mark_deleted_safe(body.get("id"))
                mem_clear()
                sync_kick_safe()
                return self.send(200, {"ok": True, "app": APP_NAME})
            if path in ("/api/sandbox/open", "/api/sandbox/payin"):
                if not cfg["sandbox"]:
                    raise ApiError("Доступно только в режиме песочницы.", 400)
                mem_clear()
                if path.endswith("open"):
                    return self.send(200, client.call("SandboxService", "OpenSandboxAccount", {"name": "Analytics"}))
                amount = Decimal(str(body.get("amount") or 0))
                if amount <= 0:
                    raise ApiError("Сумма должна быть больше нуля.", 400)
                acc = body.get("accountId")
                if not acc or acc == "all" or str(acc).startswith("imp-"):
                    raise ApiError("Выберите счёт песочницы в списке слева.", 400)
                return self.send(200, client.call("SandboxService", "SandboxPayIn", {"accountId": acc, "amount": to_money(amount)}))
            fn = API_POST.get(path)
            if fn:
                return self._reply(fn(cfg, body))
            self.send(404, {"error": "not found"})
        if path in CONFIG_RMW_PATHS:                # «прочитать — изменить — записать» config.json по очереди,
            with _cfg_post_lock:                     # иначе параллельные сохранения теряют правки друг друга
                self.guard(run)
        else:
            self.guard(run)


# ═══════════════════════════════ окно приложения ═══════════════════════════════

def find_app_browser():
    sysname = platform.system()
    cands = []
    if sysname == "Windows":
        for r in filter(None, [os.environ.get(k) for k in ("PROGRAMFILES", "PROGRAMFILES(X86)", "LOCALAPPDATA")]):
            cands += [os.path.join(r, "Google", "Chrome", "Application", "chrome.exe"),
                      os.path.join(r, "Microsoft", "Edge", "Application", "msedge.exe"),
                      os.path.join(r, "Yandex", "YandexBrowser", "Application", "browser.exe"),
                      os.path.join(r, "BraveSoftware", "Brave-Browser", "Application", "brave.exe")]
    elif sysname == "Darwin":
        for app, exe in (("Google Chrome", "Google Chrome"), ("Microsoft Edge", "Microsoft Edge"),
                         ("Yandex", "Yandex"), ("Brave Browser", "Brave Browser"), ("Chromium", "Chromium")):
            for base in ("/Applications", os.path.expanduser("~/Applications")):
                cands.append(os.path.join(base, app + ".app", "Contents", "MacOS", exe))
    else:
        for n in ("google-chrome", "google-chrome-stable", "chromium", "chromium-browser", "microsoft-edge",
                  "yandex-browser", "brave-browser"):
            p = shutil.which(n)
            if p:
                cands.append(p)
    return next((c for c in cands if c and os.path.isfile(c)), None)


def open_window(url):
    if sys.platform == "win32":                                  # своя иконка в панели задач, а не python.exe
        try:
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("TAnalytic.App")
        except Exception:
            pass
    exe = find_app_browser()
    if exe:
        try:
            return subprocess.Popen([exe, "--app=" + url, "--user-data-dir=" + os.path.join(APP_DIR, "window"),
                                     "--window-size=1480,940", "--no-first-run", "--no-default-browser-check",
                                     "--disable-features=Translate"],
                                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except OSError:
            pass
    webbrowser.open(url)
    return None


_cfg_post_lock = threading.Lock()
CONFIG_RMW_PATHS = {"/api/config", "/api/lock/setup", "/api/shell/tray"}


class LocalHTTPServer(ThreadingHTTPServer):
    """Сервер только на 127.0.0.1. Стандартный server_bind вызывает socket.getfqdn(): обратный DNS-запрос
    по адресу машины на macOS идёт через mDNS и вызывает запрос «разрешить находить устройства в локальной сети»,
    а до ответа на него запуск зависает. Имя хоста серверу не нужно."""
    daemon_threads = True

    def server_bind(self):
        socketserver.TCPServer.server_bind(self)
        self.server_name, self.server_port = "127.0.0.1", self.server_address[1]


def running_instance(url, timeout=1.5):
    """По адресу уже отвечает эта же программа (а не чужой сервер на том же порту)."""
    try:
        with urllib.request.urlopen(url + "api/ping", timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8") or "{}").get("app") == APP_NAME
    except Exception:  # noqa: BLE001
        return False


def app_shutdown():
    """Аккуратное завершение: журнал WAL сбрасывается в data.db, соединения закрываются (а не обрываются os._exit)."""
    for hook in SHUTDOWN_HOOKS:
        try:
            hook()
        except Exception:  # noqa: BLE001
            pass
    if STORE is None:
        return
    try:
        STORE.close_all()
    except Exception:  # noqa: BLE001
        pass


sys.tanalytic_shutdown = app_shutdown        # лаунчер вызывает перед выходом (собранное приложение)


# ── оболочка Tauri: следим за её процессом, чтобы сервер не остался сиротой, если оболочку убили или она упала ──
def parent_alive_checker(pid, plat=None, getppid=None, kill=None):
    """Возвращает функцию «процесс pid ещё жив». Подменяемые getppid/kill нужны тестам.
    В onefile-сборке PyInstaller прямой родитель — загрузчик, а не оболочка, поэтому полагаемся на переданный PID,
    а сравнение с getppid() делаем, только если мы запущены оболочкой напрямую (getppid() == pid в начале)."""
    plat = sys.platform if plat is None else plat
    if plat == "win32":
        def alive_win(_=None):
            import ctypes
            k32 = ctypes.WinDLL("kernel32", use_last_error=True)
            k32.OpenProcess.restype = ctypes.c_void_p
            k32.OpenProcess.argtypes = [ctypes.c_uint32, ctypes.c_int, ctypes.c_uint32]
            k32.WaitForSingleObject.restype = ctypes.c_uint32
            k32.WaitForSingleObject.argtypes = [ctypes.c_void_p, ctypes.c_uint32]
            k32.CloseHandle.argtypes = [ctypes.c_void_p]
            h = k32.OpenProcess(0x00100000 | 0x1000, 0, int(pid))   # SYNCHRONIZE | PROCESS_QUERY_LIMITED_INFORMATION
            if not h:
                return ctypes.get_last_error() == 5                  # ERROR_ACCESS_DENIED: процесс есть, но чужой
            try:
                return k32.WaitForSingleObject(h, 0) == 0x102        # WAIT_TIMEOUT: ещё не завершился
            finally:
                k32.CloseHandle(h)
        return alive_win
    getppid = getppid or os.getppid
    kill = kill or os.kill
    direct = getppid() == pid

    def alive_posix(_=None):
        if direct and getppid() != pid:
            return False                                             # нас усыновил init/launchd: родитель умер
        try:
            kill(pid, 0)
        except ProcessLookupError:
            return False
        except PermissionError:
            return True
        except OSError:
            return False
        return True
    return alive_posix


def parent_died():
    app_shutdown()
    os._exit(0)


def parent_watch_start(pid, interval=2.0, alive=None, on_dead=None):
    """Фоновый поток: раз в interval секунд проверяет родителя и при его смерти завершает сервер."""
    alive = alive or parent_alive_checker(pid)

    def loop():
        while True:
            time.sleep(interval)
            try:
                ok = alive(pid)
            except Exception:  # noqa: BLE001 — не смогли проверить: считаем родителя живым
                ok = True
            if not ok:
                (on_dead or parent_died)()
                return
    t = threading.Thread(target=loop, daemon=True, name="parent-watch")
    t.start()
    return t


def main():
    cfg = load_config()
    port = int(os.environ.get("TINVEST_PORT") or cfg["port"])
    parent_pid = 0
    for i, a in enumerate(sys.argv):
        if a == "--port" and i + 1 < len(sys.argv):
            port = int(sys.argv[i + 1])
        if a == "--parent-pid" and i + 1 < len(sys.argv):
            try:
                parent_pid = int(sys.argv[i + 1])
            except ValueError:
                parent_pid = 0
    if parent_pid > 0:
        parent_watch_start(parent_pid)
    store()
    try:
        srv = LocalHTTPServer(("127.0.0.1", port), Handler)
    except OSError:
        other = "http://127.0.0.1:%d/" % port
        if running_instance(other):                  # программа уже открыта на этой базе: вторую копию не поднимаем
            print("%s уже запущен → %s" % (APP_NAME, other))
            if "--no-window" not in sys.argv:
                open_window(other)
            return
        srv = LocalHTTPServer(("127.0.0.1", 0), Handler)
    srv.daemon_threads = True
    url = "http://127.0.0.1:%d/" % srv.server_address[1]
    print("%s → %s   (Ctrl+C — выход)\nДанные: %s" % (APP_NAME, url, APP_DIR))
    if "--no-window" not in sys.argv:
        proc = open_window(url)
        if proc:
            def watch():
                t0 = time.time()
                proc.wait()
                if time.time() - t0 > 8:
                    return srv.shutdown()
                while True:
                    time.sleep(30)
                    if _ping[0] and time.time() - _ping[0] > 200:
                        return srv.shutdown()
            threading.Thread(target=watch, daemon=True).start()
    try:
        try:
            ratings_start()
        except Exception:  # noqa: BLE001
            pass
        try:
            warmup_start()
        except Exception:  # noqa: BLE001
            pass
        for hook in STARTUP_HOOKS:
            try:
                hook()
            except Exception:  # noqa: BLE001
                pass
        _active_server[0] = srv
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        _active_server[0] = None
        srv.server_close()
        app_shutdown()
    # окно закрыто или Ctrl+C: фоновые расчёты (пулы потоков) прерываем сразу, иначе они падают с трассировкой
    # «cannot schedule new futures after interpreter shutdown». База SQLite транзакционная, данные не теряются.
    if parent_pid > 0 or not getattr(sys, "frozen", False):   # sidecar оболочки Tauri выходит сам; в приложении с лаунчером — он
        sys.stdout.flush()
        os._exit(0)


